('gen-4-7','gen','창세기',4,7,'네가 선을 행하면 어찌 낯을 들지 못하겠느냐 선을 행하지 아니하면 죄가 문에 엎드려 있느니라 죄가 너를 원하나 너는 죄를 다스릴지니라',87),
