('gen-13-8','gen','창세기',13,8,'아브람이 롯에게 이르되 우리는 한 친족이라 나나 너나 내 목자나 네 목자나 서로 다투게 하지 말자',327),
('gen-13-9','gen','창세기',13,9,'네 앞에 온 땅이 있지 아니하냐 나를 떠나가라 네가 좌하면 나는 우하고 네가 우하면 나는 좌하리라',328),
('gen-13-10','gen','창세기',13,10,'이에 롯이 눈을 들어 요단 지역을 바라본즉 소알까지 온 땅에 물이 넉넉하니 여호와께서 소돔과 고모라를 멸하시기 전이었으므로 여호와의 동산 같고 애굽 땅과 같았더라',329),
('gen-13-11','gen','창세기',13,11,'그러므로 롯이 요단 온 지역을 택하고 동으로 옮기니 그들이 서로 떠난지라',330),
('gen-13-12','gen','창세기',13,12,'아브람은 가나안 땅에 거주하였고 롯은 그 지역의 도시들에 머무르며 그 장막을 옮겨 소돔까지 이르렀더라',331),
('gen-13-13','gen','창세기',13,13,'소돔 사람은 여호와 앞에 악하며 큰 죄인이었더라',332),
