('gen-13-17','gen','창세기',13,17,'너는 일어나 그 땅을 종과 횡으로 두루 다녀 보라 내가 그것을 네게 주리라',336),
('gen-13-18','gen','창세기',13,18,'이에 아브람이 장막을 옮겨 헤브론에 있는 마므레 상수리 수풀에 이르러 거주하며 거기서 여호와를 위하여 제단을 쌓았더라',337),
