('gen-15-16','gen','창세기',15,16,'네 자손은 사대 만에 이 땅으로 돌아오리니 이는 아모리 족속의 죄악이 아직 가득 차지 아니함이니라 하시더니',377),
('gen-15-17','gen','창세기',15,17,'해가 져서 어두울 때에 연기 나는 화로가 보이며 타는 횃불이 쪼갠 고기 사이로 지나더라',378),
