('gen-16-11','gen','창세기',16,11,'여호와의 사자가 또 그에게 이르되 네가 임신하였은즉 아들을 낳으리니 그 이름을 이스마엘이라 하라 이는 여호와께서 네 고통을 들으셨음이니라',393),
('gen-16-12','gen','창세기',16,12,'그가 사람 중에 들나귀 같이 되리니 그의 손이 모든 사람을 치겠고 모든 사람의 손이 그를 칠지며 그가 모든 형제와 대항해서 살리라 하니라',394),
('gen-16-13','gen','창세기',16,13,'하갈이 자기에게 이르신 여호와의 이름을 나를 살피시는 하나님이라 하였으니 이는 내가 어떻게 여기서 나를 살피시는 하나님을 뵈었는고 함이라',395),
('gen-16-14','gen','창세기',16,14,'이러므로 그 샘을 브엘라해로이라 불렀으며 그것은 가데스와 베렛 사이에 있더라',396),
('gen-16-15','gen','창세기',16,15,'하갈이 아브람의 아들을 낳으매 아브람이 하갈이 낳은 그 아들을 이름하여 이스마엘이라 하였더라',397),
('gen-16-16','gen','창세기',16,16,'하갈이 아브람에게 이스마엘을 낳았을 때에 아브람이 팔십육 세였더라',398),
('gen-17-1','gen','창세기',17,1,'아브람이 구십구 세 때에 여호와께서 아브람에게 나타나서 그에게 이르시되 나는 전능한 하나님이라 너는 내 앞에서 행하여 완전하라',399),
('gen-17-2','gen','창세기',17,2,'내가 내 언약을 나와 너 사이에 두어 너를 크게 번성하게 하리라 하시니',400),
('gen-17-3','gen','창세기',17,3,'아브람이 엎드렸더니 하나님이 또 그에게 말씀하여 이르시되',401),
('gen-17-4','gen','창세기',17,4,'보라 내 언약이 너와 함께 있으니 너는 여러 민족의 아버지가 될지라',402),
('gen-17-5','gen','창세기',17,5,'이제 후로는 네 이름을 아브람이라 하지 아니하고 아브라함이라 하리니 이는 내가 너를 여러 민족의 아버지가 되게 함이니라',403),
('gen-17-6','gen','창세기',17,6,'내가 너로 심히 번성하게 하리니 내가 네게서 민족들이 나게 하며 왕들이 네게로부터 나오리라',404),
('gen-17-7','gen','창세기',17,7,'내가 내 언약을 나와 너 및 네 대대 후손 사이에 세워서 영원한 언약을 삼고 너와 네 후손의 하나님이 되리라',405),
('gen-17-8','gen','창세기',17,8,'내가 너와 네 후손에게 네가 거류하는 이 땅 곧 가나안 온 땅을 주어 영원한 기업이 되게 하고 나는 그들의 하나님이 되리라',406),
('gen-17-9','gen','창세기',17,9,'하나님이 또 아브라함에게 이르시되 그런즉 너는 내 언약을 지키고 네 후손도 대대로 지키라',407),
('gen-17-10','gen','창세기',17,10,'너희 중 남자는 다 할례를 받으라 이것이 나와 너희와 너희 후손 사이에 지킬 내 언약이니라',408),
('gen-17-11','gen','창세기',17,11,'너희는 포피를 베어라 이것이 나와 너희 사이의 언약의 표징이니라',409),
('gen-17-12','gen','창세기',17,12,'너희의 대대로 모든 남자는 집에서 난 자나 또는 너희 자손이 아니라 이방 사람에게서 돈으로 산 자를 막론하고 난 지 팔 일 만에 할례를 받을 것이라',410),
('gen-17-13','gen','창세기',17,13,'너희 집에서 난 자든지 너희 돈으로 산 자든지 할례를 받아야 하리니 이에 내 언약이 너희 살에 있어 영원한 언약이 되려니와',411),
('gen-17-14','gen','창세기',17,14,'할례를 받지 아니한 남자 곧 그 포피를 베지 아니한 자는 백성 중에서 끊어지리니 그가 내 언약을 배반하였음이니라',412),
('gen-17-15','gen','창세기',17,15,'하나님이 또 아브라함에게 이르시되 네 아내 사래는 이름을 사래라 하지 말고 사라라 하라',413),
('gen-17-16','gen','창세기',17,16,'내가 그에게 복을 주어 그가 네게 아들을 낳아 주게 하며 내가 그에게 복을 주어 그를 여러 민족의 어머니가 되게 하리니 민족의 여러 왕이 그에게서 나리라',414),
('gen-17-17','gen','창세기',17,17,'아브라함이 엎드려 웃으며 마음속으로 이르되 백 세 된 사람이 어찌 자식을 낳을까 사라는 구십 세니 어찌 출산하리요 하고',415),
('gen-17-18','gen','창세기',17,18,'아브라함이 이에 하나님께 아뢰되 이스마엘이나 하나님 앞에 살기를 원하나이다',416),
('gen-17-19','gen','창세기',17,19,'하나님이 이르시되 아니라 네 아내 사라가 네게 아들을 낳으리니 너는 그 이름을 이삭이라 하라 내가 그와 내 언약을 세우리니 그의 후손에게 영원한 언약이 되리라',417),
('gen-17-20','gen','창세기',17,20,'이스마엘에 대하여는 내가 네 말을 들었나니 내가 그에게 복을 주어 그를 매우 크게 생육하고 번성하게 할지라 그가 열두 두령을 낳으리니 내가 그를 큰 나라가 되게 하려니와',418),
('gen-17-21','gen','창세기',17,21,'내 언약은 내가 내년 이 시기에 사라가 네게 낳을 이삭과 세우리라',419),
('gen-17-22','gen','창세기',17,22,'하나님이 아브라함과 말씀을 마치시고 그를 떠나 올라가셨더라',420),
('gen-17-23','gen','창세기',17,23,'이에 아브라함이 하나님이 자기에게 말씀하신 대로 이 날에 그 아들 이스마엘과 집에서 태어난 모든 자와 돈으로 산 모든 자 곧 아브라함의 집 사람 중 모든 남자를 데려다가 그 포피를 베었으니',421),
('gen-17-24','gen','창세기',17,24,'아브라함이 그의 포피를 벤 때는 구십구 세였고',422),
('gen-17-25','gen','창세기',17,25,'그의 아들 이스마엘이 그의 포피를 벤 때는 십삼 세였더라',423),
