('gen-18-18','gen','창세기',18,18,'아브라함은 강대한 나라가 되고 천하 만민은 그로 말미암아 복을 받게 될 것이 아니냐',443),
('gen-18-19','gen','창세기',18,19,'내가 그로 그 자식과 권속에게 명하여 여호와의 도를 지켜 공의와 정의를 행하게 하려고 그를 택하였나니 이는 나 여호와가 아브라함에게 대하여 말한 일을 이루려 함이니라',444),
('gen-18-20','gen','창세기',18,20,'여호와께서 또 이르시되 소돔과 고모라에 대한 부르짖음이 크고 그 죄악이 심히 무거우니',445),
