('gen-19-6','gen','창세기',19,6,'롯이 문 밖의 무리에게로 나가서 뒤로 문을 닫고',464),
('gen-19-7','gen','창세기',19,7,'이르되 청하노니 내 형제들아 이런 악을 행하지 말라',465),
('gen-19-8','gen','창세기',19,8,'내게 남자를 가까이 하지 아니한 두 딸이 있노라 청하건대 내가 그들을 너희에게로 이끌어 내리니 너희 눈에 좋을 대로 그들에게 행하고 이 사람들은 내 집에 들어왔은즉 이 사람들에게는 아무 일도 저지르지 말라',466),
('gen-19-9','gen','창세기',19,9,'그들이 이르되 너는 물러나라 또 이르되 이 자가 들어와서 거류하면서 우리의 법관이 되려 하는도다 이제 우리가 그들보다 너를 더 해하리라 하고 롯을 밀치며 가까이 가서 그 문을 부수려고 하는지라',467),
('gen-19-10','gen','창세기',19,10,'그 사람들이 손을 내밀어 롯을 집으로 끌어들이고 문을 닫고',468),
('gen-19-11','gen','창세기',19,11,'문 밖의 무리를 대소를 막론하고 그 눈을 어둡게 하니 그들이 문을 찾느라고 헤매었더라',469),
('gen-19-12','gen','창세기',19,12,'그 사람들이 롯에게 이르되 이 외에 네게 속한 자가 또 있느냐 네 사위나 자녀나 성 중에 네게 속한 자들을 다 성 밖으로 이끌어 내라',470),
('gen-19-13','gen','창세기',19,13,'그들에 대한 부르짖음이 여호와 앞에 크므로 여호와께서 이 곳을 멸하시려고 우리를 보내셨나니 우리가 멸하리라',471),
('gen-19-14','gen','창세기',19,14,'롯이 나가서 그 딸들과 결혼할 사위들에게 말하여 이르기를 여호와께서 이 성을 멸하실 터이니 너희는 일어나 이 곳에서 떠나라 하되 그의 사위들은 농담으로 여겼더라',472),
('gen-19-15','gen','창세기',19,15,'동틀 때에 천사가 롯을 재촉하여 이르되 일어나 여기 있는 네 아내와 두 딸을 이끌어 내라 이 성의 죄악 중에 함께 멸망할까 하노라',473),
('gen-19-16','gen','창세기',19,16,'그러나 롯이 지체하매 그 사람들이 롯의 손과 그 아내의 손과 두 딸의 손을 잡아 인도하여 성 밖에 두니 여호와께서 그에게 자비를 더하심이었더라',474),
('gen-19-17','gen','창세기',19,17,'그 사람들이 그들을 밖으로 이끌어 낸 후에 이르되 도망하여 생명을 보존하라 돌아보거나 들에 머물지 말고 산으로 도망하여 멸망함을 면하라',475),
('gen-19-18','gen','창세기',19,18,'롯이 그들에게 이르되 내 주여 그리 마옵소서',476),
