('gen-19-20','gen','창세기',19,20,'보소서 저 성읍은 도망하기에 가깝고 작기도 하오니 나를 그 곳으로 도망하게 하소서 이는 작은 성읍이 아니니이까 내 생명이 보존되리이다',478),
('gen-19-21','gen','창세기',19,21,'그가 그에게 이르되 내가 이 일에도 네 소원을 들었은즉 네가 말하는 그 성읍을 멸하지 아니하리니',479),
('gen-19-22','gen','창세기',19,22,'그리로 속히 도망하라 네가 거기 이르기까지는 내가 아무 일도 행할 수 없노라 하였더라 그러므로 그 성읍 이름을 소알이라 불렀더라',480),
('gen-19-23','gen','창세기',19,23,'롯이 소알에 들어갈 때에 해가 돋았더라',481),
('gen-19-24','gen','창세기',19,24,'여호와께서 하늘 곧 여호와께로부터 유황과 불을 소돔과 고모라에 비같이 내리사',482),
('gen-19-25','gen','창세기',19,25,'그 성들과 온 들과 성에 거주하는 모든 백성과 땅에 난 것을 다 엎어 멸하셨더라',483),
('gen-19-26','gen','창세기',19,26,'롯의 아내는 뒤를 돌아보았으므로 소금 기둥이 되었더라',484),
('gen-19-27','gen','창세기',19,27,'아브라함이 그 아침에 일찍이 일어나 여호와 앞에 서 있던 곳에 이르러',485),
('gen-19-28','gen','창세기',19,28,'소돔과 고모라와 그 온 지역을 향하여 눈을 들어 연기가 옹기 가마의 연기같이 치솟음을 보았더라',486),
('gen-19-29','gen','창세기',19,29,'하나님이 그 지역의 성을 멸하실 때 곧 롯이 거주하는 성을 엎으실 때에 하나님이 아브라함을 생각하사 롯을 그 엎으시는 중에서 내보내셨더라',487),
('gen-19-30','gen','창세기',19,30,'롯이 소알에 거주하기를 두려워하여 두 딸과 함께 소알에서 나와 산에 올라가 거주하되 그 두 딸과 함께 굴에 거주하였더니',488),
('gen-19-31','gen','창세기',19,31,'큰 딸이 작은 딸에게 이르되 우리 아버지는 늙으셨고 온 세상의 도리를 따라 우리의 배필 될 사람이 이 땅에는 없으니',489),
('gen-19-32','gen','창세기',19,32,'우리가 우리 아버지에게 술을 마시게 하고 동침하여 우리 아버지로 말미암아 후손을 이어가자 하고',490),
('gen-19-33','gen','창세기',19,33,'그 밤에 그들이 아버지에게 술을 마시게 하고 큰 딸이 들어가서 그 아버지와 동침하니라 그러나 그 아버지는 그 딸이 눕고 일어나는 것을 깨닫지 못하였더라',491),
('gen-19-34','gen','창세기',19,34,'이튿날 큰 딸이 작은 딸에게 이르되 어제 밤에는 내가 우리 아버지와 동침하였으니 오늘 밤에도 우리가 아버지에게 술을 마시게 하고 네가 들어가 동침하고 우리가 아버지로 말미암아 후손을 이어가자 하고',492),
('gen-19-35','gen','창세기',19,35,'그 밤에도 그들이 아버지에게 술을 마시게 하고 작은 딸이 일어나 아버지와 동침하니라 그러나 아버지는 그 딸이 눕고 일어나는 것을 깨닫지 못하였더라',493),
('gen-19-36','gen','창세기',19,36,'롯의 두 딸이 아버지로 말미암아 임신하고',494),
('gen-19-37','gen','창세기',19,37,'큰 딸은 아들을 낳아 이름을 모압이라 하였으니 오늘날 모압의 조상이요',495),
('gen-19-38','gen','창세기',19,38,'작은 딸도 아들을 낳아 이름을 벤암미라 하였으니 오늘날 암몬 자손의 조상이었더라',496),
('gen-20-1','gen','창세기',20,1,'아브라함이 거기서 네게브 땅으로 옮겨가 가데스와 술 사이 그랄에 거류하며',497),
('gen-20-2','gen','창세기',20,2,'그의 아내 사라를 자기 누이라 하였으므로 그랄 왕 아비멜렉이 사람을 보내어 사라를 데려갔더니',498),
('gen-20-3','gen','창세기',20,3,'그 밤에 하나님이 아비멜렉에게 현몽하시고 그에게 이르시되 네가 데려간 이 여인으로 말미암아 네가 죽으리니 그는 남편이 있는 여자임이라',499),
('gen-20-4','gen','창세기',20,4,'아비멜렉이 그 여인을 가까이 하지 아니하였으므로 그가 대답하되 주여 주께서 의로운 백성도 멸하시나이까',500),
('gen-20-5','gen','창세기',20,5,'그가 나에게 이는 내 누이라고 하지 아니하였나이까 그 여인도 그는 내 오라비라 하였사오니 나는 온전한 마음과 깨끗한 손으로 이렇게 하였나이다',501),
('gen-20-6','gen','창세기',20,6,'하나님이 꿈에 또 그에게 이르시되 네가 온전한 마음으로 이렇게 한 줄을 나도 알았으므로 너를 막아 내게 범죄하지 아니하게 하였나니 여인에게 가까이 하지 못하게 함이 이 때문이니라',502),
('gen-20-7','gen','창세기',20,7,'이제 그 사람의 아내를 돌려보내라 그는 선지자라 그가 너를 위하여 기도하리니 네가 살려니와 네가 돌려보내지 아니하면 너와 네게 속한 자가 다 반드시 죽을 줄 알지니라',503),
