('gen-20-9','gen','창세기',20,9,'아비멜렉이 아브라함을 불러서 그에게 이르되 네가 어찌하여 우리에게 이렇게 하느냐 내가 무슨 죄를 네게 범하였기에 네가 나와 내 나라가 큰 죄에 빠질 뻔하게 하였느냐 네가 합당하지 아니한 일을 내게 행하였도다 하고',505),
('gen-20-10','gen','창세기',20,10,'아비멜렉이 또 아브라함에게 이르되 네가 무슨 뜻으로 이렇게 하였느냐',506),
('gen-20-11','gen','창세기',20,11,'아브라함이 이르되 이 곳에서는 하나님을 두려워함이 없으니 내 아내로 말미암아 사람들이 나를 죽일까 생각하였음이요',507),
('gen-20-12','gen','창세기',20,12,'또 그는 정말로 나의 이복 누이로서 내 아내가 되었음이니라',508),
('gen-20-13','gen','창세기',20,13,'하나님이 나를 내 아버지의 집을 떠나 두루 다니게 하실 때에 내가 아내에게 말하기를 이후로 우리의 가는 곳마다 그대는 나를 그대의 오라비라 하라 이것이 그대가 내게 베풀 은혜라 하였었노라',509),
