('gen-21-13','gen','창세기',21,13,'그러나 여종의 아들도 네 씨니 내가 그로 한 민족을 이루게 하리라 하신지라',527),
('gen-21-14','gen','창세기',21,14,'아브라함이 아침에 일찍이 일어나 떡과 물 한 가죽부대를 가져다가 하갈의 어깨에 메워 주고 그 아이를 데리고 가게 하니 하갈이 나가서 브엘세바 광야에서 방황하더니',528),
('gen-21-15','gen','창세기',21,15,'가죽부대의 물이 떨어진지라 그 자식을 관목덤불 아래에 두고',529),
