('gen-21-18','gen','창세기',21,18,'일어나 아이를 일으켜 네 손으로 붙들라 그가 큰 민족을 이루게 하리라 하시니라',532),
('gen-21-19','gen','창세기',21,19,'하나님이 하갈의 눈을 밝히셨으므로 샘물을 보고 가서 가죽부대에 물을 채워다가 그 아이에게 마시게 하였더라',533),
('gen-21-20','gen','창세기',21,20,'하나님이 그 아이와 함께 계시매 그가 장성하여 광야에서 거주하며 활 쏘는 자가 되었더니',534),
('gen-21-21','gen','창세기',21,21,'그가 바란 광야에 거주할 때에 그의 어머니가 그를 위하여 애굽 땅에서 아내를 얻어 주었더라',535),
('gen-21-22','gen','창세기',21,22,'그 때에 아비멜렉과 그 군대 장관 비골이 아브라함에게 말하여 이르되 네가 무슨 일을 하든지 하나님이 너와 함께 계시도다',536),
