('gen-21-26','gen','창세기',21,26,'아비멜렉이 이르되 누가 그리하였는지 내가 알지 못하노라 너도 내게 알리지 아니하였고 나도 듣지 못하였더니 오늘에야 들었노라',540),
('gen-21-27','gen','창세기',21,27,'아브라함이 양과 소를 가져다가 아비멜렉에게 주고 두 사람이 서로 언약을 세우니라',541),
('gen-21-28','gen','창세기',21,28,'아브라함이 일곱 암양 새끼를 따로 놓으니',542),
('gen-21-29','gen','창세기',21,29,'아비멜렉이 아브라함에게 이르되 이 일곱 암양 새끼를 따로 놓음은 어찜이냐',543),
('gen-21-30','gen','창세기',21,30,'아브라함이 이르되 너는 내 손에서 이 암양 새끼 일곱을 받아 내가 이 우물 판 증거를 삼으라 하고',544),
('gen-21-31','gen','창세기',21,31,'두 사람이 거기서 서로 맹세하였으므로 그 곳을 브엘세바라 이름하였더라',545),
