('gen-21-33','gen','창세기',21,33,'아브라함은 브엘세바에 에셀 나무를 심고 거기서 영원하신 여호와의 이름을 불렀으며',547),
('gen-21-34','gen','창세기',21,34,'그가 블레셋 사람의 땅에서 여러 날을 지냈더라',548),
('gen-22-1','gen','창세기',22,1,'그 일 후에 하나님이 아브라함을 시험하시려고 그를 부르시되 아브라함아 하시니 그가 이르되 내가 여기 있나이다',549),
('gen-22-2','gen','창세기',22,2,'여호와께서 이르시되 네 아들 네 사랑하는 독자 이삭을 데리고 모리아 땅으로 가서 내가 네게 일러 준 한 산 거기서 그를 번제로 드리라',550),
('gen-22-3','gen','창세기',22,3,'아브라함이 아침에 일찍이 일어나 나귀에 안장을 지우고 두 종과 그의 아들 이삭을 데리고 번제에 쓸 나무를 쪼개어 가지고 떠나 하나님이 자기에게 일러 주신 곳으로 가더니',551),
