('gen-22-6','gen','창세기',22,6,'아브라함이 이에 번제 나무를 가져다가 그의 아들 이삭에게 지우고 자기는 불과 칼을 손에 들고 두 사람이 동행하더니',554),
('gen-22-7','gen','창세기',22,7,'이삭이 그 아버지 아브라함에게 말하여 이르되 내 아버지여 하니 그가 이르되 내 아들아 내가 여기 있노라 이삭이 이르되 불과 나무는 있거니와 번제할 어린 양은 어디 있나이까',555),
('gen-22-8','gen','창세기',22,8,'아브라함이 이르되 내 아들아 번제할 어린 양은 하나님이 자기를 위하여 친히 준비하시리라 하고 두 사람이 함께 나아가서',556),
('gen-22-9','gen','창세기',22,9,'하나님이 그에게 일러 주신 곳에 이른지라 이에 아브라함이 그 곳에 제단을 쌓고 나무를 벌여 놓고 그의 아들 이삭을 결박하여 제단 나무 위에 놓고',557),
