('gen-22-14','gen','창세기',22,14,'아브라함이 그 땅 이름을 여호와 이레라 하였으므로 오늘날까지 사람들이 이르기를 여호와의 산에서 준비되리라 하더라',562),
('gen-22-15','gen','창세기',22,15,'여호와의 사자가 하늘에서부터 두 번째 아브라함을 불러',563),
