('gen-22-17','gen','창세기',22,17,'내가 네게 큰 복을 주고 네 씨가 크게 번성하여 하늘의 별과 같고 바닷가의 모래와 같게 하리니 네 씨가 그 대적의 성문을 차지하리라',565),
('gen-22-18','gen','창세기',22,18,'또 네 씨로 말미암아 천하 만민이 복을 받으리니 이는 네가 나의 말을 준행하였음이니라 하셨다 하니라',566),
('gen-22-19','gen','창세기',22,19,'이에 아브라함이 그의 종들에게로 돌아가서 함께 떠나 브엘세바에 이르러 거기 거주하였더라',567),
('gen-22-20','gen','창세기',22,20,'이 일 후에 어떤 사람이 아브라함에게 알리어 이르기를 밀가가 당신의 형제 나홀에게 자녀를 낳았다 하였더라',568),
