('gen-23-19','gen','창세기',23,19,'그 후에 아브라함이 그 아내 사라를 가나안 땅 마므레 앞 막벨라 밭 굴에 장사하였더라 (마므레는 곧 헤브론이라)',591),
('gen-23-20','gen','창세기',23,20,'이와 같이 그 밭과 거기에 속한 굴이 헷 족속으로부터 아브라함이 매장할 소유지로 확정되었더라',592),
('gen-24-1','gen','창세기',24,1,'아브라함이 나이가 많아 늙었고 여호와께서 그에게 범사에 복을 주셨더라',593),
