('gen-24-8','gen','창세기',24,8,'만일 여자가 너를 따라 오려고 하지 아니하면 나의 이 맹세가 너와 상관이 없나니 오직 내 아들을 데리고 그리로 가지 말지니라',600),
('gen-24-9','gen','창세기',24,9,'그 종이 이에 그의 주인 아브라함의 허벅지 아래에 손을 넣고 이 일에 대하여 그에게 맹세하였더라',601),
