('gen-27-19','gen','창세기',27,19,'야곱이 아버지에게 대답하되 나는 아버지의 맏아들 에서로소이다 아버지께서 내게 명하신 대로 내가 하였사오니 원하건대 일어나 앉아서 내가 사냥한 고기를 잡수시고 아버지 마음껏 내게 축복하소서',747),
('gen-27-20','gen','창세기',27,20,'이삭이 그의 아들에게 이르되 내 아들아 네가 어떻게 이같이 속히 잡았느냐 그가 이르되 아버지의 하나님 여호와께서 나로 순조롭게 만나게 하셨음이니이다',748),
('gen-27-21','gen','창세기',27,21,'이삭이 야곱에게 이르되 내 아들아 가까이 오라 네가 과연 내 아들 에서인지 아닌지 내가 너를 만져보려 하노라',749),
('gen-27-22','gen','창세기',27,22,'야곱이 그 아버지 이삭에게 가까이 가니 이삭이 만지며 이르되 음성은 야곱의 음성이나 손은 에서의 손이로다 하며',750),
('gen-27-23','gen','창세기',27,23,'그의 손이 형 에서의 손과 같이 털이 있으므로 분별하지 못하고 축복하였더라',751),
('gen-27-24','gen','창세기',27,24,'이삭이 이르되 네가 참 내 아들 에서냐 그가 대답하되 그러하니이다',752),
('gen-27-25','gen','창세기',27,25,'이삭이 이르되 내게로 가져오라 내 아들이 사냥한 고기를 먹고 내 마음껏 네게 축복하리라 야곱이 그에게로 가져가매 그가 먹고 또 포도주를 가져가매 그가 마시고',753),
('gen-27-26','gen','창세기',27,26,'그의 아버지 이삭이 그에게 이르되 내 아들아 가까이 와서 내게 입맞추라',754),
('gen-27-27','gen','창세기',27,27,'그가 가까이 가서 그에게 입맞추니 아버지가 그의 옷의 향취를 맡고 그에게 축복하여 이르되 내 아들의 향취는 여호와께서 복 주신 밭의 향취로다',755),
('gen-27-28','gen','창세기',27,28,'하나님은 하늘의 이슬과 땅의 기름짐이며 풍성한 곡식과 포도주를 네게 주시기를 원하노라',756),
('gen-27-29','gen','창세기',27,29,'만민이 너를 섬기고 열국이 네게 굴복하리니 네가 형제들의 주가 되고 네 어머니의 아들들이 네게 굴복하며 너를 저주하는 자는 저주를 받고 너를 축복하는 자는 복을 받기를 원하노라',757),
('gen-27-30','gen','창세기',27,30,'이삭이 야곱에게 축복하기를 마치매 야곱이 그의 아버지 이삭 앞에서 나가자 곧 그의 형 에서가 사냥하여 돌아온지라',758),
('gen-27-31','gen','창세기',27,31,'그가 별미를 만들어 아버지에게로 가지고 가서 이르되 아버지여 일어나서 아들이 사냥한 고기를 잡수시고 마음껏 내게 축복하소서',759),
('gen-27-32','gen','창세기',27,32,'그의 아버지 이삭이 그에게 이르되 너는 누구냐 그가 대답하되 나는 아버지의 아들 곧 아버지의 맏아들 에서로소이다',760),
('gen-27-33','gen','창세기',27,33,'이삭이 심히 크게 떨며 이르되 그러면 사냥한 고기를 내게 가져온 자가 누구냐 네가 오기 전에 내가 다 먹고 그를 위하여 축복하였은즉 그가 반드시 복을 받을 것이니라',761),
('gen-27-34','gen','창세기',27,34,'에서가 그의 아버지의 말을 듣고 소리 내어 울며 아버지에게 이르되 내 아버지여 내게 축복하소서 내게도 그리하소서',762),
('gen-27-35','gen','창세기',27,35,'이삭이 이르되 네 아우가 와서 속여 네 복을 빼앗았도다',763),
