('gen-27-37','gen','창세기',27,37,'이삭이 에서에게 대답하여 이르되 내가 그를 너의 주로 세우고 그의 모든 형제를 내가 그에게 종으로 주었으며 곡식과 포도주를 그에게 주었으니 내 아들아 내가 네게 무엇을 할 수 있으랴',765),
('gen-27-38','gen','창세기',27,38,'에서가 아버지에게 이르되 내 아버지여 아버지가 빌 복이 이 하나 뿐이리이까 내 아버지여 내게 축복하소서 내게도 그리하소서 하고 소리를 높여 우니',766),
('gen-27-39','gen','창세기',27,39,'그 아버지 이삭이 그에게 대답하여 이르되 네 주소는 땅의 기름짐에서 멀고 내리는 하늘 이슬에서 멀 것이며',767),
('gen-27-40','gen','창세기',27,40,'너는 칼을 믿고 생활하겠고 네 아우를 섬길 것이며 네가 매임을 벗을 때에는 그 멍에를 네 목에서 떨쳐버리리라 하였더라',768),
