('gen-27-42','gen','창세기',27,42,'맏아들 에서의 이 말이 리브가에게 들리매 이에 사람을 보내어 작은 아들 야곱을 불러 그에게 이르되 네 형 에서가 너를 죽여 그 한을 풀려 하니',770),
('gen-27-43','gen','창세기',27,43,'내 아들아 내 말을 따라 일어나 하란으로 가서 내 오라버니 라반에게로 피신하여',771),
('gen-27-44','gen','창세기',27,44,'네 형의 노가 풀리기까지 몇 날 동안 그와 함께 거주하라',772),
