('gen-37-14','gen','창세기',37,14,'이스라엘이 그에게 이르되 가서 네 형들과 양 떼가 다 잘 있는지를 보고 돌아와 내게 말하라 하고 그를 헤브론 골짜기에서 보내니 그가 세겜으로 가니라',1098),
('gen-37-15','gen','창세기',37,15,'어떤 사람이 그를 만난즉 그가 들에서 방황하는지라 그 사람이 그에게 물어 이르되 네가 무엇을 찾느냐',1099),
('gen-37-16','gen','창세기',37,16,'그가 이르되 내가 내 형들을 찾으오니 청하건대 그들이 양치는 곳을 내게 가르쳐 주소서',1100),
('gen-37-17','gen','창세기',37,17,'그 사람이 이르되 그들이 여기서 떠났느니라 내가 그들의 말을 들으니 도단으로 가자 하더라 하니라 요셉이 그의 형들의 뒤를 따라 가서 도단에서 그들을 만나니라',1101),
('gen-37-18','gen','창세기',37,18,'요셉이 그들에게 가까이 오기 전에 그들이 요셉을 멀리서 보고 죽이기를 꾀하여',1102),
