('gen-38-6','gen','창세기',38,6,'유다가 장자 엘을 위하여 아내를 데려오니 그의 이름은 다말이더라',1126),
('gen-38-7','gen','창세기',38,7,'유다의 장자 엘이 여호와가 보시기에 악하므로 여호와께서 그를 죽이신지라',1127),
