('gen-41-49','gen','창세기',41,49,'쌓아 둔 곡식이 바다 모래 같이 심히 많아 세기를 그쳤으니 그 수가 한이 없음이었더라',1245),
('gen-41-50','gen','창세기',41,50,'흉년이 들기 전에 요셉에게 두 아들이 나되 곧 온의 제사장 보디베라의 딸 아스낫이 그에게서 낳은지라',1246),
('gen-41-51','gen','창세기',41,51,'요셉이 그의 장남의 이름을 므낫세라 하였으니 하나님이 내게 내 모든 고난과 내 아버지의 온 집 일을 잊어버리게 하셨다 함이요',1247),
('gen-41-52','gen','창세기',41,52,'차남의 이름을 에브라임이라 하였으니 하나님이 나를 내가 수고한 땅에서 번성하게 하셨다 함이었더라',1248),
('gen-41-53','gen','창세기',41,53,'애굽 땅에 일곱 해 풍년이 그치고',1249),
