('gen-41-55','gen','창세기',41,55,'애굽 온 땅이 굶주리매 백성이 바로에게 부르짖어 양식을 구하는지라 바로가 애굽 모든 백성에게 이르되 요셉에게 가서 그가 너희에게 이르는 대로 하라 하니라',1251),
('gen-41-56','gen','창세기',41,56,'온 지면에 기근이 있으매 요셉이 모든 창고를 열고 애굽 백성에게 팔새 애굽 땅에 기근이 심하며',1252),
('gen-41-57','gen','창세기',41,57,'각국 백성도 양식을 사려고 애굽으로 들어와 요셉에게 이르렀으니 기근이 온 세상에 심함이었더라',1253),
('gen-42-1','gen','창세기',42,1,'그 때에 야곱이 애굽에 곡식이 있음을 보고 아들들에게 이르되 너희는 어찌하여 서로 바라보고만 있느냐',1254),
('gen-42-2','gen','창세기',42,2,'야곱이 또 이르되 내가 들은즉 저 애굽에 곡식이 있다 하니 너희는 그리로 가서 거기서 우리를 위하여 사오라 그러면 우리가 살고 죽지 아니하리라 하매',1255),
('gen-42-3','gen','창세기',42,3,'요셉의 형 열 사람이 애굽에서 곡식을 사려고 내려갔으나',1256),
('gen-42-4','gen','창세기',42,4,'야곱이 요셉의 아우 베냐민은 그의 형들과 함께 보내지 아니하였으니 이는 그의 생각에 재난이 그에게 미칠까 두려워함이었더라',1257),
('gen-42-5','gen','창세기',42,5,'이스라엘의 아들들이 양식 사러 간 자 중에 있으니 가나안 땅에 기근이 있음이라',1258),
('gen-42-6','gen','창세기',42,6,'때에 요셉이 나라의 총리로서 그 땅 모든 백성에게 곡식을 팔더니 요셉의 형들이 와서 그 앞에서 땅에 엎드려 절하매',1259),
('gen-42-7','gen','창세기',42,7,'요셉이 보고 형들인 줄을 아나 모르는 체하고 엄한 소리로 그들에게 말하여 이르되 너희가 어디서 왔느냐 그들이 이르되 곡물을 사려고 가나안에서 왔나이다',1260),
('gen-42-8','gen','창세기',42,8,'요셉은 그의 형들을 알아보았으나 그들은 요셉을 알아보지 못하더라',1261),
('gen-42-9','gen','창세기',42,9,'요셉이 그들에게 대하여 꾼 꿈을 생각하고 그들에게 이르되 너희는 정탐꾼들이라 이 나라의 틈을 엿보려고 왔느니라',1262),
('gen-42-10','gen','창세기',42,10,'그들이 그에게 이르되 내 주여 아니니이다 당신의 종들은 곡물을 사러 왔나이다',1263),
('gen-42-11','gen','창세기',42,11,'우리는 다 한 사람의 아들들로서 확실한 자들이니 당신의 종들은 정탐꾼이 아니니이다',1264),
('gen-42-12','gen','창세기',42,12,'요셉이 그들에게 이르되 아니라 너희가 이 나라의 틈을 엿보러 왔느니라',1265),
('gen-42-13','gen','창세기',42,13,'그들이 이르되 당신의 종 우리들은 열두 형제로서 가나안 땅 한 사람의 아들들이라 막내 아들은 오늘 아버지와 함께 있고 또 하나는 없어졌나이다',1266),
('gen-42-14','gen','창세기',42,14,'요셉이 그들에게 이르되 내가 너희에게 이르기를 너희는 정탐꾼들이라 한 말이 이것이니라',1267),
('gen-42-15','gen','창세기',42,15,'너희는 이같이 하여 너희 진실함을 증명할 것이라 바로의 생명으로 맹세하노니 너희 막내 아우가 여기 오지 아니하면 너희가 여기서 나가지 못하리라',1268),
('gen-42-16','gen','창세기',42,16,'너희 중 하나를 보내어 너희 아우를 데려오게 하고 너희는 갇히어 있으라 내가 너희의 말을 시험하여 너희 중에 진실이 있는지 보리라 바로의 생명으로 맹세하노니 그리하지 아니하면 너희는 과연 정탐꾼이니라 하고',1269),
('gen-42-17','gen','창세기',42,17,'그들을 다 함께 삼 일을 가두었더라',1270),
('gen-42-18','gen','창세기',42,18,'사흘 만에 요셉이 그들에게 이르되 나는 하나님을 경외하노니 너희는 이같이 하여 생명을 보전하라',1271),
('gen-42-19','gen','창세기',42,19,'너희가 확실한 자들이면 너희 형제 중 한 사람만 그 옥에 갇히게 하고 너희는 곡식을 가지고 가서 너희 집안의 굶주림을 구하고',1272),
('gen-42-20','gen','창세기',42,20,'너희 막내 아우를 내게로 데리고 오라 그러면 너희 말이 진실함이 되고 너희가 죽지 아니하리라 하니 그들이 그대로 하니라',1273),
('gen-42-21','gen','창세기',42,21,'그들이 서로 말하되 우리가 아우의 일로 말미암아 범죄하였도다 그가 우리에게 애걸할 때에 그 마음의 괴로움을 보고도 듣지 아니하였으므로 이 괴로움이 우리에게 임하도다',1274),
('gen-42-22','gen','창세기',42,22,'르우벤이 그들에게 대답하여 이르되 내가 너희에게 그 아이에 대하여 죄를 짓지 말라고 하지 아니하였더냐 그래도 너희가 듣지 아니하였느니라 그러므로 그의 핏값을 치르게 되었도다 하니',1275),
('gen-42-23','gen','창세기',42,23,'그들 사이에 통역을 세웠으므로 그들은 요셉이 듣는 줄을 알지 못하였더라',1276),
('gen-42-24','gen','창세기',42,24,'요셉이 그들을 떠나가서 울고 다시 돌아와서 그들과 말하다가 그들 중에서 시므온을 끌어내어 그들의 눈 앞에서 결박하고',1277),
('gen-42-25','gen','창세기',42,25,'명하여 곡물을 그 그릇에 채우게 하고 각 사람의 돈은 그의 자루에 도로 넣게 하고 또 길 양식을 그들에게 주게 하니 그대로 행하였더라',1278),
('gen-42-26','gen','창세기',42,26,'그들이 곡식을 나귀에 싣고 그 곳을 떠났더니',1279),
('gen-42-27','gen','창세기',42,27,'한 사람이 여관에서 나귀에게 먹이를 주려고 자루를 풀고 본즉 그 돈이 자루 아귀에 있는지라',1280),
('gen-42-28','gen','창세기',42,28,'그가 그 형제에게 말하되 내 돈을 도로 넣었도다 보라 자루 속에 있도다 이에 그들이 혼이 나서 떨며 서로 돌아보며 말하되 하나님이 어찌하여 이런 일을 우리에게 행하셨는가 하고',1281),
