('gen-42-30','gen','창세기',42,30,'그 땅의 주인인 그 사람이 엄하게 우리에게 말씀하고 우리를 그 땅에 대한 정탐꾼으로 여기기로',1283),
('gen-42-31','gen','창세기',42,31,'우리가 그에게 이르되 우리는 확실한 자들이요 정탐꾼이 아니니이다',1284),
('gen-42-32','gen','창세기',42,32,'우리는 한 아버지의 아들 열두 형제로서 하나는 없어지고 막내는 오늘 우리 아버지와 함께 가나안 땅에 있나이다 하였더니',1285),
('gen-42-33','gen','창세기',42,33,'그 땅의 주인인 그 사람이 우리에게 이르되 내가 이같이 하여 너희가 확실한 자들임을 알리니 너희 형제 중의 하나를 내게 두고 양식을 가지고 가서 너희 집안의 굶주림을 구하고',1286),
('gen-42-34','gen','창세기',42,34,'너희 막내 아우를 내게로 데려 오라 그러면 너희가 정탐꾼이 아니요 확실한 자들임을 내가 알고 너희 형제를 너희에게 돌리리니 너희가 이 나라에서 무역하리라 하더이다 하고',1287),
('gen-42-35','gen','창세기',42,35,'각기 자루를 쏟고 본즉 각 사람의 돈뭉치가 그 자루 속에 있는지라 그들과 그들의 아버지가 돈뭉치를 보고 다 두려워하더니',1288),
('gen-42-36','gen','창세기',42,36,'그들의 아버지 야곱이 그들에게 이르되 너희가 나에게 내 자식들을 잃게 하도다 요셉도 없어졌고 시므온도 없어졌거늘 베냐민을 또 빼앗아 가고자 하니 이는 다 나를 해롭게 함이로다',1289),
('gen-42-37','gen','창세기',42,37,'르우벤이 그의 아버지에게 말하여 이르되 내가 그를 아버지께로 데리고 오지 아니하거든 내 두 아들을 죽이소서 그를 내 손에 맡기소서 내가 그를 아버지께로 데리고 돌아오리이다',1290),
('gen-42-38','gen','창세기',42,38,'야곱이 이르되 내 아들은 너희와 함께 내려가지 못하리니 그의 형은 죽고 그만 남았음이라 만일 너희가 가는 길에서 재난이 그에게 미치면 너희가 내 흰 머리를 슬퍼하며 스올로 내려가게 함이 되리라',1291),
('gen-43-1','gen','창세기',43,1,'그 땅에 기근이 심하고',1292),
('gen-43-2','gen','창세기',43,2,'그들이 애굽에서 가져온 곡식을 다 먹으매 그 아버지가 그들에게 이르되 다시 가서 우리를 위하여 양식을 조금 사오라',1293),
('gen-43-3','gen','창세기',43,3,'유다가 아버지에게 말하여 이르되 그 사람이 우리에게 엄히 경고하여 이르되 너희 아우가 너희와 함께 오지 아니하면 너희가 내 얼굴을 보지 못하리라 하였으니',1294),
('gen-43-4','gen','창세기',43,4,'아버지께서 우리 아우를 우리와 함께 보내시면 우리가 내려가서 아버지를 위하여 양식을 사려니와',1295),
('gen-43-5','gen','창세기',43,5,'아버지께서 만일 그를 보내지 아니하시면 우리는 내려가지 아니하리니 그 사람이 우리에게 말하기를 너희의 아우가 너희와 함께 오지 아니하면 너희가 내 얼굴을 보지 못하리라 하였음이니이다',1296),
('gen-43-6','gen','창세기',43,6,'이스라엘이 이르되 너희가 어찌하여 너희에게 또 다른 아우가 있다고 그 사람에게 말하여 나를 괴롭게 하였느냐',1297),
('gen-43-7','gen','창세기',43,7,'그들이 이르되 그 사람이 우리와 우리의 친족에 대하여 자세히 질문하여 이르기를 너희 아버지가 아직 살아 계시느냐 너희에게 아우가 있느냐 하기로 그 묻는 말에 따라 그에게 대답한 것이니 그가 너희의 아우를 데리고 내려오라 할 줄을 우리가 어찌 알았으리이까',1298),
('gen-43-8','gen','창세기',43,8,'유다가 그의 아버지 이스라엘에게 이르되 저 아이를 나와 함께 보내시면 우리가 곧 가리니 그러면 우리와 아버지와 우리 어린 아이들이 다 살고 죽지 아니하리이다',1299),
('gen-43-9','gen','창세기',43,9,'내가 그를 위하여 담보가 되오리니 아버지께서 내 손에서 그를 찾으소서 내가 만일 그를 아버지께 데려다가 아버지 앞에 두지 아니하면 내가 영원히 죄를 지리이다',1300),
('gen-43-10','gen','창세기',43,10,'우리가 지체하지 아니하였더라면 벌써 두 번 갔다 왔으리이다',1301),
('gen-43-11','gen','창세기',43,11,'그들의 아버지 이스라엘이 그들에게 이르되 그러할진대 이렇게 하라 너희는 이 땅의 아름다운 소산을 그릇에 담아가지고 내려가서 그 사람에게 예물로 드릴지니 곧 유향 조금과 꿀 조금과 향품과 몰약과 유향나무 열매와 감복숭아이니라',1302),
('gen-43-12','gen','창세기',43,12,'너희 손에 갑절의 돈을 가지고 너희 자루 아귀에 도로 넣어져 있던 그 돈을 다시 가지고 가라 혹 잘못이 있었을까 두렵도다',1303),
('gen-43-13','gen','창세기',43,13,'네 아우도 데리고 떠나 다시 그 사람에게로 가라',1304),
('gen-43-14','gen','창세기',43,14,'전능하신 하나님께서 그 사람 앞에서 너희에게 은혜를 베푸사 그 사람으로 너희 다른 형제와 베냐민을 돌려보내게 하시기를 원하노라 내가 자식을 잃게 되면 잃으리로다',1305),
('gen-43-15','gen','창세기',43,15,'그 형제들이 예물을 마련하고 갑절의 돈을 자기들의 손에 가지고 베냐민을 데리고 애굽에 내려가서 요셉 앞에 서니라',1306),
('gen-43-16','gen','창세기',43,16,'요셉은 베냐민이 그들과 함께 있음을 보고 자기의 청지기에게 이르되 이 사람들을 집으로 인도해 들이고 짐승을 잡고 준비하라 이 사람들이 정오에 나와 함께 먹을 것이니라',1307),
('gen-43-17','gen','창세기',43,17,'청지기가 요셉의 명대로 하여 그 사람들을 요셉의 집으로 인도하니',1308),
('gen-43-18','gen','창세기',43,18,'그 사람들이 요셉의 집으로 인도되매 두려워하여 이르되 전번에 우리 자루에 들어 있던 돈의 일로 우리가 끌려드는도다 이는 우리를 억류하고 달려들어 우리를 잡아 노예로 삼고 우리의 나귀를 빼앗으려 함이로다 하고',1309),
('gen-43-19','gen','창세기',43,19,'그들이 요셉의 집 청지기에게 가까이 나아가 그 집 문 앞에서 그에게 말하여',1310),
('gen-43-20','gen','창세기',43,20,'이르되 내 주여 우리가 전번에 내려와서 양식을 사가지고',1311),
('gen-43-21','gen','창세기',43,21,'여관에 이르러 자루를 풀어본즉 각 사람의 돈이 전액 그대로 자루 아귀에 있기로 우리가 도로 가져왔고',1312),
('gen-43-22','gen','창세기',43,22,'양식 살 다른 돈도 우리가 가지고 내려왔나이다 우리의 돈을 우리 자루에 넣은 자는 누구인지 우리가 알지 못하나이다',1313),
('gen-43-23','gen','창세기',43,23,'그가 이르되 너희는 안심하라 두려워하지 말라 너희 하나님, 너희 아버지의 하나님이 재물을 너희 자루에 넣어 너희에게 주신 것이니라 너희 돈은 내가 이미 받았느니라 하고 시므온을 그들에게로 이끌어내고',1314),
('gen-43-24','gen','창세기',43,24,'그들을 요셉의 집으로 인도하고 물을 주어 발을 씻게 하며 그들의 나귀에게 먹이를 주더라',1315),
('gen-43-25','gen','창세기',43,25,'그들이 거기서 음식을 먹겠다 함을 들었으므로 예물을 정돈하고 요셉이 정오에 오기를 기다리더니',1316),
('gen-43-26','gen','창세기',43,26,'요셉이 집으로 오매 그들이 집으로 들어가서 예물을 그에게 드리고 땅에 엎드려 절하니',1317),
