('gen-43-30','gen','창세기',43,30,'요셉이 아우를 사랑하는 마음이 복받쳐 급히 울 곳을 찾아 안방으로 들어가서 울고',1321),
('gen-43-31','gen','창세기',43,31,'얼굴을 씻고 나와서 그 정을 억제하고 음식을 차리라 하매',1322),
