('gen-43-33','gen','창세기',43,33,'그들이 요셉 앞에 앉되 그들의 나이에 따라 앉히게 되니 그들이 서로 이상히 여겼더라',1324),
('gen-43-34','gen','창세기',43,34,'요셉이 자기 음식을 그들에게 주되 베냐민에게는 다른 사람보다 다섯 배나 주매 그들이 마시며 요셉과 함께 즐거워하였더라',1325),
('gen-44-1','gen','창세기',44,1,'요셉이 그의 집 청지기에게 명하여 이르되 양식을 각자의 자루에 운반할 수 있을 만큼 채우고 각자의 돈을 그 자루에 넣고',1326),
('gen-44-2','gen','창세기',44,2,'또 내 잔 곧 은잔을 그 청년의 자루 아귀에 넣고 그 양식 값 돈도 함께 넣으라 하매 그가 요셉의 명령대로 하고',1327),
('gen-44-3','gen','창세기',44,3,'아침이 밝을 때에 사람들과 그들의 나귀들을 보내니라',1328),
