('gen-44-5','gen','창세기',44,5,'이것은 내 주인이 가지고 마시며 늘 점치는 데에 쓰는 것이 아니냐 너희가 이같이 하니 악하도다 하라',1330),
('gen-44-6','gen','창세기',44,6,'청지기가 그들에게 따라 가서 그대로 말하니',1331),
