('gen-44-8','gen','창세기',44,8,'우리 자루에 있던 돈도 우리가 가나안 땅에서부터 당신에게로 가져왔거늘 우리가 어찌 당신의 주인의 집에서 은 금을 도둑질하리이까',1333),
('gen-44-9','gen','창세기',44,9,'당신의 종들 중 누구에게서 발견되든지 그는 죽을 것이요 우리는 내 주의 종들이 되리이다',1334),
('gen-44-10','gen','창세기',44,10,'그가 이르되 그러면 너희의 말과 같이 하리라 그것이 누구에게서든지 발견되면 그는 내게 종이 될 것이요 너희는 죄가 없으리라',1335),
('gen-44-11','gen','창세기',44,11,'그들이 각각 급히 자루를 땅에 내려놓고 자루를 각기 푸니',1336),
