('gen-44-20','gen','창세기',44,20,'우리가 내 주께 아뢰되 우리에게 아버지가 있으니 노인이요 또 그가 노년에 얻은 아들 청년이 있으니 그의 형은 죽고 그의 어머니가 남긴 것은 그뿐이므로 그의 아버지가 그를 사랑하나이다 하였더니',1345),
