('gen-47-23','gen','창세기',47,23,'요셉이 백성에게 이르되 오늘 내가 바로를 위하여 너희 몸과 너희 토지를 샀노라 여기 종자가 있으니 너희는 그 땅에 뿌리라',1444),
('gen-47-24','gen','창세기',47,24,'추수의 오분의 일을 바로에게 상납하고 오분의 사는 너희가 가져서 토지의 종자로도 삼고 너희의 양식으로도 삼고 너희 가족과 어린 아이의 양식으로도 삼으라',1445),
('gen-47-25','gen','창세기',47,25,'그들이 이르되 주께서 우리를 살리셨사오니 우리가 주께 은혜를 입고 바로의 종이 되겠나이다',1446),
('gen-47-26','gen','창세기',47,26,'요셉이 애굽 토지법을 세우매 그 오분의 일이 바로에게 상납되나 제사장의 토지는 바로의 소유가 되지 아니하여 오늘날까지 이르니라',1447),
('gen-47-27','gen','창세기',47,27,'이스라엘 족속이 애굽 고센 땅에 거주하며 거기서 생업을 얻어 생육하고 번성하였더라',1448),
('gen-47-28','gen','창세기',47,28,'야곱이 애굽 땅에 십칠 년을 거주하였으니 그의 나이가 백사십칠 세라',1449),
('gen-47-29','gen','창세기',47,29,'이스라엘이 죽을 날이 가까우매 그의 아들 요셉을 불러 그에게 이르되 이제 내가 네게 은혜를 입었거든 청하노니 네 손을 내 허벅지 아래에 넣고 인애와 성실함으로 내게 행하여 애굽에 나를 장사하지 아니하도록 하라',1450),
('gen-47-30','gen','창세기',47,30,'내가 조상들과 함께 눕거든 너는 나를 애굽에서 메어다가 조상의 묘지에 장사하라 요셉이 이르되 내가 아버지의 말씀대로 행하리이다',1451),
('gen-47-31','gen','창세기',47,31,'야곱이 또 이르되 내게 맹세하라 하매 그가 맹세하니 이스라엘이 침상 머리에서 하나님께 경배하니라',1452),
('gen-48-1','gen','창세기',48,1,'이 일 후에 어떤 사람이 요셉에게 말하기를 네 아버지가 병들었다 하므로 그가 곧 두 아들 므낫세와 에브라임과 함께 이르니',1453),
