('gen-48-3','gen','창세기',48,3,'요셉에게 이르되 이전에 가나안 땅 루스에서 전능하신 하나님이 내게 나타나사 복을 주시며',1455),
('gen-48-4','gen','창세기',48,4,'내게 이르시되 내가 너로 생육하고 번성하게 하여 네게서 많은 백성이 나게 하고 내가 이 땅을 네 후손에게 주어 영원한 소유가 되게 하리라 하셨느니라',1456),
('gen-48-5','gen','창세기',48,5,'내가 애굽으로 와서 네게 이르기 전에 애굽에서 네가 낳은 두 아들 에브라임과 므낫세는 내 것이라 르우벤과 시므온처럼 내 것이 될 것이요',1457),
('gen-48-6','gen','창세기',48,6,'이들 후의 네 소생은 네 것이 될 것이며 그들의 유산은 그들의 형의 이름으로 함께 받으리라',1458),
('gen-48-7','gen','창세기',48,7,'내게 대하여는 내가 이전에 밧단에서 올 때에 라헬이 나를 따르는 도중 가나안 땅에서 죽었는데 그 곳은 에브랏까지 길이 아직도 먼 곳이라 내가 거기서 그를 에브랏 길에 장사하였느니라 (에브랏은 곧 베들레헴이라)',1459),
('gen-48-8','gen','창세기',48,8,'이스라엘이 요셉의 아들들을 보고 이르되 이들은 누구냐',1460),
