('gen-48-10','gen','창세기',48,10,'이스라엘의 눈이 나이로 말미암아 어두워서 보지 못하더라 요셉이 두 아들을 이끌어 아버지 앞으로 나아가니 이스라엘이 그들에게 입맞추고 그들을 안고',1462),
