('exo-2-25','exo','출애굽기',2,25,'하나님이 이스라엘 자손을 돌보셨고 하나님이 그들을 기억하셨더라',1580),
('exo-3-1','exo','출애굽기',3,1,'모세가 그의 장인 미디안 제사장 이드로의 양 떼를 치더니 그 떼를 광야 서쪽으로 인도하여 하나님의 산 호렙에 이르매',1581),
('exo-3-2','exo','출애굽기',3,2,'여호와의 사자가 떨기나무 가운데로부터 나오는 불꽃 안에서 그에게 나타나시니라 그가 보니 떨기나무에 불이 붙었으나 그 떨기나무가 사라지지 아니하는지라',1582),
('exo-3-3','exo','출애굽기',3,3,'이에 모세가 이르되 내가 돌이켜 가서 이 큰 광경을 보리라 떨기나무가 어찌하여 타지 아니하는고 하니 그 때에',1583),
('exo-3-4','exo','출애굽기',3,4,'여호와께서 그가 보려고 돌이켜 오는 것을 보신지라 하나님이 떨기나무 가운데서 그를 불러 이르시되 모세야 모세야 하시매 그가 이르되 내가 여기 있나이다',1584),
('exo-3-5','exo','출애굽기',3,5,'하나님이 이르시되 이리로 가까이 오지 말라 네가 선 곳은 거룩한 땅이니 네 발에서 신을 벗으라',1585),
('exo-3-6','exo','출애굽기',3,6,'또 이르시되 나는 네 조상의 하나님이니 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이니라 모세가 하나님 뵈옵기를 두려워하여 얼굴을 가리매',1586),
('exo-3-7','exo','출애굽기',3,7,'여호와께서 이르시되 내가 애굽에 있는 내 백성의 고통을 분명히 보고 그들이 그들의 감독자로 말미암아 부르짖음을 듣고 그 근심을 알고',1587),
('exo-3-8','exo','출애굽기',3,8,'내가 내려가서 그들을 애굽인의 손에서 건져내고 그들을 그 땅에서 인도하여 아름답고 광대한 땅, 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 지방에 데려가려 하노라',1588),
('exo-3-9','exo','출애굽기',3,9,'이제 가라 이스라엘 자손의 부르짖음이 내게 달하고 애굽 사람이 그들을 괴롭히는 학대도 내가 보았으니',1589),
('exo-3-10','exo','출애굽기',3,10,'이제 내가 너를 바로에게 보내어 너에게 내 백성 이스라엘 자손을 애굽에서 인도하여 내게 하리라',1590),
('exo-3-11','exo','출애굽기',3,11,'모세가 하나님께 아뢰되 내가 누구이기에 바로에게 가며 이스라엘 자손을 애굽에서 인도하여 내리이까',1591),
('exo-3-12','exo','출애굽기',3,12,'하나님이 이르시되 내가 반드시 너와 함께 있으리라 네가 그 백성을 애굽에서 인도하여 낸 후에 너희가 이 산에서 하나님을 섬기리니 이것이 내가 너를 보낸 증거니라',1592),
('exo-3-13','exo','출애굽기',3,13,'모세가 하나님께 아뢰되 내가 이스라엘 자손에게 가서 이르기를 너희의 조상의 하나님이 나를 너희에게 보내셨다 하면 그들이 내게 묻기를 그의 이름이 무엇이냐 하리니 내가 무엇이라고 그들에게 말하리이까',1593),
('exo-3-14','exo','출애굽기',3,14,'하나님이 모세에게 이르시되 나는 스스로 있는 자이니라 또 이르시되 너는 이스라엘 자손에게 이같이 이르기를 스스로 있는 자가 나를 너희에게 보내셨다 하라',1594),
('exo-3-15','exo','출애굽기',3,15,'하나님이 또 모세에게 이르시되 너는 이스라엘 자손에게 이같이 이르기를 너희 조상의 하나님 여호와 곧 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님께서 나를 너희에게 보내셨다 하라 이는 나의 영원한 이름이요 대대로 기억할 나의 칭호니라',1595),
('exo-3-16','exo','출애굽기',3,16,'너는 가서 이스라엘의 장로들을 모으고 그들에게 이르기를 여호와 너희 조상의 하나님 곧 아브라함과 이삭과 야곱의 하나님이 내게 나타나 이르시되 내가 너희를 돌보아 너희가 애굽에서 당한 일을 확실히 보았노라',1596),
('exo-3-17','exo','출애굽기',3,17,'내가 말하였거니와 내가 너희를 애굽의 고난 중에서 인도하여 내어 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 땅으로 올라가게 하리라 하셨다 하면',1597),
('exo-3-18','exo','출애굽기',3,18,'그들이 네 말을 들으리니 너는 그들의 장로들과 함께 애굽 왕에게 이르기를 히브리 사람의 하나님 여호와께서 우리에게 임하셨은즉 우리가 우리 하나님 여호와께 제사를 드리려 하오니 사흘길쯤 광야로 가도록 허락하소서 하라',1598),
('exo-3-19','exo','출애굽기',3,19,'내가 아노니 강한 손으로 치기 전에는 애굽 왕이 너희가 가도록 허락하지 아니하다가',1599),
('exo-3-20','exo','출애굽기',3,20,'내가 내 손을 들어 애굽 중에 여러 가지 이적으로 그 나라를 친 후에야 그가 너희를 보내리라',1600),
('exo-3-21','exo','출애굽기',3,21,'내가 애굽 사람으로 이 백성에게 은혜를 입히게 할지라 너희가 나갈 때에 빈손으로 가지 아니하리니',1601),
('exo-3-22','exo','출애굽기',3,22,'여인들은 모두 그 이웃 사람과 및 자기 집에 거류하는 여인에게 은 패물과 금 패물과 의복을 구하여 너희의 자녀를 꾸미라 너희는 애굽 사람들의 물품을 취하리라',1602),
('exo-4-1','exo','출애굽기',4,1,'모세가 대답하여 이르되 그러나 그들이 나를 믿지 아니하며 내 말을 듣지 아니하고 이르기를 여호와께서 네게 나타나지 아니하셨다 하리이다',1603),
('exo-4-2','exo','출애굽기',4,2,'여호와께서 그에게 이르시되 네 손에 있는 것이 무엇이냐 그가 이르되 지팡이니이다',1604),
('exo-4-3','exo','출애굽기',4,3,'여호와께서 이르시되 그것을 땅에 던지라 하시매 곧 땅에 던지니 그것이 뱀이 된지라 모세가 뱀 앞에서 피하매',1605),
('exo-4-4','exo','출애굽기',4,4,'여호와께서 모세에게 이르시되 네 손을 내밀어 그 꼬리를 잡으라 그가 손을 내밀어 그것을 잡으니 그의 손에서 지팡이가 된지라',1606),
('exo-4-5','exo','출애굽기',4,5,'이는 그들에게 그들의 조상의 하나님 곧 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님 여호와가 네게 나타난 줄을 믿게 하려 함이라 하시고',1607),
('exo-4-6','exo','출애굽기',4,6,'여호와께서 또 그에게 이르시되 네 손을 품에 넣으라 하시매 그가 손을 품에 넣었다가 내어보니 그의 손에 나병이 생겨 눈 같이 된지라',1608),
('exo-4-7','exo','출애굽기',4,7,'이르시되 네 손을 다시 품에 넣으라 하시매 그가 다시 손을 품에 넣었다가 내어보니 그의 손이 본래의 살로 되돌아왔더라',1609),
('exo-4-8','exo','출애굽기',4,8,'여호와께서 이르시되 만일 그들이 너를 믿지 아니하며 그 처음 표적의 표징을 받지 아니하여도 나중 표적의 표징은 믿으리라',1610),
('exo-4-9','exo','출애굽기',4,9,'그들이 이 두 이적을 믿지 아니하며 네 말을 듣지 아니하거든 너는 나일 강 물을 조금 떠다가 땅에 부으라 네가 떠온 나일 강 물이 땅에서 피가 되리라',1611),
('exo-4-10','exo','출애굽기',4,10,'모세가 여호와께 아뢰되 오 주여 나는 본래 말을 잘 하지 못하는 자니이다 주께서 주의 종에게 명령하신 후에도 역시 그러하니 나는 입이 뻣뻣하고 혀가 둔한 자니이다',1612),
('exo-4-11','exo','출애굽기',4,11,'여호와께서 그에게 이르시되 누가 사람의 입을 지었느냐 누가 말 못 하는 자나 못 듣는 자나 눈 밝은 자나 맹인이 되게 하였느냐 나 여호와가 아니냐',1613),
('exo-4-12','exo','출애굽기',4,12,'이제 가라 내가 네 입과 함께 있어서 할 말을 가르치리라',1614),
('exo-4-13','exo','출애굽기',4,13,'모세가 이르되 오 주여 보낼 만한 자를 보내소서',1615),
('exo-4-14','exo','출애굽기',4,14,'여호와께서 모세를 향하여 노하여 이르시되 레위 사람 네 형 아론이 있지 아니하냐 그가 말 잘 하는 것을 내가 아노라 그가 너를 만나러 나오나니 그가 너를 볼 때에 그의 마음에 기쁨이 있을 것이라',1616),
('exo-4-15','exo','출애굽기',4,15,'너는 그에게 말하고 그의 입에 할 말을 주라 내가 네 입과 그의 입에 함께 있어서 너희들이 행할 일을 가르치리라',1617),
('exo-4-16','exo','출애굽기',4,16,'그가 너를 대신하여 백성에게 말할 것이니 그는 네 입을 대신할 것이요 너는 그에게 하나님 같이 되리라',1618),
('exo-4-17','exo','출애굽기',4,17,'너는 이 지팡이를 손에 잡고 이것으로 이적을 행할지니라',1619),
('exo-4-18','exo','출애굽기',4,18,'모세가 그의 장인 이드로에게로 돌아가서 그에게 이르되 내가 애굽에 있는 내 형제들에게로 돌아가서 그들이 아직 살아 있는지 알아보려 하오니 나로 가게 하소서 이드로가 모세에게 평안히 가라 하니라',1620),
('exo-4-19','exo','출애굽기',4,19,'여호와께서 미디안에서 모세에게 이르시되 애굽으로 돌아가라 네 목숨을 노리던 자가 다 죽었느니라',1621),
('exo-4-20','exo','출애굽기',4,20,'모세가 그의 아내와 아들들을 나귀에 태우고 애굽으로 돌아가는데 모세가 하나님의 지팡이를 손에 잡았더라',1622),
('exo-4-21','exo','출애굽기',4,21,'여호와께서 모세에게 이르시되 네가 애굽으로 돌아가거든 내가 네 손에 준 이적을 바로 앞에서 다 행하라 그러나 내가 그의 마음을 완악하게 한즉 그가 백성을 보내 주지 아니하리니',1623),
('exo-4-22','exo','출애굽기',4,22,'너는 바로에게 이르기를 여호와의 말씀에 이스라엘은 내 아들 내 장자라',1624),
('exo-4-23','exo','출애굽기',4,23,'내가 네게 이르기를 내 아들을 보내 주어 나를 섬기게 하라 하여도 네가 보내 주기를 거절하니 내가 네 아들 네 장자를 죽이리라 하셨다 하라 하시니라',1625),
('exo-4-24','exo','출애굽기',4,24,'모세가 길을 가다가 숙소에 있을 때에 여호와께서 그를 만나사 그를 죽이려 하신지라',1626),
('exo-4-25','exo','출애굽기',4,25,'십보라가 돌칼을 가져다가 그의 아들의 포피를 베어 그의 발에 갖다 대며 이르되 당신은 참으로 내게 피 남편이로다 하니',1627),
('exo-4-26','exo','출애굽기',4,26,'여호와께서 그를 놓아 주시니라 그 때에 십보라가 피 남편이라 함은 할례 때문이었더라',1628),
('exo-4-27','exo','출애굽기',4,27,'여호와께서 아론에게 이르시되 광야에 가서 모세를 맞으라 하시매 그가 가서 하나님의 산에서 모세를 만나 그에게 입맞추니',1629),
('exo-4-28','exo','출애굽기',4,28,'모세가 여호와께서 자기에게 분부하여 보내신 모든 말씀과 여호와께서 자기에게 명령하신 모든 이적을 아론에게 알리니라',1630),
('exo-4-29','exo','출애굽기',4,29,'모세와 아론이 가서 이스라엘 자손의 모든 장로를 모으고',1631),
('exo-4-30','exo','출애굽기',4,30,'아론이 여호와께서 모세에게 이르신 모든 말씀을 전하고 그 백성 앞에서 이적을 행하니',1632),
('exo-4-31','exo','출애굽기',4,31,'백성이 믿으며 여호와께서 이스라엘 자손을 찾으시고 그들의 고난을 살피셨다 함을 듣고 머리 숙여 경배하였더라',1633),
('exo-5-1','exo','출애굽기',5,1,'그 후에 모세와 아론이 바로에게 가서 이르되 이스라엘의 하나님 여호와께서 이렇게 말씀하시기를 내 백성을 보내라 그러면 그들이 광야에서 내 앞에 절기를 지킬 것이니라 하셨나이다',1634),
('exo-5-2','exo','출애굽기',5,2,'바로가 이르되 여호와가 누구이기에 내가 그의 목소리를 듣고 이스라엘을 보내겠느냐 나는 여호와를 알지 못하니 이스라엘을 보내지 아니하리라',1635),
('exo-5-3','exo','출애굽기',5,3,'그들이 이르되 히브리인의 하나님이 우리에게 나타나셨은즉 우리가 광야로 사흘길쯤 가서 우리 하나님 여호와께 제사를 드리려 하오니 가도록 허락하소서 여호와께서 전염병이나 칼로 우리를 치실까 두려워하나이다',1636),
('exo-5-4','exo','출애굽기',5,4,'애굽 왕이 그들에게 이르되 모세와 아론아 너희가 어찌하여 백성의 노역을 쉬게 하려느냐 가서 너희의 노역이나 하라',1637),
('exo-5-5','exo','출애굽기',5,5,'바로가 또 이르되 이제 이 땅의 백성이 많아졌거늘 너희가 그들로 노역을 쉬게 하는도다 하고',1638),
('exo-5-6','exo','출애굽기',5,6,'바로가 그 날에 백성의 감독들과 기록원들에게 명령하여 이르되',1639),
