('exo-14-2','exo','출애굽기',14,2,'이스라엘 자손에게 명령하여 돌이켜 바다와 믹돌 사이의 비하히롯 앞 곧 바알스본 맞은편 바닷가에 장막을 치게 하라',1892),
('exo-14-3','exo','출애굽기',14,3,'바로가 이스라엘 자손에 대하여 말하기를 그들이 그 땅에서 멀리 떠나 광야에 갇힌 바 되었다 하리라',1893),
('exo-14-4','exo','출애굽기',14,4,'내가 바로의 마음을 완악하게 한즉 바로가 그들의 뒤를 따르리니 내가 그와 그의 온 군대로 말미암아 영광을 얻어 애굽 사람들이 나를 여호와인 줄 알게 하리라 하시매 무리가 그대로 행하니라',1894),
('exo-14-5','exo','출애굽기',14,5,'그 백성이 도망한 사실이 애굽 왕에게 알려지매 바로와 그의 신하들이 그 백성에 대하여 마음이 변하여 이르되 우리가 어찌 이같이 하여 이스라엘을 우리를 섬김에서 놓아 보내었는가 하고',1895),
('exo-14-6','exo','출애굽기',14,6,'바로가 곧 그의 병거를 갖추고 그의 백성을 데리고 갈새',1896),
