('exo-14-8','exo','출애굽기',14,8,'여호와께서 애굽 왕 바로의 마음을 완악하게 하셨으므로 그가 이스라엘 자손의 뒤를 따르니 이스라엘 자손이 담대히 나갔음이라',1898),
('exo-14-9','exo','출애굽기',14,9,'애굽 사람들과 바로의 말들, 병거들과 그 마병과 그 군대가 그들의 뒤를 따라 바알스본 맞은편 비하히롯 곁 해변 그들이 장막 친 데에 미치니라',1899),
('exo-14-10','exo','출애굽기',14,10,'바로가 가까이 올 때에 이스라엘 자손이 눈을 들어 본즉 애굽 사람들이 자기들 뒤에 이른지라 이스라엘 자손이 심히 두려워하여 여호와께 부르짖고',1900),
