('exo-14-13','exo','출애굽기',14,13,'모세가 백성에게 이르되 너희는 두려워하지 말고 가만히 서서 여호와께서 오늘 너희를 위하여 행하시는 구원을 보라 너희가 오늘 본 애굽 사람을 영원히 다시 보지 아니하리라',1903),
('exo-14-14','exo','출애굽기',14,14,'여호와께서 너희를 위하여 싸우시리니 너희는 가만히 있을지니라',1904),
('exo-14-15','exo','출애굽기',14,15,'여호와께서 모세에게 이르시되 너는 어찌하여 내게 부르짖느냐 이스라엘 자손에게 명령하여 앞으로 나아가게 하고',1905),
('exo-14-16','exo','출애굽기',14,16,'지팡이를 들고 손을 바다 위로 내밀어 그것이 갈라지게 하라 이스라엘 자손이 바다 가운데서 마른 땅으로 행하리라',1906),
('exo-14-17','exo','출애굽기',14,17,'내가 애굽 사람들의 마음을 완악하게 할 것인즉 그들이 그 뒤를 따라 들어갈 것이라 내가 바로와 그의 모든 군대와 그의 병거와 마병으로 말미암아 영광을 얻으리니',1907),
('exo-14-18','exo','출애굽기',14,18,'내가 바로와 그의 병거와 마병으로 말미암아 영광을 얻을 때에야 애굽 사람들이 나를 여호와인 줄 알리라 하시더니',1908),
