('exo-14-20','exo','출애굽기',14,20,'애굽 진과 이스라엘 진 사이에 이르러 서니 저쪽에는 구름과 흑암이 있고 이쪽에는 밤이 밝으므로 밤새도록 저쪽이 이쪽에 가까이 못하였더라',1910),
('exo-14-21','exo','출애굽기',14,21,'모세가 바다 위로 손을 내밀매 여호와께서 큰 동풍이 밤새도록 바닷물을 물러가게 하시니 물이 갈라져 바다가 마른 땅이 된지라',1911),
('exo-14-22','exo','출애굽기',14,22,'이스라엘 자손이 바다 가운데를 육지로 걸어가고 물은 그들의 좌우에 벽이 되니',1912),
('exo-14-23','exo','출애굽기',14,23,'애굽 사람들과 바로의 말들, 병거들과 그 마병들이 다 그들의 뒤를 추격하여 바다 가운데로 들어오는지라',1913),
('exo-14-24','exo','출애굽기',14,24,'새벽에 여호와께서 불과 구름 기둥 가운데서 애굽 군대를 보시고 애굽 군대를 어지럽게 하시며',1914),
