('exo-14-27','exo','출애굽기',14,27,'모세가 곧 손을 바다 위로 내밀매 새벽이 되어 바다의 힘이 회복된지라 애굽 사람들이 물을 거슬러 도망하나 여호와께서 애굽 사람들을 바다 가운데 엎으시니',1917),
