('exo-14-30','exo','출애굽기',14,30,'그 날에 여호와께서 이같이 이스라엘을 애굽 사람의 손에서 구원하시매 이스라엘이 바닷가에서 애굽 사람들이 죽어 있는 것을 보았더라',1920),
('exo-14-31','exo','출애굽기',14,31,'이스라엘이 여호와께서 애굽 사람들에게 행하신 그 큰 능력을 보았으므로 백성이 여호와를 경외하며 여호와와 그의 종 모세를 믿었더라',1921),
('exo-15-1','exo','출애굽기',15,1,'이 때에 모세와 이스라엘 자손이 이 노래로 여호와께 노래하니 일렀으되 내가 여호와를 찬송하리니 그는 높고 영화로우심이요 말과 그 탄 자를 바다에 던지셨음이로다',1922),
('exo-15-2','exo','출애굽기',15,2,'여호와는 나의 힘이요 노래시며 나의 구원이시로다 그는 나의 하나님이시니 내가 그를 찬송할 것이요 내 아버지의 하나님이시니 내가 그를 높이리로다',1923),
