('exo-15-14','exo','출애굽기',15,14,'여러 나라가 듣고 떨며 블레셋 주민이 두려움에 잡히며',1935),
('exo-15-15','exo','출애굽기',15,15,'에돔 두령들이 놀라고 모압 영웅이 떨림에 잡히며 가나안 주민이 다 낙담하나이다',1936),
('exo-15-16','exo','출애굽기',15,16,'놀람과 두려움이 그들에게 임하매 주의 팔이 크므로 그들이 돌 같이 침묵하였사오니 여호와여 주의 백성이 통과하기까지 곧 주께서 사신 백성이 통과하기까지였나이다',1937),
