('exo-15-27','exo','출애굽기',15,27,'그들이 엘림에 이르니 거기에 물 샘 열둘과 종려나무 일흔 그루가 있는지라 거기서 그들이 그 물 곁에 장막을 치니라',1948),
('exo-16-1','exo','출애굽기',16,1,'이스라엘 자손의 온 회중이 엘림에서 떠나 엘림과 시내 산 사이에 있는 신 광야에 이르니 애굽에서 나온 후 둘째 달 십오일이라',1949),
('exo-16-2','exo','출애굽기',16,2,'이스라엘 자손 온 회중이 그 광야에서 모세와 아론을 원망하여',1950),
('exo-16-3','exo','출애굽기',16,3,'이스라엘 자손이 그들에게 이르되 우리가 애굽 땅에서 고기 가마 곁에 앉아 있던 때와 떡을 배불리 먹던 때에 여호와의 손에 죽었더라면 좋았을 것을 너희가 이 광야로 우리를 인도해 내어 이 온 회중이 주려 죽게 하는도다',1951),
('exo-16-4','exo','출애굽기',16,4,'그 때에 여호와께서 모세에게 이르시되 보라 내가 너희를 위하여 하늘에서 양식을 비 같이 내리리니 백성이 나가서 일용할 것을 날마다 거둘 것이라 이같이 하여 그들이 내 율법을 준행하나 아니하나 내가 시험하리라',1952),
('exo-16-5','exo','출애굽기',16,5,'여섯째 날에는 그들이 그 거둔 것을 준비할지니 날마다 거두던 것의 갑절이 되리라',1953),
('exo-16-6','exo','출애굽기',16,6,'모세와 아론이 온 이스라엘 자손에게 이르되 저녁이 되면 너희가 여호와께서 너희를 애굽 땅에서 인도하여 내셨음을 알 것이요',1954),
('exo-16-7','exo','출애굽기',16,7,'아침에는 너희가 여호와의 영광을 보리니 이는 여호와께서 너희가 자기를 향하여 원망함을 들으셨음이라 우리가 누구이기에 너희가 우리에게 대하여 원망하느냐',1955),
('exo-16-8','exo','출애굽기',16,8,'모세가 또 이르되 여호와께서 저녁에는 너희에게 고기를 주어 먹이시고 아침에는 떡으로 배불리시리니 이는 여호와께서 자기를 향하여 너희가 원망하는 그 말을 들으셨음이라 우리가 누구냐 너희의 원망은 우리를 향하여 함이 아니요 여호와를 향하여 함이로다',1956),
('exo-16-9','exo','출애굽기',16,9,'모세가 또 아론에게 이르되 이스라엘 자손의 온 회중에게 말하기를 여호와께 가까이 나아오라 여호와께서 너희의 원망함을 들으셨느니라 하라',1957),
('exo-16-10','exo','출애굽기',16,10,'아론이 이스라엘 자손의 온 회중에게 말하매 그들이 광야를 바라보니 여호와의 영광이 구름 속에 나타나더라',1958),
('exo-16-11','exo','출애굽기',16,11,'여호와께서 모세에게 말씀하여 이르시되',1959),
('exo-16-12','exo','출애굽기',16,12,'내가 이스라엘 자손의 원망함을 들었노라 그들에게 말하여 이르기를 너희가 해 질 때에는 고기를 먹고 아침에는 떡으로 배부르리니 내가 여호와 너희의 하나님인 줄 알리라 하라 하시니라',1960),
('exo-16-13','exo','출애굽기',16,13,'저녁에는 메추라기가 와서 진에 덮이고 아침에는 이슬이 진 주위에 있더니',1961),
('exo-16-14','exo','출애굽기',16,14,'그 이슬이 마른 후에 광야 지면에 작고 둥글며 서리 같이 가는 것이 있는지라',1962),
('exo-16-15','exo','출애굽기',16,15,'이스라엘 자손이 보고 그것이 무엇인지 알지 못하여 서로 이르되 이것이 무엇이냐 하니 모세가 그들에게 이르되 이는 여호와께서 너희에게 주어 먹게 하신 양식이라',1963),
('exo-16-16','exo','출애굽기',16,16,'여호와께서 이같이 명령하시기를 너희 각 사람은 먹을 만큼만 이것을 거둘지니 곧 너희 사람 수효대로 한 사람에 한 오멜씩 거두되 각 사람이 그의 장막에 있는 자들을 위하여 거둘지니라 하셨느니라',1964),
('exo-16-17','exo','출애굽기',16,17,'이스라엘 자손이 그같이 하였더니 그 거둔 것이 많기도 하고 적기도 하나',1965),
('exo-16-18','exo','출애굽기',16,18,'오멜로 되어 본즉 많이 거둔 자도 남음이 없고 적게 거둔 자도 부족함이 없이 각 사람은 먹을 만큼만 거두었더라',1966),
('exo-16-19','exo','출애굽기',16,19,'모세가 그들에게 이르기를 아무든지 아침까지 그것을 남겨두지 말라 하였으나',1967),
('exo-16-20','exo','출애굽기',16,20,'그들이 모세에게 순종하지 아니하고 더러는 아침까지 두었더니 벌레가 생기고 냄새가 난지라 모세가 그들에게 노하니라',1968),
('exo-16-21','exo','출애굽기',16,21,'무리가 아침마다 각 사람은 먹을 만큼만 거두었고 햇볕이 뜨겁게 쬐면 그것이 스러졌더라',1969),
('exo-16-22','exo','출애굽기',16,22,'여섯째 날에는 각 사람이 갑절의 식물 곧 하나에 두 오멜씩 거둔지라 회중의 모든 지도자가 와서 모세에게 알리매',1970),
('exo-16-23','exo','출애굽기',16,23,'모세가 그들에게 이르되 여호와께서 이같이 말씀하셨느니라 내일은 휴일이니 여호와께 거룩한 안식일이라 너희가 구울 것은 굽고 삶을 것은 삶고 그 나머지는 다 너희를 위하여 아침까지 간수하라',1971),
('exo-16-24','exo','출애굽기',16,24,'그들이 모세의 명령대로 아침까지 간수하였으나 냄새도 나지 아니하고 벌레도 생기지 아니한지라',1972),
('exo-16-25','exo','출애굽기',16,25,'모세가 이르되 오늘은 그것을 먹으라 오늘은 여호와의 안식일인즉 오늘은 너희가 들에서 그것을 얻지 못하리라',1973),
('exo-16-26','exo','출애굽기',16,26,'엿새 동안은 너희가 그것을 거두되 일곱째 날은 안식일인즉 그 날에는 없으리라 하였으나',1974),
('exo-16-27','exo','출애굽기',16,27,'일곱째 날에 백성 중 어떤 사람들이 거두러 나갔다가 얻지 못하니라',1975),
('exo-16-28','exo','출애굽기',16,28,'여호와께서 모세에게 이르시되 어느 때까지 너희가 내 계명과 내 율법을 지키지 아니하려느냐',1976),
('exo-16-29','exo','출애굽기',16,29,'볼지어다 여호와가 너희에게 안식일을 줌으로 여섯째 날에는 이틀 양식을 너희에게 주는 것이니 너희는 각기 처소에 있고 일곱째 날에는 아무도 그의 처소에서 나오지 말지니라',1977),
('exo-16-30','exo','출애굽기',16,30,'그러므로 백성이 일곱째 날에 안식하니라',1978),
('exo-16-31','exo','출애굽기',16,31,'이스라엘 족속이 그 이름을 만나라 하였으며 깟씨 같이 희고 맛은 꿀 섞은 과자 같았더라',1979),
('exo-16-32','exo','출애굽기',16,32,'모세가 이르되 여호와께서 이같이 명령하시기를 이것을 오멜에 채워서 너희의 대대 후손을 위하여 간수하라 이는 내가 너희를 애굽 땅에서 인도하여 낼 때에 광야에서 너희에게 먹인 양식을 그들에게 보이기 위함이니라 하셨다 하고',1980),
('exo-16-33','exo','출애굽기',16,33,'또 모세가 아론에게 이르되 항아리를 가져다가 그 속에 만나 한 오멜을 담아 여호와 앞에 두어 너희 대대로 간수하라',1981),
('exo-16-34','exo','출애굽기',16,34,'아론이 여호와께서 모세에게 명령하신 대로 그것을 증거판 앞에 두어 간수하게 하였고',1982),
('exo-16-35','exo','출애굽기',16,35,'사람이 사는 땅에 이르기까지 이스라엘 자손이 사십 년 동안 만나를 먹었으니 곧 가나안 땅 접경에 이르기까지 그들이 만나를 먹었더라',1983),
('exo-16-36','exo','출애굽기',16,36,'오멜은 십분의 일 에바이더라',1984),
('exo-17-1','exo','출애굽기',17,1,'이스라엘 자손의 온 회중이 여호와의 명령대로 신 광야에서 떠나 그 노정대로 행하여 르비딤에 장막을 쳤으나 백성이 마실 물이 없는지라',1985),
('exo-17-2','exo','출애굽기',17,2,'백성이 모세와 다투어 이르되 우리에게 물을 주어 마시게 하라 모세가 그들에게 이르되 너희가 어찌하여 나와 다투느냐 너희가 어찌하여 여호와를 시험하느냐',1986),
('exo-17-3','exo','출애굽기',17,3,'거기서 백성이 목이 말라 물을 찾으매 그들이 모세에게 대하여 원망하여 이르되 당신이 어찌하여 우리를 애굽에서 인도해 내어서 우리와 우리 자녀와 우리 가축이 목말라 죽게 하느냐',1987),
('exo-17-4','exo','출애굽기',17,4,'모세가 여호와께 부르짖어 이르되 내가 이 백성에게 어떻게 하리이까 그들이 조금 있으면 내게 돌을 던지겠나이다',1988),
('exo-17-5','exo','출애굽기',17,5,'여호와께서 모세에게 이르시되 백성 앞을 지나서 이스라엘 장로들을 데리고 나일 강을 치던 네 지팡이를 손에 잡고 가라',1989),
('exo-17-6','exo','출애굽기',17,6,'내가 호렙 산에 있는 그 반석 위 거기서 네 앞에 서리니 너는 그 반석을 치라 그것에서 물이 나오리니 백성이 마시리라 모세가 이스라엘 장로들의 목전에서 그대로 행하니라',1990),
('exo-17-7','exo','출애굽기',17,7,'그가 그 곳 이름을 맛사 또는 므리바라 불렀으니 이는 이스라엘 자손이 다투었음이요 또는 그들이 여호와를 시험하여 이르기를 여호와께서 우리 중에 계신가 안 계신가 하였음이더라',1991),
('exo-17-8','exo','출애굽기',17,8,'그 때에 아말렉이 와서 이스라엘과 르비딤에서 싸우니라',1992),
('exo-17-9','exo','출애굽기',17,9,'모세가 여호수아에게 이르되 우리를 위하여 사람들을 택하여 나가서 아말렉과 싸우라 내일 내가 하나님의 지팡이를 손에 잡고 산 꼭대기에 서리라',1993),
('exo-17-10','exo','출애굽기',17,10,'여호수아가 모세의 말대로 행하여 아말렉과 싸우고 모세와 아론과 훌은 산 꼭대기에 올라가서',1994),
('exo-17-11','exo','출애굽기',17,11,'모세가 손을 들면 이스라엘이 이기고 손을 내리면 아말렉이 이기더니',1995),
('exo-17-12','exo','출애굽기',17,12,'모세의 팔이 피곤하매 그들이 돌을 가져다가 모세의 아래에 놓아 그가 그 위에 앉게 하고 아론과 훌이 한 사람은 이쪽에서, 한 사람은 저쪽에서 모세의 손을 붙들어 올렸더니 그 손이 해가 지도록 내려오지 아니한지라',1996),
('exo-17-13','exo','출애굽기',17,13,'여호수아가 칼날로 아말렉과 그 백성을 쳐서 무찌르니라',1997),
('exo-17-14','exo','출애굽기',17,14,'여호와께서 모세에게 이르시되 이것을 책에 기록하여 기념하게 하고 여호수아의 귀에 외워 들리라 내가 아말렉을 없이하여 천하에서 기억도 못 하게 하리라',1998),
('exo-17-15','exo','출애굽기',17,15,'모세가 제단을 쌓고 그 이름을 여호와 닛시라 하고',1999),
('exo-17-16','exo','출애굽기',17,16,'이르되 여호와께서 맹세하시기를 여호와가 아말렉과 더불어 대대로 싸우리라 하셨다 하였더라',2000),
('exo-18-1','exo','출애굽기',18,1,'모세의 장인이며 미디안 제사장인 이드로가 하나님이 모세에게와 자기 백성 이스라엘에게 하신 일 곧 여호와께서 이스라엘을 애굽에서 인도하여 내신 모든 일을 들으니라',2001),
('exo-18-2','exo','출애굽기',18,2,'모세의 장인 이드로가 모세가 돌려 보냈던 그의 아내 십보라와',2002),
('exo-18-3','exo','출애굽기',18,3,'그의 두 아들을 데리고 왔으니 그 하나의 이름은 게르솜이라 이는 모세가 이르기를 내가 이방에서 나그네가 되었다 함이요',2003),
('exo-18-4','exo','출애굽기',18,4,'하나의 이름은 엘리에셀이라 이는 내 아버지의 하나님이 나를 도우사 바로의 칼에서 구원하셨다 함이더라',2004),
('exo-18-5','exo','출애굽기',18,5,'모세의 장인 이드로가 모세의 아들들과 그의 아내와 더불어 광야에 들어와 모세에게 이르니 곧 모세가 하나님의 산에 진 친 곳이라',2005),
('exo-18-6','exo','출애굽기',18,6,'그가 모세에게 말을 전하되 네 장인 나 이드로가 네 아내와 그와 함께 한 그의 두 아들과 더불어 네게 왔노라',2006),
('exo-18-7','exo','출애굽기',18,7,'모세가 나가서 그의 장인을 맞아 절하고 그에게 입 맞추고 그들이 서로 문안하고 함께 장막에 들어가서',2007),
('exo-18-8','exo','출애굽기',18,8,'모세가 여호와께서 이스라엘을 위하여 바로와 애굽 사람에게 행하신 모든 일과 길에서 그들이 당한 모든 고난과 여호와께서 그들을 구원하신 일을 다 그 장인에게 말하매',2008),
('exo-18-9','exo','출애굽기',18,9,'이드로가 여호와께서 이스라엘에게 큰 은혜를 베푸사 애굽 사람의 손에서 구원하심을 기뻐하여',2009),
