('exo-32-14','exo','출애굽기',32,14,'여호와께서 뜻을 돌이키사 말씀하신 화를 그 백성에게 내리지 아니하시니라',2453),
('exo-32-15','exo','출애굽기',32,15,'모세가 돌이켜 산에서 내려오는데 두 증거판이 그의 손에 있고 그 판의 양면 이쪽 저쪽에 글자가 있으니',2454),
