('lev-4-7','lev','레위기',4,7,'제사장은 또 그 피를 여호와 앞 곧 회막 안 향단 뿔들에 바르고 그 송아지의 피 전부를 회막 문 앞 번제단 밑에 쏟을 것이며',2803),
('lev-4-8','lev','레위기',4,8,'또 그 속죄제물이 된 수송아지의 모든 기름을 떼어낼지니 곧 내장에 덮인 기름과 내장에 붙은 모든 기름과',2804),
('lev-4-9','lev','레위기',4,9,'두 콩팥과 그 위의 기름 곧 허리쪽에 있는 것과 간에 덮인 꺼풀을 콩팥과 함께 떼어내되',2805),
('lev-4-10','lev','레위기',4,10,'화목제 제물의 소에게서 떼어냄 같이 할 것이요 제사장은 그것을 번제단 위에서 불사를 것이며',2806),
('lev-4-11','lev','레위기',4,11,'그 수송아지의 가죽과 그 모든 고기와 그것의 머리와 정강이와 내장과',2807),
('lev-4-12','lev','레위기',4,12,'똥 곧 그 송아지의 전체를 진영 바깥 재 버리는 곳인 정결한 곳으로 가져다가 불로 나무 위에서 사르되 곧 재 버리는 곳에서 불사를지니라',2808),
('lev-4-13','lev','레위기',4,13,'만일 이스라엘 온 회중이 여호와의 계명 중 하나라도 부지중에 범하여 허물이 있으나 스스로 깨닫지 못하다가',2809),
('lev-4-14','lev','레위기',4,14,'그 범한 죄를 깨달으면 회중은 수송아지를 속죄제로 드릴지니 그것을 회막 앞으로 끌어다가',2810),
('lev-4-15','lev','레위기',4,15,'회중의 장로들이 여호와 앞에서 그 수송아지 머리에 안수하고 그것을 여호와 앞에서 잡을 것이요',2811),
('lev-4-16','lev','레위기',4,16,'기름 부음을 받은 제사장은 그 수송아지의 피를 가지고 회막에 들어가서',2812),
('lev-4-17','lev','레위기',4,17,'그 제사장이 손가락으로 그 피를 찍어 여호와 앞, 휘장 앞에 일곱 번 뿌릴 것이며',2813),
('lev-4-18','lev','레위기',4,18,'또 그 피로 회막 안 여호와 앞에 있는 제단 뿔들에 바르고 그 피 전부는 회막 문 앞 번제단 밑에 쏟을 것이며',2814),
('lev-4-19','lev','레위기',4,19,'그것의 기름은 다 떼어 제단 위에서 불사르되',2815),
('lev-4-20','lev','레위기',4,20,'그 송아지를 속죄제의 수송아지에게 한 것 같이 할지며 제사장이 그것으로 회중을 위하여 속죄한즉 그들이 사함을 받으리라',2816),
('lev-4-21','lev','레위기',4,21,'그는 그 수송아지를 진영 밖으로 가져다가 첫번 수송아지를 사름 같이 불사를지니 이는 회중의 속죄제니라',2817),
('lev-4-22','lev','레위기',4,22,'만일 족장이 그의 하나님 여호와의 계명 중 하나라도 부지중에 범하여 허물이 있었는데',2818),
('lev-4-23','lev','레위기',4,23,'그가 범한 죄를 누가 그에게 깨우쳐 주면 그는 흠 없는 숫염소를 예물로 가져다가',2819),
('lev-4-24','lev','레위기',4,24,'그 숫염소의 머리에 안수하고 여호와 앞 번제물을 잡는 곳에서 잡을지니 이는 속죄제라',2820),
('lev-4-25','lev','레위기',4,25,'제사장은 그 속죄 제물의 피를 손가락에 찍어 번제단 뿔들에 바르고 그 피는 번제단 밑에 쏟고',2821),
('lev-4-26','lev','레위기',4,26,'그 모든 기름은 화목제 제물의 기름 같이 제단 위에서 불사를지니 이같이 제사장이 그 범한 죄에 대하여 그를 위하여 속죄한즉 그가 사함을 얻으리라',2822),
('lev-4-27','lev','레위기',4,27,'만일 평민의 한 사람이 여호와의 계명 중 하나라도 부지중에 범하여 허물이 있었는데',2823),
('lev-4-28','lev','레위기',4,28,'그가 범한 죄를 누가 그에게 깨우쳐 주면 그는 흠 없는 암염소를 끌고 와서 그 범한 죄로 말미암아 그것을 예물로 삼아',2824),
('lev-4-29','lev','레위기',4,29,'그 속죄제물의 머리에 안수하고 그 제물을 번제물을 잡는 곳에서 잡을 것이요',2825),
('lev-4-30','lev','레위기',4,30,'제사장은 손가락으로 그 피를 찍어 번제단 뿔들에 바르고 그 피 전부를 제단 밑에 쏟고',2826),
('lev-4-31','lev','레위기',4,31,'그 모든 기름을 화목제물의 기름을 떼어낸 것 같이 떼어내 제단 위에서 불살라 여호와께 향기롭게 할지니 제사장이 그를 위하여 속죄한즉 그가 사함을 받으리라',2827),
('lev-4-32','lev','레위기',4,32,'그가 만일 어린 양을 속죄제물로 가져오려거든 흠 없는 암컷을 끌어다가',2828),
('lev-4-33','lev','레위기',4,33,'그 속죄제 제물의 머리에 안수하고 번제물을 잡는 곳에서 속죄제물로 잡을 것이요',2829),
('lev-4-34','lev','레위기',4,34,'제사장은 그 속죄제물의 피를 손가락으로 찍어 번제단 뿔들에 바르고 그 피는 전부 제단 밑에 쏟고',2830),
('lev-4-35','lev','레위기',4,35,'그 모든 기름을 화목제 어린 양의 기름을 떼낸 것 같이 떼내어 제단 위 여호와의 화제물 위에서 불사를지니 이같이 제사장이 그가 범한 죄에 대하여 그를 위하여 속죄한즉 그가 사함을 받으리라',2831),
('lev-5-1','lev','레위기',5,1,'만일 누구든지 저주하는 소리를 듣고서도 증인이 되어 그가 본 것이나 알고 있는 것을 알리지 아니하면 그는 자기의 죄를 져야 할 것이요 그 허물이 그에게로 돌아갈 것이며',2832),
('lev-5-2','lev','레위기',5,2,'만일 누구든지 부정한 것들 곧 들짐승의 사체나 부정한 가축의 사체나 부정한 곤충의 사체를 만졌으면 부지중이라고 할지라도 그 몸이 더러워져서 허물이 있을 것이요',2833),
('lev-5-3','lev','레위기',5,3,'만일 부지중에 어떤 사람의 부정에 닿았는데 그 사람의 부정이 어떠한 부정이든지 그것을 깨달았을 때에는 허물이 있을 것이요',2834),
('lev-5-4','lev','레위기',5,4,'만일 누구든지 입술로 맹세하여 악한 일이든지 선한 일이든지 하리라고 함부로 말하면 그 사람이 함부로 말하여 맹세한 것이 무엇이든지 그가 깨닫지 못하다가 그것을 깨닫게 되었을 때에는 그 중 하나에 그에게 허물이 있을 것이니',2835),
('lev-5-5','lev','레위기',5,5,'이 중 하나에 허물이 있을 때에는 아무 일에 잘못하였노라 자복하고',2836),
('lev-5-6','lev','레위기',5,6,'그 잘못으로 말미암아 여호와께 속죄제를 드리되 양 떼의 암컷 어린 양이나 염소를 끌어다가 속죄제를 드릴 것이요 제사장은 그의 허물을 위하여 속죄할지니라',2837),
('lev-5-7','lev','레위기',5,7,'만일 그의 힘이 어린 양을 바치는 데에 미치지 못하면 그가 지은 죄를 속죄하기 위하여 산비둘기 두 마리나 집비둘기 새끼 두 마리를 여호와께로 가져가되 하나는 속죄제물을 삼고 하나는 번제물을 삼아',2838),
('lev-5-8','lev','레위기',5,8,'제사장에게로 가져갈 것이요 제사장은 그 속죄제물을 먼저 드리되 그 머리를 목에서 비틀어 끊고 몸은 아주 쪼개지 말며',2839),
('lev-5-9','lev','레위기',5,9,'그 속죄제물의 피를 제단 곁에 뿌리고 그 남은 피는 제단 밑에 흘릴지니 이는 속죄제요',2840),
('lev-5-10','lev','레위기',5,10,'그 다음 것은 규례대로 번제를 드릴지니 제사장이 그의 잘못을 위하여 속죄한즉 그가 사함을 받으리라',2841),
('lev-5-11','lev','레위기',5,11,'만일 그의 손이 산비둘기 두 마리나 집비둘기 두 마리에도 미치지 못하면 그의 범죄로 말미암아 고운 가루 십분의 일 에바를 예물로 가져다가 속죄제물로 드리되 이는 속죄제인즉 그 위에 기름을 붓지 말며 유향을 놓지 말고',2842),
('lev-5-12','lev','레위기',5,12,'그것을 제사장에게로 가져갈 것이요 제사장은 그것을 기념물로 한 움큼을 가져다가 제단 위 여호와의 화제물 위에서 불사를지니 이는 속죄제라',2843),
('lev-5-13','lev','레위기',5,13,'제사장이 그가 이 중에서 하나를 범하여 얻은 허물을 위하여 속죄한즉 그가 사함을 받으리라 그 나머지는 소제물 같이 제사장에게 돌릴지니라',2844),
('lev-5-14','lev','레위기',5,14,'여호와께서 모세에게 말씀하여 이르시되',2845),
('lev-5-15','lev','레위기',5,15,'누구든지 여호와의 성물에 대하여 부지중에 범죄하였으면 여호와께 속건제를 드리되 네가 지정한 가치를 따라 성소의 세겔로 몇 세겔 은에 상당한 흠 없는 숫양을 양 떼 중에서 끌어다가 속건제로 드려서',2846),
('lev-5-16','lev','레위기',5,16,'성물에 대한 잘못을 보상하되 그것에 오분의 일을 더하여 제사장에게 줄 것이요 제사장은 그 속건제의 숫양으로 그를 위하여 속죄한즉 그가 사함을 받으리라',2847),
('lev-5-17','lev','레위기',5,17,'만일 누구든지 여호와의 계명 중 하나를 부지중에 범하여도 허물이라 벌을 당할 것이니',2848),
('lev-5-18','lev','레위기',5,18,'그는 네가 지정한 가치대로 양 떼 중 흠 없는 숫양을 속건제물로 제사장에게로 가져갈 것이요 제사장은 그가 부지중에 범죄한 허물을 위하여 속죄한즉 그가 사함을 받으리라',2849),
('lev-5-19','lev','레위기',5,19,'이는 속건제니 그가 여호와 앞에 참으로 잘못을 저질렀음이니라',2850),
('lev-6-1','lev','레위기',6,1,'여호와께서 모세에게 말씀하여 이르시되',2851),
('lev-6-2','lev','레위기',6,2,'누구든지 여호와께 신실하지 못하여 범죄하되 곧 이웃이 맡긴 물건이나 전당물을 속이거나 도둑질하거나 착취하고도 사실을 부인하거나',2852),
('lev-6-3','lev','레위기',6,3,'남의 잃은 물건을 줍고도 사실을 부인하여 거짓 맹세하는 등 사람이 이 모든 일 중의 하나라도 행하여 범죄하면',2853),
('lev-6-4','lev','레위기',6,4,'이는 죄를 범하였고 죄가 있는 자니 그 훔친 것이나 착취한 것이나 맡은 것이나 잃은 물건을 주운 것이나',2854),
('lev-6-5','lev','레위기',6,5,'그 거짓 맹세한 모든 물건을 돌려보내되 곧 그 본래 물건에 오분의 일을 더하여 돌려보낼 것이니 그 죄가 드러나는 날에 그 임자에게 줄 것이요',2855),
('lev-6-6','lev','레위기',6,6,'그는 또 그 속건제물을 여호와께 가져갈지니 곧 네가 지정한 가치대로 양 떼 중 흠 없는 숫양을 속건제물을 위하여 제사장에게로 끌고 갈 것이요',2856),
('lev-6-7','lev','레위기',6,7,'제사장은 여호와 앞에서 그를 위하여 속죄한즉 그는 무슨 허물이든지 사함을 받으리라',2857),
('lev-6-8','lev','레위기',6,8,'여호와께서 모세에게 말씀하여 이르시되',2858),
('lev-6-9','lev','레위기',6,9,'아론과 그의 자손에게 명령하여 이르라 번제의 규례는 이러하니라 번제물은 아침까지 제단 위에 있는 석쇠 위에 두고 제단의 불이 그 위에서 꺼지지 않게 할 것이요',2859),
('lev-6-10','lev','레위기',6,10,'제사장은 세마포 긴 옷을 입고 세마포 속바지로 하체를 가리고 제단 위에서 불태운 번제의 재를 가져다가 제단 곁에 두고',2860),
('lev-6-11','lev','레위기',6,11,'그 옷을 벗고 다른 옷을 입고 그 재를 진영 바깥 정결한 곳으로 가져갈 것이요',2861),
('lev-6-12','lev','레위기',6,12,'제단 위의 불은 항상 피워 꺼지지 않게 할지니 제사장은 아침마다 나무를 그 위에서 태우고 번제물을 그 위에 벌여 놓고 화목제의 기름을 그 위에서 불사를지며',2862),
('lev-6-13','lev','레위기',6,13,'불은 끊임이 없이 제단 위에 피워 꺼지지 않게 할지니라',2863),
('lev-6-14','lev','레위기',6,14,'소제의 규례는 이러하니라 아론의 자손은 그것을 제단 앞 여호와 앞에 드리되',2864),
('lev-6-15','lev','레위기',6,15,'그 소제의 고운 기름 가루 한 움큼과 소제물 위의 유향을 다 가져다가 기념물로 제단 위에서 불살라 여호와 앞에 향기로운 냄새가 되게 하고',2865),
('lev-6-16','lev','레위기',6,16,'그 나머지는 아론과 그의 자손이 먹되 누룩을 넣지 말고 거룩한 곳 회막 뜰에서 먹을지니라',2866),
('lev-6-17','lev','레위기',6,17,'그것에 누룩을 넣어 굽지 말라 이는 나의 화제물 중에서 내가 그들에게 주어 그들의 소득이 되게 하는 것이라 속죄제와 속건제 같이 지극히 거룩한즉',2867),
('lev-6-18','lev','레위기',6,18,'아론 자손의 남자는 모두 이를 먹을지니 이는 여호와의 화제물 중에서 대대로 그들의 영원한 소득이 됨이라 이를 만지는 자마다 거룩하리라',2868),
('lev-6-19','lev','레위기',6,19,'여호와께서 모세에게 말씀하여 이르시되',2869),
('lev-6-20','lev','레위기',6,20,'아론과 그의 자손이 기름 부음을 받는 날에 여호와께 드릴 예물은 이러하니라 고운 가루 십분의 일 에바를 항상 드리는 소제물로 삼아 그 절반은 아침에, 절반은 저녁에 드리되',2870),
('lev-6-21','lev','레위기',6,21,'그것을 기름으로 반죽하여 철판에 굽고 기름에 적셔 썰어서 소제로 여호와께 드려 향기로운 냄새가 되게 하라',2871),
('lev-6-22','lev','레위기',6,22,'이 소제는 아론의 자손 중 기름 부음을 받고 그를 이어 제사장 된 자가 드릴 것이요 영원한 규례로 여호와께 온전히 불사를 것이니',2872),
('lev-6-23','lev','레위기',6,23,'제사장의 모든 소제물은 온전히 불사르고 먹지 말지니라',2873),
('lev-6-24','lev','레위기',6,24,'여호와께서 모세에게 말씀하여 이르시되',2874),
('lev-6-25','lev','레위기',6,25,'아론과 그의 아들들에게 말하여 이르라 속죄제의 규례는 이러하니라 속죄제 제물은 지극히 거룩하니 여호와 앞 번제물을 잡는 곳에서 그 속죄제 제물을 잡을 것이요',2875),
('lev-6-26','lev','레위기',6,26,'죄를 위하여 제사 드리는 제사장이 그것을 먹되 곧 회막 뜰 거룩한 곳에서 먹을 것이며',2876),
('lev-6-27','lev','레위기',6,27,'그 고기에 접촉하는 모든 자는 거룩할 것이며 그 피가 어떤 옷에든지 묻었으면 묻은 그것을 거룩한 곳에서 빨 것이요',2877),
('lev-6-28','lev','레위기',6,28,'그 고기를 토기에 삶았으면 그 그릇을 깨뜨릴 것이요 유기에 삶았으면 그 그릇을 닦고 물에 씻을 것이며',2878),
('lev-6-29','lev','레위기',6,29,'제사장인 남자는 모두 그것을 먹을지니 그것은 지극히 거룩하니라',2879),
('lev-6-30','lev','레위기',6,30,'그러나 피를 가지고 회막에 들어가 성소에서 속죄하게 한 속죄제 제물의 고기는 먹지 못할지니 불사를지니라',2880),
('lev-7-1','lev','레위기',7,1,'속건제의 규례는 이러하니라 이는 지극히 거룩하니',2881),
('lev-7-2','lev','레위기',7,2,'번제물을 잡는 곳에서 속건제의 번제물을 잡을 것이요 제사장은 그 피를 제단 사방에 뿌릴 것이며',2882),
('lev-7-3','lev','레위기',7,3,'그 기름을 모두 드리되 곧 그 기름진 꼬리와 내장에 덮인 기름과',2883),
('lev-7-4','lev','레위기',7,4,'두 콩팥과 그 위의 기름 곧 허리 쪽에 있는 것과 간에 덮인 꺼풀을 콩팥과 함께 떼어내고',2884),
('lev-7-5','lev','레위기',7,5,'제사장은 그것을 다 제단 위에서 불살라 여호와께 화제로 드릴 것이니 이는 속건제니라',2885),
('lev-7-6','lev','레위기',7,6,'제사장인 남자는 모두 그것을 먹되 거룩한 곳에서 먹을지니라 그것은 지극히 거룩하니라',2886),
('lev-7-7','lev','레위기',7,7,'속죄제와 속건제는 규례가 같으니 그 제물은 속죄하는 제사장에게로 돌아갈 것이요',2887),
('lev-7-8','lev','레위기',7,8,'사람을 위하여 번제를 드리는 제사장 곧 그 제사장은 그 드린 번제물의 가죽을 자기가 가질 것이며',2888),
('lev-7-9','lev','레위기',7,9,'화덕에 구운 소제물과 냄비에나 철판에서 만든 소제물은 모두 그 드린 제사장에게로 돌아갈 것이니',2889),
('lev-7-10','lev','레위기',7,10,'소제물은 기름 섞은 것이나 마른 것이나 모두 아론의 모든 자손이 균등하게 분배할 것이니라',2890),
('lev-7-11','lev','레위기',7,11,'여호와께 드릴 화목제물의 규례는 이러하니라',2891),
('lev-7-12','lev','레위기',7,12,'만일 그것을 감사함으로 드리려면 기름 섞은 무교병과 기름 바른 무교전병과 고운 가루에 기름 섞어 구운 과자를 그 감사제물과 함께 드리고',2892),
('lev-7-13','lev','레위기',7,13,'또 유교병을 화목제의 감사제물과 함께 그 예물로 드리되',2893),
('lev-7-14','lev','레위기',7,14,'그 전체의 예물 중에서 하나씩 여호와께 거제로 드리고 그것을 화목제의 피를 뿌린 제사장들에게로 돌릴지니라',2894),
('lev-7-15','lev','레위기',7,15,'감사함으로 드리는 화목제물의 고기는 드리는 그 날에 먹을 것이요 조금이라도 이튿날 아침까지 두지 말 것이니라',2895),
('lev-7-16','lev','레위기',7,16,'그러나 그의 예물의 제물이 서원이나 자원하는 것이면 그 제물을 드린 날에 먹을 것이요 그 남은 것은 이튿날에도 먹되',2896),
('lev-7-17','lev','레위기',7,17,'그 제물의 고기가 셋째 날까지 남았으면 불사를지니',2897),
('lev-7-18','lev','레위기',7,18,'만일 그 화목제물의 고기를 셋째 날에 조금이라도 먹으면 그 제사는 기쁘게 받아들여지지 않을 것이라 드린 자에게도 예물답게 되지 못하고 도리어 가증한 것이 될 것이며 그것을 먹는 자는 그 죄를 짊어지리라',2898),
('lev-7-19','lev','레위기',7,19,'그 고기가 부정한 물건에 접촉되었으면 먹지 말고 불사를 것이라 그 고기는 깨끗한 자만 먹을 것이니',2899),
('lev-7-20','lev','레위기',7,20,'만일 몸이 부정한 자가 여호와께 속한 화목제물의 고기를 먹으면 그 사람은 자기 백성 중에서 끊어질 것이요',2900),
('lev-7-21','lev','레위기',7,21,'만일 누구든지 부정한 것 곧 사람의 부정이나 부정한 짐승이나 부정하고 가증한 무슨 물건을 만지고 여호와께 속한 화목제물의 고기를 먹으면 그 사람도 자기 백성 중에서 끊어지리라',2901),
('lev-7-22','lev','레위기',7,22,'여호와께서 모세에게 말씀하여 이르시되',2902),
('lev-7-23','lev','레위기',7,23,'이스라엘 자손에게 말하여 이르라 너희는 소나 양이나 염소의 기름을 먹지 말 것이요',2903),
('lev-7-24','lev','레위기',7,24,'스스로 죽은 것의 기름이나 짐승에게 찢긴 것의 기름은 다른 데는 쓰려니와 결단코 먹지는 말지니라',2904),
('lev-7-25','lev','레위기',7,25,'사람이 여호와께 화제로 드리는 제물의 기름을 먹으면 그 먹는 자는 자기 백성 중에서 끊어지리라',2905),
('lev-7-26','lev','레위기',7,26,'너희가 사는 모든 곳에서 새나 짐승의 피나 무슨 피든지 먹지 말라',2906),
('lev-7-27','lev','레위기',7,27,'무슨 피든지 먹는 사람이 있으면 그 사람은 다 자기 백성 중에서 끊어지리라',2907),
('lev-7-28','lev','레위기',7,28,'여호와께서 모세에게 말씀하여 이르시되',2908),
('lev-7-29','lev','레위기',7,29,'이스라엘 자손에게 말하여 이르라 화목제물을 여호와께 드리려는 자는 그 화목제물 중에서 그의 예물을 여호와께 가져오되',2909),
('lev-7-30','lev','레위기',7,30,'여호와의 화제물은 그 사람이 자기 손으로 가져올지니 곧 그 제물의 기름과 가슴을 가져올 것이요 제사장은 그 가슴을 여호와 앞에 흔들어 요제를 삼고',2910),
('lev-7-31','lev','레위기',7,31,'그 기름은 제단 위에서 불사를 것이며 가슴은 아론과 그의 자손에게 돌릴 것이며',2911),
('lev-7-32','lev','레위기',7,32,'또 너희는 그 화목제물의 오른쪽 뒷다리를 제사장에게 주어 거제를 삼을지니',2912),
('lev-7-33','lev','레위기',7,33,'아론의 자손 중에서 화목제물의 피와 기름을 드리는 자는 그 오른쪽 뒷다리를 자기의 소득으로 삼을 것이니라',2913),
('lev-7-34','lev','레위기',7,34,'내가 이스라엘 자손의 화목제물 중에서 그 흔든 가슴과 든 뒷다리를 가져다가 제사장 아론과 그의 자손에게 주었나니 이는 이스라엘 자손에게서 받을 영원한 소득이니라',2914),
('lev-7-35','lev','레위기',7,35,'이는 여호와의 화제물 중에서 아론에게 돌릴 것과 그의 아들들에게 돌릴 것이니 그들을 세워 여호와의 제사장의 직분을 행하게 한 날',2915),
('lev-7-36','lev','레위기',7,36,'곧 그들에게 기름 부은 날에 여호와께서 명령하사 이스라엘 자손 중에서 그들에게 돌리게 하신 것이라 대대로 영원히 받을 소득이니라',2916),
('lev-7-37','lev','레위기',7,37,'이는 번제와 소제와 속죄제와 속건제와 위임식과 화목제의 규례라',2917),
('lev-7-38','lev','레위기',7,38,'여호와께서 시내 광야에서 이스라엘 자손에게 그 예물을 여호와께 드리라 명령하신 날에 시내 산에서 이같이 모세에게 명령하셨더라',2918),
