('lev-8-4','lev','레위기',8,4,'모세가 여호와께서 자기에게 명령하신 대로 하매 회중이 회막 문에 모인지라',2922),
('lev-8-5','lev','레위기',8,5,'모세가 회중에게 이르되 여호와께서 행하라고 명령하신 것이 이러하니라 하고',2923),
('lev-8-6','lev','레위기',8,6,'모세가 아론과 그의 아들들을 데려다가 물로 그들을 씻기고',2924),
