('lev-8-8','lev','레위기',8,8,'흉패를 붙이고 흉패에 우림과 둠밈을 넣고',2926),
('lev-8-9','lev','레위기',8,9,'그의 머리에 관을 씌우고 그 관 위 전면에 금 패를 붙이니 곧 거룩한 관이라 여호와께서 모세에게 명령하신 것과 같았더라',2927),
('lev-8-10','lev','레위기',8,10,'모세가 관유를 가져다가 성막과 그 안에 있는 모든 것에 발라 거룩하게 하고',2928),
('lev-8-11','lev','레위기',8,11,'또 제단에 일곱 번 뿌리고 또 그 제단과 그 모든 기구와 물두멍과 그 받침에 발라 거룩하게 하고',2929),
('lev-8-12','lev','레위기',8,12,'또 관유를 아론의 머리에 붓고 그에게 발라 거룩하게 하고',2930),
('lev-8-13','lev','레위기',8,13,'모세가 또 아론의 아들들을 데려다가 그들에게 속옷을 입히고 띠를 띠우며 관을 씌웠으니 여호와께서 모세에게 명령하신 것과 같았더라',2931),
('lev-8-14','lev','레위기',8,14,'모세가 또 속죄제의 수송아지를 끌어오니 아론과 그의 아들들이 그 속죄제의 수송아지 머리에 안수하매',2932),
