('lev-8-16','lev','레위기',8,16,'또 내장에 덮인 모든 기름과 간 꺼풀과 두 콩팥과 그 기름을 가져다가 모세가 제단 위에 불사르고',2934),
('lev-8-17','lev','레위기',8,17,'그 수송아지 곧 그 가죽과 고기와 똥은 진영 밖에서 불살랐으니 여호와께서 모세에게 명령하심과 같았더라',2935),
('lev-8-18','lev','레위기',8,18,'또 번제의 숫양을 드릴새 아론과 그의 아들들이 그 숫양의 머리에 안수하매',2936),
('lev-8-19','lev','레위기',8,19,'모세가 잡아 그 피를 제단 사방에 뿌리고',2937),
