('lev-8-21','lev','레위기',8,21,'물로 내장과 정강이들을 씻고 모세가 그 숫양의 전부를 제단 위에서 불사르니 이는 향기로운 냄새를 위하여 드리는 번제로 여호와께 드리는 화제라 여호와께서 모세에게 명령하심과 같았더라',2939),
('lev-8-22','lev','레위기',8,22,'또 다른 숫양 곧 위임식의 숫양을 드릴새 아론과 그의 아들들이 그 숫양의 머리에 안수하매',2940),
('lev-8-23','lev','레위기',8,23,'모세가 잡고 그 피를 가져다가 아론의 오른쪽 귓부리와 그의 오른쪽 엄지 손가락과 그의 오른쪽 엄지 발가락에 바르고',2941),
('lev-8-24','lev','레위기',8,24,'아론의 아들들을 데려다가 모세가 그 오른쪽 귓부리와 그들의 손의 오른쪽 엄지 손가락과 그들의 발의 오른쪽 엄지 발가락에 그 피를 바르고 또 모세가 그 피를 제단 사방에 뿌리고',2942),
('lev-8-25','lev','레위기',8,25,'그가 또 그 기름과 기름진 꼬리와 내장에 덮인 모든 기름과 간 꺼풀과 두 콩팥과 그 기름과 오른쪽 뒷다리를 떼어내고',2943),
('lev-8-26','lev','레위기',8,26,'여호와 앞 무교병 광주리에서 무교병 한 개와 기름 섞은 떡 한 개와 전병 한 개를 가져다가 그 기름 위에와 오른쪽 뒷다리 위에 놓아',2944),
('lev-8-27','lev','레위기',8,27,'그 전부를 아론의 손과 그의 아들들의 손에 두어 여호와 앞에 흔들어 요제를 삼게 하고',2945),
('lev-8-28','lev','레위기',8,28,'모세가 그것을 그들의 손에서 가져다가 제단 위에 있는 번제물 위에 불사르니 이는 향기로운 냄새를 위하여 드리는 위임식 제사로 여호와께 드리는 화제라',2946),
('lev-8-29','lev','레위기',8,29,'이에 모세가 그 가슴을 가져다가 여호와 앞에 흔들어 요제를 삼았으니 이는 위임식에서 잡은 숫양 중 모세의 몫이라 여호와께서 모세에게 명령하심과 같았더라',2947),
('lev-8-30','lev','레위기',8,30,'모세가 관유와 제단 위의 피를 가져다가 아론과 그의 옷과 그의 아들들과 그의 아들들의 옷에 뿌려서 아론과 그의 옷과 그의 아들들과 그의 아들들의 옷을 거룩하게 하고',2948),
('lev-8-31','lev','레위기',8,31,'모세가 아론과 그의 아들들에게 이르되 내게 이미 명령하시기를 아론과 그의 아들들은 먹으라 하셨은즉 너희는 회막 문에서 그 고기를 삶아 위임식 광주리 안의 떡과 아울러 그 곳에서 먹고',2949),
('lev-8-32','lev','레위기',8,32,'고기와 떡의 나머지는 불사를지며',2950),
('lev-8-33','lev','레위기',8,33,'위임식은 이레 동안 행하나니 위임식이 끝나는 날까지 이레 동안은 회막 문에 나가지 말라',2951),
('lev-8-34','lev','레위기',8,34,'오늘 행한 것은 여호와께서 너희를 위하여 속죄하게 하시려고 명령하신 것이니',2952),
('lev-8-35','lev','레위기',8,35,'너희는 칠 주야를 회막 문에 머물면서 여호와께서 지키라고 하신 것을 지키라 그리하면 사망을 면하리라 내가 이같이 명령을 받았느니라',2953),
('lev-8-36','lev','레위기',8,36,'아론과 그의 아들들이 여호와께서 모세를 통하여 명령하신 모든 일을 준행하니라',2954),
('lev-9-1','lev','레위기',9,1,'여덟째 날에 모세가 아론과 그의 아들들과 이스라엘 장로들을 불러다가',2955),
('lev-9-2','lev','레위기',9,2,'아론에게 이르되 속죄제를 위하여 흠 없는 송아지를 가져오고 번제를 위하여 흠 없는 숫양을 여호와 앞에 가져다 드리고',2956),
('lev-9-3','lev','레위기',9,3,'이스라엘 자손에게 말하여 이르기를 너희는 속죄제를 위하여 숫염소를 가져오고 또 번제를 위하여 일 년 되고 흠 없는 송아지와 어린 양을 가져오고',2957),
('lev-9-4','lev','레위기',9,4,'또 화목제를 위하여 여호와 앞에 드릴 수소와 숫양을 가져오고 또 기름 섞은 소제물을 가져오라 하라 오늘 여호와께서 너희에게 나타나실 것임이니라 하매',2958),
('lev-9-5','lev','레위기',9,5,'그들이 모세가 명령한 모든 것을 회막 앞으로 가져오고 온 회중이 나아와 여호와 앞에 선지라',2959),
('lev-9-6','lev','레위기',9,6,'모세가 이르되 이는 여호와께서 너희에게 하라고 명령하신 것이니 여호와의 영광이 너희에게 나타나리라',2960),
('lev-9-7','lev','레위기',9,7,'모세가 또 아론에게 이르되 너는 제단에 나아가 네 속죄제와 네 번제를 드려서 너를 위하여, 백성을 위하여 속죄하고 또 백성의 예물을 드려서 그들을 위하여 속죄하되 여호와의 명령대로 하라',2961),
('lev-9-8','lev','레위기',9,8,'이에 아론이 제단에 나아가 자기를 위한 속죄제 송아지를 잡으매',2962),
('lev-9-9','lev','레위기',9,9,'아론의 아들들이 그 피를 아론에게 가져오니 아론이 손가락으로 그 피를 찍어 제단 뿔들에 바르고 그 피는 제단 밑에 쏟고',2963),
('lev-9-10','lev','레위기',9,10,'그 속죄제물의 기름과 콩팥과 간 꺼풀을 제단 위에서 불사르니 여호와께서 모세에게 명령하심과 같았고',2964),
('lev-9-11','lev','레위기',9,11,'그 고기와 가죽은 진영 밖에서 불사르니라',2965),
('lev-9-12','lev','레위기',9,12,'아론이 또 번제물을 잡으매 아론의 아들들이 그 피를 그에게로 가져오니 그가 그 피를 제단 사방에 뿌리고',2966),
('lev-9-13','lev','레위기',9,13,'그들이 또 번제의 제물 곧 그의 각과 머리를 그에게로 가져오매 그가 제단 위에서 불사르고',2967),
('lev-9-14','lev','레위기',9,14,'또 내장과 정강이는 씻어서 단 위에 있는 번제물 위에서 불사르니라',2968),
('lev-9-15','lev','레위기',9,15,'그가 또 백성의 예물을 드리되 곧 백성을 위한 속죄제의 염소를 가져다가 잡아 전과 같이 죄를 위하여 드리고',2969),
('lev-9-16','lev','레위기',9,16,'또 번제물을 드리되 규례대로 드리고',2970),
('lev-9-17','lev','레위기',9,17,'또 소제를 드리되 그 중에서 그의 손에 한 움큼을 채워서 아침 번제물에 더하여 제단 위에서 불사르고',2971),
('lev-9-18','lev','레위기',9,18,'또 백성을 위하는 화목제물의 수소와 숫양을 잡으매 아론의 아들들이 그 피를 그에게로 가져오니 그가 제단 사방에 뿌리고',2972),
('lev-9-19','lev','레위기',9,19,'그들이 또 수소와 숫양의 기름과 기름진 꼬리와 내장에 덮인 것과 콩팥과 간 꺼풀을 아론에게로 가져다가',2973),
('lev-9-20','lev','레위기',9,20,'그 기름을 가슴들 위에 놓으매 아론이 그 기름을 제단 위에서 불사르고',2974),
('lev-9-21','lev','레위기',9,21,'가슴들과 오른쪽 뒷다리를 그가 여호와 앞에 요제로 흔드니 모세가 명령한 것과 같았더라',2975),
('lev-9-22','lev','레위기',9,22,'아론이 백성을 향하여 손을 들어 축복함으로 속죄제와 번제와 화목제를 마치고 내려오니라',2976),
('lev-9-23','lev','레위기',9,23,'모세와 아론이 회막에 들어갔다가 나와서 백성에게 축복하매 여호와의 영광이 온 백성에게 나타나며',2977),
('lev-9-24','lev','레위기',9,24,'불이 여호와 앞에서 나와 제단 위의 번제물과 기름을 사른지라 온 백성이 이를 보고 소리 지르며 엎드렸더라',2978),
('lev-10-1','lev','레위기',10,1,'아론의 아들 나답과 아비후가 각기 향로를 가져다가 여호와께서 명령하시지 아니하신 다른 불을 담아 여호와 앞에 분향하였더니',2979),
('lev-10-2','lev','레위기',10,2,'불이 여호와 앞에서 나와 그들을 삼키매 그들이 여호와 앞에서 죽은지라',2980),
('lev-10-3','lev','레위기',10,3,'모세가 아론에게 이르되 이는 여호와의 말씀이라 이르시기를 나는 나를 가까이 하는 자 중에서 내 거룩함을 나타내겠고 온 백성 앞에서 내 영광을 나타내리라 하셨느니라 아론이 잠잠하니',2981),
('lev-10-4','lev','레위기',10,4,'모세가 아론의 삼촌 웃시엘의 아들 미사엘과 엘사반을 불러 그들에게 이르되 나아와 너희 형제들을 성소 앞에서 진영 밖으로 메고 나가라 하매',2982),
('lev-10-5','lev','레위기',10,5,'그들이 나와 모세가 말한 대로 그들을 옷 입은 채 진영 밖으로 메어 내니',2983),
('lev-10-6','lev','레위기',10,6,'모세가 아론과 그의 아들 엘르아살과 이다말에게 이르되 너희는 머리를 풀거나 옷을 찢지 말라 그리하여 너희가 죽음을 면하고 여호와의 진노가 온 회중에게 미침을 면하게 하라 오직 너희 형제 이스라엘 온 족속은 여호와께서 치신 불로 말미암아 슬퍼할 것이니라',2984),
('lev-10-7','lev','레위기',10,7,'여호와의 관유가 너희에게 있은즉 너희는 회막 문에 나가지 말라 그리하면 죽음을 면하리라 그들이 모세의 말대로 하니라',2985),
('lev-10-8','lev','레위기',10,8,'여호와께서 아론에게 말씀하여 이르시되',2986),
('lev-10-9','lev','레위기',10,9,'너와 네 자손들이 회막에 들어갈 때에는 포도주나 독주를 마시지 말라 그리하여 너희 죽음을 면하라 이는 너희 대대로 지킬 영영한 규례라',2987),
('lev-10-10','lev','레위기',10,10,'그리하여야 너희가 거룩하고 속된 것을 분별하며 부정하고 정한 것을 분별하고',2988),
('lev-10-11','lev','레위기',10,11,'또 나 여호와가 모세를 통하여 모든 규례를 이스라엘 자손에게 가르치리라',2989),
('lev-10-12','lev','레위기',10,12,'모세가 아론과 그 남은 아들 엘르아살에게와 이다말에게 이르되 여호와께 드린 화제물 중 소제의 남은 것은 지극히 거룩하니 너희는 그것을 취하여 누룩을 넣지 말고 제단 곁에서 먹되',2990),
('lev-10-13','lev','레위기',10,13,'이는 여호와의 화제물 중 네 소득과 네 아들들의 소득인즉 너희는 그것을 거룩한 곳에서 먹으라 내가 명령을 받았느니라',2991),
('lev-10-14','lev','레위기',10,14,'흔든 가슴과 들어올린 뒷다리는 너와 네 자녀가 너와 함께 정결한 곳에서 먹을지니 이는 이스라엘 자손의 화목제물 중에서 네 소득과 네 아들들의 소득으로 주신 것임이니라',2992),
('lev-10-15','lev','레위기',10,15,'그 들어올린 뒷다리와 흔든 가슴을 화제물의 기름과 함께 가져다가 여호와 앞에 흔들어 요제를 삼을지니 이는 여호와의 명령대로 너와 네 자손의 영원한 소득이니라',2993),
('lev-10-16','lev','레위기',10,16,'모세가 속죄제 드린 염소를 찾은즉 이미 불살랐는지라 그가 아론의 남은 아들 엘르아살과 이다말에게 노하여 이르되',2994),
('lev-10-17','lev','레위기',10,17,'이 속죄제물은 지극히 거룩하거늘 너희가 어찌하여 거룩한 곳에서 먹지 아니하였느냐 이는 너희로 회중의 죄를 담당하여 그들을 위하여 여호와 앞에 속죄하게 하려고 너희에게 주신 것이니라',2995),
('lev-10-18','lev','레위기',10,18,'그 피는 성소에 들여오지 아니하는 것이었으니 그 제물은 너희가 내가 명령한 대로 거룩한 곳에서 먹었어야 했을 것이니라',2996),
('lev-10-19','lev','레위기',10,19,'아론이 모세에게 이르되 오늘 그들이 그 속죄제와 번제를 여호와께 드렸어도 이런 일이 내게 임하였거늘 오늘 내가 속죄제물을 먹었더라면 여호와께서 어찌 좋게 여기셨으리요',2997),
('lev-10-20','lev','레위기',10,20,'모세가 그 말을 듣고 좋게 여겼더라',2998),
('lev-11-1','lev','레위기',11,1,'여호와께서 모세와 아론에게 말씀하여 이르시되',2999),
('lev-11-2','lev','레위기',11,2,'이스라엘 자손에게 말하여 이르라 육지의 모든 짐승 중 너희가 먹을 만한 생물은 이러하니',3000),
('lev-11-3','lev','레위기',11,3,'모든 짐승 중 굽이 갈라져 쪽발이 되고 새김질하는 것은 너희가 먹되',3001),
('lev-11-4','lev','레위기',11,4,'새김질하는 것이나 굽이 갈라진 짐승 중에도 너희가 먹지 못할 것은 이러하니 낙타는 새김질은 하되 굽이 갈라지지 아니하였으므로 너희에게 부정하고',3002),
('lev-11-5','lev','레위기',11,5,'사반도 새김질은 하되 굽이 갈라지지 아니하였으므로 너희에게 부정하고',3003),
('lev-11-6','lev','레위기',11,6,'토끼도 새김질은 하되 굽이 갈라지지 아니하였으므로 너희에게 부정하고',3004),
('lev-11-7','lev','레위기',11,7,'돼지는 굽이 갈라져 쪽발이로되 새김질을 못하므로 너희에게 부정하니',3005),
('lev-11-8','lev','레위기',11,8,'너희는 이러한 고기를 먹지 말고 그 주검도 만지지 말라 이것들은 너희에게 부정하니라',3006),
('lev-11-9','lev','레위기',11,9,'물에 있는 모든 것 중에서 너희가 먹을 만한 것은 이것이니 강과 바다와 다른 물에 있는 모든 것 중에서 지느러미와 비늘 있는 것은 너희가 먹되',3007),
('lev-11-10','lev','레위기',11,10,'물에서 움직이는 모든 것과 물에서 사는 모든 것 곧 강과 바다에 있는 것으로서 지느러미와 비늘 없는 모든 것은 너희에게 가증한 것이라',3008),
('lev-11-11','lev','레위기',11,11,'이들은 너희에게 가증한 것이니 너희는 그 고기를 먹지 말고 그 주검을 가증히 여기라',3009),
('lev-11-12','lev','레위기',11,12,'수중 생물에 지느러미와 비늘 없는 것은 너희가 혐오할 것이니라',3010),
('lev-11-13','lev','레위기',11,13,'새 중에 너희가 가증히 여길 것은 이것이라 이것들이 가증한즉 먹지 말지니 곧 독수리와 솔개와 물수리와',3011),
