('lev-11-22','lev','레위기',11,22,'곧 그 중에 메뚜기 종류와 베짱이 종류와 귀뚜라미 종류와 팥중이 종류는 너희가 먹으려니와',3020),
('lev-11-23','lev','레위기',11,23,'오직 날개가 있고 기어다니는 곤충은 다 너희가 혐오할 것이니라',3021),
