('lev-11-32','lev','레위기',11,32,'이런 것 중 어떤 것의 주검이 나무 그릇에든지 의복에든지 가죽에든지 자루에든지 무엇에 쓰는 그릇에든지 떨어지면 부정하여지리니 물에 담그라 저녁까지 부정하다가 정할 것이며',3030),
('lev-11-33','lev','레위기',11,33,'그것 중 어떤 것이 어느 질그릇에 떨어지면 그 속에 있는 것이 다 부정하여지나니 너는 그 그릇을 깨뜨리라',3031),
('lev-11-34','lev','레위기',11,34,'먹을 만한 축축한 식물이 거기 담겼으면 부정하여질 것이요 그같은 그릇에 담긴 마실 것도 부정할 것이며',3032),
('lev-11-35','lev','레위기',11,35,'이런 것의 주검이 물건 위에 떨어지면 그것이 모두 부정하여지리니 화덕이든지 화로이든지 깨뜨려버리라 이것이 부정하여져서 너희에게 부정한 것이 되리라',3033),
('lev-11-36','lev','레위기',11,36,'샘물이나 물이 고인 웅덩이는 부정하여지지 아니하되 그 주검에 닿는 것은 모두 부정하여질 것이요',3034),
('lev-11-37','lev','레위기',11,37,'이것들의 주검이 심을 종자에 떨어지면 그것이 정하거니와',3035),
