('lev-11-39','lev','레위기',11,39,'너희가 먹을 만한 짐승이 죽은 때에 그 주검을 만지는 자는 저녁까지 부정할 것이며',3037),
('lev-11-40','lev','레위기',11,40,'그것을 먹는 자는 그 옷을 빨 것이요 저녁까지 부정할 것이며 그 주검을 옮기는 자도 그의 옷을 빨 것이요 저녁까지 부정하리라',3038),
('lev-11-41','lev','레위기',11,41,'땅에 기어 다니는 모든 길짐승은 가증한즉 먹지 못할지니',3039),
