('lev-11-43','lev','레위기',11,43,'너희는 기는 바 기어다니는 것 때문에 자기를 가증하게 되게 하지 말며 또한 그것 때문에 스스로 더럽혀 부정하게 되게 하지 말라',3041),
('lev-11-44','lev','레위기',11,44,'나는 여호와 너희의 하나님이라 내가 거룩하니 너희도 몸을 구별하여 거룩하게 하고 땅에 기는 길짐승으로 말미암아 스스로 더럽히지 말라',3042),
('lev-11-45','lev','레위기',11,45,'나는 너희의 하나님이 되려고 너희를 애굽 땅에서 인도하여 낸 여호와라 내가 거룩하니 너희도 거룩할지어다',3043),
('lev-11-46','lev','레위기',11,46,'이는 짐승과 새와 물에서 움직이는 모든 생물과 땅에 기는 모든 길짐승에 대한 규례니',3044),
('lev-11-47','lev','레위기',11,47,'부정하고 정한 것과 먹을 생물과 먹지 못할 생물을 분별한 것이니라',3045),
('lev-12-1','lev','레위기',12,1,'여호와께서 모세에게 말씀하여 이르시되',3046),
