('lev-12-3','lev','레위기',12,3,'여덟째 날에는 그 아이의 포피를 벨 것이요',3048),
('lev-12-4','lev','레위기',12,4,'그 여인은 아직도 삼십삼 일을 지내야 산혈이 깨끗하리니 정결하게 되는 기한이 차기 전에는 성물을 만지지도 말며 성소에 들어가지도 말 것이며',3049),
('lev-12-5','lev','레위기',12,5,'여자를 낳으면 그는 두 이레 동안 부정하리니 월경할 때와 같을 것이며 산혈이 깨끗하게 됨은 육십육 일을 지내야 하리라',3050),
('lev-12-6','lev','레위기',12,6,'아들이나 딸이나 정결하게 되는 기한이 차면 그 여인은 번제를 위하여 일 년 된 어린 양을 가져가고 속죄제를 위하여 집비둘기 새끼나 산비둘기를 회막 문 제사장에게로 가져갈 것이요',3051),
