('lev-12-8','lev','레위기',12,8,'그 여인이 어린 양을 바치기에 힘이 미치지 못하면 산비둘기 두 마리나 집비둘기 새끼 두 마리를 가져다가 하나는 번제물로, 하나는 속죄제물로 삼을 것이요 제사장은 그를 위하여 속죄할지니 그가 정결하리라',3053),
('lev-13-1','lev','레위기',13,1,'여호와께서 모세와 아론에게 말씀하여 이르시되',3054),
('lev-13-2','lev','레위기',13,2,'만일 사람이 그의 피부에 무엇이 돋거나 뾰루지가 나거나 색점이 생겨서 그의 피부에 나병 같은 것이 생기거든 그를 곧 제사장 아론에게나 그의 아들 중 한 제사장에게로 데리고 갈 것이요',3055),
('lev-13-3','lev','레위기',13,3,'제사장은 그 피부의 병을 진찰할지니 환부의 털이 희어졌고 환부가 피부보다 우묵하여졌으면 이는 나병의 환부라 제사장이 그를 진찰하여 그를 부정하다 할 것이요',3056),
('lev-13-4','lev','레위기',13,4,'피부에 색점이 희나 우묵하지 아니하고 그 털이 희지 아니하면 제사장은 그 환자를 이레 동안 가두어둘 것이며',3057),
('lev-13-5','lev','레위기',13,5,'이레 만에 제사장이 그를 진찰할지니 그가 보기에 그 환부가 변하지 아니하고 병색이 피부에 퍼지지 아니하였으면 제사장이 그를 또 이레 동안을 가두어둘 것이며',3058),
('lev-13-6','lev','레위기',13,6,'이레 만에 제사장이 또 진찰할지니 그 환부가 엷어졌고 병색이 피부에 퍼지지 아니하였으면 피부병이라 제사장이 그를 정하다 할 것이요 그의 옷을 빨 것이라 그리하면 정하리라',3059),
('lev-13-7','lev','레위기',13,7,'그러나 그가 정결한지를 제사장에게 보인 후에 병이 피부에 퍼지면 제사장에게 다시 보일 것이요',3060),
('lev-13-8','lev','레위기',13,8,'제사장은 진찰할지니 그 병이 피부에 퍼졌으면 그를 부정하다 할지니라 이는 나병임이니라',3061),
('lev-13-9','lev','레위기',13,9,'사람에게 나병이 들었거든 그를 제사장에게로 데려갈 것이요',3062),
('lev-13-10','lev','레위기',13,10,'제사장은 진찰할지니 피부에 흰 점이 돋고 털이 희어지고 거기 생살이 생겼으면',3063),
('lev-13-11','lev','레위기',13,11,'이는 그의 피부의 오랜 나병이라 제사장이 부정하다 할 것이요 그가 이미 부정하였은즉 가두어두지는 않을 것이며',3064),
('lev-13-12','lev','레위기',13,12,'제사장이 보기에 나병이 그 피부에 크게 발생하였으되 그 환자의 머리부터 발끝까지 퍼졌으면',3065),
('lev-13-13','lev','레위기',13,13,'그가 진찰할 것이요 나병이 과연 그의 전신에 퍼졌으면 그 환자를 정하다 할지니 다 희어진 자인즉 정하거니와',3066),
('lev-13-14','lev','레위기',13,14,'아무 때든지 그에게 생살이 보이면 그는 부정한즉',3067),
('lev-13-15','lev','레위기',13,15,'제사장이 생살을 진찰하고 그를 부정하다 할지니 그 생살은 부정한 것인즉 이는 나병이며',3068),
('lev-13-16','lev','레위기',13,16,'그 생살이 변하여 다시 희어지면 제사장에게로 갈 것이요',3069),
('lev-13-17','lev','레위기',13,17,'제사장은 그를 진찰하여서 그 환부가 희어졌으면 환자를 정하다 할지니 그는 정하니라',3070),
