('lev-13-19','lev','레위기',13,19,'그 종처에 흰 점이 돋거나 희고 불그스름한 색점이 생겼으면 제사장에게 보일 것이요',3072),
('lev-13-20','lev','레위기',13,20,'그는 진찰하여 피부보다 얕고 그 털이 희면 그를 부정하다 할지니 이는 종기로 된 나병의 환부임이니라',3073),
('lev-13-21','lev','레위기',13,21,'그러나 제사장이 진찰하여 거기 흰 털이 없고 피부보다 얕지 아니하고 빛이 엷으면 제사장은 그를 이레 동안 가두어둘 것이며',3074),
('lev-13-22','lev','레위기',13,22,'그 병이 크게 피부에 퍼졌으면 제사장은 그를 부정하다 할지니 이는 환부임이니라',3075),
('lev-13-23','lev','레위기',13,23,'그러나 그 색점이 여전하고 퍼지지 아니하였으면 이는 종기 흔적이니 제사장은 그를 정하다 할지니라',3076),
('lev-13-24','lev','레위기',13,24,'피부가 불에 데었는데 그 덴 곳에 불그스름하고 희거나 순전히 흰 색점이 생기면',3077),
('lev-13-25','lev','레위기',13,25,'제사장은 진찰할지니 그 색점의 털이 희고 그 자리가 피부보다 우묵하면 이는 화상에서 생긴 나병인즉 제사장이 그를 부정하다 할 것은 나병의 환부가 됨이니라',3078),
('lev-13-26','lev','레위기',13,26,'그러나 제사장이 보기에 그 색점에 흰 털이 없으며 그 자리가 피부보다 얕지 아니하고 빛이 엷으면 그는 그를 이레 동안 가두어둘 것이며',3079),
('lev-13-27','lev','레위기',13,27,'이레 만에 제사장이 그를 진찰할지니 만일 병이 크게 피부에 퍼졌으면 그가 그를 부정하다 할 것은 나병의 환부임이니라',3080),
('lev-13-28','lev','레위기',13,28,'만일 색점이 여전하여 피부에 퍼지지 아니하고 빛이 엷으면 화상으로 부은 것이니 제사장이 그를 정하다 할 것은 이는 화상의 흔적임이니라',3081),
('lev-13-29','lev','레위기',13,29,'남자나 여자의 머리에나 수염에 환부가 있으면',3082),
