('lev-13-31','lev','레위기',13,31,'만일 제사장이 보기에 그 옴의 환부가 피부보다 우묵하지 아니하고 그 자리에 검은 털이 없으면 제사장은 그 옴 환자를 이레 동안 가두어둘 것이며',3084),
('lev-13-32','lev','레위기',13,32,'이레 만에 제사장은 그 환부를 진찰할지니 그 옴이 퍼지지 아니하고 그 자리에 누르스름한 털이 없고 피부보다 우묵하지 아니하면',3085),
('lev-13-33','lev','레위기',13,33,'그는 모발을 밀되 환부는 밀지 말 것이요 제사장은 옴 환자를 또 이레 동안 가두어둘 것이며',3086),
('lev-13-34','lev','레위기',13,34,'이레 만에 제사장은 그 옴을 또 진찰할지니 그 옴이 피부에 퍼지지 아니하고 피부보다 우묵하지 아니하면 그는 그를 정하다 할 것이요 그는 자기의 옷을 빨아서 정하게 되려니와',3087),
