('lev-17-3','lev','레위기',17,3,'이스라엘 집의 모든 사람이 소나 어린 양이나 염소를 진영 안에서 잡든지 진영 밖에서 잡든지',3239),
('lev-17-4','lev','레위기',17,4,'먼저 회막 문으로 끌고 가서 여호와의 성막 앞에서 여호와께 예물로 드리지 아니하는 자는 피 흘린 자로 여길 것이라 그가 피를 흘렸은즉 자기 백성 중에서 끊어지리라',3240),
('lev-17-5','lev','레위기',17,5,'그런즉 이스라엘 자손이 들에서 잡던 그들의 제물을 회막 문 여호와께로 끌고 가서 제사장에게 주어 화목제로 여호와께 드려야 할 것이요',3241),
('lev-17-6','lev','레위기',17,6,'제사장은 그 피를 회막 문 여호와의 제단에 뿌리고 그 기름을 불살라 여호와께 향기로운 냄새가 되게 할 것이라',3242),
('lev-17-7','lev','레위기',17,7,'그들은 전에 음란하게 섬기던 숫염소에게 다시 제사하지 말 것이니라 이는 그들이 대대로 지킬 영원한 규례니라',3243),
('lev-17-8','lev','레위기',17,8,'너는 또 그들에게 이르라 이스라엘 집 사람이나 혹은 그들 중에 거류하는 거류민이 번제나 제물을 드리되',3244),
('lev-17-9','lev','레위기',17,9,'회막 문으로 가져다가 여호와께 드리지 아니하면 그는 백성 중에서 끊어지리라',3245),
