('lev-17-12','lev','레위기',17,12,'그러므로 내가 이스라엘 자손에게 말하기를 너희 중에 아무도 피를 먹지 말며 너희 중에 거류하는 거류민이라도 피를 먹지 말라 하였나니',3248),
('lev-17-13','lev','레위기',17,13,'모든 이스라엘 자손이나 그들 중에 거류하는 거류민이 먹을 만한 짐승이나 새를 사냥하여 잡거든 그것의 피를 흘리고 흙으로 덮을지니라',3249),
