('lev-19-32','lev','레위기',19,32,'너는 센 머리 앞에서 일어서고 노인의 얼굴을 공경하며 네 하나님을 경외하라 나는 여호와이니라',3314),
('lev-19-33','lev','레위기',19,33,'거류민이 너희의 땅에 거류하여 함께 있거든 너희는 그를 학대하지 말고',3315),
