('lev-19-35','lev','레위기',19,35,'너희는 재판할 때나 길이나 무게나 양을 잴 때 불의를 행하지 말고',3317),
('lev-19-36','lev','레위기',19,36,'공평한 저울과 공평한 추와 공평한 에바와 공평한 힌을 사용하라 나는 너희를 인도하여 애굽 땅에서 나오게 한 너희의 하나님 여호와이니라',3318),
('lev-19-37','lev','레위기',19,37,'너희는 내 모든 규례와 내 모든 법도를 지켜 행하라 나는 여호와이니라',3319),
('lev-20-1','lev','레위기',20,1,'여호와께서 모세에게 말씀하여 이르시되',3320),
('lev-20-2','lev','레위기',20,2,'너는 이스라엘 자손에게 또 이르라 그가 이스라엘 자손이든지 이스라엘에 거류하는 거류민이든지 그의 자식을 몰렉에게 주면 반드시 죽이되 그 지방 사람이 돌로 칠 것이요',3321),
('lev-20-3','lev','레위기',20,3,'나도 그 사람에게 진노하여 그를 그의 백성 중에서 끊으리니 이는 그가 그의 자식을 몰렉에게 주어서 내 성소를 더럽히고 내 성호를 욕되게 하였음이라',3322),
('lev-20-4','lev','레위기',20,4,'그가 그의 자식을 몰렉에게 주는 것을 그 지방 사람이 못 본 체하고 그를 죽이지 아니하면',3323),
('lev-20-5','lev','레위기',20,5,'내가 그 사람과 그의 권속에게 진노하여 그와 그를 본받아 몰렉을 음란하게 섬기는 모든 사람을 그들의 백성 중에서 끊으리라',3324),
('lev-20-6','lev','레위기',20,6,'접신한 자와 박수무당을 음란하게 따르는 자에게는 내가 진노하여 그를 그의 백성 중에서 끊으리니',3325),
('lev-20-7','lev','레위기',20,7,'너희는 스스로 깨끗하게 하여 거룩할지어다 나는 너희의 하나님 여호와이니라',3326),
('lev-20-8','lev','레위기',20,8,'너희는 내 규례를 지켜 행하라 나는 너희를 거룩하게 하는 여호와이니라',3327),
('lev-20-9','lev','레위기',20,9,'만일 누구든지 자기의 아버지나 어머니를 저주하는 자는 반드시 죽일지니 그가 자기의 아버지나 어머니를 저주하였은즉 그의 피가 자기에게로 돌아가리라',3328),
('lev-20-10','lev','레위기',20,10,'누구든지 남의 아내와 간음하는 자 곧 그의 이웃의 아내와 간음하는 자는 그 간부와 음부를 반드시 죽일지니라',3329),
('lev-20-11','lev','레위기',20,11,'누구든지 그의 아버지의 아내와 동침하는 자는 그의 아버지의 하체를 범하였은즉 둘 다 반드시 죽일지니 그들의 피가 자기들에게로 돌아가리라',3330),
