('lev-20-14','lev','레위기',20,14,'누구든지 아내와 자기의 장모를 함께 데리고 살면 악행인즉 그와 그들을 함께 불사를지니 이는 너희 중에 악행이 없게 하려 함이니라',3333),
('lev-20-15','lev','레위기',20,15,'남자가 짐승과 교합하면 반드시 죽이고 너희는 그 짐승도 죽일 것이며',3334),
('lev-20-16','lev','레위기',20,16,'여자가 짐승에게 가까이 하여 교합하면 너는 여자와 짐승을 죽이되 그들을 반드시 죽일지니 그들의 피가 자기들에게로 돌아가리라',3335),
('lev-20-17','lev','레위기',20,17,'누구든지 그의 자매 곧 그의 아버지의 딸이나 그의 어머니의 딸을 데려다가 그 여자의 하체를 보고 여자는 그 남자의 하체를 보면 부끄러운 일이라 그들의 민족 앞에서 그들이 끊어질지니 그가 자기의 자매의 하체를 범하였은즉 그가 그의 죄를 담당하리라',3336),
('lev-20-18','lev','레위기',20,18,'누구든지 월경 중의 여인과 동침하여 그의 하체를 범하면 남자는 그 여인의 근원을 드러냈고 여인은 자기의 피 근원을 드러내었음인즉 둘 다 백성 중에서 끊어지리라',3337),
('lev-20-19','lev','레위기',20,19,'네 이모나 고모의 하체를 범하지 말지니 이는 살붙이의 하체인즉 그들이 그들의 죄를 담당하리라',3338),
('lev-20-20','lev','레위기',20,20,'누구든지 그의 숙모와 동침하면 그의 숙부의 하체를 범함이니 그들은 그들의 죄를 담당하여 자식이 없이 죽으리라',3339),
('lev-20-21','lev','레위기',20,21,'누구든지 그의 형제의 아내를 데리고 살면 더러운 일이라 그가 그의 형제의 하체를 범함이니 그들에게 자식이 없으리라',3340),
('lev-20-22','lev','레위기',20,22,'너희는 나의 모든 규례와 법도를 지켜 행하라 그리하여야 내가 너희를 인도하여 거주하게 하는 땅이 너희를 토하지 아니하리라',3341),
