('lev-20-26','lev','레위기',20,26,'너희는 나에게 거룩할지어다 이는 나 여호와가 거룩하고 내가 또 너희를 나의 소유로 삼으려고 너희를 만민 중에서 구별하였음이니라',3345),
('lev-20-27','lev','레위기',20,27,'남자나 여자가 접신하거나 박수무당이 되거든 반드시 죽일지니 곧 돌로 그를 치라 그들의 피가 자기들에게로 돌아가리라',3346),
