('lev-21-6','lev','레위기',21,6,'그들의 하나님께 대하여 거룩하고 그들의 하나님의 이름을 욕되게 하지 말 것이며 그들은 여호와의 화제 곧 그들의 하나님의 음식을 드리는 자인즉 거룩할 것이라',3352),
('lev-21-7','lev','레위기',21,7,'그들은 부정한 창녀나 이혼 당한 여인을 취하지 말지니 이는 그가 여호와 하나님께 거룩함이니라',3353),
('lev-21-8','lev','레위기',21,8,'너는 그를 거룩히 여기라 그는 네 하나님의 음식을 드림이니라 너는 그를 거룩히 여기라 너희를 거룩하게 하는 나 여호와는 거룩함이니라',3354),
('lev-21-9','lev','레위기',21,9,'어떤 제사장의 딸이든지 행음하여 자신을 속되게 하면 그의 아버지를 속되게 함이니 그를 불사를지니라',3355),
