('lev-21-11','lev','레위기',21,11,'어떤 시체에든지 가까이 하지 말지니 그의 부모로 말미암아서도 더러워지게 하지 말며',3357),
('lev-21-12','lev','레위기',21,12,'그 성소에서 나오지 말며 그의 하나님의 성소를 속되게 하지 말라 이는 하나님께서 성별하신 관유가 그 위에 있음이니라 나는 여호와이니라',3358),
