('lev-21-18','lev','레위기',21,18,'누구든지 흠이 있는 자는 가까이 하지 못할지니 곧 맹인이나 다리 저는 자나 코가 불완전한 자나 지체가 더한 자나',3364),
('lev-21-19','lev','레위기',21,19,'발 부러진 자나 손 부러진 자나',3365),
('lev-21-20','lev','레위기',21,20,'등 굽은 자나 키 못 자란 자나 눈에 백막이 있는 자나 습진이나 버짐이 있는 자나 고환 상한 자나',3366),
('lev-21-21','lev','레위기',21,21,'제사장 아론의 자손 중에 흠이 있는 자는 나와 여호와께 화제를 드리지 못할지니 그는 흠이 있은즉 나와서 그의 하나님께 음식을 드리지 못하느니라',3367),
('lev-21-22','lev','레위기',21,22,'그는 그의 하나님의 음식이 지성물이든지 성물이든지 먹을 것이나',3368),
('lev-21-23','lev','레위기',21,23,'휘장 안에 들어가지 못할 것이요 제단에 가까이 하지 못할지니 이는 그가 흠이 있음이니라 이와 같이 그가 내 성소를 더럽히지 못할 것은 나는 그들을 거룩하게 하는 여호와임이니라',3369),
('lev-21-24','lev','레위기',21,24,'이와 같이 모세가 아론과 그의 아들들과 온 이스라엘 자손에게 말하였더라',3370),
