('lev-22-3','lev','레위기',22,3,'그들에게 이르라 누구든지 네 자손 중에 대대로 그의 몸이 부정하면서도 이스라엘 자손이 구별하여 여호와께 드리는 성물에 가까이 하는 자는 내 앞에서 끊어지리라 나는 여호와이니라',3373),
('lev-22-4','lev','레위기',22,4,'아론의 자손 중 나병 환자나 유출병자는 그가 정결하기 전에는 그 성물을 먹지 말 것이요 시체의 부정에 접촉된 자나 설정한 자나',3374),
('lev-22-5','lev','레위기',22,5,'무릇 사람을 부정하게 하는 벌레에 접촉된 모든 사람과 무슨 부정이든지 사람을 더럽힐 만한 것에게 접촉된 자',3375),
('lev-22-6','lev','레위기',22,6,'곧 이런 것에 접촉된 자는 저녁까지 부정하니 그의 몸을 물로 씻지 아니하면 그 성물을 먹지 못할지며',3376),
('lev-22-7','lev','레위기',22,7,'해 질 때에야 정하리니 그 후에야 그 성물을 먹을 것이니라 이는 자기의 음식이 됨이니라',3377),
('lev-22-8','lev','레위기',22,8,'시체나 찢겨 죽은 짐승을 먹음으로 자기를 더럽히지 말라 나는 여호와이니라',3378),
('lev-22-9','lev','레위기',22,9,'그들은 내 명령을 지킬 것이니라 그것을 속되게 하면 그로 말미암아 죄를 짓고 그 가운데에서 죽을까 하노라 나는 그들을 거룩하게 하는 여호와이니라',3379),
('lev-22-10','lev','레위기',22,10,'일반인은 성물을 먹지 못할 것이며 제사장의 객이나 품꾼도 다 성물을 먹지 못할 것이니라',3380),
('lev-22-11','lev','레위기',22,11,'그러나 제사장이 그의 돈으로 어떤 사람을 샀으면 그는 그것을 먹을 것이며 그의 집에서 출생한 자도 그렇게 하여 그들이 제사장의 음식을 먹을 것이며',3381),
('lev-22-12','lev','레위기',22,12,'제사장의 딸이 일반인에게 출가하였으면 거제의 성물을 먹지 못하되',3382),
('lev-22-13','lev','레위기',22,13,'만일 그가 과부가 되든지 이혼을 당하든지 자식이 없이 그의 친정에 돌아와서 젊었을 때와 같으면 그는 그의 아버지 몫의 음식을 먹을 것이나 일반인은 먹지 못할 것이니라',3383),
('lev-22-14','lev','레위기',22,14,'만일 누가 부지중에 성물을 먹으면 그 성물에 그것의 오분의 일을 더하여 제사장에게 줄지니라',3384),
