('lev-24-8','lev','레위기',24,8,'안식일마다 이 떡을 여호와 앞에 항상 진설할지니 이는 이스라엘 자손을 위한 것이요 영원한 언약이니라',3455),
('lev-24-9','lev','레위기',24,9,'이 떡은 아론과 그의 자손에게 돌리고 그들은 그것을 거룩한 곳에서 먹을지니 이는 여호와의 화제 중 그에게 돌리는 것으로서 지극히 거룩함이니라 이는 영원한 규례니라',3456),
('lev-24-10','lev','레위기',24,10,'이스라엘 자손 중에 그의 어머니가 이스라엘 여인이요 그의 아버지는 애굽 사람인 어떤 사람이 나가서 한 이스라엘 사람과 진영 중에서 싸우다가',3457),
('lev-24-11','lev','레위기',24,11,'그 이스라엘 여인의 아들이 여호와의 이름을 모독하며 저주하므로 무리가 끌고 모세에게로 가니라 그의 어머니의 이름은 슬로밋이요 단 지파 디브리의 딸이었더라',3458),
('lev-24-12','lev','레위기',24,12,'그들이 그를 가두고 여호와의 명령을 기다리더니',3459),
