('lev-24-15','lev','레위기',24,15,'너는 이스라엘 자손에게 말하여 이르라 누구든지 그의 하나님을 저주하면 죄를 담당할 것이요',3462),
('lev-24-16','lev','레위기',24,16,'여호와의 이름을 모독하면 그를 반드시 죽일지니 온 회중이 돌로 그를 칠 것이니라 거류민이든지 본토인이든지 여호와의 이름을 모독하면 그를 죽일지니라',3463),
