('lev-24-20','lev','레위기',24,20,'상처에는 상처로, 눈에는 눈으로, 이에는 이로 갚을지라 남에게 상해를 입힌 그대로 그에게 그렇게 할 것이며',3467),
('lev-24-21','lev','레위기',24,21,'짐승을 죽인 자는 그것을 물어 줄 것이요 사람을 죽인 자는 죽일지니',3468),
