('lev-25-45','lev','레위기',25,45,'또 너희 중에 거류하는 동거인들의 자녀 중에서도 너희가 사올 수 있고 또 그들이 너희와 함께 있어서 너희 땅에서 가정을 이룬 자들 중에서도 그리 할 수 있은즉 그들이 너희의 소유가 될지니라',3515),
('lev-25-46','lev','레위기',25,46,'너희는 그들을 너희 후손에게 기업으로 주어 소유가 되게 할 것이라 이방인 중에서는 너희가 영원한 종을 삼으려니와 너희 동족 이스라엘 자손은 너희가 피차 엄하게 부리지 말지니라',3516),
