('lev-25-48','lev','레위기',25,48,'그가 팔린 후에 그에게는 속량 받을 권리가 있나니 그의 형제 중 하나가 그를 속량하거나',3518),
('lev-25-49','lev','레위기',25,49,'또는 그의 삼촌이나 그의 삼촌의 아들이 그를 속량하거나 그의 가족 중 그의 살붙이 중에서 그를 속량할 것이요 그가 부유하게 되면 스스로 속량하되',3519),
('lev-25-50','lev','레위기',25,50,'자기 몸이 팔린 해로부터 희년까지를 그 산 자와 계산하여 그 연수를 따라서 그 몸의 값을 정할 때에 그 사람을 섬긴 날을 그 사람에게 고용된 날로 여길 것이라',3520),
('lev-25-51','lev','레위기',25,51,'만일 남은 해가 많으면 그 연수대로 팔린 값에서 속량하는 값을 그 사람에게 도로 주고',3521),
('lev-25-52','lev','레위기',25,52,'만일 희년까지 남은 해가 적으면 그 사람과 계산하여 그 연수대로 속량하는 그 값을 그에게 도로 줄지며',3522),
('lev-25-53','lev','레위기',25,53,'주인은 그를 매년의 삯꾼과 같이 여기고 네 목전에서 엄하게 부리지 말지니라',3523),
('lev-25-54','lev','레위기',25,54,'그가 이같이 속량하지 아니하여 희년에 이르러는 그와 그의 자녀가 자유하리니',3524),
('lev-25-55','lev','레위기',25,55,'이스라엘 자손은 나의 종들이 됨이라 그들은 내가 애굽 땅에서 인도하여 낸 내 종이요 나는 너희의 하나님 여호와이니라',3525),
('lev-26-1','lev','레위기',26,1,'너희는 자기를 위하여 우상을 만들지 말지니 조각한 것이나 주상을 세우지 말며 너희 땅에 조각한 석상을 세우고 그에게 경배하지 말라 나는 너희의 하나님 여호와임이니라',3526),
('lev-26-2','lev','레위기',26,2,'너희는 내 안식일을 지키며 내 성소를 경외하라 나는 여호와이니라',3527),
