('lev-26-5','lev','레위기',26,5,'너희의 타작은 포도 딸 때까지 미치며 너희의 포도 따는 것은 파종할 때까지 미치리니 너희가 음식을 배불리 먹고 너희의 땅에 안전하게 거주하리라',3530),
