('lev-26-7','lev','레위기',26,7,'너희의 원수들을 쫓으리니 그들이 너희 앞에서 칼에 엎드러질 것이라',3532),
('lev-26-8','lev','레위기',26,8,'또 너희 다섯이 백을 쫓고 너희 백이 만을 쫓으리니 너희 대적들이 너희 앞에서 칼에 엎드러질 것이며',3533),
('lev-26-9','lev','레위기',26,9,'내가 너희를 돌보아 너희를 번성하게 하고 너희를 창대하게 할 것이며 내가 너희와 함께 한 내 언약을 이행하리라',3534),
('lev-26-10','lev','레위기',26,10,'너희는 오래 두었던 묵은 곡식을 먹다가 새 곡식으로 말미암아 묵은 곡식을 치우게 될 것이며',3535),
