('lev-26-17','lev','레위기',26,17,'내가 너희를 치리니 너희가 너희의 대적에게 패할 것이요 너희를 미워하는 자가 너희를 다스릴 것이며 너희는 쫓는 자가 없어도 도망하리라',3542),
