('lev-26-44','lev','레위기',26,44,'그런즉 그들이 그들의 원수들의 땅에 있을 때에 내가 그들을 내버리지 아니하며 미워하지 아니하며 아주 멸하지 아니하고 그들과 맺은 내 언약을 폐하지 아니하리니 나는 여호와 그들의 하나님이 됨이니라',3569),
