('lev-26-46','lev','레위기',26,46,'이것은 여호와께서 시내 산에서 자기와 이스라엘 자손 사이에 모세를 통하여 세우신 규례와 법도와 율법이니라',3571),
('lev-27-1','lev','레위기',27,1,'여호와께서 모세에게 말씀하여 이르시되',3572),
