('lev-27-3','lev','레위기',27,3,'네가 정한 값은 스무 살로부터 예순 살까지는 남자면 성소의 세겔로 은 오십 세겔로 하고',3574),
('lev-27-4','lev','레위기',27,4,'여자면 그 값을 삼십 세겔로 하며',3575),
