('lev-27-6','lev','레위기',27,6,'일 개월로부터 다섯 살까지는 남자면 그 값을 은 다섯 세겔로 하고 여자면 그 값을 은 삼 세겔로 하며',3577),
('lev-27-7','lev','레위기',27,7,'예순 살 이상은 남자면 그 값을 십오 세겔로 하고 여자는 열 세겔로 하라',3578),
