('lev-27-9','lev','레위기',27,9,'사람이 서원하는 예물로 여호와께 드리는 것이 가축이면 여호와께 드릴 때는 다 거룩하니',3580),
('lev-27-10','lev','레위기',27,10,'그것을 변경하여 우열간 바꾸지 못할 것이요 혹 가축으로 가축을 바꾸면 둘 다 거룩할 것이며',3581),
('lev-27-11','lev','레위기',27,11,'부정하여 여호와께 예물로 드리지 못할 가축이면 그 가축을 제사장 앞으로 끌어갈 것이요',3582),
('lev-27-12','lev','레위기',27,12,'제사장은 우열간에 값을 정할지니 그 값이 제사장의 정한 대로 될 것이며',3583),
('lev-27-13','lev','레위기',27,13,'만일 그가 그것을 무르려면 네가 정한 값에 그 오분의 일을 더할지니라',3584),
