('deu-2-7','deu','신명기',2,7,'네 하나님 여호와께서 네가 하는 모든 일에 네게 복을 주시고 네가 이 큰 광야에 두루 다님을 알고 네 하나님 여호와께서 이 사십 년 동안을 너와 함께 하셨으므로 네게 부족함이 없었느니라 하시기로',4946),
('deu-2-8','deu','신명기',2,8,'우리가 세일 산에 거주하는 우리 동족 에서의 자손을 떠나서 아라바를 지나며 엘랏과 에시온 게벨 곁으로 지나 행진하고 돌이켜 모압 광야 길로 지날 때에',4947),
('deu-2-9','deu','신명기',2,9,'여호와께서 내게 이르시되 모압을 괴롭히지 말라 그와 싸우지도 말라 그 땅을 내가 네게 기업으로 주지 아니하리니 이는 내가 롯 자손에게 아르를 기업으로 주었음이라',4948),
('deu-2-10','deu','신명기',2,10,'(이전에는 에밈 사람이 거기 거주하였는데 아낙 족속 같이 강하고 많고 키가 크므로',4949),
('deu-2-11','deu','신명기',2,11,'그들을 아낙 족속과 같이 르바임이라 불렀으나 모압 사람은 그들을 에밈이라 불렀으며',4950),
('deu-2-12','deu','신명기',2,12,'호리 사람도 세일에 거주하였는데 에서의 자손이 그들을 멸하고 그 땅에 거주하였으니 이스라엘이 여호와께서 주신 기업의 땅에서 행한 것과 같았느니라)',4951),
('deu-2-13','deu','신명기',2,13,'이제 너희는 일어나서 세렛 시내를 건너가라 하시기로 우리가 세렛 시내를 건넜으니',4952),
('deu-2-14','deu','신명기',2,14,'가데스 바네아에서 떠나 세렛 시내를 건너기까지 삼십팔 년 동안이라 이 때에는 그 시대의 모든 군인들이 여호와께서 그들에게 맹세하신 대로 진영 중에서 다 멸망하였나니',4953),
('deu-2-15','deu','신명기',2,15,'여호와께서 손으로 그들을 치사 진영 중에서 멸하신 고로 마침내는 다 멸망되었느니라',4954),
('deu-2-16','deu','신명기',2,16,'모든 군인이 사망하여 백성 중에서 멸망한 후에',4955),
('deu-2-17','deu','신명기',2,17,'여호와께서 내게 말씀하여 이르시되',4956),
('deu-2-18','deu','신명기',2,18,'네가 오늘 모압 변경 아르를 지나리니',4957),
('deu-2-19','deu','신명기',2,19,'암몬 족속에게 가까이 이르거든 그들을 괴롭히지 말고 그들과 다투지도 말라 암몬 족속의 땅은 내가 네게 기업으로 주지 아니하리니 이는 내가 그것을 롯 자손에게 기업으로 주었음이라',4958),
('deu-2-20','deu','신명기',2,20,'(이곳도 르바임의 땅이라 하였나니 전에 르바임이 거기 거주하였음이요 암몬 족속은 그들을 삼숨밈이라 일컬었으며',4959),
('deu-2-21','deu','신명기',2,21,'그 백성은 아낙 족속과 같이 강하고 많고 키가 컸으나 여호와께서 암몬 족속 앞에서 그들을 멸하셨으므로 암몬 족속이 대신하여 그 땅에 거주하였으니',4960),
('deu-2-22','deu','신명기',2,22,'마치 세일에 거주한 에서 자손 앞에 호리 사람을 멸하심과 같으니 그들이 호리 사람을 쫓아내고 대신하여 오늘까지 거기에 거주하였으며',4961),
('deu-2-23','deu','신명기',2,23,'또 갑돌에서 나온 갑돌 사람이 가사까지 각 촌에 거주하는 아위 사람을 멸하고 그들을 대신하여 거기에 거주하였느니라)',4962),
('deu-2-24','deu','신명기',2,24,'너희는 일어나 행진하여 아르논 골짜기를 건너라 내가 헤스본 왕 아모리 사람 시혼과 그의 땅을 네 손에 넘겼은즉 이제 더불어 싸워서 그 땅을 차지하라',4963),
('deu-2-25','deu','신명기',2,25,'오늘부터 내가 천하 만민이 너를 무서워하며 너를 두려워하게 하리니 그들이 네 명성을 듣고 떨며 너로 말미암아 근심하리라 하셨느니라',4964),
('deu-2-26','deu','신명기',2,26,'내가 그데못 광야에서 헤스본 왕 시혼에게 사자를 보내어 평화의 말로 이르기를',4965),
('deu-2-27','deu','신명기',2,27,'나를 네 땅으로 통과하게 하라 내가 큰길로만 행하고 좌로나 우로나 치우치지 아니하리라',4966),
('deu-2-28','deu','신명기',2,28,'너는 돈을 받고 양식을 팔아 내가 먹게 하고 돈을 받고 물을 주어 내가 마시게 하라 나는 걸어서 지날 뿐인즉',4967),
('deu-2-29','deu','신명기',2,29,'세일에 거주하는 에서 자손과 아르에 거주하는 모압 사람이 내게 행한 것 같이 하라 그리하면 내가 요단을 건너서 우리 하나님 여호와께서 우리에게 주시는 땅에 이르리라 하였으나',4968),
('deu-2-30','deu','신명기',2,30,'헤스본 왕 시혼이 우리가 통과하기를 허락하지 아니하였으니 이는 네 하나님 여호와께서 그를 네 손에 넘기시려고 그의 성품을 완강하게 하셨고 그의 마음을 완고하게 하셨음이 오늘날과 같으니라',4969),
('deu-2-31','deu','신명기',2,31,'그 때에 여호와께서 내게 이르시되 내가 이제 시혼과 그의 땅을 네게 넘기노니 너는 이제부터 그의 땅을 차지하여 기업으로 삼으라 하시더니',4970),
('deu-2-32','deu','신명기',2,32,'시혼이 그의 모든 백성을 거느리고 나와서 우리를 대적하여 야하스에서 싸울 때에',4971),
('deu-2-33','deu','신명기',2,33,'우리 하나님 여호와께서 그를 우리에게 넘기시매 우리가 그와 그의 아들들과 그의 모든 백성을 쳤고',4972),
('deu-2-34','deu','신명기',2,34,'그 때에 우리가 그의 모든 성읍을 점령하고 그의 각 성읍을 그 남녀와 유아와 함께 하나도 남기지 아니하고 진멸하였고',4973),
('deu-2-35','deu','신명기',2,35,'다만 그 가축과 성읍에서 탈취한 것은 우리의 소유로 삼았으며',4974),
('deu-2-36','deu','신명기',2,36,'우리 하나님 여호와께서 그 모든 땅을 우리에게 넘겨주심으로 아르논 골짜기 가장자리에 있는 아로엘과 골짜기 가운데에 있는 성읍으로부터 길르앗까지 우리가 모든 높은 성읍을 점령하지 못한 것이 하나도 없었으나',4975),
('deu-2-37','deu','신명기',2,37,'오직 암몬 족속의 땅 얍복 강 가와 산지에 있는 성읍들과 우리 하나님 여호와께서 우리가 가기를 금하신 모든 곳은 네가 가까이 하지 못하였느니라',4976),
('deu-3-1','deu','신명기',3,1,'우리가 돌이켜 바산으로 올라가매 바산 왕 옥이 그의 모든 백성을 거느리고 나와서 우리를 대적하여 에드레이에서 싸우고자 하는지라',4977),
('deu-3-2','deu','신명기',3,2,'여호와께서 내게 이르시되 그를 두려워하지 말라 내가 그와 그의 모든 백성과 그의 땅을 네 손에 넘겼으니 네가 헤스본에 거주하던 아모리 족속의 왕 시혼에게 행한 것과 같이 그에게도 행할 것이니라 하시고',4978),
('deu-3-3','deu','신명기',3,3,'우리 하나님 여호와께서 바산 왕 옥과 그의 모든 백성을 우리 손에 넘기시매 우리가 그들을 쳐서 한 사람도 남기지 아니하였느니라',4979),
('deu-3-4','deu','신명기',3,4,'그 때에 우리가 그들에게서 빼앗지 아니한 성읍이 하나도 없이 다 빼앗았는데 그 성읍이 육십이니 곧 아르곱 온 지방이요 바산에 있는 옥의 나라이니라',4980),
('deu-3-5','deu','신명기',3,5,'그 모든 성읍이 높은 성벽으로 둘려 있고 문과 빗장이 있어 견고하며 그 외에 성벽 없는 고을이 심히 많았느니라',4981),
('deu-3-6','deu','신명기',3,6,'우리가 헤스본 왕 시혼에게 행한 것과 같이 그 성읍들을 멸망시키되 각 성읍의 남녀와 유아를 멸망시켰으나',4982),
('deu-3-7','deu','신명기',3,7,'다만 모든 가축과 그 성읍들에서 탈취한 것은 우리의 소유로 삼았으며',4983),
('deu-3-8','deu','신명기',3,8,'그 때에 우리가 요단 강 이쪽 땅을 아르논 골짜기에서부터 헤르몬 산에까지 아모리 족속의 두 왕에게서 빼앗았으니',4984),
('deu-3-9','deu','신명기',3,9,'(헤르몬 산을 시돈 사람은 시룐이라 부르고 아모리 족속은 스닐이라 불렀느니라)',4985),
('deu-3-10','deu','신명기',3,10,'우리가 빼앗은 것은 평원의 모든 성읍과 길르앗 온 땅과 바산의 온 땅 곧 옥의 나라 바산의 성읍 살르가와 에드레이까지이니라',4986),
('deu-3-11','deu','신명기',3,11,'(르바임 족속의 남은 자는 바산 왕 옥뿐이었으며 그의 침상은 철 침상이라 아직도 암몬 족속의 랍바에 있지 아니하냐 그것을 사람의 보통 규빗으로 재면 그 길이가 아홉 규빗이요 너비가 네 규빗이니라)',4987),
('deu-3-12','deu','신명기',3,12,'그 때에 우리가 이 땅을 얻으매 아르논 골짜기 곁의 아로엘에서부터 길르앗 산지 절반과 그 성읍들을 내가 르우벤 자손과 갓 자손에게 주었고',4988),
('deu-3-13','deu','신명기',3,13,'길르앗의 남은 땅과 옥의 나라였던 아르곱 온 지방 곧 온 바산으로는 내가 므낫세 반 지파에게 주었노라 (바산을 옛적에는 르바임의 땅이라 부르더니',4989),
('deu-3-14','deu','신명기',3,14,'므낫세의 아들 야일이 그술 족속과 마아갓 족속의 경계까지의 아르곱 온 지방을 점령하고 자기의 이름으로 이 바산을 오늘날까지 하봇야일이라 불러오느니라)',4990),
('deu-3-15','deu','신명기',3,15,'내가 마길에게 길르앗을 주었고',4991),
('deu-3-16','deu','신명기',3,16,'르우벤 자손과 갓 자손에게는 길르앗에서부터 아르논 골짜기까지 주었으되 그 골짜기의 중앙으로 지역을 정하였으니 곧 암몬 자손의 지역 얍복 강까지며',4992),
('deu-3-17','deu','신명기',3,17,'또는 아라바와 요단과 그 지역이요 긴네렛에서 아라바 바다 곧 염해와 비스가 산기슭에 이르기까지의 동쪽 지역이니라',4993),
('deu-3-18','deu','신명기',3,18,'그 때에 내가 너희에게 명령하여 이르기를 너희의 하나님 여호와께서 이 땅을 너희에게 주어 기업이 되게 하셨은즉 너희의 군인들은 무장하고 너희의 형제 이스라엘 자손의 선봉이 되어 건너가되',4994),
('deu-3-19','deu','신명기',3,19,'너희에게 가축이 많은 줄 내가 아노니 너희의 처자와 가축은 내가 너희에게 준 성읍에 머무르게 하라',4995),
('deu-3-20','deu','신명기',3,20,'여호와께서 너희에게 주신 것 같이 너희의 형제에게도 안식을 주시리니 그들도 요단 저쪽에서 너희의 하나님 여호와께서 그들에게 주시는 땅을 받아 기업을 삼기에 이르거든 너희는 각기 내가 준 기업으로 돌아갈 것이니라 하고',4996),
('deu-3-21','deu','신명기',3,21,'그 때에 내가 여호수아에게 명령하여 이르기를 너희의 하나님 여호와께서 이 두 왕에게 행하신 모든 일을 네 눈으로 보았거니와 네가 가는 모든 나라에도 여호와께서 이와 같이 행하시리니',4997),
('deu-3-22','deu','신명기',3,22,'너희는 그들을 두려워하지 말라 너희의 하나님 여호와께서 친히 너희를 위하여 싸우시리라 하였노라',4998),
('deu-3-23','deu','신명기',3,23,'그 때에 내가 여호와께 간구하기를',4999),
('deu-3-24','deu','신명기',3,24,'주 여호와여 주께서 주의 크심과 주의 권능을 주의 종에게 나타내시기를 시작하셨사오니 천지간에 어떤 신이 능히 주께서 행하신 일 곧 주의 큰 능력으로 행하신 일 같이 행할 수 있으리이까',5000),
('deu-3-25','deu','신명기',3,25,'구하옵나니 나를 건너가게 하사 요단 저쪽에 있는 아름다운 땅, 아름다운 산과 레바논을 보게 하옵소서 하되',5001),
('deu-3-26','deu','신명기',3,26,'여호와께서 너희 때문에 내게 진노하사 내 말을 듣지 아니하시고 내게 이르시기를 그만해도 족하니 이 일로 다시 내게 말하지 말라',5002),
('deu-3-27','deu','신명기',3,27,'너는 비스가 산 꼭대기에 올라가서 눈을 들어 동서남북을 바라고 네 눈으로 그 땅을 바라보라 너는 이 요단을 건너지 못할 것임이니라',5003),
('deu-3-28','deu','신명기',3,28,'너는 여호수아에게 명령하고 그를 담대하게 하며 그를 강하게 하라 그는 이 백성을 거느리고 건너가서 네가 볼 땅을 그들이 기업으로 얻게 하리라 하셨느니라',5004),
('deu-3-29','deu','신명기',3,29,'그 때에 우리가 벳브올 맞은편 골짜기에 거주하였느니라',5005),
('deu-4-1','deu','신명기',4,1,'이스라엘아 이제 내가 너희에게 가르치는 규례와 법도를 듣고 준행하라 그리하면 너희가 살 것이요 너희 조상의 하나님 여호와께서 너희에게 주시는 땅에 들어가서 그것을 얻게 되리라',5006),
('deu-4-2','deu','신명기',4,2,'내가 너희에게 명령하는 말을 너희는 가감하지 말고 내가 너희에게 내리는 너희 하나님 여호와의 명령을 지키라',5007),
('deu-4-3','deu','신명기',4,3,'여호와께서 바알브올의 일로 말미암아 행하신 바를 너희가 눈으로 보았거니와 바알브올을 따른 모든 사람을 너희의 하나님 여호와께서 너희 가운데에서 멸망시키셨으되',5008),
('deu-4-4','deu','신명기',4,4,'오직 너희의 하나님 여호와께 붙어 떠나지 않은 너희는 오늘까지 다 생존하였느니라',5009),
('deu-4-5','deu','신명기',4,5,'내가 나의 하나님 여호와께서 명령하신 대로 규례와 법도를 너희에게 가르쳤나니 이는 너희가 들어가서 기업으로 차지할 땅에서 그대로 행하게 하려 함인즉',5010),
('deu-4-6','deu','신명기',4,6,'너희는 지켜 행하라 이것이 여러 민족 앞에서 너희의 지혜요 너희의 지식이라 그들이 이 모든 규례를 듣고 이르기를 이 큰 나라 사람은 과연 지혜와 지식이 있는 백성이로다 하리라',5011),
('deu-4-7','deu','신명기',4,7,'우리 하나님 여호와께서 우리가 그에게 기도할 때마다 우리에게 가까이 하심과 같이 그 신이 가까이 함을 얻은 큰 나라가 어디 있느냐',5012),
('deu-4-8','deu','신명기',4,8,'오늘 내가 너희에게 선포하는 이 율법과 같이 그 규례와 법도가 공의로운 큰 나라가 어디 있느냐',5013),
('deu-4-9','deu','신명기',4,9,'오직 너는 스스로 삼가며 네 마음을 힘써 지키라 그리하여 네가 눈으로 본 그 일을 잊어버리지 말라 네가 생존하는 날 동안에 그 일들이 네 마음에서 떠나지 않도록 조심하라 너는 그 일들을 네 아들들과 네 손자들에게 알게 하라',5014),
('deu-4-10','deu','신명기',4,10,'네가 호렙 산에서 네 하나님 여호와 앞에 섰던 날에 여호와께서 내게 이르시기를 나에게 백성을 모으라 내가 그들에게 내 말을 들려주어 그들이 세상에 사는 날 동안 나를 경외함을 배우게 하며 그 자녀에게 가르치게 하리라 하시매',5015),
('deu-4-11','deu','신명기',4,11,'너희가 가까이 나아와서 산 아래에 서니 그 산에 불이 붙어 불길이 충천하고 어둠과 구름과 흑암이 덮였는데',5016),
('deu-4-12','deu','신명기',4,12,'여호와께서 불길 중에서 너희에게 말씀하시되 음성뿐이므로 너희가 그 말소리만 듣고 형상은 보지 못하였느니라',5017),
('deu-4-13','deu','신명기',4,13,'여호와께서 그의 언약을 너희에게 반포하시고 너희에게 지키라 명령하셨으니 곧 십계명이며 두 돌판에 친히 쓰신 것이라',5018),
('deu-4-14','deu','신명기',4,14,'그 때에 여호와께서 내게 명령하사 너희에게 규례와 법도를 교훈하게 하셨나니 이는 너희가 거기로 건너가 받을 땅에서 행하게 하려 하심이니라',5019),
('deu-4-15','deu','신명기',4,15,'여호와께서 호렙 산 불길 중에서 너희에게 말씀하시던 날에 너희가 어떤 형상도 보지 못하였은즉 너희는 깊이 삼가라',5020),
('deu-4-16','deu','신명기',4,16,'그리하여 스스로 부패하여 자기를 위해 어떤 형상대로든지 우상을 새겨 만들지 말라 남자의 형상이든지, 여자의 형상이든지,',5021),
('deu-4-17','deu','신명기',4,17,'땅 위에 있는 어떤 짐승의 형상이든지, 하늘을 나는 날개 가진 어떤 새의 형상이든지,',5022),
('deu-4-18','deu','신명기',4,18,'땅 위에 기는 어떤 곤충의 형상이든지, 땅 아래 물 속에 있는 어떤 어족의 형상이든지 만들지 말라',5023),
('deu-4-19','deu','신명기',4,19,'또 그리하여 네가 하늘을 향하여 눈을 들어 해와 달과 별들, 하늘 위의 모든 천체 곧 너희의 하나님 여호와께서 천하 만민을 위하여 배정하신 것을 보고 미혹하여 그것에 경배하며 섬기지 말라',5024),
('deu-4-20','deu','신명기',4,20,'여호와께서 너희를 택하시고 너희를 쇠 풀무불 곧 애굽에서 인도하여 내사 자기 기업의 백성을 삼으신 것이 오늘과 같아도',5025),
('deu-4-21','deu','신명기',4,21,'여호와께서 너희로 말미암아 내게 진노하사 내게 요단을 건너지 못하며 네 하나님 여호와께서 네게 기업으로 주신 그 아름다운 땅에 들어가지 못하게 하리라고 맹세하셨은즉',5026),
('deu-4-22','deu','신명기',4,22,'나는 이 땅에서 죽고 요단을 건너지 못하려니와 너희는 건너가서 그 아름다운 땅을 얻으리니',5027),
('deu-4-23','deu','신명기',4,23,'너희는 스스로 삼가 너희의 하나님 여호와께서 너희와 세우신 언약을 잊지 말고 네 하나님 여호와께서 금하신 어떤 형상의 우상도 조각하지 말라',5028),
('deu-4-24','deu','신명기',4,24,'네 하나님 여호와는 소멸하는 불이시요 질투하시는 하나님이시니라',5029),
('deu-4-25','deu','신명기',4,25,'네가 그 땅에서 아들을 낳고 손자를 얻으며 오래 살 때에 만일 스스로 부패하여 무슨 형상의 우상이든지 조각하여 네 하나님 여호와 앞에 악을 행함으로 그의 노를 일으키면',5030),
('deu-4-26','deu','신명기',4,26,'내가 오늘 천지를 불러 증거를 삼노니 너희가 요단을 건너가서 얻는 땅에서 속히 망할 것이라 너희가 거기서 너희의 날이 길지 못하고 전멸될 것이니라',5031),
('deu-4-27','deu','신명기',4,27,'여호와께서 너희를 여러 민족 중에 흩으실 것이요 여호와께서 너희를 쫓아 보내실 그 여러 민족 중에 너희의 남은 수가 많지 못할 것이며',5032),
('deu-4-28','deu','신명기',4,28,'너희는 거기서 사람의 손으로 만든 바 보지도 못하며 듣지도 못하며 먹지도 못하며 냄새도 맡지 못하는 목석의 신들을 섬기리라',5033),
('deu-4-29','deu','신명기',4,29,'그러나 네가 거기서 네 하나님 여호와를 찾게 되리니 만일 마음을 다하고 뜻을 다하여 그를 찾으면 만나리라',5034),
('deu-4-30','deu','신명기',4,30,'이 모든 일이 네게 임하여 환난을 당하다가 끝날에 네가 네 하나님 여호와께로 돌아와서 그의 말씀을 청종하리니',5035),
('deu-4-31','deu','신명기',4,31,'네 하나님 여호와는 자비하신 하나님이심이라 그가 너를 버리지 아니하시며 너를 멸하지 아니하시며 네 조상들에게 맹세하신 언약을 잊지 아니하시리라',5036),
('deu-4-32','deu','신명기',4,32,'네가 있기 전 하나님이 사람을 세상에 창조하신 날부터 지금까지 지나간 날을 상고하여 보라 하늘 이 끝에서 저 끝까지 이런 큰 일이 있었느냐 이런 일을 들은 적이 있었느냐',5037),
('deu-4-33','deu','신명기',4,33,'어떤 국민이 불 가운데에서 말씀하시는 하나님의 음성을 너처럼 듣고 생존하였느냐',5038),
('deu-4-34','deu','신명기',4,34,'어떤 신이 와서 시험과 이적과 기사와 전쟁과 강한 손과 편 팔과 크게 두려운 일로 한 민족을 다른 민족에게서 인도하여 낸 일이 있느냐 이는 다 너희의 하나님 여호와께서 애굽에서 너희를 위하여 너희의 목전에서 행하신 일이라',5039),
('deu-4-35','deu','신명기',4,35,'이것을 네게 나타내심은 여호와는 하나님이시요 그 외에는 다른 신이 없음을 네게 알게 하려 하심이니라',5040),
('deu-4-36','deu','신명기',4,36,'여호와께서 너를 교훈하시려고 하늘에서부터 그의 음성을 네게 듣게 하시며 땅에서는 그의 큰 불을 네게 보이시고 네가 불 가운데서 나오는 그의 말씀을 듣게 하셨느니라',5041),
('deu-4-37','deu','신명기',4,37,'여호와께서 네 조상들을 사랑하신 고로 그 후손인 너를 택하시고 큰 권능으로 친히 인도하여 애굽에서 나오게 하시며',5042),
('deu-4-38','deu','신명기',4,38,'너보다 강대한 여러 민족을 네 앞에서 쫓아내고 너를 그들의 땅으로 인도하여 들여서 그것을 네게 기업으로 주려 하심이 오늘과 같으니라',5043),
('deu-4-39','deu','신명기',4,39,'그런즉 너는 오늘 위로 하늘에나 아래로 땅에 오직 여호와는 하나님이시요 다른 신이 없는 줄을 알아 명심하고',5044),
('deu-4-40','deu','신명기',4,40,'오늘 내가 네게 명령하는 여호와의 규례와 명령을 지키라 너와 네 후손이 복을 받아 네 하나님 여호와께서 네게 주시는 땅에서 한 없이 오래 살리라',5045),
('deu-4-41','deu','신명기',4,41,'그 때에 모세가 요단 이쪽 해 돋는 쪽에서 세 성읍을 구별하였으니',5046),
('deu-4-42','deu','신명기',4,42,'이는 과거에 원한이 없이 부지중에 살인한 자가 그 곳으로 도피하게 하기 위함이며 그 중 한 성읍으로 도피한 자가 그의 생명을 보전하게 하기 위함이라',5047),
('deu-4-43','deu','신명기',4,43,'하나는 광야 평원에 있는 베셀이라 르우벤 지파를 위한 것이요 하나는 길르앗 라못이라 갓 지파를 위한 것이요 하나는 바산 골란이라 므낫세 지파를 위한 것이었더라',5048),
('deu-4-44','deu','신명기',4,44,'모세가 이스라엘 자손에게 선포한 율법은 이러하니라',5049),
('deu-4-45','deu','신명기',4,45,'이스라엘 자손이 애굽에서 나온 후에 모세가 증언과 규례와 법도를 선포하였으니',5050),
('deu-4-46','deu','신명기',4,46,'요단 동쪽 벳브올 맞은편 골짜기에서 그리하였더라 이 땅은 헤스본에 사는 아모리 족속의 왕 시혼에게 속하였더니 모세와 이스라엘 자손이 애굽에서 나온 후에 그를 쳐서 멸하고',5051),
('deu-4-47','deu','신명기',4,47,'그 땅을 기업으로 얻었고 또 바산 왕 옥의 땅을 얻었으니 그 두 사람은 아모리 족속의 왕으로서 요단 이쪽 해 돋는 쪽에 살았으며',5052),
('deu-4-48','deu','신명기',4,48,'그 얻은 땅은 아르논 골짜기 가장자리의 아로엘에서부터 시온 산 곧 헤르몬 산까지요',5053),
('deu-4-49','deu','신명기',4,49,'요단 이쪽 곧 그 동쪽 온 아라바니 비스가 기슭 아래 아라바의 바다까지이니라',5054),
('deu-5-1','deu','신명기',5,1,'모세가 온 이스라엘을 불러 그들에게 이르되 이스라엘아 오늘 내가 너희의 귀에 말하는 규례와 법도를 듣고 그것을 배우며 지켜 행하라',5055),
('deu-5-2','deu','신명기',5,2,'우리 하나님 여호와께서 호렙 산에서 우리와 언약을 세우셨나니',5056),
('deu-5-3','deu','신명기',5,3,'이 언약은 여호와께서 우리 조상들과 세우신 것이 아니요 오늘 여기 살아 있는 우리 곧 우리와 세우신 것이라',5057),
('deu-5-4','deu','신명기',5,4,'여호와께서 산 위 불 가운데에서 너희와 대면하여 말씀하시매',5058),
('deu-5-5','deu','신명기',5,5,'그 때에 너희가 불을 두려워하여 산에 오르지 못하므로 내가 여호와와 너희 중간에 서서 여호와의 말씀을 너희에게 전하였노라 여호와께서 이르시되',5059),
('deu-5-6','deu','신명기',5,6,'나는 너를 애굽 땅, 종 되었던 집에서 인도하여 낸 네 하나님 여호와라',5060),
('deu-5-7','deu','신명기',5,7,'나 외에는 다른 신들을 네게 두지 말지니라',5061),
('deu-5-8','deu','신명기',5,8,'너는 자기를 위하여 새긴 우상을 만들지 말고 위로 하늘에 있는 것이나 아래로 땅에 있는 것이나 땅밑 물 속에 있는 것의 어떤 형상도 만들지 말며',5062),
('deu-5-9','deu','신명기',5,9,'그것들에게 절하지 말며 그것들을 섬기지 말라 나 네 하나님 여호와는 질투하는 하나님인즉 나를 미워하는 자의 죄를 갚되 아버지로부터 아들에게로 삼사 대까지 이르게 하거니와',5063),
('deu-5-10','deu','신명기',5,10,'나를 사랑하고 내 계명을 지키는 자에게는 천 대까지 은혜를 베푸느니라',5064),
('deu-5-11','deu','신명기',5,11,'너는 네 하나님 여호와의 이름을 망령되이 일컫지 말라 나 여호와는 내 이름을 망령되이 일컫는 자를 죄 없는 줄로 인정하지 아니하리라',5065),
('deu-5-12','deu','신명기',5,12,'네 하나님 여호와가 네게 명령한 대로 안식일을 지켜 거룩하게 하라',5066),
('deu-5-13','deu','신명기',5,13,'엿새 동안은 힘써 네 모든 일을 행할 것이나',5067),
('deu-5-14','deu','신명기',5,14,'일곱째 날은 네 하나님 여호와의 안식일인즉 너나 네 아들이나 네 딸이나 네 남종이나 네 여종이나 네 소나 네 나귀나 네 모든 가축이나 네 문 안에 유하는 객이라도 아무 일도 하지 못하게 하고 네 남종이나 네 여종에게 너 같이 안식하게 할지니라',5068),
('deu-5-15','deu','신명기',5,15,'너는 기억하라 네가 애굽 땅에서 종이 되었더니 네 하나님 여호와가 강한 손과 편 팔로 거기서 너를 인도하여 내었나니 그러므로 네 하나님 여호와가 네게 명령하여 안식일을 지키라 하느니라',5069),
('deu-5-16','deu','신명기',5,16,'너는 네 하나님 여호와께서 명령한 대로 네 부모를 공경하라 그리하면 네 하나님 여호와가 네게 준 땅에서 네 생명이 길고 복을 누리리라',5070),
('deu-5-17','deu','신명기',5,17,'살인하지 말지니라',5071),
('deu-5-18','deu','신명기',5,18,'간음하지 말지니라',5072),
('deu-5-19','deu','신명기',5,19,'도둑질 하지 말지니라',5073),
('deu-5-20','deu','신명기',5,20,'네 이웃에 대하여 거짓 증거하지 말지니라',5074),
('deu-5-21','deu','신명기',5,21,'네 이웃의 아내를 탐내지 말지니라 네 이웃의 집이나 그의 밭이나 그의 남종이나 그의 여종이나 그의 소나 그의 나귀나 네 이웃의 모든 소유를 탐내지 말지니라',5075),
('deu-5-22','deu','신명기',5,22,'여호와께서 이 모든 말씀을 산 위 불 가운데, 구름 가운데, 흑암 가운데에서 큰 음성으로 너희 총회에 이르신 후에 더 말씀하지 아니하시고 그것을 두 돌판에 써서 내게 주셨느니라',5076),
('deu-5-23','deu','신명기',5,23,'산이 불에 타며 캄캄한 가운데에서 나오는 그 소리를 너희가 듣고 너희 지파의 수령과 장로들이 내게 나아와',5077),
('deu-5-24','deu','신명기',5,24,'말하되 우리 하나님 여호와께서 그의 영광과 위엄을 우리에게 보이시매 불 가운데에서 나오는 음성을 우리가 들었고 하나님이 사람과 말씀하시되 그 사람이 생존하는 것을 오늘 우리가 보았나이다',5078),
('deu-5-25','deu','신명기',5,25,'이제 우리가 죽을 까닭이 무엇이니이까 이 큰 불이 우리를 삼킬 것이요 만일 우리가 우리 하나님 여호와의 음성을 다시 들으면 죽을 것이라',5079),
('deu-5-26','deu','신명기',5,26,'육신을 가진 자로서 우리처럼 살아 계시는 하나님의 음성이 불 가운데에서 발함을 듣고 생존한 자가 누구니이까',5080),
('deu-5-27','deu','신명기',5,27,'당신은 가까이 나아가서 우리 하나님 여호와께서 하시는 말씀을 다 듣고 우리 하나님 여호와께서 당신에게 이르시는 것을 다 우리에게 전하소서 우리가 듣고 행하겠나이다 하였느니라',5081),
('deu-5-28','deu','신명기',5,28,'여호와께서 너희가 내게 말할 때에 너희가 말하는 소리를 들으신지라 여호와께서 내게 이르시되 이 백성이 네게 말하는 그 말소리를 내가 들은즉 그 말이 다 옳도다',5082),
('deu-5-29','deu','신명기',5,29,'다만 그들이 항상 이같은 마음을 품어 나를 경외하며 내 모든 명령을 지켜서 그들과 그 자손이 영원히 복 받기를 원하노라',5083),
('deu-5-30','deu','신명기',5,30,'가서 그들에게 각기 장막으로 돌아가라 이르고',5084),
('deu-5-31','deu','신명기',5,31,'너는 여기 내 곁에 서 있으라 내가 모든 명령과 규례와 법도를 네게 이르리니 너는 그것을 그들에게 가르쳐서 내가 그들에게 기업으로 주는 땅에서 그들에게 이것을 행하게 하라 하셨나니',5085),
('deu-5-32','deu','신명기',5,32,'그런즉 너희 하나님 여호와께서 너희에게 명령하신 대로 너희는 삼가 행하여 좌로나 우로나 치우치지 말고',5086),
('deu-5-33','deu','신명기',5,33,'너희 하나님 여호와께서 너희에게 명령하신 모든 도를 행하라 그리하면 너희가 살 것이요 복이 너희에게 있을 것이며 너희가 차지한 땅에서 너희의 날이 길리라',5087),
('deu-6-1','deu','신명기',6,1,'이는 곧 너희의 하나님 여호와께서 너희에게 가르치라고 명하신 명령과 규례와 법도라 너희가 건너가서 차지할 땅에서 행할 것이니',5088),
('deu-6-2','deu','신명기',6,2,'곧 너와 네 아들과 네 손자들이 평생에 네 하나님 여호와를 경외하며 내가 너희에게 명한 그 모든 규례와 명령을 지키게 하기 위한 것이며 또 네 날을 장구하게 하기 위한 것이라',5089),
('deu-6-3','deu','신명기',6,3,'이스라엘아 듣고 삼가 그것을 행하라 그리하면 네가 복을 받고 네 조상들의 하나님 여호와께서 네게 허락하심 같이 젖과 꿀이 흐르는 땅에서 네가 크게 번성하리라',5090),
('deu-6-4','deu','신명기',6,4,'이스라엘아 들으라 우리 하나님 여호와는 오직 유일한 여호와이시니',5091),
('deu-6-5','deu','신명기',6,5,'너는 마음을 다하고 뜻을 다하고 힘을 다하여 네 하나님 여호와를 사랑하라',5092),
('deu-6-6','deu','신명기',6,6,'오늘 내가 네게 명하는 이 말씀을 너는 마음에 새기고',5093),
('deu-6-7','deu','신명기',6,7,'네 자녀에게 부지런히 가르치며 집에 앉았을 때에든지 길을 갈 때에든지 누워 있을 때에든지 일어날 때에든지 이 말씀을 강론할 것이며',5094),
('deu-6-8','deu','신명기',6,8,'너는 또 그것을 네 손목에 매어 기호를 삼으며 네 미간에 붙여 표로 삼고',5095),
('deu-6-9','deu','신명기',6,9,'또 네 집 문설주와 바깥 문에 기록할지니라',5096),
('deu-6-10','deu','신명기',6,10,'네 하나님 여호와께서 네 조상 아브라함과 이삭과 야곱을 향하여 네게 주리라 맹세하신 땅으로 너를 들어가게 하시고 네가 건축하지 아니한 크고 아름다운 성읍을 얻게 하시며',5097),
('deu-6-11','deu','신명기',6,11,'네가 채우지 아니한 아름다운 물건이 가득한 집을 얻게 하시며 네가 파지 아니한 우물을 차지하게 하시며 네가 심지 아니한 포도원과 감람나무를 차지하게 하사 네게 배불리 먹게 하실 때에',5098),
('deu-6-12','deu','신명기',6,12,'너는 조심하여 너를 애굽 땅 종 되었던 집에서 인도하여 내신 여호와를 잊지 말고',5099),
('deu-6-13','deu','신명기',6,13,'네 하나님 여호와를 경외하며 그를 섬기며 그의 이름으로 맹세할 것이니라',5100),
('deu-6-14','deu','신명기',6,14,'너희는 다른 신들 곧 네 사면에 있는 백성의 신들을 따르지 말라',5101),
('deu-6-15','deu','신명기',6,15,'너희 중에 계신 너희의 하나님 여호와는 질투하시는 하나님이신즉 너희의 하나님 여호와께서 네게 진노하사 너를 지면에서 멸절시키실까 두려워하노라',5102),
('deu-6-16','deu','신명기',6,16,'너희가 맛사에서 시험한 것 같이 너희의 하나님 여호와를 시험하지 말고',5103),
('deu-6-17','deu','신명기',6,17,'너희의 하나님 여호와께서 너희에게 명하신 명령과 증거와 규례를 삼가 지키며',5104),
('deu-6-18','deu','신명기',6,18,'여호와께서 보시기에 정직하고 선량한 일을 행하라 그리하면 네가 복을 받고 그 땅에 들어가서 여호와께서 모든 대적을 네 앞에서 쫓아내시겠다고 네 조상들에게 맹세하신 아름다운 땅을 차지하리니 여호와의 말씀과 같으니라',5105),
('deu-6-19','deu','신명기',6,19,'여호와께서 보시기에 정직하고 선량한 일을 행하라 그리하면 네가 복을 받고 그 땅에 들어가서 여호와께서 모든 대적을 네 앞에서 쫓아내시겠다고 네 조상들에게 맹세하신 아름다운 땅을 차지하리니 여호와의 말씀과 같으니라',5106),
('deu-6-20','deu','신명기',6,20,'후일에 네 아들이 네게 묻기를 우리 하나님 여호와께서 명령하신 증거와 규례와 법도가 무슨 뜻이냐 하거든',5107),
('deu-6-21','deu','신명기',6,21,'너는 네 아들에게 이르기를 우리가 옛적에 애굽에서 바로의 종이 되었더니 여호와께서 권능의 손으로 우리를 애굽에서 인도하여 내셨나니',5108),
('deu-6-22','deu','신명기',6,22,'곧 여호와께서 우리의 목전에서 크고 두려운 이적과 기사를 애굽과 바로와 그의 온 집에 베푸시고',5109),
('deu-6-23','deu','신명기',6,23,'우리 조상들에게 맹세하신 땅을 우리에게 주어 들어가게 하시려고 우리를 거기서 인도하여 내시고',5110),
('deu-6-24','deu','신명기',6,24,'여호와께서 우리에게 이 모든 규례를 지키라 명령하셨으니 이는 우리가 우리 하나님 여호와를 경외하여 항상 복을 누리게 하기 위하심이며 또 여호와께서 우리를 오늘과 같이 살게 하려 하심이라',5111),
('deu-6-25','deu','신명기',6,25,'우리가 그 명령하신 대로 이 모든 명령을 우리 하나님 여호와 앞에서 삼가 지키면 그것이 곧 우리의 의로움이니라 할지니라',5112),
('deu-7-1','deu','신명기',7,1,'네 하나님 여호와께서 너를 인도하사 네가 가서 차지할 땅으로 들이시고 네 앞에서 여러 민족 헷 족속과 기르가스 족속과 아모리 족속과 가나안 족속과 브리스 족속과 히위 족속과 여부스 족속 곧 너보다 많고 힘이 센 일곱 족속을 쫓아내실 때에',5113),
('deu-7-2','deu','신명기',7,2,'네 하나님 여호와께서 그들을 네게 넘겨 네게 치게 하시리니 그 때에 너는 그들을 진멸할 것이라 그들과 어떤 언약도 하지 말 것이요 그들을 불쌍히 여기지도 말 것이며',5114),
('deu-7-3','deu','신명기',7,3,'또 그들과 혼인하지도 말지니 네 딸을 그들의 아들에게 주지 말 것이요 그들의 딸도 네 며느리로 삼지 말 것은',5115),
('deu-7-4','deu','신명기',7,4,'그가 네 아들을 유혹하여 그가 여호와를 떠나고 다른 신들을 섬기게 하므로 여호와께서 너희에게 진노하사 갑자기 너희를 멸하실 것임이니라',5116),
('deu-7-5','deu','신명기',7,5,'오직 너희가 그들에게 행할 것은 이러하니 그들의 제단을 헐며 주상을 깨뜨리며 아세라 목상을 찍으며 조각한 우상들을 불사를 것이니라',5117),
('deu-7-6','deu','신명기',7,6,'너는 여호와 네 하나님의 성민이라 네 하나님 여호와께서 지상 만민 중에서 너를 자기 기업의 백성으로 택하셨나니',5118),
('deu-7-7','deu','신명기',7,7,'여호와께서 너희를 기뻐하시고 너희를 택하심은 너희가 다른 민족보다 수효가 많기 때문이 아니니라 너희는 오히려 모든 민족 중에 가장 적으니라',5119),
('deu-7-8','deu','신명기',7,8,'여호와께서 다만 너희를 사랑하심으로 말미암아, 또는 너희의 조상들에게 하신 맹세를 지키려 하심으로 말미암아 자기의 권능의 손으로 너희를 인도하여 내시되 너희를 그 종 되었던 집에서 애굽 왕 바로의 손에서 속량하셨나니',5120),
('deu-7-9','deu','신명기',7,9,'그런즉 너는 알라 오직 네 하나님 여호와는 하나님이시요 신실하신 하나님이시라 그를 사랑하고 그의 계명을 지키는 자에게는 천 대까지 그의 언약을 이행하시며 인애를 베푸시되',5121),
('deu-7-10','deu','신명기',7,10,'그를 미워하는 자에게는 당장에 보응하여 멸하시나니 여호와는 자기를 미워하는 자에게 지체하지 아니하시고 당장에 그에게 보응하시느니라',5122),
('deu-7-11','deu','신명기',7,11,'그런즉 너는 오늘 내가 네게 명하는 명령과 규례와 법도를 지켜 행할지니라',5123),
('deu-7-12','deu','신명기',7,12,'너희가 이 모든 법도를 듣고 지켜 행하면 네 하나님 여호와께서 네 조상들에게 맹세하신 언약을 지켜 네게 인애를 베푸실 것이라',5124),
('deu-7-13','deu','신명기',7,13,'곧 너를 사랑하시고 복을 주사 너를 번성하게 하시되 네게 주리라고 네 조상들에게 맹세하신 땅에서 네 소생에게 은혜를 베푸시며 네 토지 소산과 곡식과 포도주와 기름을 풍성하게 하시고 네 소와 양을 번식하게 하시리니',5125),
('deu-7-14','deu','신명기',7,14,'네가 복을 받음이 만민보다 훨씬 더하여 너희 중의 남녀와 너희의 짐승의 암수에 생육하지 못함이 없을 것이며',5126),
('deu-7-15','deu','신명기',7,15,'여호와께서 또 모든 질병을 네게서 멀리 하사 너희가 아는 애굽의 악질에 걸리지 않게 하시고 너를 미워하는 모든 자에게 걸리게 하실 것이라',5127),
('deu-7-16','deu','신명기',7,16,'네 하나님 여호와께서 네게 넘겨주신 모든 민족을 네 눈이 긍휼히 여기지 말고 진멸하며 그들의 신을 섬기지 말라 그것이 네게 올무가 되리라',5128),
('deu-7-17','deu','신명기',7,17,'네가 혹시 심중에 이르기를 이 민족들이 나보다 많으니 내가 어찌 그를 쫓아낼 수 있으리요 하리라마는',5129),
('deu-7-18','deu','신명기',7,18,'그들을 두려워하지 말고 네 하나님 여호와께서 바로와 온 애굽에 행하신 것을 잘 기억하되',5130),
('deu-7-19','deu','신명기',7,19,'네 하나님 여호와께서 너를 인도하여 내실 때에 네가 본 큰 시험과 이적과 기사와 강한 손과 편 팔을 기억하라 네 하나님 여호와께서 네가 두려워하는 모든 민족에게 그와 같이 행하실 것이요',5131),
('deu-7-20','deu','신명기',7,20,'네 하나님 여호와께서 또 왕벌을 그들 중에 보내어 그들의 남은 자와 너를 피하여 숨은 자를 멸하시리니',5132),
('deu-7-21','deu','신명기',7,21,'너는 그들을 두려워하지 말라 너희의 하나님 여호와 곧 크고 두려운 하나님이 너희 중에 계심이니라',5133),
('deu-7-22','deu','신명기',7,22,'네 하나님 여호와께서 이 민족들을 네 앞에서 조금씩 쫓아내시리니 너는 그들을 급히 멸하지 말라 들짐승이 번성하여 너를 해할까 하노라',5134),
('deu-7-23','deu','신명기',7,23,'네 하나님 여호와께서 그들을 네게 넘기시고 그들을 크게 혼란하게 하여 마침내 진멸하시고',5135),
('deu-7-24','deu','신명기',7,24,'그들의 왕들을 네 손에 넘기시리니 너는 그들의 이름을 천하에서 제하여 버리라 너를 당할 자가 없이 네가 마침내 그들을 진멸하리라',5136),
('deu-7-25','deu','신명기',7,25,'너는 그들이 조각한 신상들을 불사르고 그것에 입힌 은이나 금을 탐내지 말며 취하지 말라 네가 그것으로 말미암아 올무에 걸릴까 하노니 이는 네 하나님 여호와께서 가증히 여기시는 것임이니라',5137),
('deu-7-26','deu','신명기',7,26,'너는 가증한 것을 네 집에 들이지 말라 너도 그것과 같이 진멸 당할까 하노라 너는 그것을 멀리하며 심히 미워하라 그것은 진멸 당할 것임이니라',5138),
('deu-8-1','deu','신명기',8,1,'내가 오늘 명하는 모든 명령을 너희는 지켜 행하라 그리하면 너희가 살고 번성하고 여호와께서 너희의 조상들에게 맹세하신 땅에 들어가서 그것을 차지하리라',5139),
('deu-8-2','deu','신명기',8,2,'네 하나님 여호와께서 이 사십 년 동안에 네게 광야 길을 걷게 하신 것을 기억하라 이는 너를 낮추시며 너를 시험하사 네 마음이 어떠한지 그 명령을 지키는지 지키지 않는지 알려 하심이라',5140),
('deu-8-3','deu','신명기',8,3,'너를 낮추시며 너를 주리게 하시며 또 너도 알지 못하며 네 조상들도 알지 못하던 만나를 네게 먹이신 것은 사람이 떡으로만 사는 것이 아니요 여호와의 입에서 나오는 모든 말씀으로 사는 줄을 네가 알게 하려 하심이니라',5141),
('deu-8-4','deu','신명기',8,4,'이 사십 년 동안에 네 의복이 해어지지 아니하였고 네 발이 부르트지 아니하였느니라',5142),
('deu-8-5','deu','신명기',8,5,'너는 사람이 그 아들을 징계함 같이 네 하나님 여호와께서 너를 징계하시는 줄 마음에 생각하고',5143),
('deu-8-6','deu','신명기',8,6,'네 하나님 여호와의 명령을 지켜 그의 길을 따라가며 그를 경외할지니라',5144),
('deu-8-7','deu','신명기',8,7,'네 하나님 여호와께서 너를 아름다운 땅에 이르게 하시나니 그 곳은 골짜기든지 산지든지 시내와 분천과 샘이 흐르고',5145),
('deu-8-8','deu','신명기',8,8,'밀과 보리의 소산지요 포도와 무화과와 석류와 감람나무와 꿀의 소산지라',5146),
('deu-8-9','deu','신명기',8,9,'네가 먹을 것에 모자람이 없고 네게 아무 부족함이 없는 땅이며 그 땅의 돌은 철이요 산에서는 동을 캘 것이라',5147),
('deu-8-10','deu','신명기',8,10,'네가 먹어서 배부르고 네 하나님 여호와께서 옥토를 네게 주셨음으로 말미암아 그를 찬송하리라',5148),
('deu-8-11','deu','신명기',8,11,'내가 오늘 네게 명하는 여호와의 명령과 법도와 규례를 지키지 아니하고 네 하나님 여호와를 잊어버리지 않도록 삼갈지어다',5149),
('deu-8-12','deu','신명기',8,12,'네가 먹어서 배부르고 아름다운 집을 짓고 거주하게 되며',5150),
('deu-8-13','deu','신명기',8,13,'또 네 소와 양이 번성하며 네 은금이 증식되며 네 소유가 다 풍부하게 될 때에',5151),
('deu-8-14','deu','신명기',8,14,'네 마음이 교만하여 네 하나님 여호와를 잊어버릴까 염려하노라 여호와는 너를 애굽 땅 종 되었던 집에서 이끌어 내시고',5152),
('deu-8-15','deu','신명기',8,15,'너를 인도하여 그 광대하고 위험한 광야 곧 불뱀과 전갈이 있고 물이 없는 간조한 땅을 지나게 하셨으며 또 너를 위하여 단단한 반석에서 물을 내셨으며',5153),
('deu-8-16','deu','신명기',8,16,'네 조상들도 알지 못하던 만나를 광야에서 네게 먹이셨나니 이는 다 너를 낮추시며 너를 시험하사 마침내 네게 복을 주려 하심이었느니라',5154),
('deu-8-17','deu','신명기',8,17,'그러나 네가 마음에 이르기를 내 능력과 내 손의 힘으로 내가 이 재물을 얻었다 말할 것이라',5155),
('deu-8-18','deu','신명기',8,18,'네 하나님 여호와를 기억하라 그가 네게 재물 얻을 능력을 주셨음이라 이같이 하심은 네 조상들에게 맹세하신 언약을 오늘과 같이 이루려 하심이니라',5156),
('deu-8-19','deu','신명기',8,19,'네가 만일 네 하나님 여호와를 잊어버리고 다른 신들을 따라 그들을 섬기며 그들에게 절하면 내가 너희에게 증거하노니 너희가 반드시 멸망할 것이라',5157),
('deu-8-20','deu','신명기',8,20,'여호와께서 너희 앞에서 멸망시키신 민족들 같이 너희도 멸망하리니 이는 너희가 너희의 하나님 여호와의 소리를 청종하지 아니함이니라',5158),
('deu-9-1','deu','신명기',9,1,'이스라엘아 들으라 네가 오늘 요단을 건너 너보다 강대한 나라들로 들어가서 그것을 차지하리니 그 성읍들은 크고 성벽은 하늘에 닿았으며',5159),
('deu-9-2','deu','신명기',9,2,'크고 많은 백성은 네가 아는 아낙 자손이라 그에 대한 말을 네가 들었나니 이르기를 누가 아낙 자손을 능히 당하리요 하거니와',5160),
('deu-9-3','deu','신명기',9,3,'오늘 너는 알라 네 하나님 여호와께서 맹렬한 불과 같이 네 앞에 나아가신즉 여호와께서 그들을 멸하사 네 앞에 엎드러지게 하시리니 여호와께서 네게 말씀하신 것 같이 너는 그들을 쫓아내며 속히 멸할 것이라',5161),
('deu-9-4','deu','신명기',9,4,'네 하나님 여호와께서 그들을 네 앞에서 쫓아내신 후에 네가 심중에 이르기를 내 공의로움으로 말미암아 여호와께서 나를 이 땅으로 인도하여 들여서 그것을 차지하게 하셨다 하지 말라 이 민족들이 악함으로 말미암아 여호와께서 그들을 네 앞에서 쫓아내심이니라',5162),
('deu-9-5','deu','신명기',9,5,'네가 가서 그 땅을 차지함은 네 공의로 말미암음도 아니며 네 마음이 정직함으로 말미암음도 아니요 이 민족들이 악함으로 말미암아 네 하나님 여호와께서 그들을 네 앞에서 쫓아내심이라 여호와께서 이같이 하심은 네 조상 아브라함과 이삭과 야곱에게 하신 맹세를 이루려 하심이니라',5163),
('deu-9-6','deu','신명기',9,6,'그러므로 네가 알 것은 네 하나님 여호와께서 네게 이 아름다운 땅을 기업으로 주신 것이 네 공의로 말미암음이 아니니라 너는 목이 곧은 백성이니라',5164),
('deu-9-7','deu','신명기',9,7,'너는 광야에서 네 하나님 여호와를 격노하게 하던 일을 잊지 말고 기억하라 네가 애굽 땅에서 나오던 날부터 이 곳에 이르기까지 늘 여호와를 거역하였으되',5165),
('deu-9-8','deu','신명기',9,8,'호렙 산에서 너희가 여호와를 격노하게 하였으므로 여호와께서 진노하사 너희를 멸하려 하셨느니라',5166),
('deu-9-9','deu','신명기',9,9,'그 때에 내가 돌판들 곧 여호와께서 너희와 세우신 언약의 돌판들을 받으려고 산에 올라가서 사십 주 사십 야를 산에 머물며 떡도 먹지 아니하고 물도 마시지 아니하였더니',5167),
('deu-9-10','deu','신명기',9,10,'여호와께서 두 돌판을 내게 주셨나니 그 돌판의 글은 하나님이 손으로 기록하신 것이요 너희의 총회 날에 여호와께서 산상 불 가운데서 너희에게 이르신 모든 말씀이니라',5168),
('deu-9-11','deu','신명기',9,11,'사십 주 사십 야를 지난 후에 여호와께서 내게 돌판 곧 언약의 두 돌판을 주시고',5169),
('deu-9-12','deu','신명기',9,12,'내게 이르시되 일어나 여기서 속히 내려가라 네가 애굽에서 인도하여 낸 네 백성이 스스로 부패하여 내가 그들에게 명령한 도를 속히 떠나 자기를 위하여 우상을 부어 만들었느니라',5170),
('deu-9-13','deu','신명기',9,13,'여호와께서 또 내게 말씀하여 이르시되 내가 이 백성을 보았노라 보라 이는 목이 곧은 백성이니라',5171),
('deu-9-14','deu','신명기',9,14,'나를 막지 말라 내가 그들을 멸하여 그들의 이름을 천하에서 없애고 너를 그들보다 강대한 나라가 되게 하리라 하시기로',5172),
('deu-9-15','deu','신명기',9,15,'내가 돌이켜 산에서 내려오는데 산에는 불이 붙었고 언약의 두 돌판은 내 두 손에 있었느니라',5173),
('deu-9-16','deu','신명기',9,16,'내가 본즉 너희가 너희의 하나님 여호와께 범죄하여 자기를 위하여 송아지를 부어 만들어서 여호와께서 명령하신 도를 빨리 떠났기로',5174),
('deu-9-17','deu','신명기',9,17,'내가 그 두 돌판을 내 두 손으로 들어 던져 너희의 목전에서 깨뜨렸노라',5175),
('deu-9-18','deu','신명기',9,18,'그리고 내가 전과 같이 사십 주 사십 야를 여호와 앞에 엎드려서 떡도 먹지 아니하고 물도 마시지 아니하였으니 이는 너희가 여호와의 목전에 악을 행하여 그를 격노하게 하여 크게 죄를 지었음이라',5176),
('deu-9-19','deu','신명기',9,19,'여호와께서 심히 분노하사 너희를 멸하려 하셨으므로 내가 두려워하였노라 그러나 여호와께서 그 때에도 내 말을 들으셨고',5177),
('deu-9-20','deu','신명기',9,20,'여호와께서 또 아론에게 진노하사 그를 멸하려 하셨으므로 내가 그 때에도 아론을 위하여 기도하고',5178),
('deu-9-21','deu','신명기',9,21,'너희의 죄 곧 너희가 만든 송아지를 가져다가 불살라 찧고 티끌 같이 가늘게 갈아 그 가루를 산에서 흘러내리는 시내에 뿌렸느니라',5179),
('deu-9-22','deu','신명기',9,22,'너희가 다베라와 맛사와 기브롯 핫다아와에서도 여호와를 격노하게 하였느니라',5180),
('deu-9-23','deu','신명기',9,23,'여호와께서 너희를 가데스 바네아에서 떠나게 하실 때에 이르시기를 너희는 올라가서 내가 너희에게 준 땅을 차지하라 하시되 너희가 너희의 하나님 여호와의 명령을 거역하여 믿지 아니하고 그 말씀을 듣지 아니하였나니',5181),
('deu-9-24','deu','신명기',9,24,'내가 너희를 알던 날부터 너희가 항상 여호와를 거역하여 왔느니라',5182),
('deu-9-25','deu','신명기',9,25,'그 때에 여호와께서 너희를 멸하겠다 하셨으므로 내가 여전히 사십 주 사십 야를 여호와 앞에 엎드리고',5183),
('deu-9-26','deu','신명기',9,26,'여호와께 간구하여 이르되 주 여호와여 주께서 큰 위엄으로 속량하시고 강한 손으로 애굽에서 인도하여 내신 주의 백성 곧 주의 기업을 멸하지 마옵소서',5184),
('deu-9-27','deu','신명기',9,27,'주의 종 아브라함과 이삭과 야곱을 생각하사 이 백성의 완악함과 악과 죄를 보지 마옵소서',5185),
('deu-9-28','deu','신명기',9,28,'주께서 우리를 인도하여 내신 그 땅 백성이 말하기를 여호와께서 그들에게 허락하신 땅으로 그들을 인도하여 들일 만한 능력도 없고 그들을 미워하기도 하사 광야에서 죽이려고 인도하여 내셨다 할까 두려워하나이다',5186),
('deu-9-29','deu','신명기',9,29,'그들은 주의 큰 능력과 펴신 팔로 인도하여 내신 주의 백성 곧 주의 기업이로소이다 하였노라',5187),
('deu-10-1','deu','신명기',10,1,'그 때에 여호와께서 내게 이르시기를 너는 처음과 같은 두 돌판을 다듬어 가지고 산에 올라 내게로 나아오고 또 나무궤 하나를 만들라',5188),
('deu-10-2','deu','신명기',10,2,'네가 깨뜨린 처음 판에 쓴 말을 내가 그 판에 쓰리니 너는 그것을 그 궤에 넣으라 하시기로',5189),
('deu-10-3','deu','신명기',10,3,'내가 조각목으로 궤를 만들고 처음 것과 같은 돌판 둘을 다듬어 손에 들고 산에 오르매',5190),
('deu-10-4','deu','신명기',10,4,'여호와께서 그 총회 날에 산 위 불 가운데에서 너희에게 이르신 십계명을 처음과 같이 그 판에 쓰시고 그것을 내게 주시기로',5191),
('deu-10-5','deu','신명기',10,5,'내가 돌이켜 산에서 내려와서 여호와께서 내게 명령하신 대로 그 판을 내가 만든 궤에 넣었더니 지금까지 있느니라',5192),
('deu-10-6','deu','신명기',10,6,'(이스라엘 자손이 브에롯 브네야아간에서 길을 떠나 모세라에 이르러 아론이 거기서 죽어 장사되었고 그의 아들 엘르아살이 그를 이어 제사장의 직임을 행하였으며',5193),
('deu-10-7','deu','신명기',10,7,'또 거기를 떠나 굿고다에 이르고 굿고다를 떠나 욧바다에 이른즉 그 땅에는 시내가 많았으며',5194),
('deu-10-8','deu','신명기',10,8,'그 때에 여호와께서 레위 지파를 구별하여 여호와의 언약 궤를 메게 하며 여호와 앞에 서서 그를 섬기며 또 여호와의 이름으로 축복하게 하셨으니 그 일은 오늘까지 이르느니라',5195),
('deu-10-9','deu','신명기',10,9,'그러므로 레위는 그의 형제 중에 분깃이 없으며 기업이 없고 네 하나님 여호와께서 그에게 말씀하심 같이 여호와가 그의 기업이시니라)',5196),
('deu-10-10','deu','신명기',10,10,'내가 처음과 같이 사십 주 사십 야를 산에 머물렀고 그 때에도 여호와께서 내 말을 들으사 너를 참아 멸하지 아니하시고',5197),
('deu-10-11','deu','신명기',10,11,'여호와께서 내게 이르시되 일어나서 백성보다 먼저 길을 떠나라 내가 그들에게 주리라고 그들의 조상들에게 맹세한 땅에 그들이 들어가서 그것을 차지하리라 하셨느니라',5198),
('deu-10-12','deu','신명기',10,12,'이스라엘아 네 하나님 여호와께서 네게 요구하시는 것이 무엇이냐 곧 네 하나님 여호와를 경외하여 그의 모든 도를 행하고 그를 사랑하며 마음을 다하고 뜻을 다하여 네 하나님 여호와를 섬기고',5199),
('deu-10-13','deu','신명기',10,13,'내가 오늘 네 행복을 위하여 네게 명하는 여호와의 명령과 규례를 지킬 것이 아니냐',5200),
('deu-10-14','deu','신명기',10,14,'하늘과 모든 하늘의 하늘과 땅과 그 위의 만물은 본래 네 하나님 여호와께 속한 것이로되',5201),
('deu-10-15','deu','신명기',10,15,'여호와께서 오직 네 조상들을 기뻐하시고 그들을 사랑하사 그들의 후손인 너희를 만민 중에서 택하셨음이 오늘과 같으니라',5202),
('deu-10-16','deu','신명기',10,16,'그러므로 너희는 마음에 할례를 행하고 다시는 목을 곧게 하지 말라',5203),
('deu-10-17','deu','신명기',10,17,'너희의 하나님 여호와는 신 가운데 신이시며 주 가운데 주시요 크고 능하시며 두려우신 하나님이시라 사람을 외모로 보지 아니하시며 뇌물을 받지 아니하시고',5204),
('deu-10-18','deu','신명기',10,18,'고아와 과부를 위하여 정의를 행하시며 나그네를 사랑하여 그에게 떡과 옷을 주시나니',5205),
('deu-10-19','deu','신명기',10,19,'너희는 나그네를 사랑하라 전에 너희도 애굽 땅에서 나그네 되었음이니라',5206),
('deu-10-20','deu','신명기',10,20,'네 하나님 여호와를 경외하여 그를 섬기며 그에게 의지하고 그의 이름으로 맹세하라',5207),
('deu-10-21','deu','신명기',10,21,'그는 네 찬송이시요 네 하나님이시라 네 눈으로 본 이같이 크고 두려운 일을 너를 위하여 행하셨느니라',5208),
('deu-10-22','deu','신명기',10,22,'애굽에 내려간 네 조상들이 겨우 칠십 인이었으나 이제는 네 하나님 여호와께서 너를 하늘의 별 같이 많게 하셨느니라',5209),
('deu-11-1','deu','신명기',11,1,'그런즉 네 하나님 여호와를 사랑하여 그가 주신 책무와 법도와 규례와 명령을 항상 지키라',5210),
('deu-11-2','deu','신명기',11,2,'너희의 자녀는 알지도 못하고 보지도 못하였으나 너희가 오늘날 기억할 것은 너희의 하나님 여호와의 교훈과 그의 위엄과 그의 강한 손과 펴신 팔과',5211),
('deu-11-3','deu','신명기',11,3,'애굽에서 그 왕 바로와 그 전국에 행하신 이적과 기사와',5212),
