('deu-11-5','deu','신명기',11,5,'또 너희가 이 곳에 이르기까지 광야에서 너희에게 행하신 일과',5214),
('deu-11-6','deu','신명기',11,6,'르우벤 자손 엘리압의 아들 다단과 아비람에게 하신 일 곧 땅이 입을 벌려서 그들과 그들의 가족과 그들의 장막과 그들을 따르는 온 이스라엘의 한가운데에서 모든 것을 삼키게 하신 일이라',5215),
('deu-11-7','deu','신명기',11,7,'너희가 여호와께서 행하신 이 모든 큰 일을 너희의 눈으로 보았느니라',5216),
('deu-11-8','deu','신명기',11,8,'그러므로 너희는 내가 오늘 너희에게 명하는 모든 명령을 지키라 그리하면 너희가 강성할 것이요 너희가 건너가 차지할 땅에 들어가서 그것을 차지할 것이며',5217),
('deu-11-9','deu','신명기',11,9,'또 여호와께서 너희의 조상들에게 맹세하여 그들과 그들의 후손에게 주리라고 하신 땅 곧 젖과 꿀이 흐르는 땅에서 너희의 날이 장구하리라',5218),
('deu-11-10','deu','신명기',11,10,'네가 들어가 차지하려 하는 땅은 네가 나온 애굽 땅과 같지 아니하니 거기에서는 너희가 파종한 후에 발로 물 대기를 채소밭에 댐과 같이 하였거니와',5219),
('deu-11-11','deu','신명기',11,11,'너희가 건너가서 차지할 땅은 산과 골짜기가 있어서 하늘에서 내리는 비를 흡수하는 땅이요',5220),
('deu-11-12','deu','신명기',11,12,'네 하나님 여호와께서 돌보아 주시는 땅이라 연초부터 연말까지 네 하나님 여호와의 눈이 항상 그 위에 있느니라',5221),
('deu-11-13','deu','신명기',11,13,'내가 오늘 너희에게 명하는 내 명령을 너희가 만일 청종하고 너희의 하나님 여호와를 사랑하여 마음을 다하고 뜻을 다하여 섬기면',5222),
('deu-11-14','deu','신명기',11,14,'여호와께서 너희의 땅에 이른 비, 늦은 비를 적당한 때에 내리시리니 너희가 곡식과 포도주와 기름을 얻을 것이요',5223),
('deu-11-15','deu','신명기',11,15,'또 가축을 위하여 들에 풀이 나게 하시리니 네가 먹고 배부를 것이라',5224),
