('deu-11-18','deu','신명기',11,18,'이러므로 너희는 나의 이 말을 너희의 마음과 뜻에 두고 또 그것을 너희의 손목에 매어 기호를 삼고 너희 미간에 붙여 표를 삼으며',5227),
('deu-11-19','deu','신명기',11,19,'또 그것을 너희의 자녀에게 가르치며 집에 앉아 있을 때에든지, 길을 갈 때에든지, 누워 있을 때에든지, 일어날 때에든지 이 말씀을 강론하고',5228),
('deu-11-20','deu','신명기',11,20,'또 네 집 문설주와 바깥 문에 기록하라',5229),
('deu-11-21','deu','신명기',11,21,'그리하면 여호와께서 너희 조상들에게 주리라고 맹세하신 땅에서 너희의 날과 너희의 자녀의 날이 많아서 하늘이 땅을 덮는 날과 같으리라',5230),
('deu-11-22','deu','신명기',11,22,'너희가 만일 내가 너희에게 명하는 이 모든 명령을 잘 지켜 행하여 너희의 하나님 여호와를 사랑하고 그의 모든 도를 행하여 그에게 의지하면',5231),
('deu-11-23','deu','신명기',11,23,'여호와께서 그 모든 나라 백성을 너희 앞에서 다 쫓아내실 것이라 너희가 너희보다 강대한 나라들을 차지할 것인즉',5232),
('deu-11-24','deu','신명기',11,24,'너희의 발바닥으로 밟는 곳은 다 너희의 소유가 되리니 너희의 경계는 곧 광야에서부터 레바논까지와 유브라데 강에서부터 서해까지라',5233),
