('deu-11-29','deu','신명기',11,29,'네 하나님 여호와께서 네가 가서 차지할 땅으로 너를 인도하여 들이실 때에 너는 그리심 산에서 축복을 선포하고 에발 산에서 저주를 선포하라',5238),
('deu-11-30','deu','신명기',11,30,'이 두 산은 요단 강 저쪽 곧 해지는 쪽으로 가는 길 뒤 길갈 맞은편 모레 상수리나무 곁의 아라바에 거주하는 가나안 족속의 땅에 있지 아니하냐',5239),
('deu-11-31','deu','신명기',11,31,'너희가 요단을 건너 너희의 하나님 여호와께서 너희에게 주시는 땅에 들어가서 그 땅을 차지하려 하나니 반드시 그것을 차지하여 거기 거주할지라',5240),
('deu-11-32','deu','신명기',11,32,'내가 오늘 너희 앞에 베푸는 모든 규례와 법도를 너희는 지켜 행할지니라',5241),
('deu-12-1','deu','신명기',12,1,'네 조상의 하나님 여호와께서 네게 주셔서 차지하게 하신 땅에서 너희가 평생에 지켜 행할 규례와 법도는 이러하니라',5242),
('deu-12-2','deu','신명기',12,2,'너희가 쫓아낼 민족들이 그들의 신들을 섬기는 곳은 높은 산이든지 작은 산이든지 푸른 나무 아래든지를 막론하고 그 모든 곳을 너희가 마땅히 파멸하며',5243),
('deu-12-3','deu','신명기',12,3,'그 제단을 헐며 주상을 깨뜨리며 아세라 상을 불사르고 또 그 조각한 신상들을 찍어 그 이름을 그 곳에서 멸하라',5244),
('deu-12-4','deu','신명기',12,4,'너희의 하나님 여호와께는 너희가 그처럼 행하지 말고',5245),
('deu-12-5','deu','신명기',12,5,'오직 너희의 하나님 여호와께서 자기의 이름을 두시려고 너희 모든 지파 중에서 택하신 곳인 그 계실 곳으로 찾아 나아가서',5246),
('deu-12-6','deu','신명기',12,6,'너희의 번제와 너희의 제물과 너희의 십일조와 너희 손의 거제와 너희의 서원제와 낙헌 예물과 너희 소와 양의 처음 난 것들을 너희는 그리로 가져다가 드리고',5247),
('deu-12-7','deu','신명기',12,7,'거기 곧 너희의 하나님 여호와 앞에서 먹고 너희의 하나님 여호와께서 너희의 손으로 수고한 일에 복 주심으로 말미암아 너희와 너희의 가족이 즐거워할지니라',5248),
