('deu-12-9','deu','신명기',12,9,'너희가 너희 하나님 여호와께서 주시는 안식과 기업에 아직은 이르지 못하였거니와',5250),
('deu-12-10','deu','신명기',12,10,'너희가 요단을 건너 너희 하나님 여호와께서 너희에게 기업으로 주시는 땅에 거주하게 될 때 또는 여호와께서 너희에게 너희 주위의 모든 대적을 이기게 하시고 너희에게 안식을 주사 너희를 평안히 거주하게 하실 때에',5251),
