('deu-12-12','deu','신명기',12,12,'너희와 너희의 자녀와 노비와 함께 너희의 하나님 여호와 앞에서 즐거워할 것이요 네 성중에 있는 레위인과도 그리할지니 레위인은 너희 중에 분깃이나 기업이 없음이니라',5253),
('deu-12-13','deu','신명기',12,13,'너는 삼가서 네게 보이는 아무 곳에서나 번제를 드리지 말고',5254),
('deu-12-14','deu','신명기',12,14,'오직 너희의 한 지파 중에 여호와께서 택하실 그 곳에서 번제를 드리고 또 내가 네게 명령하는 모든 것을 거기서 행할지니라',5255),
('deu-12-15','deu','신명기',12,15,'그러나 네 하나님 여호와께서 네게 주신 복을 따라 각 성에서 네 마음에 원하는 대로 가축을 잡아 그 고기를 먹을 수 있나니 곧 정한 자나 부정한 자를 막론하고 노루나 사슴을 먹는 것 같이 먹으려니와',5256),
('deu-12-16','deu','신명기',12,16,'오직 그 피는 먹지 말고 물 같이 땅에 쏟을 것이며',5257),
