('deu-12-21','deu','신명기',12,21,'만일 네 하나님 여호와께서 자기 이름을 두시려고 택하신 곳이 네게서 멀거든 내가 네게 명령한 대로 너는 여호와께서 주신 소와 양을 잡아 네 각 성에서 네가 마음에 원하는 모든 것을 먹되',5262),
('deu-12-22','deu','신명기',12,22,'정한 자나 부정한 자를 막론하고 노루나 사슴을 먹는 것 같이 먹을 수 있거니와',5263),
('deu-12-23','deu','신명기',12,23,'다만 크게 삼가서 그 피는 먹지 말라 피는 그 생명인즉 네가 그 생명을 고기와 함께 먹지 못하리니',5264),
