('deu-12-28','deu','신명기',12,28,'내가 네게 명령하는 이 모든 말을 너는 듣고 지키라 네 하나님 여호와의 목전에 선과 의를 행하면 너와 네 후손에게 영구히 복이 있으리라',5269),
('deu-12-29','deu','신명기',12,29,'네 하나님 여호와께서 네가 들어가서 쫓아낼 그 민족들을 네 앞에서 멸절하시고 네가 그 땅을 차지하여 거기에 거주하게 하실 때에',5270),
