('deu-13-1','deu','신명기',13,1,'너희 중에 선지자나 꿈 꾸는 자가 일어나서 이적과 기사를 네게 보이고',5274),
('deu-13-2','deu','신명기',13,2,'그가 네게 말한 그 이적과 기사가 이루어지고 너희가 알지 못하던 다른 신들을 우리가 따라 섬기자고 말할지라도',5275),
('deu-13-3','deu','신명기',13,3,'너는 그 선지자나 꿈 꾸는 자의 말을 청종하지 말라 이는 너희의 하나님 여호와께서 너희가 마음을 다하고 뜻을 다하여 너희의 하나님 여호와를 사랑하는 여부를 알려 하사 너희를 시험하심이니라',5276),
('deu-13-4','deu','신명기',13,4,'너희는 너희의 하나님 여호와를 따르며 그를 경외하며 그의 명령을 지키며 그의 목소리를 청종하며 그를 섬기며 그를 의지하며',5277),
