('deu-13-7','deu','신명기',13,7,'곧 네 사방을 둘러싸고 있는 민족 혹 네게서 가깝든지 네게서 멀든지 땅 이 끝에서 저 끝까지에 있는 민족의 신들을 우리가 가서 섬기자 할지라도',5280),
('deu-13-8','deu','신명기',13,8,'너는 그를 따르지 말며 듣지 말며 긍휼히 여기지 말며 애석히 여기지 말며 덮어 숨기지 말고',5281),
('deu-13-9','deu','신명기',13,9,'너는 용서 없이 그를 죽이되 죽일 때에 네가 먼저 그에게 손을 대고 후에 뭇 백성이 손을 대라',5282),
('deu-13-10','deu','신명기',13,10,'그는 애굽 땅 종 되었던 집에서 너를 인도하여 내신 네 하나님 여호와에게서 너를 꾀어 떠나게 하려 한 자이니 너는 돌로 쳐죽이라',5283),
('deu-13-11','deu','신명기',13,11,'그리하면 온 이스라엘이 듣고 두려워하여 이같은 악을 다시는 너희 중에서 행하지 못하리라',5284),
