('deu-13-16','deu','신명기',13,16,'또 그 속에서 빼앗아 차지한 물건을 다 거리에 모아 놓고 그 성읍과 그 탈취물 전부를 불살라 네 하나님 여호와께 드릴지니 그 성읍은 영구히 폐허가 되어 다시는 건축되지 아니할 것이라',5289),
