('deu-13-18','deu','신명기',13,18,'네가 만일 네 하나님 여호와의 말씀을 듣고 오늘 내가 네게 명하는 그 모든 명령을 지켜 네 하나님 여호와의 목전에서 정직하게 행하면 이같이 되리라',5291),
('deu-14-1','deu','신명기',14,1,'너희는 너희 하나님 여호와의 자녀이니 죽은 자를 위하여 자기 몸을 베지 말며 눈썹 사이 이마 위의 털을 밀지 말라',5292),
('deu-14-2','deu','신명기',14,2,'너는 네 하나님 여호와의 성민이라 여호와께서 지상 만민 중에서 너를 택하여 자기 기업의 백성으로 삼으셨느니라',5293),
('deu-14-3','deu','신명기',14,3,'너는 가증한 것은 무엇이든지 먹지 말라',5294),
('deu-14-4','deu','신명기',14,4,'너희가 먹을 만한 짐승은 이러하니 곧 소와 양과 염소와',5295),
