('deu-14-6','deu','신명기',14,6,'짐승 중에 굽이 갈라져 쪽발도 되고 새김질도 하는 모든 것은 너희가 먹을 것이니라',5297),
('deu-14-7','deu','신명기',14,7,'다만 새김질을 하거나 굽이 갈라진 짐승 중에도 너희가 먹지 못할 것은 이것이니 곧 낙타와 토끼와 사반, 그것들은 새김질은 하나 굽이 갈라지지 아니하였으니 너희에게 부정하고',5298),
('deu-14-8','deu','신명기',14,8,'돼지는 굽은 갈라졌으나 새김질을 못하므로 너희에게 부정하니 너희는 이런 것의 고기를 먹지 말 것이며 그 사체도 만지지 말 것이니라',5299),
('deu-14-9','deu','신명기',14,9,'물에 있는 모든 것 중에서 이런 것은 너희가 먹을 것이니 지느러미와 비늘 있는 모든 것은 너희가 먹을 것이요',5300),
('deu-14-10','deu','신명기',14,10,'지느러미와 비늘이 없는 모든 것은 너희가 먹지 말지니 이는 너희에게 부정함이니라',5301),
