('deu-14-24','deu','신명기',14,24,'그러나 네 하나님 여호와께서 자기의 이름을 두시려고 택하신 곳이 네게서 너무 멀고 행로가 어려워서 네 하나님 여호와께서 그 풍부히 주신 것을 가지고 갈 수 없거든',5315),
('deu-14-25','deu','신명기',14,25,'그것을 돈으로 바꾸어 그 돈을 싸 가지고 네 하나님 여호와께서 택하신 곳으로 가서',5316),
('deu-14-26','deu','신명기',14,26,'네 마음에 원하는 모든 것을 그 돈으로 사되 소나 양이나 포도주나 독주 등 네 마음에 원하는 모든 것을 구하고 거기 네 하나님 여호와 앞에서 너와 네 권속이 함께 먹고 즐거워할 것이며',5317),
('deu-14-27','deu','신명기',14,27,'네 성읍에 거주하는 레위인은 너희 중에 분깃이나 기업이 없는 자이니 또한 저버리지 말지니라',5318),
('deu-14-28','deu','신명기',14,28,'매 삼 년 끝에 그 해 소산의 십분의 일을 다 내어 네 성읍에 저축하여',5319),
('deu-14-29','deu','신명기',14,29,'너희 중에 분깃이나 기업이 없는 레위인과 네 성중에 거류하는 객과 및 고아와 과부들이 와서 먹고 배부르게 하라 그리하면 네 하나님 여호와께서 네 손으로 하는 범사에 네게 복을 주시리라',5320),
('deu-15-1','deu','신명기',15,1,'매 칠 년 끝에는 면제하라',5321),
('deu-15-2','deu','신명기',15,2,'면제의 규례는 이러하니라 그의 이웃에게 꾸어준 모든 채주는 그것을 면제하고 그의 이웃에게나 그 형제에게 독촉하지 말지니 이는 여호와를 위하여 면제를 선포하였음이라',5322),
('deu-15-3','deu','신명기',15,3,'이방인에게는 네가 독촉하려니와 네 형제에게 꾸어준 것은 네 손에서 면제하라',5323),
('deu-15-4','deu','신명기',15,4,'네가 만일 네 하나님 여호와의 말씀만 듣고 내가 오늘 네게 내리는 그 명령을 다 지켜 행하면 네 하나님 여호와께서 네게 기업으로 주신 땅에서 네가 반드시 복을 받으리니 너희 중에 가난한 자가 없으리라',5324),
('deu-15-5','deu','신명기',15,5,'네가 만일 네 하나님 여호와의 말씀만 듣고 내가 오늘 네게 내리는 그 명령을 다 지켜 행하면 네 하나님 여호와께서 네게 기업으로 주신 땅에서 네가 반드시 복을 받으리니 너희 중에 가난한 자가 없으리라',5325),
('deu-15-6','deu','신명기',15,6,'네 하나님 여호와께서 네게 허락하신 대로 네게 복을 주시리니 네가 여러 나라에 꾸어 줄지라도 너는 꾸지 아니하겠고 네가 여러 나라를 통치할지라도 너는 통치를 당하지 아니하리라',5326),
('deu-15-7','deu','신명기',15,7,'네 하나님 여호와께서 네게 주신 땅 어느 성읍에서든지 가난한 형제가 너와 함께 거주하거든 그 가난한 형제에게 네 마음을 완악하게 하지 말며 네 손을 움켜 쥐지 말고',5327),
('deu-15-8','deu','신명기',15,8,'반드시 네 손을 그에게 펴서 그에게 필요한 대로 쓸 것을 넉넉히 꾸어주라',5328),
('deu-15-9','deu','신명기',15,9,'삼가 너는 마음에 악한 생각을 품지 말라 곧 이르기를 일곱째 해 면제년이 가까이 왔다 하고 네 궁핍한 형제를 악한 눈으로 바라보며 아무것도 주지 아니하면 그가 너를 여호와께 호소하리니 그것이 네게 죄가 되리라',5329),
('deu-15-10','deu','신명기',15,10,'너는 반드시 그에게 줄 것이요, 줄 때에는 아끼는 마음을 품지 말 것이니라 이로 말미암아 네 하나님 여호와께서 네가 하는 모든 일과 네 손이 닿는 모든 일에 네게 복을 주시리라',5330),
('deu-15-11','deu','신명기',15,11,'땅에는 언제든지 가난한 자가 그치지 아니하겠으므로 내가 네게 명령하여 이르노니 너는 반드시 네 땅 안에 네 형제 중 곤란한 자와 궁핍한 자에게 네 손을 펼지니라',5331),
('deu-15-12','deu','신명기',15,12,'네 동족 히브리 남자나 히브리 여자가 네게 팔렸다 하자 만일 여섯 해 동안 너를 섬겼거든 일곱째 해에 너는 그를 놓아 자유롭게 할 것이요',5332),
('deu-15-13','deu','신명기',15,13,'그를 놓아 자유하게 할 때에는 빈 손으로 가게 하지 말고',5333),
