('deu-15-15','deu','신명기',15,15,'너는 애굽 땅에서 종 되었던 것과 네 하나님 여호와께서 너를 속량하셨음을 기억하라 그것으로 말미암아 내가 오늘 이같이 네게 명령하노라',5335),
('deu-15-16','deu','신명기',15,16,'종이 만일 너와 네 집을 사랑하므로 너와 동거하기를 좋게 여겨 네게 향하여 내가 주인을 떠나지 아니하겠노라 하거든',5336),
