('deu-16-16','deu','신명기',16,16,'너의 가운데 모든 남자는 일 년에 세 번 곧 무교절과 칠칠절과 초막절에 네 하나님 여호와께서 택하신 곳에서 여호와를 뵈옵되 빈손으로 여호와를 뵈옵지 말고',5359),
('deu-16-17','deu','신명기',16,17,'각 사람이 네 하나님 여호와께서 주신 복을 따라 그 힘대로 드릴지니라',5360),
('deu-16-18','deu','신명기',16,18,'네 하나님 여호와께서 네게 주시는 각 성에서 네 지파를 따라 재판장들과 지도자들을 둘 것이요 그들은 공의로 백성을 재판할 것이니라',5361),
('deu-16-19','deu','신명기',16,19,'너는 재판을 굽게 하지 말며 사람을 외모로 보지 말며 또 뇌물을 받지 말라 뇌물은 지혜자의 눈을 어둡게 하고 의인의 말을 굽게 하느니라',5362),
('deu-16-20','deu','신명기',16,20,'너는 마땅히 공의만을 따르라 그리하면 네가 살겠고 네 하나님 여호와께서 네게 주시는 땅을 차지하리라',5363),
('deu-16-21','deu','신명기',16,21,'네 하나님 여호와를 위하여 쌓은 제단 곁에 어떤 나무로든지 아세라 상을 세우지 말며',5364),
('deu-16-22','deu','신명기',16,22,'자기를 위하여 주상을 세우지 말라 네 하나님 여호와께서 미워하시느니라',5365),
('deu-17-1','deu','신명기',17,1,'흠이나 악질이 있는 소와 양은 아무것도 네 하나님 여호와께 드리지 말지니 이는 네 하나님 여호와께 가증한 것이 됨이니라',5366),
('deu-17-2','deu','신명기',17,2,'네 하나님 여호와께서 네게 주시는 어느 성중에서든지 너희 가운데에 어떤 남자나 여자가 네 하나님 여호와의 목전에 악을 행하여 그 언약을 어기고',5367),
('deu-17-3','deu','신명기',17,3,'가서 다른 신들을 섬겨 그것에게 절하며 내가 명령하지 아니한 일월성신에게 절한다 하자',5368),
('deu-17-4','deu','신명기',17,4,'그것이 네게 알려지므로 네가 듣거든 자세히 조사해 볼지니 만일 그 일과 말이 확실하여 이스라엘 중에 이런 가증한 일을 행함이 있으면',5369),
('deu-17-5','deu','신명기',17,5,'너는 그 악을 행한 남자나 여자를 네 성문으로 끌어내고 그 남자나 여자를 돌로 쳐죽이되',5370),
('deu-17-6','deu','신명기',17,6,'죽일 자를 두 사람이나 세 사람의 증언으로 죽일 것이요 한 사람의 증언으로는 죽이지 말 것이며',5371),
('deu-17-7','deu','신명기',17,7,'이런 자를 죽이기 위하여는 증인이 먼저 그에게 손을 댄 후에 뭇 백성이 손을 댈지니라 너는 이와 같이 하여 너희 중에서 악을 제할지니라',5372),
('deu-17-8','deu','신명기',17,8,'네 성중에서 서로 피를 흘렸거나 다투었거나 구타하였거나 서로 간에 고소하여 네가 판결하기 어려운 일이 생기거든 너는 일어나 네 하나님 여호와께서 택하실 곳으로 올라가서',5373),
('deu-17-9','deu','신명기',17,9,'레위 사람 제사장과 당시 재판장에게 나아가서 물으라 그리하면 그들이 어떻게 판결할지를 네게 가르치리니',5374),
('deu-17-10','deu','신명기',17,10,'여호와께서 택하신 곳에서 그들이 네게 보이는 판결의 뜻대로 네가 행하되 그들이 네게 가르치는 대로 삼가 행할 것이니',5375),
('deu-17-11','deu','신명기',17,11,'곧 그들이 네게 가르치는 율법의 뜻대로, 그들이 네게 말하는 판결대로 행할 것이요 그들이 네게 보이는 판결을 어겨 좌로나 우로나 치우치지 말 것이니라',5376),
('deu-17-12','deu','신명기',17,12,'사람이 만일 무법하게 행하고 네 하나님 여호와 앞에 서서 섬기는 제사장이나 재판장에게 듣지 아니하거든 그 사람을 죽여 이스라엘 중에서 악을 제하여 버리라',5377),
('deu-17-13','deu','신명기',17,13,'그리하면 온 백성이 듣고 두려워하여 다시는 무법하게 행하지 아니하리라',5378),
('deu-17-14','deu','신명기',17,14,'네가 네 하나님 여호와께서 네게 주시는 땅에 이르러 그 땅을 차지하고 거주할 때에 만일 우리도 우리 주위의 모든 민족들 같이 우리 위에 왕을 세워야겠다는 생각이 나거든',5379),
('deu-17-15','deu','신명기',17,15,'반드시 네 하나님 여호와께서 택하신 자를 네 위에 왕으로 세울 것이며 네 위에 왕을 세우려면 네 형제 중에서 한 사람을 할 것이요 네 형제 아닌 타국인을 네 위에 세우지 말 것이며',5380),
('deu-17-16','deu','신명기',17,16,'그는 병마를 많이 두지 말 것이요 병마를 많이 얻으려고 그 백성을 애굽으로 돌아가게 하지 말 것이니 이는 여호와께서 너희에게 이르시기를 너희가 이 후에는 그 길로 다시 돌아가지 말 것이라 하셨음이며',5381),
('deu-17-17','deu','신명기',17,17,'그에게 아내를 많이 두어 그의 마음이 미혹되게 하지 말 것이며 자기를 위하여 은금을 많이 쌓지 말 것이니라',5382),
('deu-17-18','deu','신명기',17,18,'그가 왕위에 오르거든 이 율법서의 등사본을 레위 사람 제사장 앞에서 책에 기록하여',5383),
('deu-17-19','deu','신명기',17,19,'평생에 자기 옆에 두고 읽어 그의 하나님 여호와 경외하기를 배우며 이 율법의 모든 말과 이 규례를 지켜 행할 것이라',5384),
('deu-17-20','deu','신명기',17,20,'그리하면 그의 마음이 그의 형제 위에 교만하지 아니하고 이 명령에서 떠나 좌로나 우로나 치우치지 아니하리니 이스라엘 중에서 그와 그의 자손이 왕위에 있는 날이 장구하리라',5385),
('deu-18-1','deu','신명기',18,1,'레위 사람 제사장과 레위의 온 지파는 이스라엘 중에 분깃도 없고 기업도 없을지니 그들은 여호와의 화제물과 그 기업을 먹을 것이라',5386),
('deu-18-2','deu','신명기',18,2,'그들이 그들의 형제 중에서 기업을 가지지 않을 것은 여호와께서 그들의 기업이 되심이니 그들에게 말씀하심 같으니라',5387),
('deu-18-3','deu','신명기',18,3,'제사장이 백성에게서 받을 몫은 이러하니 곧 그 드리는 제물의 소나 양이나 그 앞다리와 두 볼과 위라 이것을 제사장에게 줄 것이요',5388),
('deu-18-4','deu','신명기',18,4,'또 네가 처음 거둔 곡식과 포도주와 기름과 네가 처음 깎은 양털을 네가 그에게 줄 것이니',5389),
('deu-18-5','deu','신명기',18,5,'이는 네 하나님 여호와께서 네 모든 지파 중에서 그를 택하여 내시고 그와 그의 자손에게 항상 여호와의 이름으로 서서 섬기게 하셨음이니라',5390),
('deu-18-6','deu','신명기',18,6,'이스라엘 온 땅 어떤 성읍에든지 거주하는 레위인이 간절한 소원이 있어 그가 사는 곳을 떠날지라도 여호와께서 택하신 곳에 이르면',5391),
('deu-18-7','deu','신명기',18,7,'여호와 앞에 선 그의 모든 형제 레위인과 같이 그의 하나님 여호와의 이름으로 섬길 수 있나니',5392),
('deu-18-8','deu','신명기',18,8,'그 사람의 몫은 그들과 같을 것이요 그가 조상의 것을 판 것은 별도의 소유이니라',5393),
('deu-18-9','deu','신명기',18,9,'네 하나님 여호와께서 네게 주시는 땅에 들어가거든 너는 그 민족들의 가증한 행위를 본받지 말 것이니',5394),
('deu-18-10','deu','신명기',18,10,'그의 아들이나 딸을 불 가운데로 지나게 하는 자나 점쟁이나 길흉을 말하는 자나 요술하는 자나 무당이나',5395),
('deu-18-11','deu','신명기',18,11,'진언자나 신접자나 박수나 초혼자를 너희 가운데에 용납하지 말라',5396),
('deu-18-12','deu','신명기',18,12,'이런 일을 행하는 모든 자를 여호와께서 가증히 여기시나니 이런 가증한 일로 말미암아 네 하나님 여호와께서 그들을 네 앞에서 쫓아내시느니라',5397),
('deu-18-13','deu','신명기',18,13,'너는 네 하나님 여호와 앞에서 완전하라',5398),
('deu-18-14','deu','신명기',18,14,'네가 쫓아낼 이 민족들은 길흉을 말하는 자나 점쟁이의 말을 듣거니와 네게는 네 하나님 여호와께서 이런 일을 용납하지 아니하시느니라',5399),
('deu-18-15','deu','신명기',18,15,'네 하나님 여호와께서 너희 가운데 네 형제 중에서 너를 위하여 나와 같은 선지자 하나를 일으키시리니 너희는 그의 말을 들을지니라',5400),
('deu-18-16','deu','신명기',18,16,'이것이 곧 네가 총회의 날에 호렙 산에서 네 하나님 여호와께 구한 것이라 곧 네가 말하기를 내가 다시는 내 하나님 여호와의 음성을 듣지 않게 하시고 다시는 이 큰 불을 보지 않게 하소서 두렵건대 내가 죽을까 하나이다 하매',5401),
('deu-18-17','deu','신명기',18,17,'여호와께서 내게 이르시되 그들의 말이 옳도다',5402),
('deu-18-18','deu','신명기',18,18,'내가 그들의 형제 중에서 너와 같은 선지자 하나를 그들을 위하여 일으키고 내 말을 그 입에 두리니 내가 그에게 명령하는 것을 그가 무리에게 다 말하리라',5403),
('deu-18-19','deu','신명기',18,19,'누구든지 내 이름으로 전하는 내 말을 듣지 아니하는 자는 내게 벌을 받을 것이요',5404),
('deu-18-20','deu','신명기',18,20,'만일 어떤 선지자가 내가 전하라고 명령하지 아니한 말을 제 마음대로 내 이름으로 전하든지 다른 신들의 이름으로 말하면 그 선지자는 죽임을 당하리라 하셨느니라',5405),
('deu-18-21','deu','신명기',18,21,'네가 마음속으로 이르기를 그 말이 여호와께서 이르신 말씀인지 우리가 어떻게 알리요 하리라',5406),
('deu-18-22','deu','신명기',18,22,'만일 선지자가 있어 여호와의 이름으로 말한 일에 증험도 없고 성취함도 없으면 이는 여호와께서 말씀하신 것이 아니요 그 선지자가 제 마음대로 한 말이니 너는 그를 두려워하지 말지니라',5407),
('deu-19-1','deu','신명기',19,1,'네 하나님 여호와께서 이 여러 민족을 멸절하시고 네 하나님 여호와께서 그 땅을 네게 주시므로 네가 그것을 받고 그들의 성읍과 가옥에 거주할 때에',5408),
('deu-19-2','deu','신명기',19,2,'네 하나님 여호와께서 네게 기업으로 주신 땅 가운데에서 세 성읍을 너를 위하여 구별하고',5409),
('deu-19-3','deu','신명기',19,3,'네 하나님 여호와께서 네게 기업으로 주시는 땅 전체를 세 구역으로 나누어 길을 닦고 모든 살인자를 그 성읍으로 도피하게 하라',5410),
('deu-19-4','deu','신명기',19,4,'살인자가 그리로 도피하여 살 만한 경우는 이러하니 곧 누구든지 본래 원한이 없이 부지중에 그의 이웃을 죽인 일,',5411),
('deu-19-5','deu','신명기',19,5,'가령 사람이 그 이웃과 함께 벌목하러 삼림에 들어가서 손에 도끼를 들고 벌목하려고 찍을 때에 도끼가 자루에서 빠져 그의 이웃을 맞춰 그를 죽게 함과 같은 것이라 이런 사람은 그 성읍 중 하나로 도피하여 생명을 보존할 것이니라',5412),
('deu-19-6','deu','신명기',19,6,'그 사람이 그에게 본래 원한이 없으니 죽이기에 합당하지 아니하나 두렵건대 그 피를 보복하는 자의 마음이 복수심에 불타서 살인자를 뒤쫓는데 그 가는 길이 멀면 그를 따라 잡아 죽일까 하노라',5413),
('deu-19-7','deu','신명기',19,7,'그러므로 내가 네게 명령하기를 세 성읍을 너를 위하여 구별하라 하노라',5414),
('deu-19-8','deu','신명기',19,8,'네 하나님 여호와께서 네 조상들에게 맹세하신 대로 네 지경을 넓혀 네 조상들에게 주리라고 말씀하신 땅을 다 네게 주실 때',5415),
('deu-19-9','deu','신명기',19,9,'또 너희가 오늘 내가 너희에게 명하는 이 모든 명령을 지켜 행하여 네 하나님 여호와를 사랑하고 항상 그의 길로 행할 때에는 이 셋 외에 세 성읍을 더하여',5416),
('deu-19-10','deu','신명기',19,10,'네 하나님 여호와께서 네게 기업으로 주시는 땅에서 무죄한 피를 흘리지 말라 이같이 하면 그의 피가 네게로 돌아가지 아니하리라',5417),
('deu-19-11','deu','신명기',19,11,'그러나 만일 어떤 사람이 그의 이웃을 미워하여 엎드려 그를 기다리다가 일어나 상처를 입혀 죽게 하고 이 한 성읍으로 도피하면',5418),
('deu-19-12','deu','신명기',19,12,'그 본 성읍 장로들이 사람을 보내어 그를 거기서 잡아다가 보복자의 손에 넘겨 죽이게 할 것이라',5419),
('deu-19-13','deu','신명기',19,13,'네 눈이 그를 긍휼히 여기지 말고 무죄한 피를 흘린 죄를 이스라엘에서 제하라 그리하면 네게 복이 있으리라',5420),
('deu-19-14','deu','신명기',19,14,'네 하나님 여호와께서 네게 주어 차지하게 하시는 땅 곧 네 소유가 된 기업의 땅에서 조상이 정한 네 이웃의 경계표를 옮기지 말지니라',5421),
('deu-19-15','deu','신명기',19,15,'사람의 모든 악에 관하여 또한 모든 죄에 관하여는 한 증인으로만 정할 것이 아니요 두 증인의 입으로나 또는 세 증인의 입으로 그 사건을 확정할 것이며',5422),
('deu-19-16','deu','신명기',19,16,'만일 위증하는 자가 있어 어떤 사람이 악을 행하였다고 말하면',5423),
('deu-19-17','deu','신명기',19,17,'그 논쟁하는 쌍방이 같이 하나님 앞에 나아가 그 당시의 제사장과 재판장 앞에 설 것이요',5424),
('deu-19-18','deu','신명기',19,18,'재판장은 자세히 조사하여 그 증인이 거짓 증거하여 그 형제를 거짓으로 모함한 것이 판명되면',5425),
('deu-19-19','deu','신명기',19,19,'그가 그의 형제에게 행하려고 꾀한 그대로 그에게 행하여 너희 중에서 악을 제하라',5426),
('deu-19-20','deu','신명기',19,20,'그리하면 그 남은 자들이 듣고 두려워하여 다시는 그런 악을 너희 중에서 행하지 아니하리라',5427),
('deu-19-21','deu','신명기',19,21,'네 눈이 긍휼히 여기지 말라 생명에는 생명으로, 눈에는 눈으로, 이에는 이로, 손에는 손으로, 발에는 발로이니라',5428),
('deu-20-1','deu','신명기',20,1,'네가 나가서 적군과 싸우려 할 때에 말과 병거와 백성이 너보다 많음을 볼지라도 그들을 두려워하지 말라 애굽 땅에서 너를 인도하여 내신 네 하나님 여호와께서 너와 함께 하시느니라',5429),
('deu-20-2','deu','신명기',20,2,'너희가 싸울 곳에 가까이 가면 제사장은 백성에게 나아가서 고하여 그들에게',5430),
('deu-20-3','deu','신명기',20,3,'말하여 이르기를 이스라엘아 들으라 너희가 오늘 너희의 대적과 싸우려고 나아왔으니 마음에 겁내지 말며 두려워하지 말며 떨지 말며 그들로 말미암아 놀라지 말라',5431),
('deu-20-4','deu','신명기',20,4,'너희 하나님 여호와는 너희와 함께 행하시며 너희를 위하여 너희 적군과 싸우시고 구원하실 것이라 할 것이며',5432),
('deu-20-5','deu','신명기',20,5,'책임자들은 백성에게 말하여 이르기를 새 집을 건축하고 낙성식을 행하지 못한 자가 있느냐 그는 집으로 돌아갈지니 전사하면 타인이 낙성식을 행할까 하노라',5433),
('deu-20-6','deu','신명기',20,6,'포도원을 만들고 그 과실을 먹지 못한 자가 있느냐 그는 집으로 돌아갈지니 전사하면 타인이 그 과실을 먹을까 하노라',5434),
('deu-20-7','deu','신명기',20,7,'여자와 약혼하고 그와 결혼하지 못한 자가 있느냐 그는 집으로 돌아갈지니 전사하면 타인이 그를 데려갈까 하노라 하고',5435),
('deu-20-8','deu','신명기',20,8,'책임자들은 또 백성에게 말하여 이르기를 두려워서 마음이 허약한 자가 있느냐 그는 집으로 돌아갈지니 그의 형제들의 마음도 그의 마음과 같이 낙심될까 하노라 하고',5436),
('deu-20-9','deu','신명기',20,9,'백성에게 이르기를 마친 후에 군대의 지휘관들을 세워 무리를 거느리게 할지니라',5437),
('deu-20-10','deu','신명기',20,10,'네가 어떤 성읍으로 나아가서 치려 할 때에는 그 성읍에 먼저 화평을 선언하라',5438),
('deu-20-11','deu','신명기',20,11,'그 성읍이 만일 화평하기로 회답하고 너를 향하여 성문을 열거든 그 모든 주민들에게 네게 조공을 바치고 너를 섬기게 할 것이요',5439),
('deu-20-12','deu','신명기',20,12,'만일 너와 화평하기를 거부하고 너를 대적하여 싸우려 하거든 너는 그 성읍을 에워쌀 것이며',5440),
('deu-20-13','deu','신명기',20,13,'네 하나님 여호와께서 그 성읍을 네 손에 넘기시거든 너는 칼날로 그 안의 남자를 다 쳐죽이고',5441),
('deu-20-14','deu','신명기',20,14,'너는 오직 여자들과 유아들과 가축들과 성읍 가운데에 있는 모든 것을 너를 위하여 탈취물로 삼을 것이며 너는 네 하나님 여호와께서 네게 주신 적군에게서 빼앗은 것을 먹을지니라',5442),
('deu-20-15','deu','신명기',20,15,'네가 네게서 멀리 떠난 성읍들 곧 이 민족들에게 속하지 아니한 성읍들에게는 이같이 행하려니와',5443),
('deu-20-16','deu','신명기',20,16,'오직 네 하나님 여호와께서 네게 기업으로 주시는 이 민족들의 성읍에서는 호흡 있는 자를 하나도 살리지 말지니',5444),
('deu-20-17','deu','신명기',20,17,'곧 헷 족속과 아모리 족속과 가나안 족속과 브리스 족속과 히위 족속과 여부스 족속을 네가 진멸하되 네 하나님 여호와께서 네게 명령하신 대로 하라',5445),
('deu-20-18','deu','신명기',20,18,'이는 그들이 그 신들에게 행하는 모든 가증한 일을 너희에게 가르쳐 본받게 하여 너희가 너희의 하나님 여호와께 범죄하게 할까 함이니라',5446),
('deu-20-19','deu','신명기',20,19,'너희가 어떤 성읍을 오랫동안 에워싸고 그 성읍을 쳐서 점령하려 할 때에도 도끼를 둘러 그 곳의 나무를 찍어내지 말라 이는 너희가 먹을 것이 될 것임이니 찍지 말라 들의 수목이 사람이냐 너희가 어찌 그것을 에워싸겠느냐',5447),
('deu-20-20','deu','신명기',20,20,'다만 과목이 아닌 수목은 찍어내어 너희와 싸우는 그 성읍을 치는 기구를 만들어 그 성읍을 함락시킬 때까지 쓸지니라',5448),
('deu-21-1','deu','신명기',21,1,'네 하나님 여호와께서 네게 주어 차지하게 하신 땅에서 피살된 시체가 들에 엎드러진 것을 발견하고 그 쳐죽인 자가 누구인지 알지 못하거든',5449),
('deu-21-2','deu','신명기',21,2,'너희의 장로들과 재판장들은 나가서 그 피살된 곳의 사방에 있는 성읍의 원근을 잴 것이요',5450),
('deu-21-3','deu','신명기',21,3,'그 피살된 곳에서 제일 가까운 성읍의 장로들이 그 성읍에서 아직 부리지 아니하고 멍에를 메지 아니한 암송아지를 취하여',5451),
('deu-21-4','deu','신명기',21,4,'그 성읍의 장로들이 물이 항상 흐르고 갈지도 않고 씨를 뿌린 일도 없는 골짜기로 그 송아지를 끌고 가서 그 골짜기에서 그 송아지의 목을 꺾을 것이요',5452),
('deu-21-5','deu','신명기',21,5,'레위 자손 제사장들도 그리로 갈지니 그들은 네 하나님 여호와께서 택하사 자기를 섬기게 하시며 또 여호와의 이름으로 축복하게 하신 자라 모든 소송과 모든 투쟁이 그들의 말대로 판결될 것이니라',5453),
('deu-21-6','deu','신명기',21,6,'그 피살된 곳에서 제일 가까운 성읍의 모든 장로들은 그 골짜기에서 목을 꺾은 암송아지 위에 손을 씻으며',5454),
('deu-21-7','deu','신명기',21,7,'말하기를 우리의 손이 이 피를 흘리지 아니하였고 우리의 눈이 이것을 보지도 못하였나이다',5455),
('deu-21-8','deu','신명기',21,8,'여호와여 주께서 속량하신 주의 백성 이스라엘을 사하시고 무죄한 피를 주의 백성 이스라엘 중에 머물러 두지 마옵소서 하면 그 피 흘린 죄가 사함을 받으리니',5456),
('deu-21-9','deu','신명기',21,9,'너는 이와 같이 여호와께서 보시기에 정직한 일을 행하여 무죄한 자의 피 흘린 죄를 너희 중에서 제할지니라',5457),
('deu-21-10','deu','신명기',21,10,'네가 나가서 적군과 싸울 때에 네 하나님 여호와께서 그들을 네 손에 넘기시므로 네가 그들을 사로잡은 후에',5458),
('deu-21-11','deu','신명기',21,11,'네가 만일 그 포로 중의 아리따운 여자를 보고 그에게 연연하여 아내를 삼고자 하거든',5459),
('deu-21-12','deu','신명기',21,12,'그를 네 집으로 데려갈 것이요 그는 그 머리를 밀고 손톱을 베고',5460),
