('deu-21-14','deu','신명기',21,14,'그 후에 네가 그를 기뻐하지 아니하거든 그의 마음대로 가게 하고 결코 돈을 받고 팔지 말지라 네가 그를 욕보였은즉 종으로 여기지 말지니라',5462),
('deu-21-15','deu','신명기',21,15,'어떤 사람이 두 아내를 두었는데 하나는 사랑을 받고 하나는 미움을 받다가 그 사랑을 받는 자와 미움을 받는 자가 둘 다 아들을 낳았다 하자 그 미움을 받는 자의 아들이 장자이면',5463),
('deu-21-16','deu','신명기',21,16,'자기의 소유를 그의 아들들에게 기업으로 나누는 날에 그 사랑을 받는 자의 아들을 장자로 삼아 참 장자 곧 미움을 받는 자의 아들보다 앞세우지 말고',5464),
