('deu-21-18','deu','신명기',21,18,'사람에게 완악하고 패역한 아들이 있어 그의 아버지의 말이나 그 어머니의 말을 순종하지 아니하고 부모가 징계하여도 순종하지 아니하거든',5466),
('deu-21-19','deu','신명기',21,19,'그의 부모가 그를 끌고 성문에 이르러 그 성읍 장로들에게 나아가서',5467),
('deu-21-20','deu','신명기',21,20,'그 성읍 장로들에게 말하기를 우리의 이 자식은 완악하고 패역하여 우리 말을 듣지 아니하고 방탕하며 술에 잠긴 자라 하면',5468),
