('deu-22-2','deu','신명기',22,2,'네 형제가 네게서 멀거나 또는 네가 그를 알지 못하거든 그 짐승을 네 집으로 끌고 가서 네 형제가 찾기까지 네게 두었다가 그에게 돌려 줄지니',5473),
('deu-22-3','deu','신명기',22,3,'나귀라도 그리하고 의복이라도 그리하고 형제가 잃어버린 어떤 것이든지 네가 얻거든 다 그리하고 못 본 체하지 말 것이며',5474),
('deu-22-4','deu','신명기',22,4,'네 형제의 나귀나 소가 길에 넘어진 것을 보거든 못 본 체하지 말고 너는 반드시 형제를 도와 그것들을 일으킬지니라',5475),
('deu-22-5','deu','신명기',22,5,'여자는 남자의 의복을 입지 말 것이요 남자는 여자의 의복을 입지 말 것이라 이같이 하는 자는 네 하나님 여호와께 가증한 자이니라',5476),
('deu-22-6','deu','신명기',22,6,'길을 가다가 나무에나 땅에 있는 새의 보금자리에 새 새끼나 알이 있고 어미 새가 그의 새끼나 알을 품은 것을 보거든 그 어미 새와 새끼를 아울러 취하지 말고',5477),
('deu-22-7','deu','신명기',22,7,'어미는 반드시 놓아 줄 것이요 새끼는 취하여도 되나니 그리하면 네가 복을 누리고 장수하리라',5478),
('deu-22-8','deu','신명기',22,8,'네가 새 집을 지을 때에 지붕에 난간을 만들어 사람이 떨어지지 않게 하라 그 피가 네 집에 돌아갈까 하노라',5479),
('deu-22-9','deu','신명기',22,9,'네 포도원에 두 종자를 섞어 뿌리지 말라 그리하면 네가 뿌린 씨의 열매와 포도원의 소산을 다 빼앗길까 하노라',5480),
('deu-22-10','deu','신명기',22,10,'너는 소와 나귀를 겨리하여 갈지 말며',5481),
