('deu-22-12','deu','신명기',22,12,'너희는 너희가 입는 겉옷의 네 귀에 술을 만들지니라',5483),
('deu-22-13','deu','신명기',22,13,'누구든지 아내를 맞이하여 그에게 들어간 후에 그를 미워하여',5484),
