('deu-22-17','deu','신명기',22,17,'비방거리를 만들어 말하기를 내가 네 딸에게서 처녀임을 보지 못하였노라 하나 보라 내 딸의 처녀의 표적이 이것이라 하고 그 부모가 그 자리옷을 그 성읍 장로들 앞에 펼 것이요',5488),
