('deu-22-24','deu','신명기',22,24,'너희는 그들을 둘 다 성읍 문으로 끌어내고 그들을 돌로 쳐죽일 것이니 그 처녀는 성안에 있으면서도 소리 지르지 아니하였음이요 그 남자는 그 이웃의 아내를 욕보였음이라 너는 이같이 하여 너희 가운데에서 악을 제할지니라',5495),
