('deu-25-19','deu','신명기',25,19,'그러므로 네 하나님 여호와께서 네게 기업으로 주어 차지하게 하시는 땅에서 네 하나님 여호와께서 사방에 있는 모든 적군으로부터 네게 안식을 주실 때에 너는 천하에서 아말렉에 대한 기억을 지워버리라 너는 잊지 말지니라',5567),
('deu-26-1','deu','신명기',26,1,'네 하나님 여호와께서 네게 기업으로 주어 차지하게 하실 땅에 네가 들어가서 거기에 거주할 때에',5568),
