('deu-28-67','deu','신명기',28,67,'네 마음의 두려움과 눈이 보는 것으로 말미암아 아침에는 이르기를 아하 저녁이 되었으면 좋겠다 할 것이요 저녁에는 이르기를 아하 아침이 되었으면 좋겠다 하리라',5679),
