('deu-29-1','deu','신명기',29,1,'호렙에서 이스라엘 자손과 세우신 언약 외에 여호와께서 모세에게 명령하여 모압 땅에서 그들과 세우신 언약의 말씀은 이러하니라',5681),
('deu-29-2','deu','신명기',29,2,'모세가 온 이스라엘을 소집하고 그들에게 이르되 여호와께서 애굽 땅에서 너희의 목전에 바로와 그의 모든 신하와 그의 온 땅에 행하신 모든 일을 너희가 보았나니',5682),
('deu-29-3','deu','신명기',29,3,'곧 그 큰 시험과 이적과 큰 기사를 네 눈으로 보았느니라',5683),
('deu-29-4','deu','신명기',29,4,'그러나 깨닫는 마음과 보는 눈과 듣는 귀는 오늘 여호와께서 너희에게 주지 아니하셨느니라',5684),
('deu-29-5','deu','신명기',29,5,'주께서 사십 년 동안 너희를 광야에서 인도하게 하셨거니와 너희 몸의 옷이 낡아지지 아니하였고 너희 발의 신이 해어지지 아니하였으며',5685),
('deu-29-6','deu','신명기',29,6,'너희에게 떡도 먹지 못하며 포도주나 독주를 마시지 못하게 하셨음은 주는 너희의 하나님 여호와이신 줄을 알게 하려 하심이니라',5686),
('deu-29-7','deu','신명기',29,7,'너희가 이 곳에 올 때에 헤스본 왕 시혼과 바산 왕 옥이 우리와 싸우러 나왔으므로 우리가 그들을 치고',5687),
('deu-29-8','deu','신명기',29,8,'그 땅을 차지하여 르우벤과 갓과 므낫세 반 지파에게 기업으로 주었나니',5688),
