('deu-29-12','deu','신명기',29,12,'네 하나님 여호와의 언약에 참여하며 또 네 하나님 여호와께서 오늘 네게 하시는 맹세에 참여하여',5692),
('deu-29-13','deu','신명기',29,13,'여호와께서 네게 말씀하신 대로 또 네 조상 아브라함과 이삭과 야곱에게 맹세하신 대로 오늘 너를 세워 자기 백성을 삼으시고 그는 친히 네 하나님이 되시려 함이니라',5693),
('deu-29-14','deu','신명기',29,14,'내가 이 언약과 맹세를 너희에게만 세우는 것이 아니라',5694),
