('deu-29-16','deu','신명기',29,16,'(우리가 애굽 땅에서 살았던 것과 너희가 여러 나라를 통과한 것을 너희가 알며',5696),
('deu-29-17','deu','신명기',29,17,'너희가 또 그들 중에 있는 가증한 것과 목석과 은금의 우상을 보았느니라)',5697),
('deu-29-18','deu','신명기',29,18,'너희 중에 남자나 여자나 가족이나 지파나 오늘 그 마음이 우리 하나님 여호와를 떠나서 그 모든 민족의 신들에게 가서 섬길까 염려하며 독초와 쑥의 뿌리가 너희 중에 생겨서',5698),
('deu-29-19','deu','신명기',29,19,'이 저주의 말을 듣고도 심중에 스스로 복을 빌어 이르기를 내가 내 마음이 완악하여 젖은 것과 마른 것이 멸망할지라도 내게는 평안이 있으리라 할까 함이라',5699),
('deu-29-20','deu','신명기',29,20,'여호와는 이런 자를 사하지 않으실 뿐 아니라 그 위에 여호와의 분노와 질투의 불을 부으시며 또 이 책에 기록된 모든 저주를 그에게 더하실 것이라 여호와께서 그의 이름을 천하에서 지워버리시되',5700),
('deu-29-21','deu','신명기',29,21,'여호와께서 곧 이스라엘 모든 지파 중에서 그를 구별하시고 이 율법책에 기록된 모든 언약의 저주대로 그에게 화를 더하시리라',5701),
('deu-29-22','deu','신명기',29,22,'너희 뒤에 일어나는 너희의 자손과 멀리서 오는 객이 그 땅의 재앙과 여호와께서 그 땅에 유행시키시는 질병을 보며',5702),
('deu-29-23','deu','신명기',29,23,'그 온 땅이 유황이 되며 소금이 되며 또 불에 타서 심지도 못하며 결실함도 없으며 거기에는 아무 풀도 나지 아니함이 옛적에 여호와께서 진노와 격분으로 멸하신 소돔과 고모라와 아드마와 스보임의 무너짐과 같음을 보고 물을 것이요',5703),
('deu-29-24','deu','신명기',29,24,'여러 나라 사람들도 묻기를 여호와께서 어찌하여 이 땅에 이같이 행하셨느냐 이같이 크고 맹렬하게 노하심은 무슨 뜻이냐 하면',5704),
('deu-29-25','deu','신명기',29,25,'그 때에 사람들이 대답하기를 그 무리가 자기 조상의 하나님 여호와께서 그들의 조상을 애굽에서 인도하여 내실 때에 더불어 세우신 언약을 버리고',5705),
('deu-29-26','deu','신명기',29,26,'가서 자기들이 알지도 못하고 여호와께서 그들에게 주시지도 아니한 다른 신들을 따라가서 그들을 섬기고 절한 까닭이라',5706),
('deu-29-27','deu','신명기',29,27,'이러므로 여호와께서 이 땅에 진노하사 이 책에 기록된 모든 저주대로 재앙을 내리시고',5707),
('deu-29-28','deu','신명기',29,28,'여호와께서 또 진노와 격분과 크게 통한하심으로 그들을 이 땅에서 뽑아내사 다른 나라에 내던지심이 오늘과 같다 하리라',5708),
('deu-29-29','deu','신명기',29,29,'감추어진 일은 우리 하나님 여호와께 속하였거니와 나타난 일은 영원히 우리와 우리 자손에게 속하였나니 이는 우리에게 이 율법의 모든 말씀을 행하게 하심이니라',5709),
('deu-30-1','deu','신명기',30,1,'내가 네게 진술한 모든 복과 저주가 네게 임하므로 네가 네 하나님 여호와로부터 쫓겨간 모든 나라 가운데서 이 일이 마음에서 기억이 나거든',5710),
