('deu-30-3','deu','신명기',30,3,'네 하나님 여호와께서 마음을 돌이키시고 너를 긍휼히 여기사 포로에서 돌아오게 하시되 네 하나님 여호와께서 흩으신 그 모든 백성 중에서 너를 모으시리니',5712),
('deu-30-4','deu','신명기',30,4,'네 쫓겨간 자들이 하늘 가에 있을지라도 네 하나님 여호와께서 거기서 너를 모으실 것이며 거기서부터 너를 이끄실 것이라',5713),
