('deu-31-3','deu','신명기',31,3,'여호와께서 이미 말씀하신 것과 같이 네 하나님 여호와께서 너보다 먼저 건너가사 이 민족들을 네 앞에서 멸하시고 네가 그 땅을 차지하게 할 것이며 여호수아는 네 앞에서 건너갈지라',5732),
('deu-31-4','deu','신명기',31,4,'또한 여호와께서 이미 멸하신 아모리 왕 시혼과 옥과 및 그 땅에 행하신 것과 같이 그들에게도 행하실 것이라',5733),
('deu-31-5','deu','신명기',31,5,'또한 여호와께서 그들을 너희 앞에 넘기시리니 너희는 내가 너희에게 명한 모든 명령대로 그들에게 행할 것이라',5734),
('deu-31-6','deu','신명기',31,6,'너희는 강하고 담대하라 두려워하지 말라 그들 앞에서 떨지 말라 이는 네 하나님 여호와 그가 너와 함께 가시며 결코 너를 떠나지 아니하시며 버리지 아니하실 것임이라 하고',5735),
('deu-31-7','deu','신명기',31,7,'모세가 여호수아를 불러 온 이스라엘의 목전에서 그에게 이르되 너는 강하고 담대하라 너는 이 백성을 거느리고 여호와께서 그들의 조상에게 주리라고 맹세하신 땅에 들어가서 그들에게 그 땅을 차지하게 하라',5736),
('deu-31-8','deu','신명기',31,8,'그리하면 여호와 그가 네 앞에서 가시며 너와 함께 하사 너를 떠나지 아니하시며 버리지 아니하시리니 너는 두려워하지 말라 놀라지 말라',5737),
('deu-31-9','deu','신명기',31,9,'또 모세가 이 율법을 써서 여호와의 언약궤를 메는 레위 자손 제사장들과 이스라엘 모든 장로에게 주고',5738),
('deu-31-10','deu','신명기',31,10,'모세가 그들에게 명령하여 이르기를 매 칠 년 끝 해 곧 면제년의 초막절에',5739),
('deu-31-11','deu','신명기',31,11,'온 이스라엘이 네 하나님 여호와 앞 그가 택하신 곳에 모일 때에 이 율법을 낭독하여 온 이스라엘에게 듣게 할지니',5740),
('deu-31-12','deu','신명기',31,12,'곧 백성의 남녀와 어린이와 네 성읍 안에 거류하는 타국인을 모으고 그들에게 듣고 배우고 네 하나님 여호와를 경외하며 이 율법의 모든 말씀을 지켜 행하게 하고',5741),
('deu-31-13','deu','신명기',31,13,'또 너희가 요단을 건너가서 차지할 땅에 거주할 동안에 이 말씀을 알지 못하는 그들의 자녀에게 듣고 네 하나님 여호와 경외하기를 배우게 할지니라',5742),
('deu-31-14','deu','신명기',31,14,'여호와께서 모세에게 이르시되 네가 죽을 기한이 가까웠으니 여호수아를 불러서 함께 회막으로 나아오라 내가 그에게 명령을 내리리라 모세와 여호수아가 나아가서 회막에 서니',5743),
('deu-31-15','deu','신명기',31,15,'여호와께서 구름 기둥 가운데에서 장막에 나타나시고 구름 기둥은 장막 문 위에 머물러 있더라',5744),
('deu-31-16','deu','신명기',31,16,'또 여호와께서 모세에게 이르시되 너는 네 조상과 함께 누우려니와 이 백성은 그 땅으로 들어가 음란히 그 땅의 이방 신들을 따르며 일어날 것이요 나를 버리고 내가 그들과 맺은 언약을 어길 것이라',5745),
('deu-31-17','deu','신명기',31,17,'내가 그들에게 진노하여 그들을 버리며 내 얼굴을 숨겨 그들에게 보이지 않게 할 것인즉 그들이 삼킴을 당하여 허다한 재앙과 환난이 그들에게 임할 그 때에 그들이 말하기를 이 재앙이 우리에게 내림은 우리 하나님이 우리 가운데에 계시지 않은 까닭이 아니냐 할 것이라',5746),
('deu-31-18','deu','신명기',31,18,'또 그들이 돌이켜 다른 신들을 따르는 모든 악행으로 말미암아 내가 그 때에 반드시 내 얼굴을 숨기리라',5747),
('deu-31-19','deu','신명기',31,19,'그러므로 이제 너희는 이 노래를 써서 이스라엘 자손들에게 가르쳐 그들의 입으로 부르게 하여 이 노래로 나를 위하여 이스라엘 자손들에게 증거가 되게 하라',5748),
('deu-31-20','deu','신명기',31,20,'내가 그들의 조상들에게 맹세한 바 젖과 꿀이 흐르는 땅으로 그들을 인도하여 들인 후에 그들이 먹어 배부르고 살찌면 돌이켜 다른 신들을 섬기며 나를 멸시하여 내 언약을 어기리니',5749),
('deu-31-21','deu','신명기',31,21,'그들이 수많은 재앙과 환난을 당할 때에 그들의 자손이 부르기를 잊지 아니한 이 노래가 그들 앞에 증인처럼 되리라 나는 내가 맹세한 땅으로 그들을 인도하여 들이기 전 오늘 나는 그들이 생각하는 바를 아노라',5750),
('deu-31-22','deu','신명기',31,22,'그러므로 모세가 그 날 이 노래를 써서 이스라엘 자손들에게 가르쳤더라',5751),
('deu-31-23','deu','신명기',31,23,'여호와께서 또 눈의 아들 여호수아에게 명령하여 이르시되 너는 이스라엘 자손들을 인도하여 내가 그들에게 맹세한 땅으로 들어가게 하리니 강하고 담대하라 내가 너와 함께 하리라 하시니라',5752),
('deu-31-24','deu','신명기',31,24,'모세가 이 율법의 말씀을 다 책에 써서 마친 후에',5753),
('deu-31-25','deu','신명기',31,25,'모세가 여호와의 언약궤를 메는 레위 사람에게 명령하여 이르되',5754),
('deu-31-26','deu','신명기',31,26,'이 율법책을 가져다가 너희 하나님 여호와의 언약궤 곁에 두어 너희에게 증거가 되게 하라',5755),
('deu-31-27','deu','신명기',31,27,'내가 너희의 반역함과 목이 곧은 것을 아나니 오늘 내가 살아서 너희와 함께 있어도 너희가 여호와를 거역하였거든 하물며 내가 죽은 후의 일이랴',5756),
('deu-31-28','deu','신명기',31,28,'너희 지파 모든 장로와 관리들을 내 앞에 모으라 내가 이 말씀을 그들의 귀에 들려주고 그들에게 하늘과 땅을 증거로 삼으리라',5757),
('deu-31-29','deu','신명기',31,29,'내가 알거니와 내가 죽은 후에 너희가 스스로 부패하여 내가 너희에게 명령한 길을 떠나 여호와의 목전에 악을 행하여 너희의 손으로 하는 일로 그를 격노하게 하므로 너희가 후일에 재앙을 당하리라 하니라',5758),
('deu-31-30','deu','신명기',31,30,'그리고 모세가 이스라엘 총회에 이 노래의 말씀을 끝까지 읽어 들리니라',5759),
('deu-32-1','deu','신명기',32,1,'하늘이여 귀를 기울이라 내가 말하리라 땅은 내 입의 말을 들을지어다',5760),
('deu-32-2','deu','신명기',32,2,'내 교훈은 비처럼 내리고 내 말은 이슬처럼 맺히나니 연한 풀 위의 가는 비 같고 채소 위의 단비 같도다',5761),
('deu-32-3','deu','신명기',32,3,'내가 여호와의 이름을 전파하리니 너희는 우리 하나님께 위엄을 돌릴지어다',5762),
('deu-32-4','deu','신명기',32,4,'그는 반석이시니 그가 하신 일이 완전하고 그의 모든 길이 정의롭고 진실하고 거짓이 없으신 하나님이시니 공의로우시고 바르시도다',5763),
('deu-32-5','deu','신명기',32,5,'그들이 여호와를 향하여 악을 행하니 하나님의 자녀가 아니요 흠이 있고 삐뚤어진 세대로다',5764),
('deu-32-6','deu','신명기',32,6,'어리석고 지혜 없는 백성아 여호와께 이같이 보답하느냐 그는 네 아버지시요 너를 지으신 이가 아니시냐 그가 너를 만드시고 너를 세우셨도다',5765),
('deu-32-7','deu','신명기',32,7,'옛날을 기억하라 역대의 연대를 생각하라 네 아버지에게 물으라 그가 네게 설명할 것이요 네 어른들에게 물으라 그들이 네게 말하리로다',5766),
('deu-32-8','deu','신명기',32,8,'지극히 높으신 자가 민족들에게 기업을 주실 때에, 인종을 나누실 때에 이스라엘 자손의 수효대로 백성들의 경계를 정하셨도다',5767),
('deu-32-9','deu','신명기',32,9,'여호와의 분깃은 자기 백성이라 야곱은 그가 택하신 기업이로다',5768),
('deu-32-10','deu','신명기',32,10,'여호와께서 그를 황무지에서, 짐승이 부르짖는 광야에서 만나시고 호위하시며 보호하시며 자기의 눈동자 같이 지키셨도다',5769),
('deu-32-11','deu','신명기',32,11,'마치 독수리가 자기의 보금자리를 어지럽게 하며 자기의 새끼 위에 너풀거리며 그의 날개를 펴서 새끼를 받으며 그의 날개 위에 그것을 업는 것 같이',5770),
('deu-32-12','deu','신명기',32,12,'여호와께서 홀로 그를 인도하셨고 그와 함께 한 다른 신이 없었도다',5771),
('deu-32-13','deu','신명기',32,13,'여호와께서 그가 땅의 높은 곳을 타고 다니게 하시며 밭의 소산을 먹게 하시며 반석에서 꿀을, 굳은 반석에서 기름을 빨게 하시며',5772),
('deu-32-14','deu','신명기',32,14,'소의 엉긴 젖과 양의 젖과 어린 양의 기름과 바산에서 난 숫양과 염소와 지극히 아름다운 밀을 먹이시며 또 포도즙의 붉은 술을 마시게 하셨도다',5773),
('deu-32-15','deu','신명기',32,15,'그런데 여수룬이 기름지매 발로 찼도다 네가 살찌고 비대하고 윤택하매 자기를 지으신 하나님을 버리고 자기를 구원하신 반석을 업신여겼도다',5774),
('deu-32-16','deu','신명기',32,16,'그들이 다른 신으로 그의 질투를 일으키며 가증한 것으로 그의 진노를 격발하였도다',5775),
('deu-32-17','deu','신명기',32,17,'그들은 하나님께 제사하지 아니하고 귀신들에게 하였으니 곧 그들이 알지 못하던 신들, 근래에 들어온 새로운 신들 너희의 조상들이 두려워하지 아니하던 것들이로다',5776),
('deu-32-18','deu','신명기',32,18,'너를 낳은 반석을 네가 상관하지 아니하고 너를 내신 하나님을 네가 잊었도다',5777),
('deu-32-19','deu','신명기',32,19,'그러므로 여호와께서 보시고 미워하셨으니 그 자녀가 그를 격노하게 한 까닭이로다',5778),
('deu-32-20','deu','신명기',32,20,'그가 말씀하시기를 내가 내 얼굴을 그들에게서 숨겨 그들의 종말이 어떠함을 보리니 그들은 심히 패역한 세대요 진실이 없는 자녀임이로다',5779),
('deu-32-21','deu','신명기',32,21,'그들이 하나님이 아닌 것으로 내 질투를 일으키며 허무한 것으로 내 진노를 일으켰으니 나도 백성이 아닌 자로 그들에게 시기가 나게 하며 어리석은 민족으로 그들의 분노를 일으키리로다',5780),
('deu-32-22','deu','신명기',32,22,'그러므로 내 분노의 불이 일어나서 스올의 깊은 곳까지 불사르며 땅과 그 소산을 삼키며 산들의 터도 불타게 하는도다',5781),
('deu-32-23','deu','신명기',32,23,'내가 재앙을 그들 위에 쌓으며 내 화살이 다할 때까지 그들을 쏘리로다',5782),
('deu-32-24','deu','신명기',32,24,'그들이 주리므로 쇠약하며 불 같은 더위와 독한 질병에 삼켜질 것이라 내가 들짐승의 이와 티끌에 기는 것의 독을 그들에게 보내리로다',5783),
('deu-32-25','deu','신명기',32,25,'밖으로는 칼에, 방 안에서는 놀람에 멸망하리니 젊은 남자도 처녀도 백발 노인과 함께 젖 먹는 아이까지 그러하리로다',5784),
('deu-32-26','deu','신명기',32,26,'내가 그들을 흩어서 사람들 사이에서 그들에 대한 기억이 끊어지게 하리라 하였으나',5785),
('deu-32-27','deu','신명기',32,27,'혹시 내가 원수를 자극하여 그들의 원수가 잘못 생각할까 걱정하였으니 원수들이 말하기를 우리의 수단이 높으며 여호와가 이 모든 것을 행함이 아니라 할까 염려함이라',5786),
('deu-32-28','deu','신명기',32,28,'그들은 모략이 없는 민족이라 그들 중에 분별력이 없도다',5787),
('deu-32-29','deu','신명기',32,29,'만일 그들이 지혜가 있어 이것을 깨달았으면 자기들의 종말을 분별하였으리라',5788),
('deu-32-30','deu','신명기',32,30,'그들의 반석이 그들을 팔지 아니하였고 여호와께서 그들을 내주지 아니하셨더라면 어찌 하나가 천을 쫓으며 둘이 만을 도망하게 하였으리요',5789),
('deu-32-31','deu','신명기',32,31,'진실로 그들의 반석이 우리의 반석과 같지 아니하니 우리의 원수들이 스스로 판단하도다',5790),
('deu-32-32','deu','신명기',32,32,'이는 그들의 포도나무는 소돔의 포도나무요 고모라의 밭의 소산이라 그들의 포도는 독이 든 포도이니 그 송이는 쓰며',5791),
('deu-32-33','deu','신명기',32,33,'그들의 포도주는 뱀의 독이요 독사의 맹독이라',5792),
('deu-32-34','deu','신명기',32,34,'이것이 내게 쌓여 있고 내 곳간에 봉하여 있지 아니한가',5793),
('deu-32-35','deu','신명기',32,35,'그들이 실족할 그 때에 내가 보복하리라 그들의 환난날이 가까우니 그들에게 닥칠 그 일이 속히 오리로다',5794),
('deu-32-36','deu','신명기',32,36,'참으로 여호와께서 자기 백성을 판단하시고 그 종들을 불쌍히 여기시리니 곧 그들의 무력함과 갇힌 자나 놓인 자가 없음을 보시는 때에로다',5795),
('deu-32-37','deu','신명기',32,37,'또한 그가 말씀하시기를 그들의 신들이 어디 있으며 그들이 피하던 반석이 어디 있느냐',5796),
('deu-32-38','deu','신명기',32,38,'그들의 제물의 기름을 먹고 그들의 전제의 제물인 포도주를 마시던 자들이 일어나 너희를 돕게 하고 너희를 위해 피난처가 되게 하라',5797),
('deu-32-39','deu','신명기',32,39,'이제는 나 곧 내가 그인 줄 알라 나 외에는 신이 없도다 나는 죽이기도 하며 살리기도 하며 상하게도 하며 낫게도 하나니 내 손에서 능히 빼앗을 자가 없도다',5798),
('deu-32-40','deu','신명기',32,40,'이는 내가 하늘을 향하여 내 손을 들고 말하기를 내가 영원히 살리라 하였노라',5799),
('deu-32-41','deu','신명기',32,41,'내가 내 번쩍이는 칼을 갈며 내 손이 정의를 붙들고 내 대적들에게 복수하며 나를 미워하는 자들에게 보응할 것이라',5800),
('deu-32-42','deu','신명기',32,42,'내 화살이 피에 취하게 하고 내 칼이 그 고기를 삼키게 하리니 곧 피살자와 포로된 자의 피요 대적의 우두머리의 머리로다',5801),
