('deu-32-44','deu','신명기',32,44,'모세와 눈의 아들 호세아가 와서 이 노래의 모든 말씀을 백성에게 말하여 들리니라',5803),
('deu-32-45','deu','신명기',32,45,'모세가 이 모든 말씀을 온 이스라엘에게 말하기를 마치고',5804),
