('deu-32-52','deu','신명기',32,52,'네가 비록 내가 이스라엘 자손에게 주는 땅을 맞은편에서 바라보기는 하려니와 그리로 들어가지는 못하리라 하시니라',5811),
('deu-33-1','deu','신명기',33,1,'하나님의 사람 모세가 죽기 전에 이스라엘 자손을 위하여 축복함이 이러하니라',5812),
('deu-33-2','deu','신명기',33,2,'그가 일렀으되 여호와께서 시내 산에서 오시고 세일 산에서 일어나시고 바란 산에서 비추시고 일만 성도 가운데에 강림하셨고 그의 오른손에는 그들을 위해 번쩍이는 불이 있도다',5813),
