('deu-33-11','deu','신명기',33,11,'여호와여 그의 재산을 풍족하게 하시고 그의 손의 일을 받으소서 그를 대적하여 일어나는 자와 미워하는 자의 허리를 꺾으사 다시 일어나지 못하게 하옵소서',5822),
('deu-33-12','deu','신명기',33,12,'베냐민에 대하여는 일렀으되 여호와의 사랑을 입은 자는 그 곁에 안전히 살리로다 여호와께서 그를 날이 마치도록 보호하시고 그를 자기 어깨 사이에 있게 하시리로다',5823),
('deu-33-13','deu','신명기',33,13,'요셉에 대하여는 일렀으되 원하건대 그 땅이 여호와께 복을 받아 하늘의 보물인 이슬과 땅 아래에 저장한 물과',5824),
('deu-33-14','deu','신명기',33,14,'태양이 결실하게 하는 선물과 태음이 자라게 하는 선물과',5825),
