('jos-1-8','jos','여호수아',1,8,'이 율법책을 네 입에서 떠나지 말게 하며 주야로 그것을 묵상하여 그 안에 기록된 대로 다 지켜 행하라 그리하면 네 길이 평탄하게 될 것이며 네가 형통하리라',5860),
('jos-1-9','jos','여호수아',1,9,'내가 네게 명령한 것이 아니냐 강하고 담대하라 두려워하지 말며 놀라지 말라 네가 어디로 가든지 네 하나님 여호와가 너와 함께 하느니라 하시니라',5861),
('jos-1-10','jos','여호수아',1,10,'이에 여호수아가 그 백성의 관리들에게 명령하여 이르되',5862),
('jos-1-11','jos','여호수아',1,11,'진중에 두루 다니며 그 백성에게 명령하여 이르기를 양식을 준비하라 사흘 안에 너희가 이 요단을 건너 너희의 하나님 여호와께서 너희에게 주사 차지하게 하시는 땅을 차지하기 위하여 들어갈 것임이니라 하라',5863),
('jos-1-12','jos','여호수아',1,12,'여호수아가 또 르우벤 지파와 갓 지파와 므낫세 반 지파에게 말하여 이르되',5864),
('jos-1-13','jos','여호수아',1,13,'여호와의 종 모세가 너희에게 명령하여 이르기를 너희의 하나님 여호와께서 너희에게 안식을 주시며 이 땅을 너희에게 주시리라 하였나니 너희는 그 말을 기억하라',5865),
('jos-1-14','jos','여호수아',1,14,'너희의 처자와 가축은 모세가 너희에게 준 요단 이쪽 땅에 머무르려니와 너희 모든 용사들은 무장하고 너희의 형제보다 앞서 건너가서 그들을 돕되',5866),
('jos-1-15','jos','여호수아',1,15,'여호와께서 너희를 안식하게 하신 것 같이 너희의 형제도 안식하며 그들도 너희의 하나님 여호와께서 주시는 그 땅을 차지하기까지 하라 그리고 너희는 너희 소유지 곧 여호와의 종 모세가 너희에게 준 요단 이쪽 해 돋는 곳으로 돌아와서 그것을 차지할지니라',5867),
('jos-1-16','jos','여호수아',1,16,'그들이 여호수아에게 대답하여 이르되 당신이 우리에게 명령하신 것은 우리가 다 행할 것이요 당신이 우리를 보내시는 곳에는 우리가 가리이다',5868),
('jos-1-17','jos','여호수아',1,17,'우리는 범사에 모세에게 순종한 것 같이 당신에게 순종하려니와 오직 당신의 하나님 여호와께서 모세와 함께 계시던 것 같이 당신과 함께 계시기를 원하나이다',5869),
('jos-1-18','jos','여호수아',1,18,'누구든지 당신의 명령을 거역하며 당신의 말씀을 순종하지 아니하는 자는 죽임을 당하리니 오직 강하고 담대하소서',5870),
('jos-2-1','jos','여호수아',2,1,'눈의 아들 여호수아가 싯딤에서 두 사람을 정탐꾼으로 보내며 이르되 가서 그 땅과 여리고를 엿보라 하매 그들이 가서 라합이라 하는 기생의 집에 들어가 거기서 유숙하더니',5871),
('jos-2-2','jos','여호수아',2,2,'어떤 사람이 여리고 왕에게 말하여 이르되 보소서 이 밤에 이스라엘 자손 중의 몇 사람이 이 땅을 정탐하러 이리로 들어왔나이다',5872),
('jos-2-3','jos','여호수아',2,3,'여리고 왕이 라합에게 사람을 보내어 이르되 네게로 와서 네 집에 들어간 그 사람들을 끌어내라 그들은 이 온 땅을 정탐하러 왔느니라',5873),
('jos-2-4','jos','여호수아',2,4,'그 여인이 그 두 사람을 이미 숨긴지라 이르되 과연 그 사람들이 내게 왔었으나 그들이 어디에서 왔는지 나는 알지 못하였고',5874),
('jos-2-5','jos','여호수아',2,5,'그 사람들이 어두워 성문을 닫을 때쯤 되어 나갔으니 어디로 갔는지 내가 알지 못하나 급히 따라가라 그리하면 그들을 따라잡으리라 하였으나',5875),
('jos-2-6','jos','여호수아',2,6,'그가 이미 그들을 이끌고 지붕에 올라가서 그 지붕에 벌여 놓은 삼대에 숨겼더라',5876),
('jos-2-7','jos','여호수아',2,7,'그 사람들은 요단 나루터까지 그들을 쫓아갔고 그들을 뒤쫓는 자들이 나가자 곧 성문을 닫았더라',5877),
('jos-2-8','jos','여호수아',2,8,'또 그들이 눕기 전에 라합이 지붕에 올라가서 그들에게 이르러',5878),
('jos-2-9','jos','여호수아',2,9,'말하되 여호와께서 이 땅을 너희에게 주신 줄을 내가 아노라 우리가 너희를 심히 두려워하고 이 땅 주민들이 다 너희 앞에서 간담이 녹나니',5879),
('jos-2-10','jos','여호수아',2,10,'이는 너희가 애굽에서 나올 때에 여호와께서 너희 앞에서 홍해 물을 마르게 하신 일과 너희가 요단 저쪽에 있는 아모리 사람의 두 왕 시혼과 옥에게 행한 일 곧 그들을 전멸시킨 일을 우리가 들었음이니라',5880),
('jos-2-11','jos','여호수아',2,11,'우리가 듣자 곧 마음이 녹았고 너희로 말미암아 사람이 정신을 잃었나니 너희의 하나님 여호와는 위로는 하늘에서도 아래로는 땅에서도 하나님이시니라',5881),
('jos-2-12','jos','여호수아',2,12,'그러므로 이제 청하노니 내가 너희를 선대하였은즉 너희도 내 아버지의 집을 선대하도록 여호와의 이름으로 내게 맹세하고 내게 증표를 내라',5882),
('jos-2-13','jos','여호수아',2,13,'그리고 나의 부모와 나의 남녀 형제와 그들에게 속한 모든 사람을 살려 주어 우리 목숨을 죽음에서 건져내라',5883),
('jos-2-14','jos','여호수아',2,14,'그 사람들이 그에게 이르되 네가 우리의 이 일을 누설하지 아니하면 우리의 목숨으로 너희를 대신할 것이요 여호와께서 우리에게 이 땅을 주실 때에는 인자하고 진실하게 너를 대우하리라',5884),
('jos-2-15','jos','여호수아',2,15,'라합이 그들을 창문에서 줄로 달아 내리니 그의 집이 성벽 위에 있으므로 그가 성벽 위에 거주하였음이라',5885),
('jos-2-16','jos','여호수아',2,16,'라합이 그들에게 이르되 두렵건대 뒤쫓는 사람들이 너희와 마주칠까 하노니 너희는 산으로 가서 거기서 사흘 동안 숨어 있다가 뒤쫓는 자들이 돌아간 후에 너희의 길을 갈지니라',5886),
('jos-2-17','jos','여호수아',2,17,'그 사람들이 그에게 이르되 네가 우리에게 서약하게 한 이 맹세에 대하여 우리가 허물이 없게 하리니',5887),
('jos-2-18','jos','여호수아',2,18,'우리가 이 땅에 들어올 때에 우리를 달아 내린 창문에 이 붉은 줄을 매고 네 부모와 형제와 네 아버지의 가족을 다 네 집에 모으라',5888),
('jos-2-19','jos','여호수아',2,19,'누구든지 네 집 문을 나가서 거리로 가면 그의 피가 그의 머리로 돌아갈 것이요 우리는 허물이 없으리라 그러나 누구든지 너와 함께 집에 있는 자에게 손을 대면 그의 피는 우리의 머리로 돌아오려니와',5889),
('jos-2-20','jos','여호수아',2,20,'네가 우리의 이 일을 누설하면 네가 우리에게 서약하게 한 맹세에 대하여 우리에게 허물이 없으리라 하니',5890),
('jos-2-21','jos','여호수아',2,21,'라합이 이르되 너희의 말대로 할 것이라 하고 그들을 보내어 가게 하고 붉은 줄을 창문에 매니라',5891),
('jos-2-22','jos','여호수아',2,22,'그들이 가서 산에 이르러 뒤쫓는 자들이 돌아가기까지 사흘을 거기 머물매 뒤쫓는 자들이 그들을 길에서 두루 찾다가 찾지 못하니라',5892),
('jos-2-23','jos','여호수아',2,23,'그 두 사람이 돌이켜 산에서 내려와 강을 건너 눈의 아들 여호수아에게 나아가서 그들이 겪은 모든 일을 고하고',5893),
('jos-2-24','jos','여호수아',2,24,'또 여호수아에게 이르되 진실로 여호와께서 그 온 땅을 우리 손에 주셨으므로 그 땅의 모든 주민이 우리 앞에서 간담이 녹더이다 하더라',5894),
('jos-3-1','jos','여호수아',3,1,'또 여호수아가 아침에 일찍이 일어나서 그와 모든 이스라엘 자손들과 더불어 싯딤에서 떠나 요단에 이르러 건너가기 전에 거기서 유숙하니라',5895),
('jos-3-2','jos','여호수아',3,2,'사흘 후에 관리들이 진중으로 두루 다니며',5896),
('jos-3-3','jos','여호수아',3,3,'백성에게 명령하여 이르되 너희는 레위 사람 제사장들이 너희 하나님 여호와의 언약궤 메는 것을 보거든 너희가 있는 곳을 떠나 그 뒤를 따르라',5897),
('jos-3-4','jos','여호수아',3,4,'그러나 너희와 그 사이 거리가 이천 규빗쯤 되게 하고 그것에 가까이 하지는 말라 그리하면 너희가 행할 길을 알리니 너희가 이전에 이 길을 지나보지 못하였음이니라 하니라',5898),
('jos-3-5','jos','여호수아',3,5,'여호수아가 또 백성에게 이르되 너희는 자신을 성결하게 하라 여호와께서 내일 너희 가운데에 기이한 일들을 행하시리라',5899),
('jos-3-6','jos','여호수아',3,6,'여호수아가 또 제사장들에게 말하여 이르되 언약궤를 메고 백성에 앞서 건너라 하매 곧 언약궤를 메고 백성에 앞서 나아가니라',5900),
('jos-3-7','jos','여호수아',3,7,'여호와께서 여호수아에게 이르시되 내가 오늘부터 시작하여 너를 온 이스라엘의 목전에서 크게 하여 내가 모세와 함께 있었던 것 같이 너와 함께 있는 것을 그들이 알게 하리라',5901),
('jos-3-8','jos','여호수아',3,8,'너는 언약궤를 멘 제사장들에게 명령하여 이르기를 너희가 요단 물 가에 이르거든 요단에 들어서라 하라',5902),
('jos-3-9','jos','여호수아',3,9,'여호수아가 이스라엘 자손에게 이르되 이리 와서 너희의 하나님 여호와의 말씀을 들으라 하고',5903),
('jos-3-10','jos','여호수아',3,10,'또 말하되 살아 계신 하나님이 너희 가운데에 계시사 가나안 족속과 헷 족속과 히위 족속과 브리스 족속과 기르가스 족속과 아모리 족속과 여부스 족속을 너희 앞에서 반드시 쫓아내실 줄을 이것으로서 너희가 알리라',5904),
('jos-3-11','jos','여호수아',3,11,'보라 온 땅의 주의 언약궤가 너희 앞에서 요단을 건너가나니',5905),
('jos-3-12','jos','여호수아',3,12,'이제 이스라엘 지파 중에서 각 지파에 한 사람씩 열두 명을 택하라',5906),
('jos-3-13','jos','여호수아',3,13,'온 땅의 주 여호와의 궤를 멘 제사장들의 발바닥이 요단 물을 밟고 멈추면 요단 물 곧 위에서부터 흘러내리던 물이 끊어지고 한 곳에 쌓여 서리라',5907),
('jos-3-14','jos','여호수아',3,14,'백성이 요단을 건너려고 자기들의 장막을 떠날 때에 제사장들은 언약궤를 메고 백성 앞에서 나아가니라',5908),
('jos-3-15','jos','여호수아',3,15,'요단이 곡식 거두는 시기에는 항상 언덕에 넘치더라 궤를 멘 자들이 요단에 이르며 궤를 멘 제사장들의 발이 물 가에 잠기자',5909),
('jos-3-16','jos','여호수아',3,16,'곧 위에서부터 흘러내리던 물이 그쳐서 사르단에 가까운 매우 멀리 있는 아담 성읍 변두리에 일어나 한 곳에 쌓이고 아라바의 바다 염해로 향하여 흘러가는 물은 온전히 끊어지매 백성이 여리고 앞으로 바로 건널새',5910),
('jos-3-17','jos','여호수아',3,17,'여호와의 언약궤를 멘 제사장들은 요단 가운데 마른 땅에 굳게 섰고 그 모든 백성이 요단을 건너기를 마칠 때까지 모든 이스라엘은 그 마른 땅으로 건너갔더라',5911),
('jos-4-1','jos','여호수아',4,1,'그 모든 백성이 요단을 건너가기를 마치매 여호와께서 여호수아에게 말씀하여 이르시되',5912),
('jos-4-2','jos','여호수아',4,2,'백성의 각 지파에 한 사람씩 열두 사람을 택하고',5913),
('jos-4-3','jos','여호수아',4,3,'그들에게 명령하여 이르기를 요단 가운데 제사장들의 발이 굳게 선 그 곳에서 돌 열둘을 택하여 그것을 가져다가 오늘밤 너희가 유숙할 그 곳에 두게 하라 하시니라',5914),
('jos-4-4','jos','여호수아',4,4,'여호수아가 이스라엘 자손 중에서 각 지파에 한 사람씩 준비한 그 열두 사람을 불러',5915),
('jos-4-5','jos','여호수아',4,5,'그들에게 이르되 요단 가운데로 들어가 너희 하나님 여호와의 궤 앞으로 가서 이스라엘 자손들의 지파 수대로 각기 돌 한 개씩 가져다가 어깨에 메라',5916),
('jos-4-6','jos','여호수아',4,6,'이것이 너희 중에 표징이 되리라 후일에 너희의 자손들이 물어 이르되 이 돌들은 무슨 뜻이냐 하거든',5917),
('jos-4-7','jos','여호수아',4,7,'그들에게 이르기를 요단 물이 여호와의 언약궤 앞에서 끊어졌나니 곧 언약궤가 요단을 건널 때에 요단 물이 끊어졌으므로 이 돌들이 이스라엘 자손에게 영원히 기념이 되리라 하라 하니라',5918),
('jos-4-8','jos','여호수아',4,8,'이스라엘 자손들이 여호수아가 명령한 대로 행하되 여호와께서 여호수아에게 이르신 대로 이스라엘 자손들의 지파의 수를 따라 요단 가운데에서 돌 열둘을 택하여 자기들이 유숙할 곳으로 가져다가 거기에 두었더라',5919),
('jos-4-9','jos','여호수아',4,9,'여호수아가 또 요단 가운데 곧 언약궤를 멘 제사장들의 발이 선 곳에 돌 열둘을 세웠더니 오늘까지 거기에 있더라',5920),
('jos-4-10','jos','여호수아',4,10,'또 여호와께서 여호수아에게 명령하사 백성에게 말하게 하신 일 곧 모세가 여호수아에게 명령한 일이 다 마치기까지 궤를 멘 제사장들이 요단 가운데에 서 있고 백성은 속히 건넜으며',5921),
('jos-4-11','jos','여호수아',4,11,'모든 백성이 건너기를 마친 후에 여호와의 궤와 제사장들이 백성의 목전에서 건넜으며',5922),
('jos-4-12','jos','여호수아',4,12,'르우벤 자손과 갓 자손과 므낫세 반 지파는 모세가 그들에게 이른 것 같이 무장하고 이스라엘 자손들보다 앞서 건너갔으니',5923),
('jos-4-13','jos','여호수아',4,13,'무장한 사만 명 가량이 여호와 앞에서 건너가 싸우려고 여리고 평지에 이르니라',5924),
('jos-4-14','jos','여호수아',4,14,'그 날에 여호와께서 모든 이스라엘의 목전에서 여호수아를 크게 하시매 그가 생존한 날 동안에 백성이 그를 두려워하기를 모세를 두려워하던 것 같이 하였더라',5925),
('jos-4-15','jos','여호수아',4,15,'여호와께서 여호수아에게 말씀하여 이르시되',5926),
('jos-4-16','jos','여호수아',4,16,'증거궤를 멘 제사장들에게 명령하여 요단에서 올라오게 하라 하신지라',5927),
('jos-4-17','jos','여호수아',4,17,'여호수아가 제사장들에게 명령하여 이르기를 요단에서 올라오라 하매',5928),
('jos-4-18','jos','여호수아',4,18,'여호와의 언약궤를 멘 제사장들이 요단 가운데에서 나오며 그 발바닥으로 육지를 밟는 동시에 요단 물이 본 곳으로 도로 흘러서 전과 같이 언덕에 넘쳤더라',5929),
('jos-4-19','jos','여호수아',4,19,'첫째 달 십일에 백성이 요단에서 올라와 여리고 동쪽 경계 길갈에 진 치매',5930),
('jos-4-20','jos','여호수아',4,20,'여호수아가 요단에서 가져온 그 열두 돌을 길갈에 세우고',5931),
('jos-4-21','jos','여호수아',4,21,'이스라엘 자손들에게 말하여 이르되 후일에 너희의 자손들이 그들의 아버지에게 묻기를 이 돌들은 무슨 뜻이니이까 하거든',5932),
('jos-4-22','jos','여호수아',4,22,'너희는 너희의 자손들에게 알게 하여 이르기를 이스라엘이 마른 땅을 밟고 이 요단을 건넜음이라',5933),
('jos-4-23','jos','여호수아',4,23,'너희의 하나님 여호와께서 요단 물을 너희 앞에서 마르게 하사 너희를 건너게 하신 것이 너희의 하나님 여호와께서 우리 앞에 홍해를 말리시고 우리를 건너게 하심과 같았나니',5934),
('jos-4-24','jos','여호수아',4,24,'이는 땅의 모든 백성에게 여호와의 손이 강하신 것을 알게 하며 너희가 너희의 하나님 여호와를 항상 경외하게 하려 하심이라 하라',5935),
('jos-5-1','jos','여호수아',5,1,'요단 서쪽의 아모리 사람의 모든 왕들과 해변의 가나안 사람의 모든 왕들이 여호와께서 요단 물을 이스라엘 자손들 앞에서 말리시고 우리를 건너게 하셨음을 듣고 마음이 녹았고 이스라엘 자손들 때문에 정신을 잃었더라',5936),
('jos-5-2','jos','여호수아',5,2,'그 때에 여호와께서 여호수아에게 이르시되 너는 부싯돌로 칼을 만들어 이스라엘 자손들에게 다시 할례를 행하라 하시매',5937),
('jos-5-3','jos','여호수아',5,3,'여호수아가 부싯돌로 칼을 만들어 할례 산에서 이스라엘 자손들에게 할례를 행하니라',5938),
('jos-5-4','jos','여호수아',5,4,'여호수아가 할례를 시행한 까닭은 이것이니 애굽에서 나온 모든 백성 중 남자 곧 모든 군사는 애굽에서 나온 후 광야 길에서 죽었는데',5939),
('jos-5-5','jos','여호수아',5,5,'그 나온 백성은 다 할례를 받았으나 다만 애굽에서 나온 후 광야 길에서 난 자는 할례를 받지 못하였음이라',5940),
('jos-5-6','jos','여호수아',5,6,'이스라엘 자손들이 여호와의 음성을 청종하지 아니하므로 여호와께서 그들에게 대하여 맹세하사 그들의 조상들에게 맹세하여 우리에게 주리라고 하신 땅 곧 젖과 꿀이 흐르는 땅을 그들이 보지 못하게 하리라 하시매 애굽에서 나온 족속 곧 군사들이 다 멸절하기까지 사십 년 동안을 광야에서 헤매었더니',5941),
('jos-5-7','jos','여호수아',5,7,'그들의 대를 잇게 하신 이 자손에게 여호수아가 할례를 행하였으니 길에서는 그들에게 할례를 행하지 못하였으므로 할례 없는 자가 되었음이었더라',5942),
('jos-5-8','jos','여호수아',5,8,'또 그 모든 백성에게 할례 행하기를 마치매 백성이 진중 각 처소에 머물며 낫기를 기다릴 때에',5943),
('jos-5-9','jos','여호수아',5,9,'여호와께서 여호수아에게 이르시되 내가 오늘 애굽의 수치를 너희에게서 떠나가게 하였다 하셨으므로 그 곳 이름을 오늘까지 길갈이라 하느니라',5944),
('jos-5-10','jos','여호수아',5,10,'또 이스라엘 자손들이 길갈에 진 쳤고 그 달 십사일 저녁에는 여리고 평지에서 유월절을 지켰으며',5945),
('jos-5-11','jos','여호수아',5,11,'유월절 이튿날에 그 땅의 소산물을 먹되 그 날에 무교병과 볶은 곡식을 먹었더라',5946),
('jos-5-12','jos','여호수아',5,12,'또 그 땅의 소산물을 먹은 다음 날에 만나가 그쳤으니 이스라엘 사람들이 다시는 만나를 얻지 못하였고 그 해에 가나안 땅의 소출을 먹었더라',5947),
('jos-5-13','jos','여호수아',5,13,'여호수아가 여리고에 가까이 이르렀을 때에 눈을 들어 본즉 한 사람이 칼을 빼어 손에 들고 마주 서 있는지라 여호수아가 나아가서 그에게 묻되 너는 우리를 위하느냐 우리의 적들을 위하느냐 하니',5948),
('jos-5-14','jos','여호수아',5,14,'그가 이르되 아니라 나는 여호와의 군대 대장으로 지금 왔느니라 하는지라 여호수아가 얼굴을 땅에 대고 엎드려 절하고 그에게 이르되 내 주여 종에게 무슨 말씀을 하려 하시나이까',5949),
('jos-5-15','jos','여호수아',5,15,'여호와의 군대 대장이 여호수아에게 이르되 네 발에서 신을 벗으라 네가 선 곳은 거룩하니라 하니 여호수아가 그대로 행하니라',5950),
('jos-6-1','jos','여호수아',6,1,'이스라엘 자손들로 말미암아 여리고는 굳게 닫혔고 출입하는 자가 없더라',5951),
('jos-6-2','jos','여호수아',6,2,'여호와께서 여호수아에게 이르시되 보라 내가 여리고와 그 왕과 용사들을 네 손에 넘겨 주었으니',5952),
('jos-6-3','jos','여호수아',6,3,'너희 모든 군사는 그 성을 둘러 성 주위를 매일 한 번씩 돌되 엿새 동안을 그리하라',5953),
('jos-6-4','jos','여호수아',6,4,'제사장 일곱은 일곱 양각 나팔을 잡고 언약궤 앞에서 나아갈 것이요 일곱째 날에는 그 성을 일곱 번 돌며 그 제사장들은 나팔을 불 것이며',5954),
('jos-6-5','jos','여호수아',6,5,'제사장들이 양각 나팔을 길게 불어 그 나팔 소리가 너희에게 들릴 때에는 백성은 다 큰 소리로 외쳐 부를 것이라 그리하면 그 성벽이 무너져 내리리니 백성은 각기 앞으로 올라갈지니라 하시매',5955),
('jos-6-6','jos','여호수아',6,6,'눈의 아들 여호수아가 제사장들을 불러 그들에게 이르되 너희는 언약궤를 메고 제사장 일곱은 양각 나팔 일곱을 잡고 여호와의 궤 앞에서 나아가라 하고',5956),
('jos-6-7','jos','여호수아',6,7,'또 백성에게 이르되 나아가서 그 성을 돌되 무장한 자들이 여호와의 궤 앞에서 나아갈지니라 하니라',5957),
('jos-6-8','jos','여호수아',6,8,'여호수아가 백성에게 이르기를 마치매 제사장 일곱은 양각 나팔 일곱을 잡고 여호와 앞에서 나아가며 나팔을 불고 여호와의 언약궤는 그 뒤를 따르며',5958),
('jos-6-9','jos','여호수아',6,9,'그 무장한 자들은 나팔 부는 제사장들 앞에서 행진하며 후군은 궤 뒤를 따르고 제사장들은 나팔을 불며 행진하더라',5959),
('jos-6-10','jos','여호수아',6,10,'여호수아가 백성에게 명령하여 이르되 너희는 외치지 말며 너희 음성을 들리게 하지 말며 너희 입에서 아무 말도 내지 말라 그리하다가 내가 너희에게 명령하여 외치라 하는 날에 외칠지니라 하고',5960),
('jos-6-11','jos','여호수아',6,11,'여호와의 궤가 그 성을 한 번 돌게 하고 그들이 진영으로 들어와서 진영에서 자니라',5961),
('jos-6-12','jos','여호수아',6,12,'또 여호수아가 아침에 일찍이 일어나니 제사장들이 여호와의 궤를 메고',5962),
('jos-6-13','jos','여호수아',6,13,'제사장 일곱은 양각 나팔 일곱을 잡고 여호와의 궤 앞에서 계속 행진하며 나팔을 불고 무장한 자들은 그 앞에 행진하며 후군은 여호와의 궤 뒤를 따르고 제사장들은 나팔을 불며 행진하니라',5963),
('jos-6-14','jos','여호수아',6,14,'그 둘째 날에도 그 성을 한 번 돌고 진영으로 돌아오니라 엿새 동안을 이같이 행하니라',5964),
('jos-6-15','jos','여호수아',6,15,'일곱째 날 새벽에 그들이 일찍이 일어나서 전과 같은 방식으로 그 성을 일곱 번 도니 그 성을 일곱 번 돌기는 그 날뿐이었더라',5965),
('jos-6-16','jos','여호수아',6,16,'일곱 번째에 제사장들이 나팔을 불 때에 여호수아가 백성에게 이르되 외치라 여호와께서 너희에게 이 성을 주셨느니라',5966),
('jos-6-17','jos','여호수아',6,17,'이 성과 그 가운데에 있는 모든 것은 여호와께 온전히 바치되 기생 라합과 그 집에 동거하는 자는 모두 살려 주라 이는 우리가 보낸 사자들을 그가 숨겨 주었음이니라',5967),
('jos-6-18','jos','여호수아',6,18,'너희는 온전히 바치고 그 바친 것 중에서 어떤 것이든지 취하여 너희가 이스라엘 진영으로 바치는 것이 되게 하여 고통을 당하게 되지 아니하도록 오직 너희는 그 바친 물건에 손대지 말라',5968),
('jos-6-19','jos','여호수아',6,19,'은금과 동철 기구들은 다 여호와께 구별될 것이니 그것을 여호와의 곳간에 들일지니라 하니라',5969),
('jos-6-20','jos','여호수아',6,20,'이에 백성은 외치고 제사장들은 나팔을 불매 백성이 나팔 소리를 들을 때에 크게 소리 질러 외치니 성벽이 무너져 내린지라 백성이 각기 앞으로 나아가 그 성에 들어가서 그 성을 점령하고',5970),
('jos-6-21','jos','여호수아',6,21,'그 성 안에 있는 모든 것을 온전히 바치되 남녀 노소와 소와 양과 나귀를 칼날로 멸하니라',5971),
('jos-6-22','jos','여호수아',6,22,'여호수아가 그 땅을 정탐한 두 사람에게 이르되 그 기생의 집에 들어가서 너희가 그 여인에게 맹세한 대로 그와 그에게 속한 모든 것을 이끌어 내라 하매',5972),
('jos-6-23','jos','여호수아',6,23,'정탐한 젊은이들이 들어가서 라합과 그의 부모와 그의 형제와 그에게 속한 모든 것을 이끌어 내고 또 그의 친족도 다 이끌어 내어 그들을 이스라엘의 진영 밖에 두고',5973),
('jos-6-24','jos','여호수아',6,24,'무리가 그 성과 그 가운데에 있는 모든 것을 불로 사르고 은금과 동철 기구는 여호와의 집 곳간에 두었더라',5974),
('jos-6-25','jos','여호수아',6,25,'여호수아가 기생 라합과 그의 아버지의 가족과 그에게 속한 모든 것을 살렸으므로 그가 오늘까지 이스라엘 중에 거주하였으니 이는 여호수아가 여리고를 정탐하려고 보낸 사자들을 숨겼음이었더라',5975),
('jos-6-26','jos','여호수아',6,26,'여호수아가 그 때에 맹세하게 하여 이르되 누구든지 일어나서 이 여리고 성을 건축하는 자는 여호와 앞에서 저주를 받을 것이라 그 기초를 쌓을 때에 그의 맏아들을 잃을 것이요 그 문을 세울 때에 그의 막내아들을 잃으리라 하였더라',5976),
('jos-6-27','jos','여호수아',6,27,'여호와께서 여호수아와 함께 하시니 여호수아의 소문이 그 온 땅에 퍼지니라',5977),
('jos-7-1','jos','여호수아',7,1,'이스라엘 자손들이 온전히 바친 물건으로 말미암아 범죄하였으니 이는 유다 지파 세라의 증손 삽디의 손자 갈미의 아들 아간이 온전히 바친 물건을 가졌음이라 여호와께서 이스라엘 자손들에게 진노하시니라',5978),
('jos-7-2','jos','여호수아',7,2,'여호수아가 여리고에서 사람을 벧엘 동쪽 벧아웬 곁에 있는 아이로 보내며 그들에게 말하여 이르되 올라가서 그 땅을 정탐하라 하매 그 사람들이 올라가서 아이를 정탐하고',5979),
('jos-7-3','jos','여호수아',7,3,'여호수아에게로 돌아와 그에게 이르되 백성을 다 올라가게 하지 말고 이삼천 명만 올라가서 아이를 치게 하소서 그들은 소수이니 모든 백성을 그리로 보내어 수고롭게 하지 마소서 하므로',5980),
('jos-7-4','jos','여호수아',7,4,'백성 중 삼천 명쯤 그리로 올라갔다가 아이 사람 앞에서 도망하니',5981),
('jos-7-5','jos','여호수아',7,5,'아이 사람이 그들을 삼십육 명쯤 쳐죽이고 성문 앞에서부터 스바림까지 쫓아가 내려가는 비탈에서 쳤으므로 백성의 마음이 녹아 물 같이 된지라',5982),
('jos-7-6','jos','여호수아',7,6,'여호수아가 옷을 찢고 이스라엘 장로들과 함께 여호와의 궤 앞에서 땅에 엎드려 머리에 티끌을 뒤집어쓰고 저물도록 있다가',5983),
('jos-7-7','jos','여호수아',7,7,'이르되 슬프도소이다 주 여호와여 어찌하여 이 백성을 인도하여 요단을 건너게 하시고 우리를 아모리 사람의 손에 넘겨 멸망시키려 하셨나이까 우리가 요단 저쪽을 만족하게 여겨 거주하였더면 좋을 뻔하였나이다',5984),
('jos-7-8','jos','여호수아',7,8,'주여 이스라엘이 그의 원수들 앞에서 돌아섰으니 내가 무슨 말을 하오리이까',5985),
('jos-7-9','jos','여호수아',7,9,'가나안 사람과 이 땅의 모든 사람들이 듣고 우리를 둘러싸고 우리 이름을 세상에서 끊으리니 주의 크신 이름을 위하여 어떻게 하시려 하나이까 하니',5986),
('jos-7-10','jos','여호수아',7,10,'여호와께서 여호수아에게 이르시되 일어나라 어찌하여 이렇게 엎드렸느냐',5987),
('jos-7-11','jos','여호수아',7,11,'이스라엘이 범죄하여 내가 그들에게 명령한 나의 언약을 어겼으며 또한 그들이 온전히 바친 물건을 가져가고 도둑질하며 속이고 그것을 그들의 물건들 가운데에 두었느니라',5988),
('jos-7-12','jos','여호수아',7,12,'그러므로 이스라엘 자손들이 그들의 원수 앞에 능히 맞서지 못하고 그 앞에서 돌아섰나니 이는 그들도 온전히 바친 것이 됨이라 그 온전히 바친 물건을 너희 중에서 멸하지 아니하면 내가 다시는 너희와 함께 있지 아니하리라',5989),
('jos-7-13','jos','여호수아',7,13,'너는 일어나서 백성을 거룩하게 하여 이르기를 너희는 내일을 위하여 스스로 거룩하게 하라 이스라엘의 하나님 여호와의 말씀에 이스라엘아 너희 가운데에 온전히 바친 물건이 있나니 너희가 그 온전히 바친 물건을 너희 가운데에서 제하기까지는 네 원수들 앞에 능히 맞서지 못하리라',5990),
('jos-7-14','jos','여호수아',7,14,'너희는 아침에 너희의 지파대로 가까이 나아오라 여호와께 뽑히는 그 지파는 그 족속대로 가까이 나아올 것이요 여호와께 뽑히는 족속은 그 가족대로 가까이 나아올 것이요 여호와께 뽑히는 그 가족은 그 남자들이 가까이 나아올 것이며',5991),
('jos-7-15','jos','여호수아',7,15,'온전히 바친 물건을 가진 자로 뽑힌 자를 불사르되 그와 그의 모든 소유를 그리하라 이는 여호와의 언약을 어기고 이스라엘 가운데에서 망령된 일을 행하였음이라 하셨다 하라',5992),
('jos-7-16','jos','여호수아',7,16,'이에 여호수아가 아침 일찍이 일어나서 이스라엘을 그의 지파대로 가까이 나아오게 하였더니 유다 지파가 뽑혔고',5993),
('jos-7-17','jos','여호수아',7,17,'유다 족속을 가까이 나아오게 하였더니 세라 족속이 뽑혔고 세라 족속의 각 남자를 가까이 나아오게 하였더니 삽디가 뽑혔고',5994),
('jos-7-18','jos','여호수아',7,18,'삽디의 가족 각 남자를 가까이 나아오게 하였더니 유다 지파 세라의 증손이요 삽디의 손자요 갈미의 아들인 아간이 뽑혔더라',5995),
('jos-7-19','jos','여호수아',7,19,'그러므로 여호수아가 아간에게 이르되 내 아들아 청하노니 이스라엘의 하나님 여호와께 영광을 돌려 그 앞에 자복하고 네가 행한 일을 내게 알게 하라 그 일을 내게 숨기지 말라 하니',5996),
('jos-7-20','jos','여호수아',7,20,'아간이 여호수아에게 대답하여 이르되 참으로 나는 이스라엘의 하나님 여호와께 범죄하여 이러이러하게 행하였나이다',5997),
('jos-7-21','jos','여호수아',7,21,'내가 노략한 물건 중에 시날 산의 아름다운 외투 한 벌과 은 이백 세겔과 그 무게가 오십 세겔 되는 금덩이 하나를 보고 탐내어 가졌나이다 보소서 이제 그 물건들을 내 장막 가운데 땅 속에 감추었는데 은은 그 밑에 있나이다 하더라',5998),
('jos-7-22','jos','여호수아',7,22,'이에 여호수아가 사자들을 보내매 그의 장막에 달려가 본즉 물건이 그의 장막 안에 감추어져 있는데 은은 그 밑에 있는지라',5999),
('jos-7-23','jos','여호수아',7,23,'그들이 그것을 장막 가운데서 취하여 여호수아와 이스라엘 모든 자손에게 가지고 오매 그들이 그것을 여호와 앞에 쏟아 놓으니라',6000),
('jos-7-24','jos','여호수아',7,24,'여호수아가 이스라엘 모든 사람과 더불어 세라의 아들 아간을 잡고 그 은과 그 외투와 그 금덩이와 그의 아들들과 그의 딸들과 그의 소들과 그의 나귀들과 그의 양들과 그의 장막과 그에게 속한 모든 것을 이끌고 아골 골짜기로 가서',6001),
('jos-7-25','jos','여호수아',7,25,'여호수아가 이르되 네가 어찌하여 우리를 괴롭게 하였느냐 여호와께서 오늘 너를 괴롭게 하시리라 하니 온 이스라엘이 그를 돌로 치고 물건들도 돌로 치고 불사르고',6002),
('jos-7-26','jos','여호수아',7,26,'그 위에 돌 무더기를 크게 쌓았더니 오늘까지 있더라 여호와께서 그의 맹렬한 진노를 그치시니 그러므로 그 곳 이름을 오늘까지 아골 골짜기라 부르더라',6003),
('jos-8-1','jos','여호수아',8,1,'여호와께서 여호수아에게 이르시되 두려워하지 말라 놀라지 말라 군사를 다 거느리고 일어나 아이로 올라가라 보라 내가 아이 왕과 그의 백성과 그의 성읍과 그의 땅을 다 네 손에 넘겨 주었으니',6004),
('jos-8-2','jos','여호수아',8,2,'너는 여리고와 그 왕에게 행한 것 같이 아이와 그 왕에게 행하되 오직 거기서 탈취할 물건과 가축은 스스로 가지라 너는 아이 성 뒤에 복병을 둘지니라 하시니',6005),
('jos-8-3','jos','여호수아',8,3,'이에 여호수아가 일어나서 군사와 함께 아이로 올라가려 하여 용사 삼만 명을 뽑아 밤에 보내며',6006),
('jos-8-4','jos','여호수아',8,4,'그들에게 명령하여 이르되 너희는 성읍 뒤로 가서 성읍을 향하여 매복하되 그 성읍에서 너무 멀리 하지 말고 다 스스로 준비하라',6007),
('jos-8-5','jos','여호수아',8,5,'나와 나를 따르는 모든 백성은 다 성읍으로 가까이 가리니 그들이 처음과 같이 우리에게로 쳐 올라올 것이라 그리 할 때에 우리가 그들 앞에서 도망하면',6008),
('jos-8-6','jos','여호수아',8,6,'그들이 나와서 우리를 추격하며 이르기를 그들이 처음과 같이 우리 앞에서 도망한다 하고 우리의 유인을 받아 그 성읍에서 멀리 떠날 것이라 우리가 그들 앞에서 도망하거든',6009),
('jos-8-7','jos','여호수아',8,7,'너희는 매복한 곳에서 일어나 그 성읍을 점령하라 너희 하나님 여호와께서 그 성읍을 너희 손에 주시리라',6010),
('jos-8-8','jos','여호수아',8,8,'너희가 그 성읍을 취하거든 그것을 불살라 여호와의 말씀대로 행하라 보라 내가 너희에게 명령하였느니라 하고',6011),
('jos-8-9','jos','여호수아',8,9,'그들을 보내매 그들이 매복할 곳으로 가서 아이 서쪽 벧엘과 아이 사이에 매복하였고 여호수아는 그 밤에 백성 가운데에서 잤더라',6012),
('jos-8-10','jos','여호수아',8,10,'여호수아가 아침에 일찍이 일어나 백성을 점호하고 이스라엘 장로들과 더불어 백성에 앞서 아이로 올라가매',6013),
('jos-8-11','jos','여호수아',8,11,'그와 함께 한 군사가 다 올라가서 그 성읍 앞에 가까이 이르러 아이 북쪽에 진 치니 그와 아이 사이에는 한 골짜기가 있더라',6014),
('jos-8-12','jos','여호수아',8,12,'그가 약 오천 명을 택하여 성읍 서쪽 벧엘과 아이 사이에 매복시키니',6015),
('jos-8-13','jos','여호수아',8,13,'이와 같이 성읍 북쪽에는 온 군대가 있고 성읍 서쪽에는 복병이 있었더라 여호수아가 그 밤에 골짜기 가운데로 들어가니',6016),
('jos-8-14','jos','여호수아',8,14,'아이 왕이 이를 보고 그 성읍 백성과 함께 일찍이 일어나 급히 나가 아라바 앞에 이르러 정한 때에 이스라엘과 싸우려 하나 성읍 뒤에 복병이 있는 줄은 알지 못하였더라',6017),
('jos-8-15','jos','여호수아',8,15,'여호수아와 온 이스라엘이 그들 앞에서 거짓으로 패한 척하여 광야 길로 도망하매',6018),
('jos-8-16','jos','여호수아',8,16,'그 성읍에 있는 모든 백성이 그들을 추격하려고 모여 여호수아를 추격하며 유인함을 받아 아이 성읍을 멀리 떠나니',6019),
('jos-8-17','jos','여호수아',8,17,'아이와 벧엘에 이스라엘을 따라가지 아니한 자가 하나도 없으며 성문을 열어 놓고 이스라엘을 추격하였더라',6020),
('jos-8-18','jos','여호수아',8,18,'여호와께서 여호수아에게 이르시되 네 손에 잡은 단창을 들어 아이를 가리키라 내가 이 성읍을 네 손에 넘겨 주리라 여호수아가 그의 손에 잡은 단창을 들어 그 성읍을 가리키니',6021),
('jos-8-19','jos','여호수아',8,19,'그의 손을 드는 순간에 복병이 그들의 자리에서 급히 일어나 성읍으로 달려 들어가서 점령하고 곧 성읍에 불을 놓았더라',6022),
('jos-8-20','jos','여호수아',8,20,'아이 사람이 뒤를 돌아본즉 그 성읍에 연기가 하늘에 닿은 것이 보이니 이 길로도 저 길로도 도망할 수 없이 되었고 광야로 도망하던 이스라엘 백성은 그 추격하던 자에게로 돌아섰더라',6023),
('jos-8-21','jos','여호수아',8,21,'여호수아와 온 이스라엘이 그 복병이 성읍을 점령함과 성읍에 연기가 오름을 보고 다시 돌이켜 아이 사람들을 쳐죽이고',6024),
('jos-8-22','jos','여호수아',8,22,'복병도 성읍에서 나와 그들을 치매 그들이 이스라엘 중간에 든지라 어떤 사람들은 이쪽에서 어떤 사람들은 저쪽에서 쳐죽여서 한 사람도 남거나 도망하지 못하게 하였고',6025),
('jos-8-23','jos','여호수아',8,23,'아이 왕을 사로잡아 여호수아 앞으로 끌어 왔더라',6026),
('jos-8-24','jos','여호수아',8,24,'이스라엘이 자기들을 광야로 추격하던 모든 아이 주민을 들에서 죽이되 그들을 다 칼날에 엎드러지게 하여 진멸하기를 마치고 온 이스라엘이 아이로 돌아와서 칼날로 죽이매',6027),
('jos-8-25','jos','여호수아',8,25,'그 날에 엎드러진 아이 사람들은 남녀가 모두 만 이천 명이라',6028),
('jos-8-26','jos','여호수아',8,26,'아이 주민들을 진멸하여 바치기까지 여호수아가 단창을 잡아 든 손을 거두지 아니하였고',6029),
('jos-8-27','jos','여호수아',8,27,'오직 그 성읍의 가축과 노략한 것은 여호와께서 여호수아에게 명령하신 대로 이스라엘이 탈취하였더라',6030),
('jos-8-28','jos','여호수아',8,28,'이에 여호수아가 아이를 불살라 그것으로 영원한 무더기를 만들었더니 오늘까지 황폐하였으며',6031),
('jos-8-29','jos','여호수아',8,29,'그가 또 아이 왕을 저녁 때까지 나무에 달았다가 해 질 때에 명령하여 그의 시체를 나무에서 내려 그 성문 어귀에 던지고 그 위에 돌로 큰 무더기를 쌓았더니 그것이 오늘까지 있더라',6032),
('jos-8-30','jos','여호수아',8,30,'그 때에 여호수아가 이스라엘의 하나님 여호와를 위하여 에발 산에 한 제단을 쌓았으니',6033),
('jos-8-31','jos','여호수아',8,31,'이는 여호와의 종 모세가 이스라엘 자손에게 명령한 것과 모세의 율법책에 기록된 대로 쇠 연장으로 다듬지 아니한 새 돌로 만든 제단이라 무리가 여호와께 번제물과 화목제물을 그 위에 드렸으며',6034),
('jos-8-32','jos','여호수아',8,32,'여호수아가 거기서 모세가 기록한 율법을 이스라엘 자손의 목전에서 그 돌에 기록하매',6035),
('jos-8-33','jos','여호수아',8,33,'온 이스라엘과 그 장로들과 관리들과 재판장들과 본토인뿐 아니라 이방인까지 여호와의 언약궤를 멘 레위 사람 제사장들 앞에서 궤의 좌우에 서되 절반은 그리심 산 앞에, 절반은 에발 산 앞에 섰으니 이는 전에 여호와의 종 모세가 이스라엘 백성에게 축복하라고 명령한 대로 함이라',6036),
('jos-8-34','jos','여호수아',8,34,'그 후에 여호수아가 율법책에 기록된 모든 것 대로 축복과 저주하는 율법의 모든 말씀을 낭독하였으니',6037),
('jos-8-35','jos','여호수아',8,35,'모세가 명령한 것은 여호수아가 이스라엘 온 회중과 여자들과 아이와 그들 중에 동행하는 거류민들 앞에서 낭독하지 아니한 말이 하나도 없었더라',6038),
('jos-9-1','jos','여호수아',9,1,'이 일 후에 요단 서쪽 산지와 평지와 레바논 앞 대해 연안에 있는 헷 사람과 아모리 사람과 가나안 사람과 브리스 사람과 히위 사람과 여부스 사람의 모든 왕들이 이 일을 듣고',6039),
('jos-9-2','jos','여호수아',9,2,'모여서 일심으로 여호수아와 이스라엘에 맞서서 싸우려 하더라',6040),
('jos-9-3','jos','여호수아',9,3,'기브온 주민들이 여호수아가 여리고와 아이에 행한 일을 듣고',6041),
('jos-9-4','jos','여호수아',9,4,'꾀를 내어 사신의 모양을 꾸미되 해어진 전대와 해어지고 찢어져서 기운 가죽 포도주 부대를 나귀에 싣고',6042),
('jos-9-5','jos','여호수아',9,5,'그 발에는 낡아서 기운 신을 신고 낡은 옷을 입고 다 마르고 곰팡이가 난 떡을 준비하고',6043),
('jos-9-6','jos','여호수아',9,6,'그들이 길갈 진영으로 가서 여호수아에게 이르러 그와 이스라엘 사람들에게 이르되 우리는 먼 나라에서 왔나이다 이제 우리와 조약을 맺읍시다 하니',6044),
('jos-9-7','jos','여호수아',9,7,'이스라엘 사람들이 히위 사람에게 이르되 너희가 우리 가운데에 거주하는 듯하니 우리가 어떻게 너희와 조약을 맺을 수 있으랴 하나',6045),
('jos-9-8','jos','여호수아',9,8,'그들이 여호수아에게 이르되 우리는 당신의 종들이니이다 하매 여호수아가 그들에게 묻되 너희는 누구며 어디서 왔느냐 하니',6046),
('jos-9-9','jos','여호수아',9,9,'그들이 여호수아에게 대답하되 종들은 당신의 하나님 여호와의 이름으로 말미암아 심히 먼 나라에서 왔사오니 이는 우리가 그의 소문과 그가 애굽에서 행하신 모든 일을 들으며',6047),
('jos-9-10','jos','여호수아',9,10,'또 그가 요단 동쪽에 있는 아모리 사람의 두 왕들 곧 헤스본 왕 시혼과 아스다롯에 있는 바산 왕 옥에게 행하신 모든 일을 들었음이니이다',6048),
('jos-9-11','jos','여호수아',9,11,'그러므로 우리 장로들과 우리 나라의 모든 주민이 우리에게 말하여 이르되 너희는 여행할 양식을 손에 가지고 가서 그들을 만나서 그들에게 이르기를 우리는 당신들의 종들이니 이제 우리와 조약을 맺읍시다 하라 하였나이다',6049),
('jos-9-12','jos','여호수아',9,12,'우리의 이 떡은 우리가 당신들에게로 오려고 떠나던 날에 우리들의 집에서 아직도 뜨거운 것을 양식으로 가지고 왔으나 보소서 이제 말랐고 곰팡이가 났으며',6050),
('jos-9-13','jos','여호수아',9,13,'또 우리가 포도주를 담은 이 가죽 부대도 새 것이었으나 찢어지게 되었으며 우리의 이 옷과 신도 여행이 매우 길었으므로 낡아졌나이다 한지라',6051),
('jos-9-14','jos','여호수아',9,14,'무리가 그들의 양식을 취하고는 어떻게 할지를 여호와께 묻지 아니하고',6052),
('jos-9-15','jos','여호수아',9,15,'여호수아가 곧 그들과 화친하여 그들을 살리리라는 조약을 맺고 회중 족장들이 그들에게 맹세하였더라',6053),
('jos-9-16','jos','여호수아',9,16,'그들과 조약을 맺은 후 사흘이 지나서야 그들이 이웃에서 자기들 중에 거주하는 자들이라 함을 들으니라',6054),
('jos-9-17','jos','여호수아',9,17,'이스라엘 자손이 행군하여 셋째 날에 그들의 여러 성읍들에 이르렀으니 그들의 성읍들은 기브온과 그비라와 브에롯과 기럇여아림이라',6055),
('jos-9-18','jos','여호수아',9,18,'그러나 회중 족장들이 이스라엘의 하나님 여호와로 그들에게 맹세했기 때문에 이스라엘 자손이 그들을 치지 못한지라 그러므로 회중이 다 족장들을 원망하니',6056),
('jos-9-19','jos','여호수아',9,19,'모든 족장이 온 회중에게 이르되 우리가 이스라엘의 하나님 여호와로 그들에게 맹세하였은즉 이제 그들을 건드리지 못하리라',6057),
('jos-9-20','jos','여호수아',9,20,'우리가 그들에게 맹세한 맹약으로 말미암아 진노가 우리에게 임할까 하노니 이렇게 행하여 그들을 살리리라 하고',6058),
('jos-9-21','jos','여호수아',9,21,'무리에게 이르되 그들을 살리라 하니 족장들이 그들에게 이른 대로 그들이 온 회중을 위하여 나무를 패며 물을 긷는 자가 되었더라',6059),
('jos-9-22','jos','여호수아',9,22,'여호수아가 그들을 불러다가 말하여 이르되 너희가 우리 가운데에 거주하면서 어찌하여 심히 먼 곳에서 왔다고 하여 우리를 속였느냐',6060),
('jos-9-23','jos','여호수아',9,23,'그러므로 너희가 저주를 받나니 너희가 대를 이어 종이 되어 다 내 하나님의 집을 위하여 나무를 패며 물을 긷는 자가 되리라 하니',6061),
('jos-9-24','jos','여호수아',9,24,'그들이 여호수아에게 대답하여 이르되 당신의 하나님 여호와께서 그의 종 모세에게 명령하사 이 땅을 다 당신들에게 주고 이 땅의 모든 주민을 당신들 앞에서 멸하라 하신 것이 당신의 종들에게 분명히 들리므로 당신들로 말미암아 우리의 목숨을 잃을까 심히 두려워하여 이같이 하였나이다',6062),
('jos-9-25','jos','여호수아',9,25,'보소서 이제 우리가 당신의 손에 있으니 당신의 의향에 좋고 옳은 대로 우리에게 행하소서 한지라',6063),
('jos-9-26','jos','여호수아',9,26,'여호수아가 곧 그대로 그들에게 행하여 그들을 이스라엘 자손의 손에서 건져서 죽이지 못하게 하니라',6064),
('jos-9-27','jos','여호수아',9,27,'그 날에 여호수아가 그들을 여호와께서 택하신 곳에서 회중을 위하며 여호와의 제단을 위하여 나무를 패며 물을 긷는 자들로 삼았더니 오늘까지 이르니라',6065),
('jos-10-1','jos','여호수아',10,1,'그 때에 여호수아가 아이를 빼앗아 진멸하되 여리고와 그 왕에게 행한 것 같이 아이와 그 왕에게 행한 것과 또 기브온 주민이 이스라엘과 화친하여 그 중에 있다 함을 예루살렘 왕 아도니세덱이 듣고',6066),
('jos-10-2','jos','여호수아',10,2,'크게 두려워하였으니 이는 기브온은 왕도와 같은 큰 성임이요 아이보다 크고 그 사람들은 다 강함이라',6067),
('jos-10-3','jos','여호수아',10,3,'예루살렘 왕 아도니세덱이 헤브론 왕 호함과 야르뭇 왕 비람과 라기스 왕 야비아와 에글론 왕 드빌에게 보내어 이르되',6068),
('jos-10-4','jos','여호수아',10,4,'내게로 올라와 나를 도우라 우리가 기브온을 치자 이는 기브온이 여호수아와 이스라엘 자손과 더불어 화친하였음이니라 하매',6069),
('jos-10-5','jos','여호수아',10,5,'아모리 족속의 다섯 왕들 곧 예루살렘 왕과 헤브론 왕과 야르뭇 왕과 라기스 왕과 에글론 왕이 함께 모여 자기들의 모든 군대를 거느리고 올라와 기브온에 대진하고 싸우니라',6070),
('jos-10-6','jos','여호수아',10,6,'기브온 사람들이 길갈 진영에 사람을 보내어 여호수아에게 전하되 당신의 종들 돕기를 더디게 하지 마시고 속히 우리에게 올라와 우리를 구하소서 산지에 거주하는 아모리 사람의 왕들이 다 모여 우리를 치나이다 하매',6071),
('jos-10-7','jos','여호수아',10,7,'여호수아가 모든 군사와 용사와 더불어 길갈에서 올라가니라',6072),
('jos-10-8','jos','여호수아',10,8,'그 때에 여호와께서 여호수아에게 이르시되 그들을 두려워하지 말라 내가 그들을 네 손에 넘겨 주었으니 그들 중에서 한 사람도 너를 당할 자 없으리라 하신지라',6073),
('jos-10-9','jos','여호수아',10,9,'여호수아가 길갈에서 밤새도록 올라가 갑자기 그들에게 이르니',6074),
('jos-10-10','jos','여호수아',10,10,'여호와께서 그들을 이스라엘 앞에서 패하게 하시므로 여호수아가 그들을 기브온에서 크게 살륙하고 벧 호론에 올라가는 비탈에서 추격하여 아세가와 막게다까지 이르니라',6075),
('jos-10-11','jos','여호수아',10,11,'그들이 이스라엘 앞에서 도망하여 벧 호론의 비탈에서 내려갈 때에 여호와께서 하늘에서 큰 우박 덩이를 아세가에 이르기까지 내리시매 그들이 죽었으니 이스라엘 자손의 칼에 죽은 자보다 우박에 죽은 자가 더 많았더라',6076),
('jos-10-12','jos','여호수아',10,12,'여호와께서 아모리 사람을 이스라엘 자손에게 넘겨 주시던 날에 여호수아가 여호와께 아뢰어 이스라엘의 목전에서 이르되 태양아 너는 기브온 위에 머무르라 달아 너도 아얄론 골짜기에서 그리할지어다 하매',6077),
('jos-10-13','jos','여호수아',10,13,'태양이 머물고 달이 멈추기를 백성이 그 대적에게 원수를 갚기까지 하였느니라 야살의 책에 태양이 중천에 머물러서 거의 종일토록 속히 내려가지 아니하였다고 기록되지 아니하였느냐',6078),
('jos-10-14','jos','여호수아',10,14,'여호와께서 사람의 목소리를 들으신 이같은 날은 전에도 없었고 후에도 없었나니 이는 여호와께서 이스라엘을 위하여 싸우셨음이니라',6079),
('jos-10-15','jos','여호수아',10,15,'여호수아가 온 이스라엘과 더불어 길갈 진영으로 돌아왔더라',6080),
('jos-10-16','jos','여호수아',10,16,'그 다섯 왕들이 도망하여 막게다의 굴에 숨었더니',6081),
('jos-10-17','jos','여호수아',10,17,'어떤 사람이 여호수아에게 고하여 이르되 막게다의 굴에 그 다섯 왕들이 숨은 것을 발견하였나이다 하니',6082),
('jos-10-18','jos','여호수아',10,18,'여호수아가 이르되 굴 어귀에 큰 돌을 굴려 막고 사람을 그 곁에 두어 그들을 지키게 하고',6083),
('jos-10-19','jos','여호수아',10,19,'너희는 지체하지 말고 너희 대적의 뒤를 따라가 그 후군을 쳐서 그들이 자기들의 성읍에 들어가지 못하게 하라 너희 하나님 여호와께서 그들을 너희 손에 넘겨 주셨느니라 하고',6084),
('jos-10-20','jos','여호수아',10,20,'여호수아와 이스라엘 자손이 그들을 크게 살륙하여 거의 멸하였고 그 남은 몇 사람은 견고한 성들로 들어간 고로',6085),
('jos-10-21','jos','여호수아',10,21,'모든 백성이 평안히 막게다 진영으로 돌아와 여호수아에게 이르렀더니 혀를 놀려 이스라엘 자손을 대적하는 자가 없었더라',6086),
('jos-10-22','jos','여호수아',10,22,'그 때에 여호수아가 이르되 굴 어귀를 열고 그 굴에서 그 다섯 왕들을 내게로 끌어내라 하매',6087),
('jos-10-23','jos','여호수아',10,23,'그들이 그대로 하여 그 다섯 왕들 곧 예루살렘 왕과 헤브론 왕과 야르뭇 왕과 라기스 왕과 에글론 왕을 굴에서 그에게로 끌어내니라',6088),
('jos-10-24','jos','여호수아',10,24,'그 왕들을 여호수아에게로 끌어내매 여호수아가 이스라엘 모든 사람을 부르고 자기와 함께 갔던 지휘관들에게 이르되 가까이 와서 이 왕들의 목을 발로 밟으라 하매 그들이 가까이 가서 그들의 목을 밟으매',6089),
('jos-10-25','jos','여호수아',10,25,'여호수아가 그들에게 이르되 두려워하지 말며 놀라지 말고 강하고 담대하라 너희가 맞서서 싸우는 모든 대적에게 여호와께서 다 이와 같이 하시리라 하고',6090),
('jos-10-26','jos','여호수아',10,26,'그 후에 여호수아가 그 왕들을 쳐죽여 다섯 나무에 매달고 저녁까지 나무에 달린 채로 두었다가',6091),
('jos-10-27','jos','여호수아',10,27,'해 질 때에 여호수아가 명령하매 그들의 시체를 나무에서 내려 그들이 숨었던 굴 안에 던지고 굴 어귀를 큰 돌로 막았더니 오늘까지 그대로 있더라',6092),
('jos-10-28','jos','여호수아',10,28,'그 날에 여호수아가 막게다를 취하고 칼날로 그 성읍과 왕을 쳐서 그 성읍과 그 중에 있는 모든 사람을 진멸하여 바치고 한 사람도 남기지 아니하였으니 막게다 왕에게 행한 것이 여리고 왕에게 행한 것과 같았더라',6093),
('jos-10-29','jos','여호수아',10,29,'여호수아가 온 이스라엘과 더불어 막게다에서 립나로 나아가서 립나와 싸우매',6094),
('jos-10-30','jos','여호수아',10,30,'여호와께서 또 그 성읍과 그 왕을 이스라엘의 손에 붙이신지라 칼날로 그 성읍과 그 중의 모든 사람을 쳐서 멸하여 한 사람도 남기지 아니하였으니 그 왕에게 행한 것이 여리고 왕에게 행한 것과 같았더라',6095),
('jos-10-31','jos','여호수아',10,31,'여호수아가 또 온 이스라엘과 더불어 립나에서 라기스로 나아가서 대진하고 싸우더니',6096),
('jos-10-32','jos','여호수아',10,32,'여호와께서 라기스를 이스라엘의 손에 넘겨 주신지라 이튿날에 그 성읍을 점령하고 칼날로 그것과 그 안의 모든 사람을 쳐서 멸하였으니 립나에 행한 것과 같았더라',6097),
('jos-10-33','jos','여호수아',10,33,'그 때에 게셀 왕 호람이 라기스를 도우려고 올라오므로 여호수아가 그와 그의 백성을 쳐서 한 사람도 남기지 아니하였더라',6098),
('jos-10-34','jos','여호수아',10,34,'여호수아가 온 이스라엘과 더불어 라기스에서 에글론으로 나아가서 대진하고 싸워',6099),
('jos-10-35','jos','여호수아',10,35,'그 날에 그 성읍을 취하고 칼날로 그것을 쳐서 그 중에 있는 모든 사람을 당일에 진멸하여 바쳤으니 라기스에 행한 것과 같았더라',6100),
('jos-10-36','jos','여호수아',10,36,'여호수아가 또 온 이스라엘과 더불어 에글론에서 헤브론으로 올라가서 싸워',6101),
('jos-10-37','jos','여호수아',10,37,'그 성읍을 점령하고 그것과 그 왕과 그 속한 성읍들과 그 중의 모든 사람을 칼날로 쳐서 하나도 남기지 아니하였으니 그 성읍들과 그 중의 모든 사람을 진멸하여 바친 것이 에글론에 행한 것과 같았더라',6102),
('jos-10-38','jos','여호수아',10,38,'여호수아가 온 이스라엘과 더불어 돌아와서 드빌에 이르러 싸워',6103),
('jos-10-39','jos','여호수아',10,39,'그 성읍과 그 왕과 그 속한 성읍들을 점령하고 칼날로 그 성읍을 쳐서 그 안의 모든 사람을 진멸하여 바치고 하나도 남기지 아니하였으니 드빌과 그 왕에게 행한 것이 헤브론에 행한 것과 같았으며 립나와 그 왕에게 행한 것과 같았더라',6104),
('jos-10-40','jos','여호수아',10,40,'이와 같이 여호수아가 그 온 땅 곧 산지와 네겝과 평지와 경사지와 그 모든 왕을 쳐서 하나도 남기지 아니하고 호흡이 있는 모든 자는 다 진멸하여 바쳤으니 이스라엘의 하나님 여호와께서 명령하신 것과 같았더라',6105),
('jos-10-41','jos','여호수아',10,41,'여호수아가 또 가데스 바네아에서 가사까지와 온 고센 땅을 기브온에 이르기까지 치매',6106),
('jos-10-42','jos','여호수아',10,42,'이스라엘의 하나님 여호와께서 이스라엘을 위하여 싸우셨으므로 여호수아가 이 모든 왕들과 그들의 땅을 단번에 빼앗으니라',6107),
('jos-10-43','jos','여호수아',10,43,'여호수아가 온 이스라엘과 더불어 길갈 진영으로 돌아왔더라',6108),
('jos-11-1','jos','여호수아',11,1,'하솔 왕 야빈이 이 소식을 듣고 마돈 왕 요밥과 시므론 왕과 악삽 왕과',6109),
('jos-11-2','jos','여호수아',11,2,'및 북쪽 산지와 긴네롯 남쪽 아라바와 평지와 서쪽 돌의 높은 곳에 있는 왕들과',6110),
('jos-11-3','jos','여호수아',11,3,'동쪽과 서쪽의 가나안 족속과 아모리 족속과 헷 족속과 브리스 족속과 산지의 여부스 족속과 미스바 땅 헤르몬 산 아래 히위 족속에게 사람을 보내매',6111),
('jos-11-4','jos','여호수아',11,4,'그들이 그 모든 군대를 거느리고 나왔으니 백성이 많아 해변의 수많은 모래 같고 말과 병거도 심히 많았으며',6112),
('jos-11-5','jos','여호수아',11,5,'이 왕들이 모두 모여 나아와서 이스라엘과 싸우려고 메롬 물 가에 함께 진 쳤더라',6113),
('jos-11-6','jos','여호수아',11,6,'여호와께서 여호수아에게 이르시되 그들로 말미암아 두려워하지 말라 내일 이맘때에 내가 그들을 이스라엘 앞에 넘겨 주어 몰살시키리니 너는 그들의 말 뒷발의 힘줄을 끊고 그들의 병거를 불사르라 하시니라',6114),
('jos-11-7','jos','여호수아',11,7,'이에 여호수아가 모든 군사와 함께 메롬 물 가로 가서 갑자기 습격할 때에',6115),
('jos-11-8','jos','여호수아',11,8,'여호와께서 그들을 이스라엘의 손에 넘겨 주셨기 때문에 그들을 격파하고 큰 시돈과 미스르봇 마임까지 추격하고 동쪽으로는 미스바 골짜기까지 추격하여 한 사람도 남기지 아니하고 쳐죽이고',6116),
('jos-11-9','jos','여호수아',11,9,'여호수아가 여호와께서 자기에게 명령하신 대로 행하여 그들의 말 뒷발의 힘줄을 끊고 그들의 병거를 불로 살랐더라',6117),
('jos-11-10','jos','여호수아',11,10,'하솔은 본래 그 모든 나라의 머리였더니 그 때에 여호수아가 돌아와서 하솔을 취하고 그 왕을 칼날로 쳐죽이고',6118),
('jos-11-11','jos','여호수아',11,11,'그 가운데 모든 사람을 칼날로 쳐서 진멸하여 호흡이 있는 자는 하나도 남기지 아니하였고 또 하솔을 불로 살랐고',6119),
('jos-11-12','jos','여호수아',11,12,'여호수아가 그 왕들의 모든 성읍과 그 모든 왕을 붙잡아 칼날로 쳐서 진멸하여 바쳤으니 여호와의 종 모세가 명령한 것과 같이 하였으되',6120),
('jos-11-13','jos','여호수아',11,13,'여호수아가 하솔만 불살랐고 산 위에 세운 성읍들은 이스라엘이 불사르지 아니하였으며',6121),
('jos-11-14','jos','여호수아',11,14,'이 성읍들의 모든 재물과 가축은 이스라엘 자손들이 탈취하고 모든 사람은 칼날로 쳐서 멸하여 호흡이 있는 자는 하나도 남기지 아니하였으니',6122),
('jos-11-15','jos','여호수아',11,15,'여호와께서 그의 종 모세에게 명령하신 것을 모세는 여호수아에게 명령하였고 여호수아는 그대로 행하여 여호와께서 모세에게 명하신 모든 것을 하나도 행하지 아니한 것이 없었더라',6123),
('jos-11-16','jos','여호수아',11,16,'여호수아가 이같이 그 온 땅 곧 산지와 온 네겝과 고센 온 땅과 평지와 아라바와 이스라엘 산지와 평지를 점령하였으니',6124),
('jos-11-17','jos','여호수아',11,17,'곧 세일로 올라가는 할락 산에서부터 헤르몬 산 아래 레바논 골짜기의 바알갓까지라 그들의 왕들을 모두 잡아 쳐죽였으며',6125),
('jos-11-18','jos','여호수아',11,18,'여호수아가 그 모든 왕들과 싸운 지가 오랫동안이라',6126),
('jos-11-19','jos','여호수아',11,19,'기브온 주민 히위 족속 외에는 이스라엘 자손과 화친한 성읍이 하나도 없고 이스라엘 자손이 싸워서 다 점령하였으니',6127),
('jos-11-20','jos','여호수아',11,20,'그들의 마음이 완악하여 이스라엘을 대적하여 싸우러 온 것은 여호와께서 그리하게 하신 것이라 그들을 진멸하여 바치게 하여 은혜를 입지 못하게 하시고 여호와께서 모세에게 명령하신 대로 그들을 멸하려 하심이었더라',6128),
('jos-11-21','jos','여호수아',11,21,'그 때에 여호수아가 가서 산지와 헤브론과 드빌과 아납과 유다 온 산지와 이스라엘의 온 산지에서 아낙 사람들을 멸절하고 그가 또 그들의 성읍들을 진멸하여 바쳤으므로',6129),
('jos-11-22','jos','여호수아',11,22,'이스라엘 자손의 땅에는 아낙 사람들이 하나도 남지 아니하였고 가사와 가드와 아스돗에만 남았더라',6130),
('jos-11-23','jos','여호수아',11,23,'이와 같이 여호수아가 여호와께서 모세에게 말씀하신 대로 그 온 땅을 점령하여 이스라엘 지파의 구분에 따라 기업으로 주매 그 땅에 전쟁이 그쳤더라',6131),
('jos-12-1','jos','여호수아',12,1,'이스라엘 자손이 요단 저편 해 돋는 쪽 곧 아르논 골짜기에서 헤르몬 산까지의 동쪽 온 아라바를 차지하고 그 땅에서 쳐죽인 왕들은 이러하니라',6132),
('jos-12-2','jos','여호수아',12,2,'시혼은 헤스본에 거주하던 아모리 족속의 왕이라 그가 다스리던 땅은 아르논 골짜기 가에 있는 아로엘에서부터 골짜기 가운데 성읍과 길르앗 절반 곧 암몬 자손의 경계 얍복 강까지이며',6133),
('jos-12-3','jos','여호수아',12,3,'또 동방 아라바 긴네롯 바다까지이며 또 동방 아라바의 바다 곧 염해의 벧여시못으로 통한 길까지와 남쪽으로 비스가 산기슭까지이며',6134),
('jos-12-4','jos','여호수아',12,4,'옥은 르바의 남은 족속으로서 아스다롯과 에드레이에 거주하던 바산의 왕이라',6135),
('jos-12-5','jos','여호수아',12,5,'그가 다스리던 땅은 헤르몬 산과 살르가와 온 바산과 및 그술 사람과 마아가 사람의 경계까지의 길르앗 절반이니 헤스본 왕 시혼의 경계에 접한 곳이라',6136),
('jos-12-6','jos','여호수아',12,6,'여호와의 종 모세와 이스라엘 자손이 그들을 치고 여호와의 종 모세가 그 땅을 르우벤 사람과 갓 사람과 므낫세 반 지파에게 기업으로 주었더라',6137),
('jos-12-7','jos','여호수아',12,7,'여호수아와 이스라엘 자손이 요단 이편 곧 서쪽 레바논 골짜기의 바알갓에서부터 세일로 올라가는 곳 할락 산까지 쳐서 멸한 그 땅의 왕들은 이러하니라 (그 땅을 여호수아가 이스라엘의 지파들에게 구분에 따라 소유로 주었으니',6138),
('jos-12-8','jos','여호수아',12,8,'곧 산지와 평지와 아라바와 경사지와 광야와 네겝 곧 헷 족속과 아모리 족속과 가나안 족속과 브리스 족속과 히위 족속과 여부스 족속의 땅이라)',6139),
