('jos-13-27','jos','여호수아',13,27,'골짜기에 있는 벧 하람과 벧니므라와 숙곳과 사본 곧 헤스본 왕 시혼의 나라의 남은 땅 요단과 그 강 가에서부터 요단 동쪽 긴네렛 바다의 끝까지라',6182),
