('jos-13-30','jos','여호수아',13,30,'그 지역은 마하나임에서부터 온 바산 곧 바산 왕 옥의 온 나라와 바산에 있는 야일의 모든 고을 육십 성읍과',6185),
('jos-13-31','jos','여호수아',13,31,'길르앗 절반과 바산 왕 옥의 나라 성읍 아스다롯과 에드레이라 이는 므낫세의 아들 마길의 자손에게 돌린 것이니 곧 마길 자손의 절반이 그들의 가족대로 받으니라',6186),
('jos-13-32','jos','여호수아',13,32,'요단 동쪽 여리고 맞은편 모압 평지에서 모세가 분배한 기업이 이러하여도',6187),
('jos-13-33','jos','여호수아',13,33,'오직 레위 지파에게는 모세가 기업을 주지 아니하였으니 이는 그들에게 말씀하신 것과 같이 이스라엘의 하나님 여호와께서 그들의 기업이 되심이었더라',6188),
