('jos-14-3','jos','여호수아',14,3,'이는 두 지파와 반 지파의 기업은 모세가 요단 저쪽에서 주었음이요 레위 자손에게는 그들 가운데에서 기업을 주지 아니하였으니',6191),
('jos-14-4','jos','여호수아',14,4,'이는 요셉의 자손이 므낫세와 에브라임의 두 지파가 되었음이라 이 땅에서 레위 사람에게 아무 분깃도 주지 아니하고 다만 거주할 성읍들과 가축과 재산을 위한 목초지만 주었으니',6192),
('jos-14-5','jos','여호수아',14,5,'이스라엘 자손이 여호와께서 모세에게 명령하신 것과 같이 행하여 그 땅을 나누었더라',6193),
('jos-14-6','jos','여호수아',14,6,'그 때에 유다 자손이 길갈에 있는 여호수아에게 나아오고 그니스 사람 여분네의 아들 갈렙이 여호수아에게 말하되 여호와께서 가데스 바네아에서 나와 당신에게 대하여 하나님의 사람 모세에게 이르신 일을 당신이 아시는 바라',6194),
('jos-14-7','jos','여호수아',14,7,'내 나이 사십 세에 여호와의 종 모세가 가데스 바네아에서 나를 보내어 이 땅을 정탐하게 하였으므로 내가 성실한 마음으로 그에게 보고하였고',6195),
('jos-14-8','jos','여호수아',14,8,'나와 함께 올라갔던 내 형제들은 백성의 간담을 녹게 하였으나 나는 내 하나님 여호와께 충성하였으므로',6196),
('jos-14-9','jos','여호수아',14,9,'그 날에 모세가 맹세하여 이르되 네가 내 하나님 여호와께 충성하였은즉 네 발로 밟는 땅은 영원히 너와 네 자손의 기업이 되리라 하였나이다',6197),
('jos-14-10','jos','여호수아',14,10,'이제 보소서 여호와께서 이 말씀을 모세에게 이르신 때로부터 이스라엘이 광야에서 방황한 이 사십오 년 동안을 여호와께서 말씀하신 대로 나를 생존하게 하셨나이다 오늘 내가 팔십오 세로되',6198),
('jos-14-11','jos','여호수아',14,11,'모세가 나를 보내던 날과 같이 오늘도 내가 여전히 강건하니 내 힘이 그 때나 지금이나 같아서 싸움에나 출입에 감당할 수 있으니',6199),
('jos-14-12','jos','여호수아',14,12,'그 날에 여호와께서 말씀하신 이 산지를 지금 내게 주소서 당신도 그 날에 들으셨거니와 그 곳에는 아낙 사람이 있고 그 성읍들은 크고 견고할지라도 여호와께서 나와 함께 하시면 내가 여호와께서 말씀하신 대로 그들을 쫓아내리이다 하니',6200),
('jos-14-13','jos','여호수아',14,13,'여호수아가 여분네의 아들 갈렙을 위하여 축복하고 헤브론을 그에게 주어 기업을 삼게 하매',6201),
('jos-14-14','jos','여호수아',14,14,'헤브론이 그니스 사람 여분네의 아들 갈렙의 기업이 되어 오늘까지 이르렀으니 이는 그가 이스라엘의 하나님 여호와께 충성하였음이라',6202),
('jos-14-15','jos','여호수아',14,15,'헤브론의 옛 이름은 기럇 아르바라 아르바는 아낙 사람 가운데에서 가장 큰 사람이었더라 그리고 그 땅에 전쟁이 그쳤더라',6203),
('jos-15-1','jos','여호수아',15,1,'또 유다 자손의 지파가 그들의 가족대로 제비 뽑은 땅의 남쪽으로는 에돔 경계에 이르고 또 남쪽 끝은 신 광야까지라',6204),
('jos-15-2','jos','여호수아',15,2,'또 그들의 남쪽 경계는 염해의 끝 곧 남향한 해만에서부터',6205),
('jos-15-3','jos','여호수아',15,3,'아그랍빔 비탈 남쪽으로 지나 신에 이르고 가데스 바네아 남쪽으로 올라가서 헤스론을 지나며 아달로 올라가서 돌이켜 갈가에 이르고',6206),
('jos-15-4','jos','여호수아',15,4,'거기서 아스몬에 이르러 애굽 시내로 나아가 바다에 이르러 경계의 끝이 되나니 이것이 너희 남쪽 경계가 되리라',6207),
('jos-15-5','jos','여호수아',15,5,'그 동쪽 경계는 염해이니 요단 끝까지요 그 북쪽 경계는 요단 끝에 있는 해만에서부터',6208),
('jos-15-6','jos','여호수아',15,6,'벧 호글라로 올라가서 벧 아라바 북쪽을 지나 르우벤 자손 보한의 돌에 이르고',6209),
