('jos-17-1','jos','여호수아',17,1,'므낫세 지파를 위하여 제비 뽑은 것은 이러하니라 므낫세는 요셉의 장자였고 므낫세의 장자 마길은 길르앗의 아버지라 그는 용사였기 때문에 길르앗과 바산을 받았으므로',6277),
