('jos-17-3','jos','여호수아',17,3,'헤벨의 아들 길르앗의 손자 마길의 증손 므낫세의 현손 슬로브핫은 아들이 없고 딸뿐이요 그 딸들의 이름은 말라와 노아와 호글라와 밀가와 디르사라',6279),
('jos-17-4','jos','여호수아',17,4,'그들이 제사장 엘르아살과 눈의 아들 여호수아와 지도자들 앞에 나아와서 말하기를 여호와께서 모세에게 명령하사 우리 형제 중에서 우리에게 기업을 주라 하셨다 하매 여호와의 명령을 따라 그들에게 그들의 아버지 형제들 중에서 기업을 주므로',6280),
('jos-17-5','jos','여호수아',17,5,'요단 동쪽 길르앗과 바산 외에 므낫세에게 열 분깃이 돌아갔으니',6281),
('jos-17-6','jos','여호수아',17,6,'므낫세의 여자 자손들이 그의 남자 자손들 중에서 기업을 받은 까닭이었으며 길르앗 땅은 므낫세의 남은 자손들에게 속하였더라',6282),
('jos-17-7','jos','여호수아',17,7,'므낫세의 경계는 아셀에서부터 세겜 앞 믹므닷까지이며 그 오른쪽으로 가서 엔답부아 주민의 경계에 이르나니',6283),
('jos-17-8','jos','여호수아',17,8,'답부아 땅은 므낫세에게 속하였으되 므낫세 경계에 있는 답부아는 에브라임 자손에게 속하였으며',6284),
('jos-17-9','jos','여호수아',17,9,'또 그 경계가 가나 시내로 내려가서 그 시내 남쪽에 이르나니 므낫세의 성읍 중에 이 성읍들은 에브라임에게 속하였으며 므낫세의 경계는 그 시내 북쪽이요 그 끝은 바다이며',6285),
('jos-17-10','jos','여호수아',17,10,'남쪽으로는 에브라임에 속하였고 북쪽으로는 므낫세에 속하였고 바다가 그 경계가 되었으며 그들의 땅의 북쪽은 아셀에 이르고 동쪽은 잇사갈에 이르렀으며',6286),
('jos-17-11','jos','여호수아',17,11,'잇사갈과 아셀에도 므낫세의 소유가 있으니 곧 벧 스안과 그 마을들과 이블르암과 그 마을들과 돌의 주민과 그 마을들이요 또 엔돌 주민과 그 마을들과 다아낙 주민과 그 마을들과 므깃도 주민과 그 마을들 세 언덕 지역이라',6287),
('jos-17-12','jos','여호수아',17,12,'그러나 므낫세 자손이 그 성읍들의 주민을 쫓아내지 못하매 가나안 족속이 결심하고 그 땅에 거주하였더니',6288),
('jos-17-13','jos','여호수아',17,13,'이스라엘 자손이 강성한 후에야 가나안 족속에게 노역을 시켰고 다 쫓아내지 아니하였더라',6289),
('jos-17-14','jos','여호수아',17,14,'요셉 자손이 여호수아에게 말하여 이르되 여호와께서 지금까지 내게 복을 주시므로 내가 큰 민족이 되었거늘 당신이 나의 기업을 위하여 한 제비, 한 분깃으로만 내게 주심은 어찌함이니이까 하니',6290),
('jos-17-15','jos','여호수아',17,15,'여호수아가 그들에게 이르되 네가 큰 민족이 되므로 에브라임 산지가 네게 너무 좁을진대 브리스 족속과 르바임 족속의 땅 삼림에 올라가서 스스로 개척하라 하니라',6291),
('jos-17-16','jos','여호수아',17,16,'요셉 자손이 이르되 그 산지는 우리에게 넉넉하지도 못하고 골짜기 땅에 거주하는 모든 가나안 족속에게는 벧 스안과 그 마을들에 거주하는 자이든지 이스르엘 골짜기에 거주하는 자이든지 다 철 병거가 있나이다 하니',6292),
('jos-17-17','jos','여호수아',17,17,'여호수아가 다시 요셉의 족속 곧 에브라임과 므낫세에게 말하여 이르되 너는 큰 민족이요 큰 권능이 있은즉 한 분깃만 가질 것이 아니라',6293),
('jos-17-18','jos','여호수아',17,18,'그 산지도 네 것이 되리니 비록 삼림이라도 네가 개척하라 그 끝까지 네 것이 되리라 가나안 족속이 비록 철 병거를 가졌고 강할지라도 네가 능히 그를 쫓아내리라 하였더라',6294),
('jos-18-1','jos','여호수아',18,1,'이스라엘 자손의 온 회중이 실로에 모여서 거기에 회막을 세웠으며 그 땅은 그들 앞에서 돌아와 정복되었더라',6295),
('jos-18-2','jos','여호수아',18,2,'그러나 이스라엘 자손 중에 그 기업의 분배를 받지 못한 자가 아직도 일곱 지파라',6296),
('jos-18-3','jos','여호수아',18,3,'여호수아가 이스라엘 자손에게 이르되 너희가 너희 조상의 하나님 여호와께서 너희에게 주신 땅을 점령하러 가기를 어느 때까지 지체하겠느냐',6297),
('jos-18-4','jos','여호수아',18,4,'너희는 각 지파에 세 사람씩 선정하라 내가 그들을 보내리니 그들은 일어나서 그 땅에 두루 다니며 그들의 기업에 따라 그 땅을 그려 가지고 내게로 돌아올 것이라',6298),
('jos-18-5','jos','여호수아',18,5,'그들이 그 땅을 일곱 부분으로 나누되 유다는 남쪽 자기 지역에 있고 요셉의 족속은 북쪽에 있는 그들의 지역에 있으니',6299),
('jos-18-6','jos','여호수아',18,6,'그 땅을 일곱 부분으로 그려서 이 곳 내게로 가져오라 그러면 내가 여기서 너희를 위하여 우리 하나님 여호와 앞에서 제비를 뽑으리라',6300),
('jos-18-7','jos','여호수아',18,7,'레위 사람은 너희 중에 분깃이 없나니 여호와의 제사장 직분이 그들의 기업이 됨이며 갓과 르우벤과 므낫세 반 지파는 요단 저편 동쪽에서 이미 기업을 받았나니 이는 여호와의 종 모세가 그들에게 준 것이니라 하더라',6301),
('jos-18-8','jos','여호수아',18,8,'그 사람들이 일어나 떠나니 여호수아가 그 땅을 그리러 가는 사람들에게 명령하여 이르되 가서 그 땅으로 두루 다니며 그것을 그려 가지고 내게로 돌아오라 내가 여기 실로의 여호와 앞에서 너희를 위하여 제비를 뽑으리라 하니',6302),
('jos-18-9','jos','여호수아',18,9,'그 사람들이 가서 그 땅으로 두루 다니며 성읍들을 따라서 일곱 부분으로 책에 그려서 실로 진영에 돌아와 여호수아에게 나아오니',6303),
('jos-18-10','jos','여호수아',18,10,'여호수아가 그들을 위하여 실로의 여호와 앞에서 제비를 뽑고 그가 거기서 이스라엘 자손의 분파대로 그 땅을 분배하였더라',6304),
('jos-18-11','jos','여호수아',18,11,'베냐민 자손 지파를 위하여 그들의 가족대로 제비를 뽑았으니 그 제비 뽑은 땅의 경계는 유다 자손과 요셉 자손의 중간이라',6305),
