('jos-22-2','jos','여호수아',22,2,'그들에게 이르되 여호와의 종 모세가 너희에게 명령한 것을 너희가 다 지키며 또 내가 너희에게 명령한 모든 일에 너희가 내 말을 순종하여',6429),
('jos-22-3','jos','여호수아',22,3,'오늘까지 날이 오래도록 너희가 너희 형제를 떠나지 아니하고 오직 너희의 하나님 여호와께서 명령하신 그 책임을 지키도다',6430),
('jos-22-4','jos','여호수아',22,4,'이제는 너희의 하나님 여호와께서 이미 말씀하신 대로 너희 형제에게 안식을 주셨으니 그런즉 이제 너희는 여호와의 종 모세가 요단 저쪽에서 너희에게 준 소유지로 가서 너희의 장막으로 돌아가되',6431),
('jos-22-5','jos','여호수아',22,5,'오직 여호와의 종 모세가 너희에게 명령한 명령과 율법을 반드시 행하여 너희의 하나님 여호와를 사랑하고 그의 모든 길로 행하며 그의 계명을 지켜 그에게 친근히 하고 너희의 마음을 다하며 성품을 다하여 그를 섬길지니라 하고',6432),
('jos-22-6','jos','여호수아',22,6,'여호수아가 그들에게 축복하여 보내매 그들이 자기 장막으로 갔더라',6433),
('jos-22-7','jos','여호수아',22,7,'므낫세 반 지파에게는 모세가 바산에서 기업을 주었고 그 남은 반 지파에게는 여호수아가 요단 이쪽 서쪽에서 그들의 형제들과 함께 기업을 준지라 여호수아가 그들을 그들의 장막으로 돌려보낼 때에 그들에게 축복하고',6434),
('jos-22-8','jos','여호수아',22,8,'말하여 이르되 너희는 많은 재산과 심히 많은 가축과 은과 금과 구리와 쇠와 심히 많은 의복을 가지고 너희의 장막으로 돌아가서 너희의 원수들에게서 탈취한 것을 너희의 형제와 나눌지니라 하매',6435),
('jos-22-9','jos','여호수아',22,9,'르우벤 자손과 갓 자손과 므낫세 반 지파가 가나안 땅 실로에서 이스라엘 자손을 떠나 여호와께서 모세에게 명령하신 대로 받은 땅 곧 그들의 소유지 길르앗으로 가니라',6436),
('jos-22-10','jos','여호수아',22,10,'르우벤 자손과 므낫세 반 지파가 가나안 땅 요단 언덕 가에 이르자 거기서 요단 가에 제단을 쌓았는데 보기에 큰 제단이었더라',6437),
('jos-22-11','jos','여호수아',22,11,'이스라엘 자손이 들은즉 이르기를 르우벤 자손과 갓 자손과 므낫세 반 지파가 가나안 땅의 맨 앞쪽 요단 언덕 가 이스라엘 자손에게 속한 쪽에 제단을 쌓았다 하는지라',6438),
('jos-22-12','jos','여호수아',22,12,'이스라엘 자손이 이를 듣자 곧 이스라엘 자손의 온 회중이 실로에 모여서 그들과 싸우러 가려 하니라',6439),
('jos-22-13','jos','여호수아',22,13,'이스라엘 자손이 제사장 엘르아살의 아들 비느하스를 길르앗 땅으로 보내어 르우벤 자손과 갓 자손과 므낫세 반 지파를 보게 하되',6440),
('jos-22-14','jos','여호수아',22,14,'이스라엘 각 지파에서 한 지도자씩 열 지도자들을 그와 함께 하게 하니 그들은 각기 그들의 조상들의 가문의 수령으로서 이스라엘 중에서 천부장들이라',6441),
('jos-22-15','jos','여호수아',22,15,'그들이 길르앗 땅에 이르러 르우벤 자손과 갓 자손과 므낫세 반 지파에게 나아가서 그들에게 말하여 이르되',6442),
('jos-22-16','jos','여호수아',22,16,'여호와의 온 회중이 말하기를 너희가 어찌하여 이스라엘 하나님께 범죄하여 오늘 여호와를 따르는 데서 돌아서서 너희를 위하여 제단을 쌓아 너희가 오늘 여호와께 거역하고자 하느냐',6443),
('jos-22-17','jos','여호수아',22,17,'브올의 죄악으로 말미암아 여호와의 회중에 재앙이 내렸으나 오늘까지 우리가 그 죄에서 정결함을 받지 못하였거늘 그 죄악이 우리에게 부족하여서',6444),
('jos-22-18','jos','여호수아',22,18,'오늘 너희가 돌이켜 여호와를 따르지 아니하려고 하느냐 너희가 오늘 여호와를 배역하면 내일은 그가 이스라엘 온 회중에게 진노하시리라',6445),
('jos-22-19','jos','여호수아',22,19,'그런데 너희의 소유지가 만일 깨끗하지 아니하거든 여호와의 성막이 있는 여호와의 소유지로 건너와 우리 중에서 소유지를 나누어 가질 것이니라 오직 우리 하나님 여호와의 제단 외에 다른 제단을 쌓음으로 여호와를 거역하지 말며 우리에게도 거역하지 말라',6446),
('jos-22-20','jos','여호수아',22,20,'세라의 아들 아간이 온전히 바친 물건에 대하여 범죄하므로 이스라엘 온 회중에 진노가 임하지 아니하였느냐 그의 죄악으로 멸망한 자가 그 한 사람만이 아니었느니라 하니라',6447),
('jos-22-21','jos','여호수아',22,21,'르우벤 자손과 갓 자손과 므낫세 반 지파가 이스라엘 천천의 수령들에게 대답하여 이르되',6448),
('jos-22-22','jos','여호수아',22,22,'전능하신 자 하나님 여호와, 전능하신 자 하나님 여호와께서 아시나니 이스라엘도 장차 알리라 이 일이 만일 여호와를 거역함이거나 범죄함이거든 주께서는 오늘 우리를 구원하지 마시옵소서',6449),
('jos-22-23','jos','여호수아',22,23,'우리가 제단을 쌓은 것이 돌이켜 여호와를 따르지 아니하려 함이거나 또는 그 위에 번제나 소제를 드리려 함이거나 또는 화목제물을 드리려 함이거든 여호와는 친히 벌하시옵소서',6450),
('jos-22-24','jos','여호수아',22,24,'우리가 목적이 있어서 주의하고 이같이 하였노라 곧 생각하기를 후일에 너희의 자손이 우리 자손에게 말하여 이르기를 너희가 이스라엘 하나님 여호와와 무슨 상관이 있느냐',6451),
('jos-22-25','jos','여호수아',22,25,'너희 르우벤 자손 갓 자손아 여호와께서 우리와 너희 사이에 요단으로 경계를 삼으셨나니 너희는 여호와께 받을 분깃이 없느니라 하여 너희의 자손이 우리 자손에게 여호와 경외하기를 그치게 할까 하여',6452),
('jos-22-26','jos','여호수아',22,26,'우리가 말하기를 우리가 이제 한 제단 쌓기를 준비하자 하였노니 이는 번제를 위함도 아니요 다른 제사를 위함도 아니라',6453),
('jos-22-27','jos','여호수아',22,27,'우리가 여호와 앞에서 우리의 번제와 우리의 다른 제사와 우리의 화목제로 섬기는 것을 우리와 너희 사이와 우리의 후대 사이에 증거가 되게 할 뿐으로서 너희 자손들이 후일에 우리 자손들에게 이르기를 너희는 여호와께 받을 분깃이 없다 하지 못하게 하려 함이라',6454),
('jos-22-28','jos','여호수아',22,28,'우리가 말하였거니와 만일 그들이 후일에 우리에게나 우리 후대에게 이같이 말하면 우리가 말하기를 우리 조상이 지은 여호와의 제단 모형을 보라 이는 번제를 위한 것도 아니요 다른 제사를 위한 것도 아니라 오직 우리와 너희 사이에 증거만 되게 할 뿐이라',6455),
('jos-22-29','jos','여호수아',22,29,'우리가 번제나 소제나 다른 제사를 위하여 우리 하나님 여호와의 성막 앞에 있는 제단 외에 제단을 쌓음으로 여호와를 거역하고 오늘 여호와를 따르는 데에서 돌아서려는 것은 결단코 아니라 하리라',6456),
('jos-22-30','jos','여호수아',22,30,'제사장 비느하스와 그와 함께 한 회중의 지도자들 곧 이스라엘 천천의 수령들이 르우벤 자손과 갓 자손과 므낫세 자손의 말을 듣고 좋게 여긴지라',6457),
('jos-22-31','jos','여호수아',22,31,'제사장 엘르아살의 아들 비느하스가 르우벤 자손과 갓 자손과 므낫세 자손에게 이르되 우리가 오늘 여호와께서 우리 중에 계신 줄을 아노니 이는 너희가 이 죄를 여호와께 범하지 아니하였음이니라 너희가 이제 이스라엘 자손을 여호와의 손에서 건져내었느니라 하고',6458),
('jos-22-32','jos','여호수아',22,32,'제사장 엘르아살의 아들 비느하스와 지도자들이 르우벤 자손과 갓 자손을 떠나 길르앗 땅에서 가나안 땅 이스라엘 자손에게 돌아와 그들에게 보고하매',6459),
('jos-22-33','jos','여호수아',22,33,'그 일이 이스라엘 자손을 즐겁게 한지라 이스라엘 자손이 하나님을 찬송하고 르우벤 자손과 갓 자손이 거주하는 땅에 가서 싸워 그것을 멸하자 하는 말을 다시는 하지 아니하였더라',6460),
('jos-22-34','jos','여호수아',22,34,'르우벤 자손과 갓 자손이 그 제단을 엣이라 불렀으니 우리 사이에 이 제단은 여호와께서 하나님이 되시는 증거라 함이었더라',6461),
('jos-23-1','jos','여호수아',23,1,'여호와께서 주위의 모든 원수들로부터 이스라엘을 쉬게 하신 지 오랜 후에 여호수아가 나이 많아 늙은지라',6462),
('jos-23-2','jos','여호수아',23,2,'여호수아가 온 이스라엘 곧 그들의 장로들과 수령들과 재판장들과 관리들을 불러다가 그들에게 이르되 나는 나이가 많아 늙었도다',6463),
('jos-23-3','jos','여호수아',23,3,'너희의 하나님 여호와께서 너희를 위하여 이 모든 나라에 행하신 일을 너희가 다 보았거니와 너희의 하나님 여호와 그는 너희를 위하여 싸우신 이시니라',6464),
('jos-23-4','jos','여호수아',23,4,'보라 내가 요단에서부터 해 지는 쪽 대해까지의 남아 있는 나라들과 이미 멸한 모든 나라를 내가 너희를 위하여 제비 뽑아 너희의 지파에게 기업이 되게 하였느니라',6465),
('jos-23-5','jos','여호수아',23,5,'너희의 하나님 여호와 그가 너희 앞에서 그들을 쫓아내사 너희 목전에서 그들을 떠나게 하시리니 너희의 하나님 여호와께서 너희에게 말씀하신 대로 너희가 그 땅을 차지할 것이라',6466),
('jos-23-6','jos','여호수아',23,6,'그러므로 너희는 크게 힘써 모세의 율법 책에 기록된 것을 다 지켜 행하라 그것을 떠나 우로나 좌로나 치우치지 말라',6467),
('jos-23-7','jos','여호수아',23,7,'너희 중에 남아 있는 이 민족들 중에 들어 가지 말라 그들의 신들의 이름을 부르지 말라 그것들을 가리켜 맹세하지 말라 또 그것을 섬겨서 그것들에게 절하지 말라',6468),
('jos-23-8','jos','여호수아',23,8,'오직 너희의 하나님 여호와께 가까이 하기를 오늘까지 행한 것 같이 하라',6469),
('jos-23-9','jos','여호수아',23,9,'이는 여호와께서 강대한 나라들을 너희의 앞에서 쫓아내셨으므로 오늘까지 너희에게 맞선 자가 하나도 없었느니라',6470),
('jos-23-10','jos','여호수아',23,10,'너희 중 한 사람이 천 명을 쫓으리니 이는 너희의 하나님 여호와 그가 너희에게 말씀하신 것 같이 너희를 위하여 싸우심이라',6471),
('jos-23-11','jos','여호수아',23,11,'그러므로 스스로 조심하여 너희의 하나님 여호와를 사랑하라',6472),
('jos-23-12','jos','여호수아',23,12,'너희가 만일 돌아서서 너희 중에 남아 있는 이 민족들을 가까이 하여 더불어 혼인하며 서로 왕래하면',6473),
('jos-23-13','jos','여호수아',23,13,'확실히 알라 너희의 하나님 여호와께서 이 민족들을 너희 목전에서 다시는 쫓아내지 아니하시리니 그들이 너희에게 올무가 되며 덫이 되며 너희의 옆구리에 채찍이 되며 너희의 눈에 가시가 되어서 너희가 마침내 너희의 하나님 여호와께서 너희에게 주신 이 아름다운 땅에서 멸하리라',6474),
('jos-23-14','jos','여호수아',23,14,'보라 나는 오늘 온 세상이 가는 길로 가려니와 너희의 하나님 여호와께서 너희에게 대하여 말씀하신 모든 선한 말씀이 하나도 틀리지 아니하고 다 너희에게 응하여 그 중에 하나도 어김이 없음을 너희 모든 사람은 마음과 뜻으로 아는 바라',6475),
('jos-23-15','jos','여호수아',23,15,'너희의 하나님 여호와께서 너희에게 말씀하신 모든 선한 말씀이 너희에게 임한 것 같이 여호와께서 모든 불길한 말씀도 너희에게 임하게 하사 너희의 하나님 여호와께서 너희에게 주신 이 아름다운 땅에서 너희를 멸절하기까지 하실 것이라',6476),
('jos-23-16','jos','여호수아',23,16,'만일 너희가 너희의 하나님 여호와께서 너희에게 명령하신 언약을 범하고 가서 다른 신들을 섬겨 그들에게 절하면 여호와의 진노가 너희에게 미치리니 너희에게 주신 아름다운 땅에서 너희가 속히 멸망하리라 하니라',6477),
('jos-24-1','jos','여호수아',24,1,'여호수아가 이스라엘 모든 지파를 세겜에 모으고 이스라엘 장로들과 그들의 수령들과 재판장들과 관리들을 부르매 그들이 하나님 앞에 나와 선지라',6478),
('jos-24-2','jos','여호수아',24,2,'여호수아가 모든 백성에게 이르되 이스라엘의 하나님 여호와께서 이같이 말씀하시기를 옛적에 너희의 조상들 곧 아브라함의 아버지, 나홀의 아버지 데라가 강 저쪽에 거주하여 다른 신들을 섬겼으나',6479),
('jos-24-3','jos','여호수아',24,3,'내가 너희의 조상 아브라함을 강 저쪽에서 이끌어 내어 가나안 온 땅에 두루 행하게 하고 그의 씨를 번성하게 하려고 그에게 이삭을 주었으며',6480),
('jos-24-4','jos','여호수아',24,4,'이삭에게는 야곱과 에서를 주었고 에서에게는 세일 산을 소유로 주었으나 야곱과 그의 자손들은 애굽으로 내려갔으므로',6481),
('jos-24-5','jos','여호수아',24,5,'내가 모세와 아론을 보내었고 또 애굽에 재앙을 내렸나니 곧 내가 그들 가운데 행한 것과 같고 그 후에 너희를 인도하여 내었노라',6482),
('jos-24-6','jos','여호수아',24,6,'내가 너희의 조상들을 애굽에서 인도하여 내어 바다에 이르게 한즉 애굽 사람들이 병거와 마병을 거느리고 너희의 조상들을 홍해까지 쫓아오므로',6483),
('jos-24-7','jos','여호수아',24,7,'너희의 조상들이 나 여호와께 부르짖기로 내가 너희와 애굽 사람들 사이에 흑암을 두고 바다를 이끌어 그들을 덮었나니 내가 애굽에서 행한 일을 너희의 눈이 보았으며 또 너희가 많은 날을 광야에서 거주하였느니라',6484),
('jos-24-8','jos','여호수아',24,8,'내가 또 너희를 인도하여 요단 저쪽에 거주하는 아모리 족속의 땅으로 들어가게 하매 그들이 너희와 싸우기로 내가 그들을 너희 손에 넘겨 주매 너희가 그 땅을 점령하였고 나는 그들을 너희 앞에서 멸절시켰으며',6485),
('jos-24-9','jos','여호수아',24,9,'또한 모압 왕 십볼의 아들 발락이 일어나 이스라엘과 싸우더니 사람을 보내어 브올의 아들 발람을 불러다가 너희를 저주하게 하려 하였으나',6486),
('jos-24-10','jos','여호수아',24,10,'내가 발람을 위해 듣기를 원하지 아니하였으므로 그가 오히려 너희를 축복하였고 나는 너희를 그의 손에서 건져내었으며',6487),
('jos-24-11','jos','여호수아',24,11,'너희가 요단을 건너 여리고에 이른즉 여리고 주민들 곧 아모리 족속과 브리스 족속과 가나안 족속과 헷 족속과 기르가스 족속과 히위 족속과 여부스 족속이 너희와 싸우기로 내가 그들을 너희의 손에 넘겨 주었으며',6488),
('jos-24-12','jos','여호수아',24,12,'내가 왕벌을 너희 앞에 보내어 그 아모리 족속의 두 왕을 너희 앞에서 쫓아내게 하였나니 너희의 칼이나 너희의 활로써 이같이 한 것이 아니며',6489),
('jos-24-13','jos','여호수아',24,13,'내가 또 너희가 수고하지 아니한 땅과 너희가 건설하지 아니한 성읍들을 너희에게 주었더니 너희가 그 가운데에 거주하며 너희는 또 너희가 심지 아니한 포도원과 감람원의 열매를 먹는다 하셨느니라',6490),
('jos-24-14','jos','여호수아',24,14,'그러므로 이제는 여호와를 경외하며 온전함과 진실함으로 그를 섬기라 너희의 조상들이 강 저쪽과 애굽에서 섬기던 신들을 치워 버리고 여호와만 섬기라',6491),
('jos-24-15','jos','여호수아',24,15,'만일 여호와를 섬기는 것이 너희에게 좋지 않게 보이거든 너희 조상들이 강 저쪽에서 섬기던 신들이든지 또는 너희가 거주하는 땅에 있는 아모리 족속의 신들이든지 너희가 섬길 자를 오늘 택하라 오직 나와 내 집은 여호와를 섬기겠노라 하니',6492),
('jos-24-16','jos','여호수아',24,16,'백성이 대답하여 이르되 우리가 결단코 여호와를 버리고 다른 신들을 섬기기를 하지 아니하오리니',6493),
('jos-24-17','jos','여호수아',24,17,'이는 우리 하나님 여호와께서 친히 우리와 우리 조상들을 인도하여 애굽 땅 종 되었던 집에서 올라오게 하시고 우리 목전에서 그 큰 이적들을 행하시고 우리가 행한 모든 길과 우리가 지나온 모든 백성들 중에서 우리를 보호하셨음이며',6494),
('jos-24-18','jos','여호수아',24,18,'여호와께서 또 모든 백성들과 이 땅에 거주하던 아모리 족속을 우리 앞에서 쫓아내셨음이라 그러므로 우리도 여호와를 섬기리니 그는 우리 하나님이심이니이다 하니라',6495),
('jos-24-19','jos','여호수아',24,19,'여호수아가 백성에게 이르되 너희가 여호와를 능히 섬기지 못할 것은 그는 거룩하신 하나님이시요 질투하시는 하나님이시니 너희의 잘못과 죄들을 사하지 아니하실 것임이라',6496),
('jos-24-20','jos','여호수아',24,20,'만일 너희가 여호와를 버리고 이방 신들을 섬기면 너희에게 복을 내리신 후에라도 돌이켜 너희에게 재앙을 내리시고 너희를 멸하시리라 하니',6497),
('jos-24-21','jos','여호수아',24,21,'백성이 여호수아에게 말하되 아니니이다 우리가 여호와를 섬기겠나이다 하는지라',6498),
('jos-24-22','jos','여호수아',24,22,'여호수아가 백성에게 이르되 너희가 여호와를 택하고 그를 섬기리라 하였으니 스스로 증인이 되었느니라 하니 그들이 이르되 우리가 증인이 되었나이다 하더라',6499),
('jos-24-23','jos','여호수아',24,23,'여호수아가 이르되 그러면 이제 너희 중에 있는 이방 신들을 치워 버리고 너희의 마음을 이스라엘의 하나님 여호와께로 향하라 하니',6500),
('jos-24-24','jos','여호수아',24,24,'백성이 여호수아에게 말하되 우리 하나님 여호와를 우리가 섬기고 그의 목소리를 우리가 청종하리이다 하는지라',6501),
('jos-24-25','jos','여호수아',24,25,'그 날에 여호수아가 세겜에서 백성과 더불어 언약을 맺고 그들을 위하여 율례와 법도를 제정하였더라',6502),
('jos-24-26','jos','여호수아',24,26,'여호수아가 이 모든 말씀을 하나님의 율법책에 기록하고 큰 돌을 가져다가 거기 여호와의 성소 곁에 있는 상수리나무 아래에 세우고',6503),
('jos-24-27','jos','여호수아',24,27,'모든 백성에게 이르되 보라 이 돌이 우리에게 증거가 되리니 이는 여호와께서 우리에게 하신 모든 말씀을 이 돌이 들었음이니라 그런즉 너희가 너희의 하나님을 부인하지 못하도록 이 돌이 증거가 되리라 하고',6504),
('jos-24-28','jos','여호수아',24,28,'백성을 보내어 각기 기업으로 돌아가게 하였더라',6505),
('jos-24-29','jos','여호수아',24,29,'이 일 후에 여호와의 종 눈의 아들 여호수아가 백십 세에 죽으매',6506),
('jos-24-30','jos','여호수아',24,30,'그들이 그를 그의 기업의 경내 딤낫 세라에 장사하였으니 딤낫 세라는 에브라임 산지 가아스 산 북쪽이었더라',6507),
('jos-24-31','jos','여호수아',24,31,'이스라엘이 여호수아가 사는 날 동안과 여호수아 뒤에 생존한 장로들 곧 여호와께서 이스라엘을 위하여 행하신 모든 일을 아는 자들이 사는 날 동안 여호와를 섬겼더라',6508),
('jos-24-32','jos','여호수아',24,32,'또 이스라엘 자손이 애굽에서 가져 온 요셉의 뼈를 세겜에 장사하였으니 이곳은 야곱이 백 크시타를 주고 세겜의 아버지 하몰의 자손들에게서 산 밭이라 그것이 요셉 자손의 기업이 되었더라',6509),
('jos-24-33','jos','여호수아',24,33,'아론의 아들 엘르아살도 죽으매 그들이 그를 그의 아들 비느하스가 에브라임 산지에서 받은 산에 장사하였더라',6510),
('jdg-1-1','jdg','사사기',1,1,'여호수아가 죽은 후에 이스라엘 자손이 여호와께 여쭈어 이르되 우리 가운데 누가 먼저 올라가서 가나안 족속과 싸우리이까',6511),
('jdg-1-2','jdg','사사기',1,2,'여호와께서 이르시되 유다가 올라갈지니라 보라 내가 이 땅을 그의 손에 넘겨 주었노라 하시니라',6512),
('jdg-1-3','jdg','사사기',1,3,'유다가 그의 형제 시므온에게 이르되 내가 제비 뽑아 얻은 땅에 나와 함께 올라가서 가나안 족속과 싸우자 그리하면 나도 네가 제비 뽑아 얻은 땅에 함께 가리라 하니 이에 시므온이 그와 함께 가니라',6513),
('jdg-1-4','jdg','사사기',1,4,'유다가 올라가매 여호와께서 가나안 족속과 브리스 족속을 그들의 손에 넘겨 주시니 그들이 베섹에서 만 명을 죽이고',6514),
('jdg-1-5','jdg','사사기',1,5,'또 베섹에서 아도니 베섹을 만나 그와 싸워서 가나안 족속과 브리스 족속을 죽이니',6515),
('jdg-1-6','jdg','사사기',1,6,'아도니 베섹이 도망하는지라 그를 쫓아가서 잡아 그의 엄지손가락과 엄지발가락을 자르매',6516),
('jdg-1-7','jdg','사사기',1,7,'아도니 베섹이 이르되 옛적에 칠십 명의 왕들이 그들의 엄지손가락과 엄지발가락이 잘리고 내 상 아래에서 먹을 것을 줍더니 하나님이 내가 행한 대로 내게 갚으심이로다 하니라 무리가 그를 끌고 예루살렘에 이르렀더니 그가 거기서 죽었더라',6517),
('jdg-1-8','jdg','사사기',1,8,'유다 자손이 예루살렘을 쳐서 점령하여 칼날로 치고 그 성을 불살랐으며',6518),
('jdg-1-9','jdg','사사기',1,9,'그 후에 유다 자손이 내려가서 산지와 남방과 평지에 거주하는 가나안 족속과 싸웠고',6519),
('jdg-1-10','jdg','사사기',1,10,'유다가 또 가서 헤브론에 거주하는 가나안 족속을 쳐서 세새와 아히만과 달매를 죽였더라 헤브론의 본 이름은 기럇 아르바였더라',6520),
('jdg-1-11','jdg','사사기',1,11,'거기서 나아가서 드빌의 주민들을 쳤으니 드빌의 본 이름은 기럇 세벨이라',6521),
('jdg-1-12','jdg','사사기',1,12,'갈렙이 말하기를 기럇 세벨을 쳐서 그것을 점령하는 자에게는 내 딸 악사를 아내로 주리라 하였더니',6522),
('jdg-1-13','jdg','사사기',1,13,'갈렙의 아우 그나스의 아들인 옷니엘이 그것을 점령하였으므로 갈렙이 그의 딸 악사를 그에게 아내로 주었더라',6523),
('jdg-1-14','jdg','사사기',1,14,'악사가 출가할 때에 그에게 청하여 자기 아버지에게 밭을 구하자 하고 나귀에서 내리매 갈렙이 묻되 네가 무엇을 원하느냐 하니',6524),
('jdg-1-15','jdg','사사기',1,15,'이르되 내게 복을 주소서 아버지께서 나를 남방으로 보내시니 샘물도 내게 주소서 하매 갈렙이 윗샘과 아랫샘을 그에게 주었더라',6525),
('jdg-1-16','jdg','사사기',1,16,'모세의 장인은 겐 사람이라 그의 자손이 유다 자손과 함께 종려나무 성읍에서 올라가서 아랏 남방의 유다 황무지에 이르러 그 백성 중에 거주하니라',6526),
('jdg-1-17','jdg','사사기',1,17,'유다가 그의 형제 시므온과 함께 가서 스밧에 거주하는 가나안 족속을 쳐서 그 곳을 진멸하였으므로 그 성읍의 이름을 호르마라 하니라',6527),
('jdg-1-18','jdg','사사기',1,18,'유다가 또 가사 및 그 지역과 아스글론 및 그 지역과 에그론 및 그 지역을 점령하였고',6528),
('jdg-1-19','jdg','사사기',1,19,'여호와께서 유다와 함께 계셨으므로 그가 산지 주민을 쫓아내었으나 골짜기의 주민들은 철 병거가 있으므로 그들을 쫓아내지 못하였으며',6529),
('jdg-1-20','jdg','사사기',1,20,'그들이 모세가 명령한 대로 헤브론을 갈렙에게 주었더니 그가 거기서 아낙의 세 아들을 쫓아내었고',6530),
('jdg-1-21','jdg','사사기',1,21,'베냐민 자손은 예루살렘에 거주하는 여부스 족속을 쫓아내지 못하였으므로 여부스 족속이 베냐민 자손과 함께 오늘까지 예루살렘에 거주하니라',6531),
('jdg-1-22','jdg','사사기',1,22,'요셉 가문도 벧엘을 치러 올라가니 여호와께서 그와 함께 하시니라',6532),
('jdg-1-23','jdg','사사기',1,23,'요셉 가문이 벧엘을 정탐하게 하였는데 그 성읍의 본 이름은 루스라',6533),
('jdg-1-24','jdg','사사기',1,24,'정탐꾼들이 그 성읍에서 한 사람이 나오는 것을 보고 그에게 이르되 청하노니 이 성읍의 입구를 우리에게 보이라 그리하면 우리가 네게 선대하리라 하매',6534),
('jdg-1-25','jdg','사사기',1,25,'그 사람이 성읍의 입구를 가리킨지라 이에 그들이 칼날로 그 성읍을 쳤으되 오직 그 사람과 그의 가족을 놓아 보내매',6535),
('jdg-1-26','jdg','사사기',1,26,'그 사람이 헷 사람들의 땅에 가서 성읍을 건축하고 그것의 이름을 루스라 하였더니 오늘까지 그 곳의 이름이 되니라',6536),
('jdg-1-27','jdg','사사기',1,27,'므낫세가 벧스안과 그에 딸린 마을들의 주민과 다아낙과 그에 딸린 마을들의 주민과 돌과 그에 딸린 마을들의 주민과 이블르암과 그에 딸린 마을들의 주민과 므깃도와 그에 딸린 마을들의 주민들을 쫓아내지 못하매 가나안 족속이 결심하고 그 땅에 거주하였더니',6537),
('jdg-1-28','jdg','사사기',1,28,'이스라엘이 강성한 후에야 가나안 족속에게 노역을 시켰고 다 쫓아내지 아니하였더라',6538),
('jdg-1-29','jdg','사사기',1,29,'에브라임이 게셀에 거주하는 가나안 족속을 쫓아내지 못하매 가나안 족속이 게셀에서 그들 중에 거주하였더라',6539),
('jdg-1-30','jdg','사사기',1,30,'스불론은 기드론 주민과 나할롤 주민을 쫓아내지 못하였으므로 가나안 족속이 그들 중에 거주하면서 노역을 하였더라',6540),
('jdg-1-31','jdg','사사기',1,31,'아셀이 악고 주민과 시돈 주민과 알랍과 악십과 헬바와 아빅과 르홉 주민을 쫓아내지 못하고',6541),
('jdg-1-32','jdg','사사기',1,32,'아셀 족속이 그 땅의 주민 가나안 족속 가운데 거주하였으니 이는 그들을 쫓아내지 못함이었더라',6542),
('jdg-1-33','jdg','사사기',1,33,'납달리는 벧세메스 주민과 벧아낫 주민을 쫓아내지 못하고 그 땅의 주민 가나안 족속 가운데 거주하였으나 벧세메스와 벧아낫 주민들이 그들에게 노역을 하였더라',6543),
('jdg-1-34','jdg','사사기',1,34,'아모리 족속이 단 자손을 산지로 몰아넣고 골짜기에 내려오기를 용납하지 아니하였으며',6544),
('jdg-1-35','jdg','사사기',1,35,'결심하고 헤레스 산과 아얄론과 사알빔에 거주하였더니 요셉의 가문의 힘이 강성하매 아모리 족속이 마침내는 노역을 하였으며',6545),
('jdg-1-36','jdg','사사기',1,36,'아모리 족속의 경계는 아그랍빔 비탈의 바위부터 위쪽이었더라',6546),
('jdg-2-1','jdg','사사기',2,1,'여호와의 사자가 길갈에서부터 보김으로 올라와 말하되 내가 너희를 애굽에서 올라오게 하여 내가 너희의 조상들에게 맹세한 땅으로 들어가게 하였으며 또 내가 이르기를 내가 너희와 함께 한 언약을 영원히 어기지 아니하리니',6547),
('jdg-2-2','jdg','사사기',2,2,'너희는 이 땅의 주민과 언약을 맺지 말며 그들의 제단들을 헐라 하였거늘 너희가 내 목소리를 듣지 아니하였으니 어찌하여 그리하였느냐',6548),
('jdg-2-3','jdg','사사기',2,3,'그러므로 내가 또 말하기를 내가 그들을 너희 앞에서 쫓아내지 아니하리니 그들이 너희 옆구리에 가시가 될 것이며 그들의 신들이 너희에게 올무가 되리라 하였노라',6549),
('jdg-2-4','jdg','사사기',2,4,'여호와의 사자가 이스라엘 모든 자손에게 이 말씀을 이르매 백성이 소리를 높여 운지라',6550),
('jdg-2-5','jdg','사사기',2,5,'그러므로 그 곳을 이름하여 보김이라 하고 그들이 거기서 여호와께 제사를 드렸더라',6551),
('jdg-2-6','jdg','사사기',2,6,'전에 여호수아가 백성을 보내매 이스라엘 자손이 각기 그들의 기업으로 가서 땅을 차지하였고',6552),
('jdg-2-7','jdg','사사기',2,7,'백성이 여호수아가 사는 날 동안과 여호수아 뒤에 생존한 장로들 곧 여호와께서 이스라엘을 위하여 행하신 모든 큰 일을 본 자들이 사는 날 동안에 여호와를 섬겼더라',6553),
('jdg-2-8','jdg','사사기',2,8,'여호와의 종 눈의 아들 여호수아가 백십 세에 죽으매',6554),
('jdg-2-9','jdg','사사기',2,9,'무리가 그의 기업의 경내 에브라임 산지 가아스 산 북쪽 딤낫 헤레스에 장사하였고',6555),
('jdg-2-10','jdg','사사기',2,10,'그 세대의 사람도 다 그 조상들에게로 돌아갔고 그 후에 일어난 다른 세대는 여호와를 알지 못하며 여호와께서 이스라엘을 위하여 행하신 일도 알지 못하였더라',6556),
('jdg-2-11','jdg','사사기',2,11,'이스라엘 자손이 여호와의 목전에 악을 행하여 바알들을 섬기며',6557),
('jdg-2-12','jdg','사사기',2,12,'애굽 땅에서 그들을 인도하여 내신 그들의 조상들의 하나님 여호와를 버리고 다른 신들 곧 그들의 주위에 있는 백성의 신들을 따라 그들에게 절하여 여호와를 진노하시게 하였으되',6558),
('jdg-2-13','jdg','사사기',2,13,'곧 그들이 여호와를 버리고 바알과 아스다롯을 섬겼으므로',6559),
('jdg-2-14','jdg','사사기',2,14,'여호와께서 이스라엘에게 진노하사 노략하는 자의 손에 넘겨 주사 그들이 노략을 당하게 하시며 또 주위에 있는 모든 대적의 손에 팔아 넘기시매 그들이 다시는 대적을 당하지 못하였으며',6560),
('jdg-2-15','jdg','사사기',2,15,'그들이 어디로 가든지 여호와의 손이 그들에게 재앙을 내리시니 곧 여호와께서 말씀하신 것과 같고 여호와께서 그들에게 맹세하신 것과 같아서 그들의 괴로움이 심하였더라',6561),
('jdg-2-16','jdg','사사기',2,16,'여호와께서 사사들을 세우사 노략자의 손에서 그들을 구원하게 하셨으나',6562),
('jdg-2-17','jdg','사사기',2,17,'그들이 그 사사들에게도 순종하지 아니하고 오히려 다른 신들을 따라가 음행하며 그들에게 절하고 여호와의 명령을 순종하던 그들의 조상들이 행하던 길에서 속히 치우쳐 떠나서 그와 같이 행하지 아니하였더라',6563),
('jdg-2-18','jdg','사사기',2,18,'여호와께서 그들을 위하여 사사들을 세우실 때에는 그 사사와 함께 하셨고 그 사사가 사는 날 동안에는 여호와께서 그들을 대적의 손에서 구원하셨으니 이는 그들이 대적에게 압박과 괴롭게 함을 받아 슬피 부르짖으므로 여호와께서 뜻을 돌이키셨음이거늘',6564),
('jdg-2-19','jdg','사사기',2,19,'그 사사가 죽은 후에는 그들이 돌이켜 그들의 조상들보다 더욱 타락하여 다른 신들을 따라 섬기며 그들에게 절하고 그들의 행위와 패역한 길을 그치지 아니하였으므로',6565),
('jdg-2-20','jdg','사사기',2,20,'여호와께서 이스라엘에게 진노하여 이르시되 이 백성이 내가 그들의 조상들에게 명령한 언약을 어기고 나의 목소리를 순종하지 아니하였은즉',6566),
('jdg-2-21','jdg','사사기',2,21,'나도 여호수아가 죽을 때에 남겨 둔 이방 민족들을 다시는 그들 앞에서 하나도 쫓아내지 아니하리니',6567),
('jdg-2-22','jdg','사사기',2,22,'이는 이스라엘이 그들의 조상들이 지킨 것 같이 나 여호와의 도를 지켜 행하나 아니하나 그들을 시험하려 함이라 하시니라',6568),
('jdg-2-23','jdg','사사기',2,23,'여호와께서 그 이방 민족들을 머물러 두사 그들을 속히 쫓아내지 아니하셨으며 여호수아의 손에 넘겨 주지 아니하셨더라',6569),
('jdg-3-1','jdg','사사기',3,1,'여호와께서 가나안의 모든 전쟁들을 알지 못한 이스라엘을 시험하려 하시며',6570),
('jdg-3-2','jdg','사사기',3,2,'이스라엘 자손의 세대 중에 아직 전쟁을 알지 못하는 자들에게 그것을 가르쳐 알게 하려 하사 남겨 두신 이방 민족들은',6571),
('jdg-3-3','jdg','사사기',3,3,'블레셋의 다섯 군주들과 모든 가나안 족속과 시돈 족속과 바알 헤르몬 산에서부터 하맛 입구까지 레바논 산에 거주하는 히위 족속이라',6572),
('jdg-3-4','jdg','사사기',3,4,'남겨 두신 이 이방 민족들로 이스라엘을 시험하사 여호와께서 모세를 통하여 그들의 조상들에게 이르신 명령들을 순종하는지 알고자 하셨더라',6573),
('jdg-3-5','jdg','사사기',3,5,'그러므로 이스라엘 자손은 가나안 족속과 헷 족속과 아모리 족속과 브리스 족속과 히위 족속과 여부스 족속 가운데에 거주하면서',6574),
('jdg-3-6','jdg','사사기',3,6,'그들의 딸들을 맞아 아내로 삼으며 자기 딸들을 그들의 아들들에게 주고 또 그들의 신들을 섬겼더라',6575),
('jdg-3-7','jdg','사사기',3,7,'이스라엘 자손이 여호와의 목전에 악을 행하여 자기들의 하나님 여호와를 잊어버리고 바알들과 아세라들을 섬긴지라',6576),
('jdg-3-8','jdg','사사기',3,8,'여호와께서 이스라엘에게 진노하사 그들을 메소보다미아 왕 구산 리사다임의 손에 팔았으므로 이스라엘 자손이 구산 리사다임을 팔 년 동안 섬겼더니',6577),
('jdg-3-9','jdg','사사기',3,9,'이스라엘 자손이 여호와께 부르짖으매 여호와께서 이스라엘 자손을 위하여 한 구원자를 세워 그들을 구원하게 하시니 그는 곧 갈렙의 아우 그나스의 아들 옷니엘이라',6578),
('jdg-3-10','jdg','사사기',3,10,'여호와의 영이 그에게 임하셨으므로 그가 이스라엘의 사사가 되어 나가서 싸울 때에 여호와께서 메소보다미아 왕 구산 리사다임을 그의 손에 넘겨 주시매 옷니엘의 손이 구산 리사다임을 이기니라',6579),
('jdg-3-11','jdg','사사기',3,11,'그 땅이 평온한 지 사십 년에 그나스의 아들 옷니엘이 죽었더라',6580),
('jdg-3-12','jdg','사사기',3,12,'이스라엘 자손이 또 여호와의 목전에 악을 행하니라 이스라엘 자손이 여호와의 목전에 악을 행하므로 여호와께서 모압 왕 에글론을 강성하게 하사 그들을 대적하게 하시매',6581),
('jdg-3-13','jdg','사사기',3,13,'에글론이 암몬과 아말렉 자손들을 모아 가지고 와서 이스라엘을 쳐서 종려나무 성읍을 점령한지라',6582),
('jdg-3-14','jdg','사사기',3,14,'이에 이스라엘 자손이 모압 왕 에글론을 열여덟 해 동안 섬기니라',6583),
('jdg-3-15','jdg','사사기',3,15,'이스라엘 자손이 여호와께 부르짖으매 여호와께서 그들을 위하여 한 구원자를 세우셨으니 그는 곧 베냐민 사람 게라의 아들 왼손잡이 에훗이라 이스라엘 자손이 그를 통하여 모압 왕 에글론에게 공물을 바칠 때에',6584),
('jdg-3-16','jdg','사사기',3,16,'에훗이 길이가 한 규빗 되는 좌우에 날선 칼을 만들어 그의 오른쪽 허벅지 옷 속에 차고',6585),
('jdg-3-17','jdg','사사기',3,17,'공물을 모압 왕 에글론에게 바쳤는데 에글론은 매우 비둔한 자였더라',6586),
('jdg-3-18','jdg','사사기',3,18,'에훗이 공물 바치기를 마친 후에 공물을 메고 온 자들을 보내고',6587),
('jdg-3-19','jdg','사사기',3,19,'자기는 길갈 근처 돌 뜨는 곳에서부터 돌아와서 이르되 왕이여 내가 은밀한 일을 왕에게 아뢰려 하나이다 하니 왕이 명령하여 조용히 하라 하매 모셔 선 자들이 다 물러간지라',6588),
('jdg-3-20','jdg','사사기',3,20,'에훗이 그에게로 들어가니 왕은 서늘한 다락방에 홀로 앉아 있는 중이라 에훗이 이르되 내가 하나님의 명령을 받들어 왕에게 아뢸 일이 있나이다 하매 왕이 그의 좌석에서 일어나니',6589),
('jdg-3-21','jdg','사사기',3,21,'에훗이 왼손을 뻗쳐 그의 오른쪽 허벅지 위에서 칼을 빼어 왕의 몸을 찌르매',6590),
('jdg-3-22','jdg','사사기',3,22,'칼자루도 날을 따라 들어가서 그 끝이 등 뒤까지 나갔고 그가 칼을 그의 몸에서 빼내지 아니하였으므로 기름이 칼날에 엉겼더라',6591),
('jdg-3-23','jdg','사사기',3,23,'에훗이 현관에 나와서 다락문들을 뒤에서 닫아 잠그니라',6592),
('jdg-3-24','jdg','사사기',3,24,'에훗이 나간 후에 왕의 신하들이 들어와서 다락문들이 잠겼음을 보고 이르되 왕이 분명히 서늘한 방에서 그의 발을 가리우신다 하고',6593),
('jdg-3-25','jdg','사사기',3,25,'그들이 오래 기다려도 왕이 다락문들을 열지 아니하는지라 열쇠를 가지고 열어 본즉 그들의 군주가 이미 땅에 엎드러져 죽었더라',6594),
('jdg-3-26','jdg','사사기',3,26,'그들이 기다리는 동안에 에훗이 피하여 돌 뜨는 곳을 지나 스이라로 도망하니라',6595),
('jdg-3-27','jdg','사사기',3,27,'그가 이르러 에브라임 산지에서 나팔을 불매 이스라엘 자손이 산지에서 그를 따라 내려오니 에훗이 앞서 가며',6596),
('jdg-3-28','jdg','사사기',3,28,'그들에게 이르되 나를 따르라 여호와께서 너희의 원수들인 모압을 너희의 손에 넘겨 주셨느니라 하매 무리가 에훗을 따라 내려가 모압 맞은편 요단 강 나루를 장악하여 한 사람도 건너지 못하게 하였고',6597),
('jdg-3-29','jdg','사사기',3,29,'그 때에 모압 사람 약 만 명을 죽였으니 모두 장사요 모두 용사라 한 사람도 도망하지 못하였더라',6598),
('jdg-3-30','jdg','사사기',3,30,'그 날에 모압이 이스라엘 수하에 굴복하매 그 땅이 팔십 년 동안 평온하였더라',6599),
('jdg-3-31','jdg','사사기',3,31,'에훗 후에는 아낫의 아들 삼갈이 있어 소 모는 막대기로 블레셋 사람 육백 명을 죽였고 그도 이스라엘을 구원하였더라',6600),
('jdg-4-1','jdg','사사기',4,1,'에훗이 죽으니 이스라엘 자손이 또 여호와의 목전에 악을 행하매',6601),
('jdg-4-2','jdg','사사기',4,2,'여호와께서 하솔에서 통치하는 가나안 왕 야빈의 손에 그들을 팔았으니 그의 군대 장관은 하로셋 학고임에 거주하는 시스라요',6602),
('jdg-4-3','jdg','사사기',4,3,'야빈 왕은 철 병거 구백 대가 있어 이십 년 동안 이스라엘 자손을 심히 학대했으므로 이스라엘 자손이 여호와께 부르짖었더라',6603),
('jdg-4-4','jdg','사사기',4,4,'그 때에 랍비돗의 아내 여선지자 드보라가 이스라엘의 사사가 되었는데',6604),
('jdg-4-5','jdg','사사기',4,5,'그는 에브라임 산지 라마와 벧엘 사이 드보라의 종려나무 아래에 거주하였고 이스라엘 자손은 그에게 나아가 재판을 받더라',6605),
('jdg-4-6','jdg','사사기',4,6,'드보라가 사람을 보내어 아비노암의 아들 바락을 납달리 게데스에서 불러다가 그에게 이르되 이스라엘의 하나님 여호와께서 이같이 명령하지 아니하셨느냐 너는 납달리 자손과 스불론 자손 만 명을 거느리고 다볼 산으로 가라',6606),
('jdg-4-7','jdg','사사기',4,7,'내가 야빈의 군대 장관 시스라와 그의 병거들과 그의 무리를 기손 강으로 이끌어 네게 이르게 하고 그를 네 손에 넘겨 주리라 하셨느니라',6607),
('jdg-4-8','jdg','사사기',4,8,'바락이 그에게 이르되 만일 당신이 나와 함께 가면 내가 가려니와 만일 당신이 나와 함께 가지 아니하면 나도 가지 아니하겠노라 하니',6608),
('jdg-4-9','jdg','사사기',4,9,'이르되 내가 반드시 너와 함께 가리라 그러나 네가 이번에 가는 길에서는 영광을 얻지 못하리니 이는 여호와께서 시스라를 여인의 손에 파실 것임이니라 하고 드보라가 일어나 바락과 함께 게데스로 가니라',6609),
('jdg-4-10','jdg','사사기',4,10,'바락이 스불론과 납달리를 게데스로 부르니 만 명이 그를 따라 올라가고 드보라도 그와 함께 올라가니라',6610),
('jdg-4-11','jdg','사사기',4,11,'모세의 장인 호밥의 자손 중 겐 사람 헤벨이 떠나 게데스에 가까운 사아난님 상수리나무 곁에 이르러 장막을 쳤더라',6611),
('jdg-4-12','jdg','사사기',4,12,'아비노암의 아들 바락이 다볼 산에 오른 것을 사람들이 시스라에게 알리매',6612),
('jdg-4-13','jdg','사사기',4,13,'시스라가 모든 병거 곧 철 병거 구백 대와 자기와 함께 있는 모든 백성을 하로셋학고임에서부터 기손 강으로 모은지라',6613),
('jdg-4-14','jdg','사사기',4,14,'드보라가 바락에게 이르되 일어나라 이는 여호와께서 시스라를 네 손에 넘겨 주신 날이라 여호와께서 너에 앞서 나가지 아니하시느냐 하는지라 이에 바락이 만 명을 거느리고 다볼 산에서 내려가니',6614),
('jdg-4-15','jdg','사사기',4,15,'여호와께서 바락 앞에서 시스라와 그의 모든 병거와 그의 온 군대를 칼날로 혼란에 빠지게 하시매 시스라가 병거에서 내려 걸어서 도망한지라',6615),
('jdg-4-16','jdg','사사기',4,16,'바락이 그의 병거들과 군대를 추격하여 하로셋학고임에 이르니 시스라의 온 군대가 다 칼에 엎드러졌고 한 사람도 남은 자가 없었더라',6616),
('jdg-4-17','jdg','사사기',4,17,'시스라가 걸어서 도망하여 겐 사람 헤벨의 아내 야엘의 장막에 이르렀으니 이는 하솔 왕 야빈과 겐 사람 헤벨의 집 사이에는 화평이 있음이라',6617),
('jdg-4-18','jdg','사사기',4,18,'야엘이 나가 시스라를 영접하며 그에게 말하되 나의 주여 들어오소서 내게로 들어오시고 두려워하지 마소서 하매 그가 그 장막에 들어가니 야엘이 이불로 그를 덮으니라',6618),
('jdg-4-19','jdg','사사기',4,19,'시스라가 그에게 말하되 청하노니 내게 물을 조금 마시게 하라 내가 목이 마르다 하매 우유 부대를 열어 그에게 마시게 하고 그를 덮으니',6619),
('jdg-4-20','jdg','사사기',4,20,'그가 또 이르되 장막 문에 섰다가 만일 사람이 와서 네게 묻기를 여기 어떤 사람이 있느냐 하거든 너는 없다 하라 하고',6620),
('jdg-4-21','jdg','사사기',4,21,'그가 깊이 잠드니 헤벨의 아내 야엘이 장막 말뚝을 가지고 손에 방망이를 들고 그에게로 가만히 가서 말뚝을 그의 관자놀이에 박으매 말뚝이 꿰뚫고 땅에 박히니 그가 기절하여 죽으니라',6621),
('jdg-4-22','jdg','사사기',4,22,'바락이 시스라를 추격할 때에 야엘이 나가서 그를 맞아 그에게 이르되 오라 네가 찾는 그 사람을 내가 네게 보이리라 하매 바락이 그에게 들어가 보니 시스라가 엎드러져 죽었고 말뚝이 그의 관자놀이에 박혔더라',6622),
('jdg-4-23','jdg','사사기',4,23,'이와 같이 이 날에 하나님이 가나안 왕 야빈을 이스라엘 자손 앞에 굴복하게 하신지라',6623),
('jdg-4-24','jdg','사사기',4,24,'이스라엘 자손의 손이 가나안 왕 야빈을 점점 더 눌러서 마침내 가나안 왕 야빈을 진멸하였더라',6624),
('jdg-5-1','jdg','사사기',5,1,'이 날에 드보라와 아비노암의 아들 바락이 노래하여 이르되',6625),
('jdg-5-2','jdg','사사기',5,2,'이스라엘의 영솔자들이 영솔하였고 백성이 즐거이 헌신하였으니 여호와를 찬송하라',6626),
('jdg-5-3','jdg','사사기',5,3,'너희 왕들아 들으라 통치자들아 귀를 기울이라 나 곧 내가 여호와를 노래할 것이요 이스라엘의 하나님 여호와를 찬송하리로다',6627),
('jdg-5-4','jdg','사사기',5,4,'여호와여 주께서 세일에서부터 나오시고 에돔 들에서부터 진행하실 때에 땅이 진동하고 하늘이 물을 내리고 구름도 물을 내렸나이다',6628),
('jdg-5-5','jdg','사사기',5,5,'산들이 여호와 앞에서 진동하니 저 시내 산도 이스라엘의 하나님 여호와 앞에서 진동하였도다',6629),
('jdg-5-6','jdg','사사기',5,6,'아낫의 아들 삼갈의 날에 또는 야엘의 날에는 대로가 비었고 길의 행인들은 오솔길로 다녔도다',6630),
('jdg-5-7','jdg','사사기',5,7,'이스라엘에는 마을 사람들이 그쳤으니 나 드보라가 일어나 이스라엘의 어머니가 되기까지 그쳤도다',6631),
('jdg-5-8','jdg','사사기',5,8,'무리가 새 신들을 택하였으므로 그 때에 전쟁이 성문에 이르렀으나 이스라엘의 사만 명 중에 방패와 창이 보였던가',6632),
('jdg-5-9','jdg','사사기',5,9,'내 마음이 이스라엘의 방백을 사모함은 그들이 백성 중에서 즐거이 헌신하였음이니 여호와를 찬송하라',6633),
('jdg-5-10','jdg','사사기',5,10,'흰 나귀를 탄 자들, 양탄자에 앉은 자들, 길에 행하는 자들아 전파할지어다',6634),
('jdg-5-11','jdg','사사기',5,11,'활 쏘는 자들의 소리로부터 멀리 떨어진 물 긷는 곳에서도 여호와의 공의로우신 일을 전하라 이스라엘에서 마을 사람들을 위한 의로우신 일을 노래하라 그 때에 여호와의 백성이 성문에 내려갔도다',6635),
('jdg-5-12','jdg','사사기',5,12,'깰지어다 깰지어다 드보라여 깰지어다 깰지어다 너는 노래할지어다 일어날지어다 바락이여 아비노암의 아들이여 네가 사로잡은 자를 끌고 갈지어다',6636),
('jdg-5-13','jdg','사사기',5,13,'그 때에 남은 귀인과 백성이 내려왔고 여호와께서 나를 위하여 용사를 치시려고 내려오셨도다',6637),
('jdg-5-14','jdg','사사기',5,14,'에브라임에게서 나온 자들은 아말렉에 뿌리 박힌 자들이요 베냐민은 백성들 중에서 너를 따르는 자들이요 마길에게서는 명령하는 자들이 내려왔고 스불론에게서는 대장군의 지팡이를 잡은 자들이 내려왔도다',6638),
('jdg-5-15','jdg','사사기',5,15,'잇사갈의 방백들이 드보라와 함께 하니 잇사갈과 같이 바락도 그의 뒤를 따라 골짜기로 달려 내려가니 르우벤 시냇가에서 큰 결심이 있었도다',6639),
('jdg-5-16','jdg','사사기',5,16,'네가 양의 우리 가운데에 앉아서 목자의 피리 부는 소리를 들음은 어찌 됨이냐 르우벤 시냇가에서 큰 결심이 있었도다',6640),
('jdg-5-17','jdg','사사기',5,17,'길르앗은 요단 강 저쪽에 거주하며 단은 배에 머무름이 어찌 됨이냐 아셀은 해변에 앉으며 자기 항만에 거주하도다',6641),
('jdg-5-18','jdg','사사기',5,18,'스불론은 죽음을 무릅쓰고 목숨을 아끼지 아니한 백성이요 납달리도 들의 높은 곳에서 그러하도다',6642),
('jdg-5-19','jdg','사사기',5,19,'왕들이 와서 싸울 때에 가나안 왕들이 므깃도 물 가 다아낙에서 싸웠으나 은을 탈취하지 못하였도다',6643),
('jdg-5-20','jdg','사사기',5,20,'별들이 하늘에서부터 싸우되 그들이 다니는 길에서 시스라와 싸웠도다',6644),
('jdg-5-21','jdg','사사기',5,21,'기손 강은 그 무리를 표류시켰으니 이 기손 강은 옛 강이라 내 영혼아 네가 힘 있는 자를 밟았도다',6645),
('jdg-5-22','jdg','사사기',5,22,'그 때에 군마가 빨리 달리니 말굽 소리가 땅을 울리도다',6646),
('jdg-5-23','jdg','사사기',5,23,'여호와의 사자의 말씀에 메로스를 저주하라 너희가 거듭거듭 그 주민들을 저주할 것은 그들이 와서 여호와를 돕지 아니하며 여호와를 도와 용사를 치지 아니함이니라 하시도다',6647),
('jdg-5-24','jdg','사사기',5,24,'겐 사람 헤벨의 아내 야엘은 다른 여인들보다 복을 받을 것이니 장막에 있는 여인들보다 더욱 복을 받을 것이로다',6648),
('jdg-5-25','jdg','사사기',5,25,'시스라가 물을 구하매 우유를 주되 곧 엉긴 우유를 귀한 그릇에 담아 주었고',6649),
('jdg-5-26','jdg','사사기',5,26,'손으로 장막 말뚝을 잡으며 오른손에 일꾼들의 방망이를 들고 시스라를 쳐서 그의 머리를 뚫되 곧 그의 관자놀이를 꿰뚫었도다',6650),
('jdg-5-27','jdg','사사기',5,27,'그가 그의 발 앞에 꾸부러지며 엎드러지고 쓰러졌고 그의 발 앞에 꾸부러져 엎드러져서 그 꾸부러진 곳에 엎드러져 죽었도다',6651),
('jdg-5-28','jdg','사사기',5,28,'시스라의 어머니가 창문을 통하여 바라보며 창살을 통하여 부르짖기를 그의 병거가 어찌하여 더디 오는가 그의 병거들의 걸음이 어찌하여 늦어지는가 하매',6652),
('jdg-5-29','jdg','사사기',5,29,'그의 지혜로운 시녀들이 대답하였겠고 그도 스스로 대답하기를',6653),
('jdg-5-30','jdg','사사기',5,30,'그들이 어찌 노략물을 얻지 못하였으랴 그것을 나누지 못하였으랴 사람마다 한두 처녀를 얻었으리로다 시스라는 채색 옷을 노략하였으리니 그것은 수 놓은 채색 옷이리로다 곧 양쪽에 수 놓은 채색 옷이리니 노략한 자의 목에 꾸미리로다 하였으리라',6654),
('jdg-5-31','jdg','사사기',5,31,'여호와여 주의 원수들은 다 이와 같이 망하게 하시고 주를 사랑하는 자들은 해가 힘 있게 돋음 같게 하시옵소서 하니라 그 땅이 사십 년 동안 평온하였더라',6655),
('jdg-6-1','jdg','사사기',6,1,'이스라엘 자손이 또 여호와의 목전에 악을 행하였으므로 여호와께서 칠 년 동안 그들을 미디안의 손에 넘겨 주시니',6656),
('jdg-6-2','jdg','사사기',6,2,'미디안의 손이 이스라엘을 이긴지라 이스라엘 자손이 미디안으로 말미암아 산에서 웅덩이와 굴과 산성을 자기들을 위하여 만들었으며',6657),
('jdg-6-3','jdg','사사기',6,3,'이스라엘이 파종한 때면 미디안과 아말렉과 동방 사람들이 치러 올라와서',6658),
('jdg-6-4','jdg','사사기',6,4,'진을 치고 가사에 이르도록 토지 소산을 멸하여 이스라엘 가운데에 먹을 것을 남겨 두지 아니하며 양이나 소나 나귀도 남기지 아니하니',6659),
('jdg-6-5','jdg','사사기',6,5,'이는 그들이 그들의 짐승과 장막을 가지고 올라와 메뚜기 떼 같이 많이 들어오니 그 사람과 낙타가 무수함이라 그들이 그 땅에 들어와 멸하려 하니',6660),
('jdg-6-6','jdg','사사기',6,6,'이스라엘이 미디안으로 말미암아 궁핍함이 심한지라 이에 이스라엘 자손이 여호와께 부르짖었더라',6661),
('jdg-6-7','jdg','사사기',6,7,'이스라엘 자손이 미디안으로 말미암아 여호와께 부르짖었으므로',6662),
('jdg-6-8','jdg','사사기',6,8,'여호와께서 이스라엘 자손에게 한 선지자를 보내시니 그가 그들에게 이르되 여호와께서 이같이 말씀하시기를 이스라엘의 하나님 내가 너희를 애굽에서 인도하여 내며 너희를 그 종 되었던 집에서 나오게 하여',6663),
('jdg-6-9','jdg','사사기',6,9,'애굽 사람의 손과 너희를 학대하는 모든 자의 손에서 너희를 건져내고 그들을 너희 앞에서 쫓아내고 그 땅을 너희에게 주었으며',6664),
('jdg-6-10','jdg','사사기',6,10,'내가 또 너희에게 이르기를 나는 너희의 하나님 여호와이니 너희가 거주하는 아모리 사람의 땅의 신들을 두려워하지 말라 하였으나 너희가 내 목소리를 듣지 아니하였느니라 하셨다 하니라',6665),
('jdg-6-11','jdg','사사기',6,11,'여호와의 사자가 아비에셀 사람 요아스에게 속한 오브라에 이르러 상수리나무 아래에 앉으니라 마침 요아스의 아들 기드온이 미디안 사람에게 알리지 아니하려 하여 밀을 포도주 틀에서 타작하더니',6666),
('jdg-6-12','jdg','사사기',6,12,'여호와의 사자가 기드온에게 나타나 이르되 큰 용사여 여호와께서 너와 함께 계시도다 하매',6667),
('jdg-6-13','jdg','사사기',6,13,'기드온이 그에게 대답하되 오 나의 주여 여호와께서 우리와 함께 계시면 어찌하여 이 모든 일이 우리에게 일어났나이까 또 우리 조상들이 일찍이 우리에게 이르기를 여호와께서 우리를 애굽에서 올라오게 하신 것이 아니냐 한 그 모든 이적이 어디 있나이까 이제 여호와께서 우리를 버리사 미디안의 손에 우리를 넘겨 주셨나이다 하니',6668),
('jdg-6-14','jdg','사사기',6,14,'여호와께서 그를 향하여 이르시되 너는 가서 이 너의 힘으로 이스라엘을 미디안의 손에서 구원하라 내가 너를 보낸 것이 아니냐 하시니라',6669),
('jdg-6-15','jdg','사사기',6,15,'그러나 기드온이 그에게 대답하되 오 주여 내가 무엇으로 이스라엘을 구원하리이까 보소서 나의 집은 므낫세 중에 극히 약하고 나는 내 아버지 집에서 가장 작은 자니이다 하니',6670),
('jdg-6-16','jdg','사사기',6,16,'여호와께서 그에게 이르시되 내가 반드시 너와 함께 하리니 네가 미디안 사람 치기를 한 사람을 치듯 하리라 하시니라',6671),
('jdg-6-17','jdg','사사기',6,17,'기드온이 그에게 대답하되 만일 내가 주께 은혜를 얻었사오면 나와 말씀하신 이가 주 되시는 표징을 내게 보이소서',6672),
('jdg-6-18','jdg','사사기',6,18,'내가 예물을 가지고 다시 주께로 와서 그것을 주 앞에 드리기까지 이 곳을 떠나지 마시기를 원하나이다 하니 그가 이르되 내가 너의 돌아오기까지 머무르리라 하니라',6673),
('jdg-6-19','jdg','사사기',6,19,'기드온이 가서 염소 새끼 하나를 준비하고 가루 한 에바로 무교병을 만들고 고기를 소쿠리에 담고 국을 양푼에 담아 상수리나무 아래 그에게로 가져다가 드리매',6674),
('jdg-6-20','jdg','사사기',6,20,'하나님의 사자가 그에게 이르되 고기와 무교병을 가져다가 이 바위 위에 놓고 국을 부으라 하니 기드온이 그대로 하니라',6675),
('jdg-6-21','jdg','사사기',6,21,'여호와의 사자가 손에 잡은 지팡이 끝을 내밀어 고기와 무교병에 대니 불이 바위에서 나와 고기와 무교병을 살랐고 여호와의 사자는 떠나서 보이지 아니한지라',6676),
('jdg-6-22','jdg','사사기',6,22,'기드온이 그가 여호와의 사자인 줄을 알고 이르되 슬프도소이다 주 여호와여 내가 여호와의 사자를 대면하여 보았나이다 하니',6677),
('jdg-6-23','jdg','사사기',6,23,'여호와께서 그에게 이르시되 너는 안심하라 두려워하지 말라 죽지 아니하리라 하시니라',6678),
('jdg-6-24','jdg','사사기',6,24,'기드온이 여호와를 위하여 거기서 제단을 쌓고 그것을 여호와 살롬이라 하였더라 그것이 오늘까지 아비에셀 사람에게 속한 오브라에 있더라',6679),
('jdg-6-25','jdg','사사기',6,25,'그 날 밤에 여호와께서 기드온에게 이르시되 네 아버지에게 있는 수소 곧 칠 년 된 둘째 수소를 끌어 오고 네 아버지에게 있는 바알의 제단을 헐며 그 곁의 아세라 상을 찍고',6680),
('jdg-6-26','jdg','사사기',6,26,'또 이 산성 꼭대기에 네 하나님 여호와를 위하여 규례대로 한 제단을 쌓고 그 둘째 수소를 잡아 네가 찍은 아세라 나무로 번제를 드릴지니라 하시니라',6681),
('jdg-6-27','jdg','사사기',6,27,'이에 기드온이 종 열 사람을 데리고 여호와께서 그에게 말씀하신 대로 행하되 그의 아버지의 가문과 그 성읍 사람들을 두려워하므로 이 일을 감히 낮에 행하지 못하고 밤에 행하니라',6682),
('jdg-6-28','jdg','사사기',6,28,'그 성읍 사람들이 아침에 일찍이 일어나 본즉 바알의 제단이 파괴되었으며 그 곁의 아세라가 찍혔고 새로 쌓은 제단 위에 그 둘째 수소를 드렸는지라',6683),
('jdg-6-29','jdg','사사기',6,29,'서로 물어 이르되 이것이 누구의 소행인가 하고 그들이 캐어 물은 후에 이르되 요아스의 아들 기드온이 이를 행하였도다 하고',6684),
('jdg-6-30','jdg','사사기',6,30,'성읍 사람들이 요아스에게 이르되 네 아들을 끌어내라 그는 당연히 죽을지니 이는 바알의 제단을 파괴하고 그 곁의 아세라를 찍었음이니라 하니',6685),
('jdg-6-31','jdg','사사기',6,31,'요아스가 자기를 둘러선 모든 자에게 이르되 너희가 바알을 위하여 다투느냐 너희가 바알을 구원하겠느냐 그를 위하여 다투는 자는 아침까지 죽임을 당하리라 바알이 과연 신일진대 그의 제단을 파괴하였은즉 그가 자신을 위해 다툴 것이니라 하니라',6686),
('jdg-6-32','jdg','사사기',6,32,'그 날에 기드온을 여룹바알이라 불렀으니 이는 그가 바알의 제단을 파괴하였으므로 바알이 그와 더불어 다툴 것이라 함이었더라',6687),
('jdg-6-33','jdg','사사기',6,33,'그 때에 미디안과 아말렉과 동방 사람들이 다 함께 모여 요단 강을 건너와서 이스르엘 골짜기에 진을 친지라',6688),
('jdg-6-34','jdg','사사기',6,34,'여호와의 영이 기드온에게 임하시니 기드온이 나팔을 불매 아비에셀이 그의 뒤를 따라 부름을 받으니라',6689),
('jdg-6-35','jdg','사사기',6,35,'기드온이 또 사자들을 온 므낫세에 두루 보내매 그들도 모여서 그를 따르고 또 사자들을 아셀과 스불론과 납달리에 보내매 그 무리도 올라와 그를 영접하더라',6690),
('jdg-6-36','jdg','사사기',6,36,'기드온이 하나님께 여쭈되 주께서 이미 말씀하심 같이 내 손으로 이스라엘을 구원하시려거든',6691),
('jdg-6-37','jdg','사사기',6,37,'보소서 내가 양털 한 뭉치를 타작 마당에 두리니 만일 이슬이 양털에만 있고 주변 땅은 마르면 주께서 이미 말씀하심 같이 내 손으로 이스라엘을 구원하실 줄을 내가 알겠나이다 하였더니',6692),
('jdg-6-38','jdg','사사기',6,38,'그대로 된지라 이튿날 기드온이 일찍이 일어나서 양털을 가져다가 그 양털에서 이슬을 짜니 물이 그릇에 가득하더라',6693),
('jdg-6-39','jdg','사사기',6,39,'기드온이 또 하나님께 여쭈되 주여 내게 노하지 마옵소서 내가 이번만 말하리이다 구하옵나니 내게 이번만 양털로 시험하게 하소서 원하건대 양털만 마르고 그 주변 땅에는 다 이슬이 있게 하옵소서 하였더니',6694),
('jdg-6-40','jdg','사사기',6,40,'그 밤에 하나님이 그대로 행하시니 곧 양털만 마르고 그 주변 땅에는 다 이슬이 있었더라',6695),
('jdg-7-1','jdg','사사기',7,1,'여룹바알이라 하는 기드온과 그를 따르는 모든 백성이 일찍이 일어나 하롯 샘 곁에 진을 쳤고 미디안의 진영은 그들의 북쪽이요 모레 산 앞 골짜기에 있었더라',6696),
('jdg-7-2','jdg','사사기',7,2,'여호와께서 기드온에게 이르시되 너를 따르는 백성이 너무 많은즉 내가 그들의 손에 미디안 사람을 넘겨 주지 아니하리니 이는 이스라엘이 나를 거슬러 스스로 자랑하기를 내 손이 나를 구원하였다 할까 함이니라',6697),
('jdg-7-3','jdg','사사기',7,3,'이제 너는 백성의 귀에 외쳐 이르기를 누구든지 두려워 떠는 자는 길르앗 산을 떠나 돌아가라 하라 하시니 이에 돌아간 백성이 이만 이천 명이요 남은 자가 만 명이었더라',6698),
('jdg-7-4','jdg','사사기',7,4,'여호와께서 또 기드온에게 이르시되 백성이 아직도 많으니 그들을 인도하여 물 가로 내려가라 거기서 내가 너를 위하여 그들을 시험하리라 내가 누구를 가리켜 네게 이르기를 이 사람이 너와 함께 가리라 하면 그는 너와 함께 갈 것이요 내가 누구를 가리켜 네게 이르기를 이 사람은 너와 함께 가지 말 것이니라 하면 그는 가지 말 것이니라 하신지라',6699),
('jdg-7-5','jdg','사사기',7,5,'이에 백성을 인도하여 물 가에 내려가매 여호와께서 기드온에게 이르시되 누구든지 개가 핥는 것 같이 혀로 물을 핥는 자들을 너는 따로 세우고 또 누구든지 무릎을 꿇고 마시는 자들도 그와 같이 하라 하시더니',6700),
('jdg-7-6','jdg','사사기',7,6,'손으로 움켜 입에 대고 핥는 자의 수는 삼백 명이요 그 외의 백성은 다 무릎을 꿇고 물을 마신지라',6701),
('jdg-7-7','jdg','사사기',7,7,'여호와께서 기드온에게 이르시되 내가 이 물을 핥아 먹은 삼백 명으로 너희를 구원하며 미디안을 네 손에 넘겨 주리니 남은 백성은 각각 자기의 처소로 돌아갈 것이니라 하시니',6702),
('jdg-7-8','jdg','사사기',7,8,'이에 백성이 양식과 나팔을 손에 든지라 기드온이 이스라엘 모든 백성을 각각 그의 장막으로 돌려보내고 그 삼백 명은 머물게 하니라 미디안 진영은 그 아래 골짜기 가운데에 있었더라',6703),
('jdg-7-9','jdg','사사기',7,9,'그 밤에 여호와께서 기드온에게 이르시되 일어나 진영으로 내려가라 내가 그것을 네 손에 넘겨 주었느니라',6704),
('jdg-7-10','jdg','사사기',7,10,'만일 네가 내려가기를 두려워하거든 네 부하 부라와 함께 그 진영으로 내려가서',6705),
('jdg-7-11','jdg','사사기',7,11,'그들이 하는 말을 들으라 그 후에 네 손이 강하여져서 그 진영으로 내려가리라 하시니 기드온이 이에 그의 부하 부라와 함께 군대가 있는 진영 근처로 내려간즉',6706),
('jdg-7-12','jdg','사사기',7,12,'미디안과 아말렉과 동방의 모든 사람들이 골짜기에 누웠는데 메뚜기의 많은 수와 같고 그들의 낙타의 수가 많아 해변의 모래가 많음 같은지라',6707),
('jdg-7-13','jdg','사사기',7,13,'기드온이 그 곳에 이른즉 어떤 사람이 그의 친구에게 꿈을 말하여 이르기를 보라 내가 한 꿈을 꾸었는데 꿈에 보리떡 한 덩어리가 미디안 진영으로 굴러 들어와 한 장막에 이르러 그것을 쳐서 무너뜨려 위쪽으로 엎으니 그 장막이 쓰러지더라',6708),
('jdg-7-14','jdg','사사기',7,14,'그의 친구가 대답하여 이르되 이는 다른 것이 아니라 이스라엘 사람 요아스의 아들 기드온의 칼이라 하나님이 미디안과 그 모든 진영을 그의 손에 넘겨 주셨느니라 하더라',6709),
('jdg-7-15','jdg','사사기',7,15,'기드온이 그 꿈과 해몽하는 말을 듣고 경배하며 이스라엘 진영으로 돌아와 이르되 일어나라 여호와께서 미디안과 그 모든 진영을 너희 손에 넘겨 주셨느니라 하고',6710),
('jdg-7-16','jdg','사사기',7,16,'삼백 명을 세 대로 나누어 각 손에 나팔과 빈 항아리를 들리고 항아리 안에는 횃불을 감추게 하고',6711),
('jdg-7-17','jdg','사사기',7,17,'그들에게 이르되 너희는 나만 보고 내가 하는 대로 하되 내가 그 진영 근처에 이르러서 내가 하는 대로 너희도 그리하여',6712),
('jdg-7-18','jdg','사사기',7,18,'나와 나를 따르는 자가 다 나팔을 불거든 너희도 모든 진영 주위에서 나팔을 불며 이르기를 여호와를 위하라, 기드온을 위하라 하라 하니라',6713),
('jdg-7-19','jdg','사사기',7,19,'기드온과 그와 함께 한 백 명이 이경 초에 진영 근처에 이른즉 바로 파수꾼들을 교대한 때라 그들이 나팔을 불며 손에 가졌던 항아리를 부수니라',6714),
('jdg-7-20','jdg','사사기',7,20,'세 대가 나팔을 불며 항아리를 부수고 왼손에 횃불을 들고 오른손에 나팔을 들어 불며 외쳐 이르되 여호와와 기드온의 칼이다 하고',6715),
('jdg-7-21','jdg','사사기',7,21,'각기 제자리에 서서 그 진영을 에워싸매 그 온 진영의 군사들이 뛰고 부르짖으며 도망하였는데',6716),
('jdg-7-22','jdg','사사기',7,22,'삼백 명이 나팔을 불 때에 여호와께서 그 온 진영에서 친구끼리 칼로 치게 하시므로 적군이 도망하여 스레라의 벧 싯다에 이르고 또 답밧에 가까운 아벨므홀라의 경계에 이르렀으며',6717),
('jdg-7-23','jdg','사사기',7,23,'이스라엘 사람들은 납달리와 아셀과 온 므낫세에서부터 부름을 받고 미디안을 추격하였더라',6718),
('jdg-7-24','jdg','사사기',7,24,'기드온이 사자들을 보내서 에브라임 온 산지로 두루 다니게 하여 이르기를 내려와서 미디안을 치고 그들을 앞질러 벧 바라와 요단 강에 이르는 수로를 점령하라 하매 이에 에브라임 사람들이 다 모여 벧 바라와 요단 강에 이르는 수로를 점령하고',6719),
('jdg-7-25','jdg','사사기',7,25,'또 미디안의 두 방백 오렙과 스엡을 사로잡아 오렙은 오렙 바위에서 죽이고 스엡은 스엡 포도주 틀에서 죽이고 미디안을 추격하였고 오렙과 스엡의 머리를 요단 강 건너편에서 기드온에게 가져왔더라',6720),
('jdg-8-1','jdg','사사기',8,1,'에브라임 사람들이 기드온에게 이르되 네가 미디안과 싸우러 갈 때에 우리를 부르지 아니하였으니 우리를 이같이 대접함은 어찌 됨이냐 하고 그와 크게 다투는지라',6721),
('jdg-8-2','jdg','사사기',8,2,'기드온이 그들에게 이르되 내가 이제 행한 일이 너희가 한 것에 비교되겠느냐 에브라임의 끝물 포도가 아비에셀의 맏물 포도보다 낫지 아니하냐',6722),
('jdg-8-3','jdg','사사기',8,3,'하나님이 미디안의 방백 오렙과 스엡을 너희 손에 넘겨 주셨으니 내가 한 일이 어찌 능히 너희가 한 것에 비교되겠느냐 하니라 기드온이 이 말을 하매 그 때에 그들의 노여움이 풀리니라',6723),
('jdg-8-4','jdg','사사기',8,4,'기드온과 그와 함께 한 자 삼백 명이 요단 강에 이르러 건너고 비록 피곤하나 추격하며',6724),
('jdg-8-5','jdg','사사기',8,5,'그가 숙곳 사람들에게 이르되 나를 따르는 백성이 피곤하니 청하건대 그들에게 떡덩이를 주라 나는 미디안의 왕들인 세바와 살문나의 뒤를 추격하고 있노라 하니',6725),
('jdg-8-6','jdg','사사기',8,6,'숙곳의 방백들이 이르되 세바와 살문나의 손이 지금 네 손 안에 있다는거냐 어찌 우리가 네 군대에게 떡을 주겠느냐 하는지라',6726),
('jdg-8-7','jdg','사사기',8,7,'기드온이 이르되 그러면 여호와께서 세바와 살문나를 내 손에 넘겨 주신 후에 내가 들가시와 찔레로 너희 살을 찢으리라 하고',6727),
('jdg-8-8','jdg','사사기',8,8,'거기서 브누엘로 올라가서 그들에게도 그같이 구한즉 브누엘 사람들의 대답도 숙곳 사람들의 대답과 같은지라',6728),
('jdg-8-9','jdg','사사기',8,9,'기드온이 또 브누엘 사람들에게 말하여 이르되 내가 평안히 돌아올 때에 이 망대를 헐리라 하니라',6729),
('jdg-8-10','jdg','사사기',8,10,'이 때에 세바와 살문나가 갈골에 있는데 동방 사람의 모든 군대 중에 칼 든 자 십이만 명이 죽었고 그 남은 만 오천 명 가량은 그들을 따라와서 거기에 있더라',6730),
('jdg-8-11','jdg','사사기',8,11,'적군이 안심하고 있는 중에 기드온이 노바와 욕브하 동쪽 장막에 거주하는 자의 길로 올라가서 그 적진을 치니',6731),
('jdg-8-12','jdg','사사기',8,12,'세바와 살문나가 도망하는지라 기드온이 그들의 뒤를 추격하여 미디안의 두 왕 세바와 살문나를 사로잡고 그 온 진영을 격파하니라',6732),
('jdg-8-13','jdg','사사기',8,13,'요아스의 아들 기드온이 헤레스 비탈 전장에서 돌아오다가',6733),
('jdg-8-14','jdg','사사기',8,14,'숙곳 사람 중 한 소년을 잡아 그를 심문하매 그가 숙곳의 방백들과 장로들 칠십칠 명을 그에게 적어 준지라',6734),
('jdg-8-15','jdg','사사기',8,15,'기드온이 숙곳 사람들에게 이르러 말하되 너희가 전에 나를 희롱하여 이르기를 세바와 살문나의 손이 지금 네 손 안에 있다는거냐 어찌 우리가 네 피곤한 사람들에게 떡을 주겠느냐 한 그 세바와 살문나를 보라 하고',6735),
('jdg-8-16','jdg','사사기',8,16,'그 성읍의 장로들을 붙잡아 들가시와 찔레로 숙곳 사람들을 징벌하고',6736),
('jdg-8-17','jdg','사사기',8,17,'브누엘 망대를 헐며 그 성읍 사람들을 죽이니라',6737),
('jdg-8-18','jdg','사사기',8,18,'이에 그가 세바와 살문나에게 말하되 너희가 다볼에서 죽인 자들은 어떠한 사람들이더냐 하니 대답하되 그들이 너와 같아서 하나 같이 왕자들의 모습과 같더라 하니라',6738),
('jdg-8-19','jdg','사사기',8,19,'그가 이르되 그들은 내 형제들이며 내 어머니의 아들들이니라 여호와께서 살아 계심을 두고 맹세하노니 너희가 만일 그들을 살렸더라면 나도 너희를 죽이지 아니하였으리라 하고',6739),
('jdg-8-20','jdg','사사기',8,20,'그의 맏아들 여델에게 이르되 일어나 그들을 죽이라 하였으나 그 소년이 그의 칼을 빼지 못하였으니 이는 아직 어려서 두려워함이었더라',6740),
('jdg-8-21','jdg','사사기',8,21,'세바와 살문나가 이르되 네가 일어나 우리를 치라 사람이 어떠하면 그의 힘도 그러하니라 하니 기드온이 일어나 세바와 살문나를 죽이고 그들의 낙타 목에 있던 초승달 장식들을 떼어서 가지니라',6741),
('jdg-8-22','jdg','사사기',8,22,'그 때에 이스라엘 사람들이 기드온에게 이르되 당신이 우리를 미디안의 손에서 구원하셨으니 당신과 당신의 아들과 당신의 손자가 우리를 다스리소서 하는지라',6742),
('jdg-8-23','jdg','사사기',8,23,'기드온이 그들에게 이르되 내가 너희를 다스리지 아니하겠고 나의 아들도 너희를 다스리지 아니할 것이요 여호와께서 너희를 다스리시리라 하니라',6743),
('jdg-8-24','jdg','사사기',8,24,'기드온이 또 그들에게 이르되 내가 너희에게 요청할 일이 있으니 너희는 각기 탈취한 귀고리를 내게 줄지니라 하였으니 이는 그들이 이스마엘 사람들이므로 금 귀고리가 있었음이라',6744),
('jdg-8-25','jdg','사사기',8,25,'무리가 대답하되 우리가 즐거이 드리리이다 하고 겉옷을 펴고 각기 탈취한 귀고리를 그 가운데에 던지니',6745),
('jdg-8-26','jdg','사사기',8,26,'기드온이 요청한 금 귀고리의 무게가 금 천칠백 세겔이요 그 외에 또 초승달 장식들과 패물과 미디안 왕들이 입었던 자색 의복과 또 그 외에 그들의 낙타 목에 둘렀던 사슬이 있었더라',6746),
('jdg-8-27','jdg','사사기',8,27,'기드온이 그 금으로 에봇 하나를 만들어 자기의 성읍 오브라에 두었더니 온 이스라엘이 그것을 음란하게 위하므로 그것이 기드온과 그의 집에 올무가 되니라',6747),
('jdg-8-28','jdg','사사기',8,28,'미디안이 이스라엘 자손 앞에 복종하여 다시는 그 머리를 들지 못하였으므로 기드온이 사는 사십 년 동안 그 땅이 평온하였더라',6748),
('jdg-8-29','jdg','사사기',8,29,'요아스의 아들 여룹바알이 돌아가서 자기 집에 거주하였는데',6749),
('jdg-8-30','jdg','사사기',8,30,'기드온이 아내가 많으므로 그의 몸에서 낳은 아들이 칠십 명이었고',6750),
('jdg-8-31','jdg','사사기',8,31,'세겜에 있는 그의 첩도 아들을 낳았으므로 그 이름을 아비멜렉이라 하였더라',6751),
('jdg-8-32','jdg','사사기',8,32,'요아스의 아들 기드온이 나이가 많아 죽으매 아비에셀 사람의 오브라에 있는 그의 아버지 요아스의 묘실에 장사되었더라',6752),
('jdg-8-33','jdg','사사기',8,33,'기드온이 이미 죽으매 이스라엘 자손이 돌아서서 바알들을 따라가 음행하였으며 또 바알브릿을 자기들의 신으로 삼고',6753),
('jdg-8-34','jdg','사사기',8,34,'이스라엘 자손이 주위의 모든 원수들의 손에서 자기들을 건져내신 여호와 자기들의 하나님을 기억하지 아니하며',6754),
('jdg-8-35','jdg','사사기',8,35,'또 여룹바알이라 하는 기드온이 이스라엘에 베푼 모든 은혜를 따라 그의 집을 후대하지도 아니하였더라',6755),
('jdg-9-1','jdg','사사기',9,1,'여룹바알의 아들 아비멜렉이 세겜에 가서 그의 어머니의 형제에게 이르러 그들과 그의 외조부의 집의 온 가족에게 말하여 이르되',6756),
('jdg-9-2','jdg','사사기',9,2,'청하노니 너희는 세겜의 모든 사람들의 귀에 말하라 여룹바알의 아들 칠십 명이 다 너희를 다스림과 한 사람이 너희를 다스림이 어느 것이 너희에게 나으냐 또 나는 너희와 골육임을 기억하라 하니',6757),
('jdg-9-3','jdg','사사기',9,3,'그의 어머니의 형제들이 그를 위하여 이 모든 말을 세겜의 모든 사람들의 귀에 말하매 그들의 마음이 아비멜렉에게로 기울어서 이르기를 그는 우리 형제라 하고',6758),
('jdg-9-4','jdg','사사기',9,4,'바알브릿 신전에서 은 칠십 개를 내어 그에게 주매 아비멜렉이 그것으로 방탕하고 경박한 사람들을 사서 자기를 따르게 하고',6759),
('jdg-9-5','jdg','사사기',9,5,'오브라에 있는 그의 아버지의 집으로 가서 여룹바알의 아들 곧 자기 형제 칠십 명을 한 바위 위에서 죽였으되 다만 여룹바알의 막내 아들 요담은 스스로 숨었으므로 남으니라',6760),
('jdg-9-6','jdg','사사기',9,6,'세겜의 모든 사람과 밀로 모든 족속이 모여서 세겜에 있는 상수리나무 기둥 곁에서 아비멜렉을 왕으로 삼으니라',6761),
('jdg-9-7','jdg','사사기',9,7,'사람들이 요담에게 그 일을 알리매 요담이 그리심 산 꼭대기로 가서 서서 그의 목소리를 높여 그들에게 외쳐 이르되 세겜 사람들아 내 말을 들으라 그리하여야 하나님이 너희의 말을 들으시리라',6762),
('jdg-9-8','jdg','사사기',9,8,'하루는 나무들이 나가서 기름을 부어 자신들 위에 왕으로 삼으려 하여 감람나무에게 이르되 너는 우리 위에 왕이 되라 하매',6763),
('jdg-9-9','jdg','사사기',9,9,'감람나무가 그들에게 이르되 내게 있는 나의 기름은 하나님과 사람을 영화롭게 하나니 내가 어찌 그것을 버리고 가서 나무들 위에 우쭐대리요 한지라',6764),
('jdg-9-10','jdg','사사기',9,10,'나무들이 또 무화과나무에게 이르되 너는 와서 우리 위에 왕이 되라 하매',6765),
('jdg-9-11','jdg','사사기',9,11,'무화과나무가 그들에게 이르되 나의 단 것과 나의 아름다운 열매를 내가 어찌 버리고 가서 나무들 위에 우쭐대리요 한지라',6766),
('jdg-9-12','jdg','사사기',9,12,'나무들이 또 포도나무에게 이르되 너는 와서 우리 위에 왕이 되라 하매',6767),
('jdg-9-13','jdg','사사기',9,13,'포도나무가 그들에게 이르되 하나님과 사람을 기쁘게 하는 내 포도주를 내가 어찌 버리고 가서 나무들 위에 우쭐대리요 한지라',6768),
('jdg-9-14','jdg','사사기',9,14,'이에 모든 나무가 가시나무에게 이르되 너는 와서 우리 위에 왕이 되라 하매',6769),
('jdg-9-15','jdg','사사기',9,15,'가시나무가 나무들에게 이르되 만일 너희가 참으로 내게 기름을 부어 너희 위에 왕으로 삼겠거든 와서 내 그늘에 피하라 그리하지 아니하면 불이 가시나무에서 나와서 레바논의 백향목을 사를 것이니라 하였느니라',6770),
('jdg-9-16','jdg','사사기',9,16,'이제 너희가 아비멜렉을 세워 왕으로 삼았으니 너희가 행한 것이 과연 진실하고 의로우냐 이것이 여룹바알과 그의 집을 선대함이냐 이것이 그의 손이 행한 대로 그에게 보답함이냐',6771),
('jdg-9-17','jdg','사사기',9,17,'우리 아버지가 전에 죽음을 무릅쓰고 너희를 위하여 싸워 미디안의 손에서 너희를 건져냈거늘',6772),
('jdg-9-18','jdg','사사기',9,18,'너희가 오늘 일어나 우리 아버지의 집을 쳐서 그의 아들 칠십 명을 한 바위 위에서 죽이고 그의 여종의 아들 아비멜렉이 너희 형제가 된다고 그를 세워 세겜 사람들 위에 왕으로 삼았도다',6773),
('jdg-9-19','jdg','사사기',9,19,'만일 너희가 오늘 여룹바알과 그의 집을 대접한 것이 진실하고 의로운 일이면 너희가 아비멜렉으로 말미암아 기뻐할 것이요 아비멜렉도 너희로 말미암아 기뻐하려니와',6774),
('jdg-9-20','jdg','사사기',9,20,'그렇지 아니하면 아비멜렉에게서 불이 나와서 세겜 사람들과 밀로의 집을 사를 것이요 세겜 사람들과 밀로의 집에서도 불이 나와 아비멜렉을 사를 것이니라 하고',6775),
('jdg-9-21','jdg','사사기',9,21,'요담이 그의 형제 아비멜렉 앞에서 도망하여 피해서 브엘로 가서 거기에 거주하니라',6776),
('jdg-9-22','jdg','사사기',9,22,'아비멜렉이 이스라엘을 다스린 지 삼 년에',6777),
('jdg-9-23','jdg','사사기',9,23,'하나님이 아비멜렉과 세겜 사람들 사이에 악한 영을 보내시매 세겜 사람들이 아비멜렉을 배반하였으니',6778),
('jdg-9-24','jdg','사사기',9,24,'이는 여룹바알의 아들 칠십 명에게 저지른 포학한 일을 갚되 그들을 죽여 피 흘린 죄를 그들의 형제 아비멜렉과 아비멜렉의 손을 도와 그의 형제들을 죽이게 한 세겜 사람들에게로 돌아가게 하심이라',6779),
('jdg-9-25','jdg','사사기',9,25,'세겜 사람들이 산들의 꼭대기에 사람을 매복시켜 아비멜렉을 엿보게 하고 그 길로 지나는 모든 자를 다 강탈하게 하니 어떤 사람이 그것을 아비멜렉에게 알리니라',6780),
('jdg-9-26','jdg','사사기',9,26,'에벳의 아들 가알이 그의 형제와 더불어 세겜에 이르니 세겜 사람들이 그를 신뢰하니라',6781),
('jdg-9-27','jdg','사사기',9,27,'그들이 밭에 가서 포도를 거두어다가 밟아 짜서 연회를 베풀고 그들의 신당에 들어가서 먹고 마시며 아비멜렉을 저주하니',6782),
('jdg-9-28','jdg','사사기',9,28,'에벳의 아들 가알이 이르되 아비멜렉은 누구며 세겜은 누구기에 우리가 아비멜렉을 섬기리요 그가 여룹바알의 아들이 아니냐 그의 신복은 스불이 아니냐 차라리 세겜의 아버지 하몰의 후손을 섬길 것이라 우리가 어찌 아비멜렉을 섬기리요',6783),
('jdg-9-29','jdg','사사기',9,29,'이 백성이 내 수하에 있었더라면 내가 아비멜렉을 제거하였으리라 하고 아비멜렉에게 이르되 네 군대를 증원해서 나오라 하니라',6784),
('jdg-9-30','jdg','사사기',9,30,'그 성읍의 방백 스불이 에벳의 아들 가알의 말을 듣고 노하여',6785),
('jdg-9-31','jdg','사사기',9,31,'사자들을 아비멜렉에게 가만히 보내어 이르되 보소서 에벳의 아들 가알과 그의 형제들이 세겜에 이르러 그 성읍이 당신을 대적하게 하니',6786),
('jdg-9-32','jdg','사사기',9,32,'당신은 당신과 함께 있는 백성과 더불어 밤에 일어나 밭에 매복하였다가',6787),
('jdg-9-33','jdg','사사기',9,33,'아침 해 뜰 때에 당신이 일찍 일어나 이 성읍을 엄습하면 가알 및 그와 함께 있는 백성이 나와서 당신을 대적하리니 당신은 기회를 보아 그에게 행하소서 하니',6788),
('jdg-9-34','jdg','사사기',9,34,'아비멜렉과 그와 함께 있는 모든 백성이 밤에 일어나 네 떼로 나누어 세겜에 맞서 매복하였더니',6789),
('jdg-9-35','jdg','사사기',9,35,'에벳의 아들 가알이 나와서 성읍 문 입구에 설 때에 아비멜렉과 그와 함께 있는 백성이 매복하였던 곳에서 일어난지라',6790),
('jdg-9-36','jdg','사사기',9,36,'가알이 그 백성을 보고 스불에게 이르되 보라 백성이 산 꼭대기에서부터 내려오는도다 하니 스불이 그에게 이르되 네가 산 그림자를 사람으로 보았느니라 하는지라',6791),
('jdg-9-37','jdg','사사기',9,37,'가알이 다시 말하여 이르되 보라 백성이 밭 가운데를 따라 내려오고 또 한 떼는 므오느님 상수리나무 길을 따라 오는도다 하니',6792),
('jdg-9-38','jdg','사사기',9,38,'스불이 그에게 이르되 네가 전에 말하기를 아비멜렉이 누구이기에 우리가 그를 섬기리요 하던 그 입이 이제 어디 있느냐 이들이 네가 업신여기던 그 백성이 아니냐 청하노니 이제 나가서 그들과 싸우라 하니',6793),
('jdg-9-39','jdg','사사기',9,39,'가알이 세겜 사람들보다 앞에 서서 나가 아비멜렉과 싸우다가',6794),
('jdg-9-40','jdg','사사기',9,40,'아비멜렉이 그를 추격하니 그 앞에서 도망하였고 부상하여 엎드러진 자가 많아 성문 입구까지 이르렀더라',6795),
('jdg-9-41','jdg','사사기',9,41,'아비멜렉은 아루마에 거주하고 스불은 가알과 그의 형제들을 쫓아내어 세겜에 거주하지 못하게 하더니',6796),
('jdg-9-42','jdg','사사기',9,42,'이튿날 백성이 밭으로 나오매 사람들이 그것을 아비멜렉에게 알리니라',6797),
('jdg-9-43','jdg','사사기',9,43,'아비멜렉이 자기 백성을 세 무리로 나누어 밭에 매복시켰더니 백성이 성에서 나오는 것을 보고 일어나 그들을 치되',6798),
('jdg-9-44','jdg','사사기',9,44,'아비멜렉과 그 떼는 돌격하여 성문 입구에 서고 두 무리는 밭에 있는 자들에게 돌격하여 그들을 죽이니',6799),
('jdg-9-45','jdg','사사기',9,45,'아비멜렉이 그 날 종일토록 그 성을 쳐서 마침내는 점령하고 거기 있는 백성을 죽이며 그 성을 헐고 소금을 뿌리니라',6800),
('jdg-9-46','jdg','사사기',9,46,'세겜 망대의 모든 사람들이 이를 듣고 엘브릿 신전의 보루로 들어갔더니',6801),
('jdg-9-47','jdg','사사기',9,47,'세겜 망대의 모든 사람들이 모인 것이 아비멜렉에게 알려지매',6802),
('jdg-9-48','jdg','사사기',9,48,'아비멜렉 및 그와 함께 있는 모든 백성이 살몬 산에 오르고 아비멜렉이 손에 도끼를 들고 나뭇가지를 찍어 그것을 들어올려 자기 어깨에 메고 그와 함께 있는 백성에게 이르되 너희는 내가 행하는 것을 보나니 빨리 나와 같이 행하라 하니',6803),
('jdg-9-49','jdg','사사기',9,49,'모든 백성들도 각각 나뭇가지를 찍어서 아비멜렉을 따라 보루 위에 놓고 그것들이 얹혀 있는 보루에 불을 놓으매 세겜 망대에 있는 사람들이 다 죽었으니 남녀가 약 천 명이었더라',6804),
('jdg-9-50','jdg','사사기',9,50,'아비멜렉이 데베스에 가서 데베스에 맞서 진 치고 그것을 점령하였더니',6805),
('jdg-9-51','jdg','사사기',9,51,'성읍 중에 견고한 망대가 있으므로 그 성읍 백성의 남녀가 모두 그리로 도망하여 들어가서 문을 잠그고 망대 꼭대기로 올라간지라',6806),
('jdg-9-52','jdg','사사기',9,52,'아비멜렉이 망대 앞에 이르러 공격하며 망대의 문에 가까이 나아가서 그것을 불사르려 하더니',6807),
('jdg-9-53','jdg','사사기',9,53,'한 여인이 맷돌 위짝을 아비멜렉의 머리 위에 내려 던져 그의 두개골을 깨뜨리니',6808),
('jdg-9-54','jdg','사사기',9,54,'아비멜렉이 자기의 무기를 든 청년을 급히 불러 그에게 이르되 너는 칼을 빼어 나를 죽이라 사람들이 나를 가리켜 이르기를 여자가 그를 죽였다 할까 하노라 하니 그 청년이 그를 찌르매 그가 죽은지라',6809),
('jdg-9-55','jdg','사사기',9,55,'이스라엘 사람들이 아비멜렉이 죽은 것을 보고 각각 자기 처소로 떠나갔더라',6810),
('jdg-9-56','jdg','사사기',9,56,'아비멜렉이 그의 형제 칠십 명을 죽여 자기 아버지에게 행한 악행을 하나님이 이같이 갚으셨고',6811),
('jdg-9-57','jdg','사사기',9,57,'또 세겜 사람들의 모든 악행을 하나님이 그들의 머리에 갚으셨으니 여룹바알의 아들 요담의 저주가 그들에게 응하니라',6812),
('jdg-10-1','jdg','사사기',10,1,'아비멜렉의 뒤를 이어서 잇사갈 사람 도도의 손자 부아의 아들 돌라가 일어나서 이스라엘을 구원하니라 그가 에브라임 산지 사밀에 거주하면서',6813),
('jdg-10-2','jdg','사사기',10,2,'이스라엘의 사사가 된 지 이십삼 년 만에 죽으매 사밀에 장사되었더라',6814),
('jdg-10-3','jdg','사사기',10,3,'그 후에 길르앗 사람 야일이 일어나서 이십이 년 동안 이스라엘의 사사가 되니라',6815),
('jdg-10-4','jdg','사사기',10,4,'그에게 아들 삼십 명이 있어 어린 나귀 삼십을 탔고 성읍 삼십을 가졌는데 그 성읍들은 길르앗 땅에 있고 오늘까지 하봇야일이라 부르더라',6816),
('jdg-10-5','jdg','사사기',10,5,'야일이 죽으매 가몬에 장사되었더라',6817),
('jdg-10-6','jdg','사사기',10,6,'이스라엘 자손이 다시 여호와의 목전에 악을 행하여 바알들과 아스다롯과 아람의 신들과 시돈의 신들과 모압의 신들과 암몬 자손의 신들과 블레셋 사람들의 신들을 섬기고 여호와를 버리고 그를 섬기지 아니하므로',6818),
('jdg-10-7','jdg','사사기',10,7,'여호와께서 이스라엘에게 진노하사 블레셋 사람들의 손과 암몬 자손의 손에 그들을 파시매',6819),
('jdg-10-8','jdg','사사기',10,8,'그 해에 그들이 요단 강 저쪽 길르앗에 있는 아모리 족속의 땅에 있는 모든 이스라엘 자손을 쳤으며 열여덟 해 동안 억압하였더라',6820),
('jdg-10-9','jdg','사사기',10,9,'암몬 자손이 또 요단을 건너서 유다와 베냐민과 에브라임 족속과 싸우므로 이스라엘의 곤고가 심하였더라',6821),
('jdg-10-10','jdg','사사기',10,10,'이스라엘 자손이 여호와께 부르짖어 이르되 우리가 우리 하나님을 버리고 바알들을 섬김으로 주께 범죄하였나이다 하니',6822),
('jdg-10-11','jdg','사사기',10,11,'여호와께서 이스라엘 자손에게 이르시되 내가 애굽 사람과 아모리 사람과 암몬 자손과 블레셋 사람에게서 너희를 구원하지 아니하였느냐',6823),
('jdg-10-12','jdg','사사기',10,12,'또 시돈 사람과 아말렉 사람과 마온 사람이 너희를 압제할 때에 너희가 내게 부르짖으므로 내가 너희를 그들의 손에서 구원하였거늘',6824),
('jdg-10-13','jdg','사사기',10,13,'너희가 나를 버리고 다른 신들을 섬기니 그러므로 내가 다시는 너희를 구원하지 아니하리라',6825),
('jdg-10-14','jdg','사사기',10,14,'가서 너희가 택한 신들에게 부르짖어 너희의 환난 때에 그들이 너희를 구원하게 하라 하신지라',6826),
('jdg-10-15','jdg','사사기',10,15,'이스라엘 자손이 여호와께 여쭈되 우리가 범죄하였사오니 주께서 보시기에 좋은 대로 우리에게 행하시려니와 오직 주께 구하옵나니 오늘 우리를 건져내옵소서 하고',6827),
('jdg-10-16','jdg','사사기',10,16,'자기 가운데에서 이방 신들을 제하여 버리고 여호와를 섬기매 여호와께서 이스라엘의 곤고로 말미암아 마음에 근심하시니라',6828),
('jdg-10-17','jdg','사사기',10,17,'그 때에 암몬 자손이 모여서 길르앗에 진을 쳤으므로 이스라엘 자손도 모여서 미스바에 진을 치고',6829),
('jdg-10-18','jdg','사사기',10,18,'길르앗 백성과 방백들이 서로 이르되 누가 먼저 나가서 암몬 자손과 싸움을 시작하랴 그가 길르앗 모든 주민의 머리가 되리라 하니라',6830),
('jdg-11-1','jdg','사사기',11,1,'길르앗 사람 입다는 큰 용사였으니 기생이 길르앗에게서 낳은 아들이었고',6831),
('jdg-11-2','jdg','사사기',11,2,'길르앗의 아내도 그의 아들들을 낳았더라 그 아내의 아들들이 자라매 입다를 쫓아내며 그에게 이르되 너는 다른 여인의 자식이니 우리 아버지의 집에서 기업을 잇지 못하리라 한지라',6832),
('jdg-11-3','jdg','사사기',11,3,'이에 입다가 그의 형제들을 피하여 돕 땅에 거주하매 잡류가 그에게로 모여 와서 그와 함께 출입하였더라',6833),
('jdg-11-4','jdg','사사기',11,4,'얼마 후에 암몬 자손이 이스라엘을 치려 하니라',6834),
('jdg-11-5','jdg','사사기',11,5,'암몬 자손이 이스라엘을 치려 할 때에 길르앗 장로들이 입다를 데려오려고 돕 땅에 가서',6835),
('jdg-11-6','jdg','사사기',11,6,'입다에게 이르되 우리가 암몬 자손과 싸우려 하니 당신은 와서 우리의 장관이 되라 하니',6836),
('jdg-11-7','jdg','사사기',11,7,'입다가 길르앗 장로들에게 이르되 너희가 전에 나를 미워하여 내 아버지 집에서 쫓아내지 아니하였느냐 이제 너희가 환난을 당하였다고 어찌하여 내게 왔느냐 하니라',6837),
('jdg-11-8','jdg','사사기',11,8,'그러므로 길르앗 장로들이 입다에게 이르되 이제 우리가 당신을 찾아온 것은 우리와 함께 가서 암몬 자손과 싸우게 하려 함이니 그리하면 당신이 우리 길르앗 모든 주민의 머리가 되리라 하매',6838),
('jdg-11-9','jdg','사사기',11,9,'입다가 길르앗 장로들에게 이르되 너희가 나를 데리고 고향으로 돌아가서 암몬 자손과 싸우게 할 때에 만일 여호와께서 그들을 내게 넘겨 주시면 내가 과연 너희의 머리가 되겠느냐 하니',6839),
('jdg-11-10','jdg','사사기',11,10,'길르앗 장로들이 입다에게 이르되 여호와는 우리 사이의 증인이시니 당신의 말대로 우리가 그렇게 행하리이다 하니라',6840),
('jdg-11-11','jdg','사사기',11,11,'이에 입다가 길르앗 장로들과 함께 가니 백성이 그를 자기들의 머리와 장관을 삼은지라 입다가 미스바에서 자기의 말을 다 여호와 앞에 아뢰니라',6841),
('jdg-11-12','jdg','사사기',11,12,'입다가 암몬 자손의 왕에게 사자들을 보내 이르되 네가 나와 무슨 상관이 있기에 내 땅을 치러 내게 왔느냐 하니',6842),
('jdg-11-13','jdg','사사기',11,13,'암몬 자손의 왕이 입다의 사자들에게 대답하되 이스라엘이 애굽에서 올라올 때에 아르논에서부터 얍복과 요단까지 내 땅을 점령했기 때문이니 이제 그것을 평화롭게 돌려 달라 하니라',6843),
('jdg-11-14','jdg','사사기',11,14,'입다가 암몬 자손의 왕에게 다시 사자들을 보내',6844),
('jdg-11-15','jdg','사사기',11,15,'그에게 이르되 입다가 이같이 말하노라 이스라엘이 모압 땅과 암몬 자손의 땅을 점령하지 아니하였느니라',6845),
('jdg-11-16','jdg','사사기',11,16,'이스라엘이 애굽에서 올라올 때에 광야로 행하여 홍해에 이르고 가데스에 이르러서는',6846),
('jdg-11-17','jdg','사사기',11,17,'이스라엘이 사자들을 에돔 왕에게 보내어 이르기를 청하건대 나를 네 땅 가운데로 지나게 하라 하였으나 에돔 왕이 이를 듣지 아니하였고 또 그와 같이 사람을 모압 왕에게도 보냈으나 그도 허락하지 아니하므로 이스라엘이 가데스에 머물렀더니',6847),
('jdg-11-18','jdg','사사기',11,18,'그 후에 광야를 지나 에돔 땅과 모압 땅을 돌아서 모압 땅의 해 뜨는 쪽으로 들어가 아르논 저쪽에 진 쳤고 아르논은 모압의 경계이므로 모압 지역 안에는 들어가지 아니하였으며',6848),
('jdg-11-19','jdg','사사기',11,19,'이스라엘이 헤스본 왕 곧 아모리 족속의 왕 시혼에게 사자들을 보내어 그에게 이르되 청하건대 우리를 당신의 땅으로 지나 우리의 곳에 이르게 하라 하였으나',6849),
('jdg-11-20','jdg','사사기',11,20,'시혼이 이스라엘을 믿지 아니하여 그의 지역으로 지나지 못하게 할 뿐 아니라 그의 모든 백성을 모아 야하스에 진 치고 이스라엘을 치므로',6850),
('jdg-11-21','jdg','사사기',11,21,'이스라엘의 하나님 여호와께서 시혼과 그의 모든 백성을 이스라엘의 손에 넘겨 주시매 이스라엘이 그들을 쳐서 그 땅 주민 아모리 족속의 온 땅을 점령하되',6851),
('jdg-11-22','jdg','사사기',11,22,'아르논에서부터 얍복까지와 광야에서부터 요단까지 아모리 족속의 온 지역을 점령하였느니라',6852),
('jdg-11-23','jdg','사사기',11,23,'이스라엘의 하나님 여호와께서 이같이 아모리 족속을 자기 백성 이스라엘 앞에서 쫓아내셨거늘 네가 그 땅을 얻고자 하는 것이 옳으냐',6853),
('jdg-11-24','jdg','사사기',11,24,'네 신 그모스가 네게 주어 차지하게 한 것을 네가 차지하지 아니하겠느냐 우리 하나님 여호와께서 우리 앞에서 어떤 사람이든지 쫓아내시면 그것을 우리가 차지하리라',6854),
('jdg-11-25','jdg','사사기',11,25,'이제 네가 모압 왕 십볼의 아들 발락보다 더 나은 것이 있느냐 그가 이스라엘과 더불어 다툰 일이 있었느냐 싸운 일이 있었느냐',6855),
('jdg-11-26','jdg','사사기',11,26,'이스라엘이 헤스본과 그 마을들과 아로엘과 그 마을들과 아르논 강 가에 있는 모든 성읍에 거주한 지 삼백 년이거늘 그 동안에 너희가 어찌하여 도로 찾지 아니하였느냐',6856),
('jdg-11-27','jdg','사사기',11,27,'내가 네게 죄를 짓지 아니하였거늘 네가 나를 쳐서 내게 악을 행하고자 하는도다 원하건대 심판하시는 여호와께서 오늘 이스라엘 자손과 암몬 자손 사이에 판결하시옵소서 하였으나',6857),
('jdg-11-28','jdg','사사기',11,28,'암몬 자손의 왕이 입다가 사람을 보내어 말한 것을 듣지 아니하였더라',6858),
('jdg-11-29','jdg','사사기',11,29,'이에 여호와의 영이 입다에게 임하시니 입다가 길르앗과 므낫세를 지나서 길르앗의 미스베에 이르고 길르앗의 미스베에서부터 암몬 자손에게로 나아갈 때에',6859),
('jdg-11-30','jdg','사사기',11,30,'그가 여호와께 서원하여 이르되 주께서 과연 암몬 자손을 내 손에 넘겨 주시면',6860),
('jdg-11-31','jdg','사사기',11,31,'내가 암몬 자손에게서 평안히 돌아올 때에 누구든지 내 집 문에서 나와서 나를 영접하는 그는 여호와께 돌릴 것이니 내가 그를 번제물로 드리겠나이다 하니라',6861),
('jdg-11-32','jdg','사사기',11,32,'이에 입다가 암몬 자손에게 이르러 그들과 싸우더니 여호와께서 그들을 그의 손에 넘겨 주시매',6862),
('jdg-11-33','jdg','사사기',11,33,'아로엘에서부터 민닛에 이르기까지 이십 성읍을 치고 또 아벨 그라밈까지 매우 크게 무찌르니 이에 암몬 자손이 이스라엘 자손 앞에 항복하였더라',6863),
('jdg-11-34','jdg','사사기',11,34,'입다가 미스바에 있는 자기 집에 이를 때에 보라 그의 딸이 소고를 잡고 춤추며 나와서 영접하니 이는 그의 무남독녀라',6864),
('jdg-11-35','jdg','사사기',11,35,'입다가 이를 보고 자기 옷을 찢으며 이르되 어찌할꼬 내 딸이여 너는 나를 참담하게 하는 자요 너는 나를 괴롭게 하는 자 중의 하나로다 내가 여호와를 향하여 입을 열었으니 능히 돌이키지 못하리로다 하니',6865),
('jdg-11-36','jdg','사사기',11,36,'딸이 그에게 이르되 나의 아버지여 아버지께서 여호와를 향하여 입을 여셨으니 아버지의 입에서 낸 말씀대로 내게 행하소서 이는 여호와께서 아버지를 위하여 아버지의 대적 암몬 자손에게 원수를 갚으셨음이니이다 하니라',6866),
('jdg-11-37','jdg','사사기',11,37,'또 그의 아버지에게 이르되 이 일만 내게 허락하사 나를 두 달만 버려 두소서 내가 내 여자 친구들과 산에 가서 나의 처녀로 죽음을 인하여 애곡하겠나이다 하니',6867),
('jdg-11-38','jdg','사사기',11,38,'그가 이르되 가라 하고 두 달을 기한하고 그를 보내니 그가 그 여자 친구들과 가서 산 위에서 처녀로 죽음을 인하여 애곡하고',6868),
('jdg-11-39','jdg','사사기',11,39,'두 달 만에 그의 아버지에게로 돌아온지라 그는 자기가 서원한 대로 딸에게 행하니 딸이 남자를 알지 못하였더라 이것이 이스라엘에 관습이 되어',6869),
('jdg-11-40','jdg','사사기',11,40,'이스라엘의 딸들이 해마다 가서 길르앗 사람 입다의 딸을 위하여 나흘씩 애곡하더라',6870),
('jdg-12-1','jdg','사사기',12,1,'에브라임 사람들이 모여 북쪽으로 가서 입다에게 이르되 네가 암몬 자손과 싸우러 건너갈 때에 어찌하여 우리를 불러 너와 함께 가게 하지 아니하였느냐 우리가 반드시 너와 네 집을 불사르리라 하니',6871),
('jdg-12-2','jdg','사사기',12,2,'입다가 그들에게 이르되 나와 내 백성이 암몬 자손과 크게 싸울 때에 내가 너희를 부르되 너희가 나를 그들의 손에서 구원하지 아니한 고로',6872),
('jdg-12-3','jdg','사사기',12,3,'나는 너희가 도와 주지 아니하는 것을 보고 내 목숨을 돌보지 아니하고 건너가서 암몬 자손을 쳤더니 여호와께서 그들을 내 손에 넘겨 주셨거늘 너희가 어찌하여 오늘 내게 올라와서 나와 더불어 싸우고자 하느냐 하니라',6873),
('jdg-12-4','jdg','사사기',12,4,'입다가 길르앗 사람을 다 모으고 에브라임과 싸웠으며 길르앗 사람들이 에브라임을 쳐서 무찔렀으니 이는 에브라임의 말이 너희 길르앗 사람은 본래 에브라임에서 도망한 자로서 에브라임과 므낫세 중에 있다 하였음이라',6874),
('jdg-12-5','jdg','사사기',12,5,'길르앗 사람이 에브라임 사람보다 앞서 요단 강 나루턱을 장악하고 에브라임 사람의 도망하는 자가 말하기를 청하건대 나를 건너가게 하라 하면 길르앗 사람이 그에게 묻기를 네가 에브라임 사람이냐 하여 그가 만일 아니라 하면',6875),
('jdg-12-6','jdg','사사기',12,6,'그에게 이르기를 쉽볼렛이라 발음하라 하여 에브라임 사람이 그렇게 바로 말하지 못하고 십볼렛이라 발음하면 길르앗 사람이 곧 그를 잡아서 요단 강 나루턱에서 죽였더라 그 때에 에브라임 사람의 죽은 자가 사만 이천 명이었더라',6876),
('jdg-12-7','jdg','사사기',12,7,'입다가 이스라엘의 사사가 된 지 육 년이라 길르앗 사람 입다가 죽으매 길르앗에 있는 그의 성읍에 장사되었더라',6877),
('jdg-12-8','jdg','사사기',12,8,'그 뒤를 이어 베들레헴의 입산이 이스라엘의 사사가 되었더라',6878),
('jdg-12-9','jdg','사사기',12,9,'그가 아들 삼십 명과 딸 삼십 명을 두었더니 그가 딸들을 밖으로 시집 보냈고 아들들을 위하여는 밖에서 여자 삼십 명을 데려왔더라 그가 이스라엘의 사사가 된 지 칠 년이라',6879),
('jdg-12-10','jdg','사사기',12,10,'입산이 죽으매 베들레헴에 장사되었더라',6880),
('jdg-12-11','jdg','사사기',12,11,'그 뒤를 이어 스불론 사람 엘론이 이스라엘의 사사가 되어 십 년 동안 이스라엘을 다스렸더라',6881),
('jdg-12-12','jdg','사사기',12,12,'스불론 사람 엘론이 죽으매 스불론 땅 아얄론에 장사되었더라',6882),
('jdg-12-13','jdg','사사기',12,13,'그 뒤를 이어 비라돈 사람 힐렐의 아들 압돈이 이스라엘의 사사가 되었더라',6883),
('jdg-12-14','jdg','사사기',12,14,'그에게 아들 사십 명과 손자 삼십 명이 있어 어린 나귀 칠십 마리를 탔더라 압돈이 이스라엘의 사사가 된 지 팔 년이라',6884),
('jdg-12-15','jdg','사사기',12,15,'비라돈 사람 힐렐의 아들 압돈이 죽으매 에브라임 땅 아말렉 사람의 산지 비라돈에 장사되었더라',6885),
('jdg-13-1','jdg','사사기',13,1,'이스라엘 자손이 다시 여호와의 목전에 악을 행하였으므로 여호와께서 그들을 사십 년 동안 블레셋 사람의 손에 넘겨 주시니라',6886),
('jdg-13-2','jdg','사사기',13,2,'소라 땅에 단 지파의 가족 중에 마노아라 이름하는 자가 있더라 그의 아내가 임신하지 못하므로 출산하지 못하더니',6887),
('jdg-13-3','jdg','사사기',13,3,'여호와의 사자가 그 여인에게 나타나서 그에게 이르시되 보라 네가 본래 임신하지 못하므로 출산하지 못하였으나 이제 임신하여 아들을 낳으리니',6888),
('jdg-13-4','jdg','사사기',13,4,'그러므로 너는 삼가 포도주와 독주를 마시지 말며 어떤 부정한 것도 먹지 말지니라',6889),
('jdg-13-5','jdg','사사기',13,5,'보라 네가 임신하여 아들을 낳으리니 그의 머리 위에 삭도를 대지 말라 이 아이는 태에서 나옴으로부터 하나님께 바쳐진 나실인이 됨이라 그가 블레셋 사람의 손에서 이스라엘을 구원하기 시작하리라 하시니',6890),
('jdg-13-6','jdg','사사기',13,6,'이에 그 여인이 가서 그의 남편에게 말하여 이르되 하나님의 사람이 내게 오셨는데 그의 모습이 하나님의 사자의 용모 같아서 심히 두려우므로 어디서부터 왔는지를 내가 묻지 못하였고 그도 자기 이름을 내게 이르지 아니하였으며',6891),
('jdg-13-7','jdg','사사기',13,7,'그가 내게 이르기를 보라 네가 임신하여 아들을 낳으리니 이제 포도주와 독주를 마시지 말며 어떤 부정한 것도 먹지 말라 이 아이는 태에서부터 그가 죽는 날까지 하나님께 바쳐진 나실인이 됨이라 하더이다 하니라',6892),
('jdg-13-8','jdg','사사기',13,8,'마노아가 여호와께 기도하여 이르되 주여 구하옵나니 주께서 보내셨던 하나님의 사람을 우리에게 다시 오게 하사 우리가 그 낳을 아이에게 어떻게 행할지를 우리에게 가르치게 하소서 하니',6893),
('jdg-13-9','jdg','사사기',13,9,'하나님이 마노아의 목소리를 들으시니라 여인이 밭에 앉았을 때에 하나님의 사자가 다시 그에게 임하였으나 그의 남편 마노아는 함께 있지 아니한지라',6894),
('jdg-13-10','jdg','사사기',13,10,'여인이 급히 달려가서 그의 남편에게 알리어 이르되 보소서 전일에 내게 오셨던 그 사람이 내게 나타났나이다 하매',6895),
('jdg-13-11','jdg','사사기',13,11,'마노아가 일어나 아내를 따라가서 그 사람에게 이르러 그에게 묻되 당신이 이 여인에게 말씀하신 그 사람이니이까 하니 이르되 내가 그로다 하니라',6896),
('jdg-13-12','jdg','사사기',13,12,'마노아가 이르되 이제 당신의 말씀대로 되기를 원하나이다 이 아이를 어떻게 기르며 우리가 그에게 어떻게 행하리이까',6897),
('jdg-13-13','jdg','사사기',13,13,'여호와의 사자가 마노아에게 이르되 내가 여인에게 말한 것들을 그가 다 삼가서',6898),
('jdg-13-14','jdg','사사기',13,14,'포도나무의 소산을 먹지 말며 포도주와 독주를 마시지 말며 어떤 부정한 것도 먹지 말고 내가 그에게 명령한 것은 다 지킬 것이니라 하니라',6899),
('jdg-13-15','jdg','사사기',13,15,'마노아가 여호와의 사자에게 말하되 구하옵나니 당신은 우리에게 머물러서 우리가 당신을 위하여 염소 새끼 하나를 준비하게 하소서 하니',6900),
('jdg-13-16','jdg','사사기',13,16,'여호와의 사자가 마노아에게 이르되 네가 비록 나를 머물게 하나 내가 네 음식을 먹지 아니하리라 번제를 준비하려거든 마땅히 여호와께 드릴지니라 하니 이는 그가 여호와의 사자인 줄을 마노아가 알지 못함이었더라',6901),
('jdg-13-17','jdg','사사기',13,17,'마노아가 또 여호와의 사자에게 말하되 당신의 이름이 무엇이니이까 당신의 말씀이 이루어질 때에 우리가 당신을 존귀히 여기리이다 하니',6902),
('jdg-13-18','jdg','사사기',13,18,'여호와의 사자가 그에게 이르되 어찌하여 내 이름을 묻느냐 내 이름은 기묘자라 하니라',6903),
('jdg-13-19','jdg','사사기',13,19,'이에 마노아가 염소 새끼와 소제물을 가져다가 바위 위에서 여호와께 드리매 이적이 일어난지라 마노아와 그의 아내가 본즉',6904),
('jdg-13-20','jdg','사사기',13,20,'불꽃이 제단에서부터 하늘로 올라가는 동시에 여호와의 사자가 제단 불꽃에 휩싸여 올라간지라 마노아와 그의 아내가 그것을 보고 그들의 얼굴을 땅에 대고 엎드리니라',6905),
('jdg-13-21','jdg','사사기',13,21,'여호와의 사자가 마노아와 그의 아내에게 다시 나타나지 아니하니 마노아가 그제야 그가 여호와의 사자인 줄 알고',6906),
('jdg-13-22','jdg','사사기',13,22,'그의 아내에게 이르되 우리가 하나님을 보았으니 반드시 죽으리로다 하니',6907),
('jdg-13-23','jdg','사사기',13,23,'그의 아내가 그에게 이르되 여호와께서 우리를 죽이려 하셨더라면 우리 손에서 번제와 소제를 받지 아니하셨을 것이요 이 모든 일을 보이지 아니하셨을 것이며 이제 이런 말씀도 우리에게 이르지 아니하셨으리이다 하였더라',6908),
('jdg-13-24','jdg','사사기',13,24,'그 여인이 아들을 낳으매 그의 이름을 삼손이라 하니라 그 아이가 자라매 여호와께서 그에게 복을 주시더니',6909),
('jdg-13-25','jdg','사사기',13,25,'소라와 에스다올 사이 마하네단에서 여호와의 영이 그를 움직이기 시작하셨더라',6910),
('jdg-14-1','jdg','사사기',14,1,'삼손이 딤나에 내려가서 거기서 블레셋 사람의 딸들 중에서 한 여자를 보고',6911),
('jdg-14-2','jdg','사사기',14,2,'올라와서 자기 부모에게 말하여 이르되 내가 딤나에서 블레셋 사람의 딸들 중에서 한 여자를 보았사오니 이제 그를 맞이하여 내 아내로 삼게 하소서 하매',6912),
('jdg-14-3','jdg','사사기',14,3,'그의 부모가 그에게 이르되 네 형제들의 딸들 중에나 내 백성 중에 어찌 여자가 없어서 네가 할례 받지 아니한 블레셋 사람에게 가서 아내를 맞으려 하느냐 하니 삼손이 그의 아버지에게 이르되 내가 그 여자를 좋아하오니 나를 위하여 그 여자를 데려오소서 하니라',6913),
('jdg-14-4','jdg','사사기',14,4,'그 때에 블레셋 사람이 이스라엘을 다스린 까닭에 삼손이 틈을 타서 블레셋 사람을 치려 함이었으나 그의 부모는 이 일이 여호와께로부터 나온 것인 줄은 알지 못하였더라',6914),
('jdg-14-5','jdg','사사기',14,5,'삼손이 그의 부모와 함께 딤나에 내려가 딤나의 포도원에 이른즉 젊은 사자가 그를 보고 소리 지르는지라',6915),
('jdg-14-6','jdg','사사기',14,6,'여호와의 영이 삼손에게 강하게 임하니 그가 손에 아무것도 없이 그 사자를 염소 새끼를 찢는 것 같이 찢었으나 그는 자기가 행한 일을 부모에게 알리지 아니하였더라',6916),
('jdg-14-7','jdg','사사기',14,7,'그가 내려가서 그 여자와 말하니 그 여자가 삼손의 눈에 들었더라',6917),
('jdg-14-8','jdg','사사기',14,8,'얼마 후에 삼손이 그 여자를 맞이하려고 다시 가다가 돌이켜 그 사자의 주검을 본즉 사자의 몸에 벌 떼와 꿀이 있는지라',6918),
('jdg-14-9','jdg','사사기',14,9,'손으로 그 꿀을 떠서 걸어가며 먹고 그의 부모에게 이르러 그들에게 그것을 드려서 먹게 하였으나 그 꿀을 사자의 몸에서 떠왔다고는 알리지 아니하였더라',6919),
('jdg-14-10','jdg','사사기',14,10,'삼손의 아버지가 여자에게로 내려가매 삼손이 거기서 잔치를 베풀었으니 청년들은 이렇게 행하는 풍속이 있음이더라',6920),
('jdg-14-11','jdg','사사기',14,11,'무리가 삼손을 보고 삼십 명을 데려와서 친구를 삼아 그와 함께 하게 한지라',6921),
('jdg-14-12','jdg','사사기',14,12,'삼손이 그들에게 이르되 이제 내가 너희에게 수수께끼를 내리니 잔치하는 이레 동안에 너희가 그것을 풀어 내게 말하면 내가 베옷 삼십 벌과 겉옷 삼십 벌을 너희에게 주리라',6922),
('jdg-14-13','jdg','사사기',14,13,'그러나 그것을 능히 내게 말하지 못하면 너희가 내게 베옷 삼십 벌과 겉옷 삼십 벌을 줄지니라 하니 그들이 이르되 네가 수수께끼를 내면 우리가 그것을 들으리라 하매',6923),
('jdg-14-14','jdg','사사기',14,14,'삼손이 그들에게 이르되 먹는 자에게서 먹는 것이 나오고 강한 자에게서 단 것이 나왔느니라 하니라 그들이 사흘이 되도록 수수께끼를 풀지 못하였더라',6924),
('jdg-14-15','jdg','사사기',14,15,'일곱째 날에 이르러 그들이 삼손의 아내에게 이르되 너는 네 남편을 꾀어 그 수수께끼를 우리에게 알려 달라 하라 그렇지 아니하면 너와 네 아버지의 집을 불사르리라 너희가 우리의 소유를 빼앗고자 하여 우리를 청한 것이 아니냐 그렇지 아니하냐 하니',6925),
('jdg-14-16','jdg','사사기',14,16,'삼손의 아내가 그의 앞에서 울며 이르되 당신이 나를 미워할 뿐이요 사랑하지 아니하는도다 우리 민족에게 수수께끼를 말하고 그 뜻을 내게 알려 주지 아니하도다 하는지라 삼손이 그에게 이르되 보라 내가 그것을 나의 부모에게도 알려 주지 아니하였거든 어찌 그대에게 알게 하리요 하였으나',6926),
('jdg-14-17','jdg','사사기',14,17,'칠 일 동안 그들이 잔치할 때 그의 아내가 그 앞에서 울며 그에게 강요함으로 일곱째 날에는 그가 그의 아내에게 수수께끼를 알려 주매 그의 아내가 그것을 자기 백성들에게 알려 주었더라',6927),
('jdg-14-18','jdg','사사기',14,18,'일곱째 날 해 지기 전에 성읍 사람들이 삼손에게 이르되 무엇이 꿀보다 달겠으며 무엇이 사자보다 강하겠느냐 한지라 삼손이 그들에게 이르되 너희가 내 암송아지로 밭 갈지 아니하였더라면 내 수수께끼를 능히 풀지 못하였으리라 하니라',6928),
('jdg-14-19','jdg','사사기',14,19,'여호와의 영이 삼손에게 갑자기 임하시매 삼손이 아스글론에 내려가서 그 곳 사람 삼십 명을 쳐죽이고 노략하여 수수께끼 푼 자들에게 옷을 주고 심히 노하여 그의 아버지의 집으로 올라갔고',6929),
('jdg-14-20','jdg','사사기',14,20,'삼손의 아내는 삼손의 친구였던 그의 친구에게 준 바 되었더라',6930),
('jdg-15-1','jdg','사사기',15,1,'얼마 후 밀 거둘 때에 삼손이 염소 새끼를 가지고 그의 아내에게로 찾아 가서 이르되 내가 방에 들어가 내 아내를 보고자 하노라 하니 장인이 들어오지 못하게 하고',6931),
('jdg-15-2','jdg','사사기',15,2,'이르되 네가 그를 심히 미워하는 줄 알고 그를 네 친구에게 주었노라 그의 동생이 그보다 더 아름답지 아니하냐 청하노니 너는 그를 대신하여 동생을 아내로 맞이하라 하니',6932),
('jdg-15-3','jdg','사사기',15,3,'삼손이 그들에게 이르되 이번은 내가 블레셋 사람들을 해할지라도 그들에게 대하여 내게 허물이 없을 것이니라 하고',6933),
('jdg-15-4','jdg','사사기',15,4,'삼손이 가서 여우 삼백 마리를 붙들어서 그 꼬리와 꼬리를 매고 홰를 가지고 그 두 꼬리 사이에 한 홰를 달고',6934),
('jdg-15-5','jdg','사사기',15,5,'홰에 불을 붙이고 그것을 블레셋 사람들의 곡식 밭으로 몰아 들여서 곡식 단과 아직 베지 아니한 곡식과 포도원과 감람나무들을 사른지라',6935),
('jdg-15-6','jdg','사사기',15,6,'블레셋 사람들이 이르되 누가 이 일을 행하였느냐 하니 사람들이 대답하되 딤나 사람의 사위 삼손이니 장인이 삼손의 아내를 빼앗아 그의 친구에게 준 까닭이라 하였더라 블레셋 사람들이 올라가서 그 여인과 그의 아버지를 불사르니라',6936),
('jdg-15-7','jdg','사사기',15,7,'삼손이 그들에게 이르되 너희가 이같이 행하였은즉 내가 너희에게 원수를 갚고야 말리라 하고',6937),
('jdg-15-8','jdg','사사기',15,8,'블레셋 사람들의 정강이와 넓적다리를 크게 쳐서 죽이고 내려가서 에담 바위 틈에 머물렀더라',6938),
('jdg-15-9','jdg','사사기',15,9,'이에 블레셋 사람들이 올라와 유다에 진을 치고 레히에 가득한지라',6939),
('jdg-15-10','jdg','사사기',15,10,'유다 사람들이 이르되 너희가 어찌하여 올라와서 우리를 치느냐 그들이 대답하되 우리가 올라온 것은 삼손을 결박하여 그가 우리에게 행한 대로 그에게 행하려 함이로라 하는지라',6940),
('jdg-15-11','jdg','사사기',15,11,'유다 사람 삼천 명이 에담 바위 틈에 내려가서 삼손에게 이르되 너는 블레셋 사람이 우리를 다스리는 줄을 알지 못하느냐 네가 어찌하여 우리에게 이같이 행하였느냐 하니 삼손이 그들에게 이르되 그들이 내게 행한 대로 나도 그들에게 행하였노라 하니라',6941),
('jdg-15-12','jdg','사사기',15,12,'그들이 삼손에게 이르되 우리가 너를 결박하여 블레셋 사람의 손에 넘겨 주려고 내려왔노라 하니 삼손이 그들에게 이르되 너희가 나를 치지 아니하겠다고 내게 맹세하라 하매',6942),
('jdg-15-13','jdg','사사기',15,13,'그들이 삼손에게 말하여 이르되 아니라 우리가 다만 너를 단단히 결박하여 그들의 손에 넘겨 줄 뿐이요 우리가 결단코 너를 죽이지 아니하리라 하고 새 밧줄 둘로 결박하고 바위 틈에서 그를 끌어내니라',6943),
('jdg-15-14','jdg','사사기',15,14,'삼손이 레히에 이르매 블레셋 사람들이 그에게로 마주 나가며 소리 지를 때 여호와의 영이 삼손에게 갑자기 임하시매 그의 팔 위의 밧줄이 불탄 삼과 같이 그의 결박되었던 손에서 떨어진지라',6944),
('jdg-15-15','jdg','사사기',15,15,'삼손이 나귀의 새 턱뼈를 보고 손을 내밀어 집어들고 그것으로 천 명을 죽이고',6945),
('jdg-15-16','jdg','사사기',15,16,'이르되 나귀의 턱뼈로 한 더미, 두 더미를 쌓았음이여 나귀의 턱뼈로 내가 천 명을 죽였도다 하니라',6946),
('jdg-15-17','jdg','사사기',15,17,'그가 말을 마치고 턱뼈를 자기 손에서 내던지고 그 곳을 라맛 레히라 이름하였더라',6947),
('jdg-15-18','jdg','사사기',15,18,'삼손이 심히 목이 말라 여호와께 부르짖어 이르되 주께서 종의 손을 통하여 이 큰 구원을 베푸셨사오나 내가 이제 목말라 죽어서 할례 받지 못한 자들의 손에 떨어지겠나이다 하니',6948),
('jdg-15-19','jdg','사사기',15,19,'하나님이 레히에서 한 우묵한 곳을 터뜨리시니 거기서 물이 솟아나오는지라 삼손이 그것을 마시고 정신이 회복되어 소생하니 그러므로 그 샘 이름을 엔학고레라 불렀으며 그 샘이 오늘까지 레히에 있더라',6949),
('jdg-15-20','jdg','사사기',15,20,'블레셋 사람의 때에 삼손이 이스라엘의 사사로 이십 년 동안 지냈더라',6950),
('jdg-16-1','jdg','사사기',16,1,'삼손이 가사에 가서 거기서 한 기생을 보고 그에게로 들어갔더니',6951),
('jdg-16-2','jdg','사사기',16,2,'가사 사람들에게 삼손이 왔다고 알려지매 그들이 곧 그를 에워싸고 밤새도록 성문에 매복하고 밤새도록 조용히 하며 이르기를 새벽이 되거든 그를 죽이리라 하였더라',6952),
('jdg-16-3','jdg','사사기',16,3,'삼손이 밤중까지 누워 있다가 그 밤중에 일어나 성 문짝들과 두 문설주와 문빗장을 빼어 가지고 그것을 모두 어깨에 메고 헤브론 앞산 꼭대기로 가니라',6953),
('jdg-16-4','jdg','사사기',16,4,'이 후에 삼손이 소렉 골짜기의 들릴라라 이름하는 여인을 사랑하매',6954),
('jdg-16-5','jdg','사사기',16,5,'블레셋 사람의 방백들이 그 여인에게로 올라가서 그에게 이르되 삼손을 꾀어서 무엇으로 말미암아 그 큰 힘이 생기는지 그리고 우리가 어떻게 하면 능히 그를 결박하여 굴복하게 할 수 있을는지 알아보라 그리하면 우리가 각각 은 천백 개씩을 네게 주리라 하니',6955),
('jdg-16-6','jdg','사사기',16,6,'들릴라가 삼손에게 말하되 청하건대 당신의 큰 힘이 무엇으로 말미암아 생기며 어떻게 하면 능히 당신을 결박하여 굴복하게 할 수 있을는지 내게 말하라 하니',6956),
('jdg-16-7','jdg','사사기',16,7,'삼손이 그에게 이르되 만일 마르지 아니한 새 활줄 일곱으로 나를 결박하면 내가 약해져서 다른 사람과 같으리라',6957),
('jdg-16-8','jdg','사사기',16,8,'블레셋 사람의 방백들이 마르지 아니한 새 활줄 일곱을 여인에게로 가져오매 그가 그것으로 삼손을 결박하고',6958),
('jdg-16-9','jdg','사사기',16,9,'이미 사람을 방 안에 매복시켰으므로 삼손에게 말하되 삼손이여 블레셋 사람들이 당신에게 들이닥쳤느니라 하니 삼손이 그 줄들을 끊기를 불탄 삼실을 끊음 같이 하였고 그의 힘의 근원은 알아내지 못하니라',6959),
('jdg-16-10','jdg','사사기',16,10,'들릴라가 삼손에게 이르되 보라 당신이 나를 희롱하여 내게 거짓말을 하였도다 청하건대 무엇으로 당신을 결박할 수 있을는지 이제는 내게 말하라 하니',6960),
('jdg-16-11','jdg','사사기',16,11,'삼손이 그에게 이르되 만일 쓰지 아니한 새 밧줄들로 나를 결박하면 내가 약해져서 다른 사람과 같으리라 하니라',6961),
('jdg-16-12','jdg','사사기',16,12,'들릴라가 새 밧줄들을 가져다가 그것들로 그를 결박하고 그에게 이르되 삼손이여 블레셋 사람이 당신에게 들이닥쳤느니라 하니 삼손이 팔 위의 줄 끊기를 실을 끊음 같이 하였고 그 때에도 사람이 방 안에 매복하였더라',6962),
('jdg-16-13','jdg','사사기',16,13,'들릴라가 삼손에게 이르되 당신이 이 때까지 나를 희롱하여 내게 거짓말을 하였도다 내가 무엇으로 당신을 결박할 수 있을는지 내게 말하라 하니 삼손이 그에게 이르되 그대가 만일 나의 머리털 일곱 가닥을 베틀의 날실에 섞어 짜면 되리라 하는지라',6963),
('jdg-16-14','jdg','사사기',16,14,'들릴라가 바디로 그 머리털을 단단히 짜고 그에게 이르되 삼손이여 블레셋 사람들이 당신에게 들이닥쳤느니라 하니 삼손이 잠을 깨어 베틀의 바디와 날실을 다 빼내니라',6964),
('jdg-16-15','jdg','사사기',16,15,'들릴라가 삼손에게 이르되 당신의 마음이 내게 있지 아니하면서 당신이 어찌 나를 사랑한다 하느냐 당신이 이로써 세 번이나 나를 희롱하고 당신의 큰 힘이 무엇으로 말미암아 생기는지를 내게 말하지 아니하였도다 하며',6965),
('jdg-16-16','jdg','사사기',16,16,'날마다 그 말로 그를 재촉하여 조르매 삼손의 마음이 번뇌하여 죽을 지경이라',6966),
('jdg-16-17','jdg','사사기',16,17,'삼손이 진심을 드러내어 그에게 이르되 내 머리 위에는 삭도를 대지 아니하였나니 이는 내가 모태에서부터 하나님의 나실인이 되었음이라 만일 내 머리가 밀리면 내 힘이 내게서 떠나고 나는 약해져서 다른 사람과 같으리라 하니라',6967),
('jdg-16-18','jdg','사사기',16,18,'들릴라가 삼손이 진심을 다 알려 주므로 사람을 보내어 블레셋 사람들의 방백들을 불러 이르되 삼손이 내게 진심을 알려 주었으니 이제 한 번만 올라오라 하니 블레셋 방백들이 손에 은을 가지고 그 여인에게로 올라오니라',6968),
('jdg-16-19','jdg','사사기',16,19,'들릴라가 삼손에게 자기 무릎을 베고 자게 하고 사람을 불러 그의 머리털 일곱 가닥을 밀고 괴롭게 하여 본즉 그의 힘이 없어졌더라',6969),
('jdg-16-20','jdg','사사기',16,20,'들릴라가 이르되 삼손이여 블레셋 사람이 당신에게 들이닥쳤느니라 하니 삼손이 잠을 깨며 이르기를 내가 전과 같이 나가서 몸을 떨치리라 하였으나 여호와께서 이미 자기를 떠나신 줄을 깨닫지 못하였더라',6970),
('jdg-16-21','jdg','사사기',16,21,'블레셋 사람들이 그를 붙잡아 그의 눈을 빼고 끌고 가사에 내려가 놋 줄로 매고 그에게 옥에서 맷돌을 돌리게 하였더라',6971),
('jdg-16-22','jdg','사사기',16,22,'그의 머리털이 밀린 후에 다시 자라기 시작하니라',6972),
('jdg-16-23','jdg','사사기',16,23,'블레셋 사람의 방백들이 이르되 우리의 신이 우리 원수 삼손을 우리 손에 넘겨 주었다 하고 다 모여 그들의 신 다곤에게 큰 제사를 드리고 즐거워하고',6973),
('jdg-16-24','jdg','사사기',16,24,'백성들도 삼손을 보았으므로 이르되 우리의 땅을 망쳐 놓고 우리의 많은 사람을 죽인 원수를 우리의 신이 우리 손에 넘겨 주었다 하고 자기들의 신을 찬양하며',6974),
('jdg-16-25','jdg','사사기',16,25,'그들의 마음이 즐거울 때에 이르되 삼손을 불러다가 우리를 위하여 재주를 부리게 하자 하고 옥에서 삼손을 불러내매 삼손이 그들을 위하여 재주를 부리니라 그들이 삼손을 두 기둥 사이에 세웠더니',6975),
('jdg-16-26','jdg','사사기',16,26,'삼손이 자기 손을 붙든 소년에게 이르되 나에게 이 집을 버틴 기둥을 찾아 그것을 의지하게 하라 하니라',6976),
('jdg-16-27','jdg','사사기',16,27,'그 집에는 남녀가 가득하니 블레셋 모든 방백들도 거기에 있고 지붕에 있는 남녀도 삼천 명 가량이라 다 삼손이 재주 부리는 것을 보더라',6977),
('jdg-16-28','jdg','사사기',16,28,'삼손이 여호와께 부르짖어 이르되 주 여호와여 구하옵나니 나를 생각하옵소서 하나님이여 구하옵나니 이번만 나를 강하게 하사 나의 두 눈을 뺀 블레셋 사람에게 원수를 단번에 갚게 하옵소서 하고',6978),
('jdg-16-29','jdg','사사기',16,29,'삼손이 집을 버틴 두 기둥 가운데 하나는 왼손으로 하나는 오른손으로 껴 의지하고',6979),
('jdg-16-30','jdg','사사기',16,30,'삼손이 이르되 블레셋 사람과 함께 죽기를 원하노라 하고 힘을 다하여 몸을 굽히매 그 집이 곧 무너져 그 안에 있는 모든 방백들과 온 백성에게 덮이니 삼손이 죽을 때에 죽인 자가 살았을 때에 죽인 자보다 더욱 많았더라',6980),
('jdg-16-31','jdg','사사기',16,31,'그의 형제와 아버지의 온 집이 다 내려가서 그의 시체를 가지고 올라가서 소라와 에스다올 사이 그의 아버지 마노아의 장지에 장사하니라 삼손이 이스라엘의 사사로 이십 년 동안 지냈더라',6981),
('jdg-17-1','jdg','사사기',17,1,'에브라임 산지에 미가라 이름하는 사람이 있더니',6982),
('jdg-17-2','jdg','사사기',17,2,'그의 어머니에게 이르되 어머니께서 은 천백을 잃어버리셨으므로 저주하시고 내 귀에도 말씀하셨더니 보소서 그 은이 내게 있나이다 내가 그것을 가졌나이다 하니 그의 어머니가 이르되 내 아들이 여호와께 복 받기를 원하노라 하니라',6983),
('jdg-17-3','jdg','사사기',17,3,'미가가 은 천백을 그의 어머니에게 도로 주매 그의 어머니가 이르되 내가 내 아들을 위하여 한 신상을 새기며 한 신상을 부어 만들기 위해 내 손에서 이 은을 여호와께 거룩히 드리노라 그러므로 내가 이제 이 은을 네게 도로 주리라',6984),
('jdg-17-4','jdg','사사기',17,4,'미가가 그 은을 그의 어머니에게 도로 주었으므로 어머니가 그 은 이백을 가져다 은장색에게 주어 한 신상을 새기고 한 신상을 부어 만들었더니 그 신상이 미가의 집에 있더라',6985),
('jdg-17-5','jdg','사사기',17,5,'그 사람 미가에게 신당이 있으므로 그가 에봇과 드라빔을 만들고 한 아들을 세워 그의 제사장으로 삼았더라',6986),
('jdg-17-6','jdg','사사기',17,6,'그 때에는 이스라엘에 왕이 없었으므로 사람마다 자기 소견에 옳은 대로 행하였더라',6987),
('jdg-17-7','jdg','사사기',17,7,'유다 가족에 속한 유다 베들레헴에 한 청년이 있었으니 그는 레위인으로서 거기서 거류하였더라',6988),
('jdg-17-8','jdg','사사기',17,8,'그 사람이 거주할 곳을 찾고자 하여 그 성읍 유다 베들레헴을 떠나 가다가 에브라임 산지로 가서 미가의 집에 이르매',6989),
('jdg-17-9','jdg','사사기',17,9,'미가가 그에게 묻되 너는 어디서부터 오느냐 하니 그가 이르되 나는 유다 베들레헴의 레위인으로서 거류할 곳을 찾으러 가노라 하는지라',6990),
('jdg-17-10','jdg','사사기',17,10,'미가가 그에게 이르되 네가 나와 함께 거주하며 나를 위하여 아버지와 제사장이 되라 내가 해마다 은 열과 의복 한 벌과 먹을 것을 주리라 하므로 그 레위인이 들어갔더라',6991),
('jdg-17-11','jdg','사사기',17,11,'그 레위인이 그 사람과 함께 거주하기를 만족하게 생각했으니 이는 그 청년이 미가의 아들 중 하나 같이 됨이라',6992),
('jdg-17-12','jdg','사사기',17,12,'미가가 그 레위인을 거룩하게 구별하매 그 청년이 미가의 제사장이 되어 그 집에 있었더라',6993),
('jdg-17-13','jdg','사사기',17,13,'이에 미가가 이르되 레위인이 내 제사장이 되었으니 이제 여호와께서 내게 복 주실 줄을 아노라 하니라',6994),
('jdg-18-1','jdg','사사기',18,1,'그 때에 이스라엘에 왕이 없었고 단 지파는 그 때에 거주할 기업의 땅을 구하는 중이었으니 이는 그들이 이스라엘 지파 중에서 그 때까지 기업을 분배 받지 못하였음이라',6995),
('jdg-18-2','jdg','사사기',18,2,'단 자손이 소라와 에스다올에서부터 그들의 가족 가운데 용맹스런 다섯 사람을 보내어 땅을 정탐하고 살피게 하며 그들에게 이르되 너희는 가서 땅을 살펴보라 하매 그들이 에브라임 산지에 가서 미가의 집에 이르러 거기서 유숙하니라',6996),
('jdg-18-3','jdg','사사기',18,3,'그들이 미가의 집에 있을 때에 그 레위 청년의 음성을 알아듣고 그리로 돌아가서 그에게 이르되 누가 너를 이리로 인도하였으며 네가 여기서 무엇을 하며 여기서 무엇을 얻었느냐 하니',6997),
('jdg-18-4','jdg','사사기',18,4,'그가 그들에게 이르되 미가가 이러이러하게 나를 대접하고 나를 고용하여 나를 자기의 제사장으로 삼았느니라 하니라',6998),
('jdg-18-5','jdg','사사기',18,5,'그들이 그에게 이르되 청하건대 우리를 위하여 하나님께 물어 보아서 우리가 가는 길이 형통할는지 우리에게 알게 하라 하니',6999),
('jdg-18-6','jdg','사사기',18,6,'그 제사장이 그들에게 이르되 평안히 가라 너희가 가는 길은 여호와 앞에 있느니라 하니라',7000)
on conflict (id) do update set
  book_key = excluded.book_key,
  book_name = excluded.book_name,
  chapter = excluded.chapter,
  verse = excluded.verse,
  content = excluded.content,
  sort_order = excluded.sort_order;
